def _add(self, node: ast.AST, kind: str, category: str, *, line: int | None = None) -> None:
        if self.excluded_depth:
            return
        lineno = line if line is not None else getattr(node, "lineno", None)
        if not isinstance(lineno, int):
            raise InventoryError(f"branch node lacks a line number: {ast.dump(node)}")
        self.points.append(BranchPoint(f"{_qualname(self.stack)}:{lineno}:{kind}", category))

def _visit_scope(self, node: ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef) -> None:
        self.stack.append(node.name)
        excluded = node.name in EXCLUDED_QUALNAMES
        if excluded:
            self.excluded_depth += 1
        self.generic_visit(node)
        if excluded:
            self.excluded_depth -= 1
        self.stack.pop()

def visit_comprehension(self, node: ast.comprehension) -> None:
        for condition in node.ifs:
            self._add(condition, "compif", "decision")
        self.generic_visit(node)

def visit_Match(self, node: ast.Match) -> None:  # noqa: N802
        if not self.excluded_depth:
            for case in node.cases:
                line = getattr(case.pattern, "lineno", node.lineno)
                self._add(case.pattern, "case", "decision", line=line)
        self.generic_visit(node)

def _top_level_symbols(tree: ast.Module) -> tuple[str, ...]:
    symbols: list[str] = []
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            symbols.append(node.name)
        elif isinstance(node, (ast.Assign, ast.AnnAssign)):
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            for target in targets:
                if isinstance(target, ast.Name):
                    symbols.append(target.id)
    return tuple(symbols)

def _scan_module(name: str, source: Path, definition: str) -> ModuleInventory:
    tree = ast.parse(source.read_text(encoding="utf-8"), filename=str(source))
    visitor = _BranchVisitor()
    visitor.visit(tree)
    ids = [point.branch_id for point in visitor.points]
    duplicates = sorted({branch_id for branch_id in ids if ids.count(branch_id) > 1})
    if duplicates:
        raise InventoryError(f"duplicate branch IDs in {source}: {duplicates}")
    return ModuleInventory(
        name=name,
        source=source,
        definition=definition,
        symbols=_top_level_symbols(tree),
        decision_ids=tuple(
            point.branch_id for point in visitor.points if point.category == "decision"
        ),
        terminal_ids=tuple(
            point.branch_id for point in visitor.points if point.category == "terminal"
        ),
    )

def _section(text: str, section: str) -> str:
    pattern = re.compile(
        rf"^## {re.escape(section)}\b.*?(?=^## (?:§|附:)|\Z)",
        re.MULTILINE | re.DOTALL,
    )
    match = pattern.search(text)
    if match is None:
        raise InventoryError(f"design section not found: {section}")
    return match.group(0)

def _markdown_table(section_text: str, header: list[str]) -> list[list[str]]:
    rows: list[list[str]] = []
    collecting = False
    for line in section_text.splitlines():
        if not line.startswith("|"):
            if collecting:
                break
            continue
        cells = [cell.strip() for cell in line.strip().strip("|").split("|")]
        if not collecting:
            if cells == header:
                collecting = True
                rows.append(cells)
            continue
        if cells and all(re.fullmatch(r":?-+:?", cell) for cell in cells):
            continue
        rows.append(cells)
    if not rows:
        raise InventoryError(f"Markdown table not found: {' | '.join(header)}")
    return rows

def _parse_symbol_table(design: Path) -> dict[tuple[str, str], str]:
    rows = _markdown_table(
        _section(design.read_text(encoding="utf-8"), "§0"),
        ["symbol", "definition", "owner"],
    )
    if not rows or rows[0] != ["symbol", "definition", "owner"]:
        raise InventoryError("§0 table must have symbol | definition | owner columns")
    parsed: dict[tuple[str, str], str] = {}
    for cells in rows[1:]:
        if len(cells) != 3:
            raise InventoryError(f"malformed §0 row: {cells}")
        symbol = cells[0].strip("`")
        definition = cells[1].strip("`")
        owner = cells[2].strip("`")
        key = (definition, symbol)
        if key in parsed:
            raise InventoryError(f"duplicate §0 symbol row: {key}")
        parsed[key] = owner
    return parsed

def _expected_symbol_table(inventories: tuple[ModuleInventory, ...]) -> dict[tuple[str, str], str]:
    return {
        (inventory.definition, symbol): OWNER
        for inventory in inventories
        for symbol in inventory.symbols
    }

def _parser_only(design: Path, inventories: tuple[ModuleInventory, ...]) -> None:
    actual = _parse_symbol_table(design)
    expected = _expected_symbol_table(inventories)
    missing = sorted(expected.keys() - actual.keys())
    extra = sorted(actual.keys() - expected.keys())
    owner_mismatch = sorted(
        (definition, symbol, expected[(definition, symbol)], actual[(definition, symbol)])
        for definition, symbol in expected.keys() & actual.keys()
        if expected[(definition, symbol)] != actual[(definition, symbol)]
    )
    if missing or extra or owner_mismatch:
        raise InventoryError(
            f"parser-only mismatch: missing={missing}, extra={extra}, "
            f"owner_mismatch={owner_mismatch}"
        )
    print(
        f"PARSER_ONLY | {len(actual)}/{len(expected)} | missing=0 | extra=0 | OWNER_MISMATCH=0 | OK"
    )

def _branch_rows(design: Path) -> tuple[BranchRow, ...]:
    rows = _markdown_table(
        _section(design.read_text(encoding="utf-8"), "§5"),
        ["契约句", "分支(代码锚)", "用例"],
    )
    if not rows or rows[0] != ["契约句", "分支(代码锚)", "用例"]:
        raise InventoryError("§5 branch table header is missing or malformed")
    result: list[BranchRow] = []
    for cells in rows[1:]:
        if len(cells) != 3:
            raise InventoryError(f"malformed §5 branch row: {cells}")
        contract, anchor, _ = cells
        external = "EXTERNAL_BRANCH" in anchor
        local_ids = (
            () if external else tuple(match.group(0) for match in BRANCH_ID_RE.finditer(anchor))
        )
        if not external and not local_ids:
            raise InventoryError(f"branch row has no exact local branch ID: {contract}")
        if external:
            calls = tuple(match.group(0) for match in CALL_ID_RE.finditer(anchor))
            required = (
                len(calls) == 1
                and "tizen_ci_shared.quickbuild_http:193:if" in anchor
                and "tizen_ci_shared.quickbuild_http:198:raise" in anchor
                and "QuickBuildError" in anchor
                and "COOKIE_EXPIRED" in anchor
            )
            if not required:
                raise InventoryError(f"EXTERNAL_BRANCH binding is incomplete for row: {contract}")
        result.append(BranchRow(contract, anchor, local_ids, external))
    return tuple(result)

def _call_name(node: ast.Call) -> str | None:
    if isinstance(node.func, ast.Name):
        return node.func.id
    if isinstance(node.func, ast.Attribute):
        return node.func.attr
    return None

def _validate_external_bindings(rows: tuple[BranchRow, ...]) -> None:
    trees = {
        inventory.name: ast.parse(inventory.source.read_text(encoding="utf-8"))
        for inventory in _scan_modules()
    }
    calls: dict[str, str | None] = {}
    for tree in trees.values():

        class Visitor(ast.NodeVisitor):
            def __init__(self) -> None:
                self.stack: list[str] = []

            def visit_FunctionDef(self, node: ast.FunctionDef) -> None:  # noqa: N802
                self.stack.append(node.name)
                self.generic_visit(node)
                self.stack.pop()

            def visit_ClassDef(self, node: ast.ClassDef) -> None:  # noqa: N802
                self.stack.append(node.name)
                self.generic_visit(node)
                self.stack.pop()

            def visit_Call(self, node: ast.Call) -> None:  # noqa: N802
                calls[f"{_qualname(self.stack)}:{node.lineno}:call"] = _call_name(node)
                self.generic_visit(node)

        Visitor().visit(tree)
    for row in rows:
        if not row.external:
            continue
        call_id = CALL_ID_RE.search(row.anchor)
        assert call_id is not None
        measured_call = calls.get(call_id.group(0))
        if measured_call != "_raise_if_login_page":
            raise InventoryError(
                "EXTERNAL_BRANCH local call mismatch: "
                f"{call_id.group(0)} -> {measured_call!r}, expected '_raise_if_login_page'"
            )

    external_tree = ast.parse(
        EXTERNAL_SOURCE.read_text(encoding="utf-8"), filename=str(EXTERNAL_SOURCE)
    )
    nodes_by_line: dict[int, list[ast.AST]] = {}
    for node in ast.walk(external_tree):
        line = getattr(node, "lineno", None)
        if isinstance(line, int):
            nodes_by_line.setdefault(line, []).append(node)
    if not any(isinstance(node, ast.If) for node in nodes_by_line.get(193, [])):
        raise InventoryError(
            "EXTERNAL_BRANCH target tizen_ci_shared.quickbuild_http:193 is not ast.If"
        )
    raises = [node for node in nodes_by_line.get(198, []) if isinstance(node, ast.Raise)]
    if len(raises) != 1:
        raise InventoryError(
            "EXTERNAL_BRANCH target tizen_ci_shared.quickbuild_http:198 is not one ast.Raise"
        )
    exc = raises[0].exc
    if not isinstance(exc, ast.Call) or _call_name(exc) != "QuickBuildError":
        raise InventoryError("EXTERNAL_BRANCH raise does not construct QuickBuildError")
    if (
        not exc.args
        or not isinstance(exc.args[0], ast.Constant)
        or exc.args[0].value != "COOKIE_EXPIRED"
    ):
        raise InventoryError("EXTERNAL_BRANCH QuickBuildError first argument is not COOKIE_EXPIRED")

def _load_data(path: Path) -> dict[str, Any]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise InventoryError(f"cannot load {path}: {exc}") from exc
    if not isinstance(value, dict) or value.get("schema_version") != SCHEMA_VERSION:
        raise InventoryError(f"unexpected data schema in {path}")
    return value

def _inventory_payload(inventories: tuple[ModuleInventory, ...]) -> dict[str, Any]:
    return {
        inventory.name: {
            "source": str(inventory.source.relative_to(REPO_ROOT)),
            "definition": inventory.definition,
            "decision_points": len(inventory.decision_ids),
            "terminal_outcomes": len(inventory.terminal_ids),
            "ids": list(inventory.all_ids),
        }
        for inventory in inventories
    }

def _check(design: Path, data_path: Path, inventories: tuple[ModuleInventory, ...]) -> None:
    data = _load_data(data_path)
    if data.get("target_design") != str(design.relative_to(REPO_ROOT)):
        raise InventoryError("data target_design does not match the checked design")
    if data.get("target_sha256") != _sha256(design):
        raise InventoryError("data target_sha256 does not match the checked design")
    expected_modules = _inventory_payload(inventories)
    if data.get("modules") != expected_modules:
        raise InventoryError("stored module inventory differs from the AST scan")

    rows = _branch_rows(design)
    _validate_external_bindings(rows)
    all_ids = {branch_id for inventory in inventories for branch_id in inventory.all_ids}
    referenced = {branch_id for row in rows for branch_id in row.local_ids}
    unknown = sorted(referenced - all_ids)
    if unknown:
        raise InventoryError(f"branch table references unknown IDs: {unknown}")
    reasons = data.get("unreferenced_reasons")
    if not isinstance(reasons, dict) or not all(
        isinstance(key, str) and isinstance(value, str) and value.strip()
        for key, value in reasons.items()
    ):
        raise InventoryError("unreferenced_reasons must be a non-empty string mapping")
    unreferenced = all_ids - referenced
    if set(reasons) != unreferenced:
        raise InventoryError(
            "unreferenced reason partition mismatch: "
            f"missing={sorted(unreferenced - set(reasons))}, "
            f"extra={sorted(set(reasons) - unreferenced)}"
        )
    external_count = sum(row.external for row in rows)
    print(
        f"BRANCH_TABLE | rows={len(rows)} | referenced_ids={len(referenced)} | "
        f"unreferenced_ids={len(unreferenced)} | external_rows={external_count} | OK"
    )
    for inventory in inventories:
        print(
            f"MODULE | {inventory.name} | decision_points={len(inventory.decision_ids)} | "
            f"terminal_outcomes={len(inventory.terminal_ids)} | "
            f"ids={len(inventory.all_ids)} | unique=YES"
        )
    print(
        f"SUMMARY | modules={len(inventories)} | ids={len(all_ids)} | "
        "collisions=0 | unknown_refs=0 | missing_reasons=0 | OK"
    )

def _admission_v17(snapshot: Path) -> int:
    text = snapshot.read_text(encoding="utf-8")
    defects = {
        "HANDWRITTEN_BOOL_COUNT": "实存 14 处" in text,
        "MISSING_V17_REVISION_BLOCK": "> **v1.7 修订" not in text,
    }
    for defect, present in defects.items():
        print(f"ADMISSION | {defect} | {'DRIFT' if present else 'NOT_FOUND'}")
    if not all(defects.values()):
        raise InventoryError(f"v1.7 admission fixture lacks required defects: {defects}")
    print("ADMISSION | snapshot=v1.7 | required=2/2 | RED_AS_EXPECTED")
    return 1

def _print_symbols(inventories: tuple[ModuleInventory, ...]) -> None:
    print("| symbol | definition | owner |")
    print("|---|---|---|")
    for inventory in inventories:
        for symbol in inventory.symbols:
            print(f"| `{symbol}` | `{inventory.definition}` | `{OWNER}` |")

def main(argv: list[str] | None = None) -> int:
    args = _parse_args(argv or sys.argv[1:])
    try:
        design = args.design if args.design.is_absolute() else REPO_ROOT / args.design
        data = args.data if args.data.is_absolute() else REPO_ROOT / args.data
        snapshot = args.snapshot if args.snapshot.is_absolute() else REPO_ROOT / args.snapshot
        inventories = _scan_modules()
        if args.action == "symbols":
            _print_symbols(inventories)
        elif args.action == "inventory":
            _print_inventory(inventories)
        elif args.action == "parser-only":
            _parser_only(design, inventories)
        elif args.action == "check":
            _parser_only(design, inventories)
            _check(design, data, inventories)
        else:
            return _admission_v17(snapshot)
    except (InventoryError, OSError, SyntaxError) as exc:
        print(f"ERROR | {exc}", file=sys.stderr)
        return 2
    return 0

def _mask_fenced_blocks(src: str, blocks: list[_FenceBlock]) -> str:
    chars = list(src)
    for block in blocks:
        for index in range(block.start, block.end):
            if chars[index] not in {"\n", "\r"}:
                chars[index] = " "
    return "".join(chars)

def _section(src: str, start_pat: str, end_pat: str) -> str:
    m = re.search(start_pat, src, re.M)
    n = re.search(end_pat, src, re.M)
    if not m:
        return ""
    return src[m.start() : n.start() if n else len(src)]

def _find_authoritative_prompt(design_path: Path) -> Path | None:
    for directory in (design_path.parent, *design_path.parents):
        candidate = directory / AUTHORITATIVE_PROMPT
        if candidate.is_file():
            return candidate
    return None

def _check_python_contracts(src: str) -> list[str]:
    problems: list[str] = []
    blocks = _fenced_blocks(src)
    for block in blocks:
        if block.language != "python":
            continue
        line_no = src.count("\n", 0, block.start) + 1
        try:
            compile(block.body, f"<design.md:L{line_no}>", "exec")
        except SyntaxError as exc:
            detail = exc.msg
            if exc.lineno is not None:
                detail += f" at block line {exc.lineno}"
            problems.append(f"[CK-API-01] L{line_no}: {detail}")

    bare_src = _mask_fenced_blocks(src, blocks)
    for match in BARE_SIGNATURE_RE.finditer(bare_src):
        line_no = bare_src.count("\n", 0, match.start()) + 1
        signature = match.group(0).rstrip("(")
        problems.append(f"[CK-API-01] L{line_no}: fence 外模块式裸签名 {signature}")
    return problems

def _check_index_contract(src: str, prompt_src: str | None) -> list[str]:
    if prompt_src is None:
        return [f"[CK-IDX-01] 缺少唯一权威 prompt: {AUTHORITATIVE_PROMPT}"]
    design_indexes = {name.lower() for name in DESIGN_INDEX_RE.findall(src)}
    prompt_indexes = set(PROMPT_INDEX_RE.findall(prompt_src.lower()))
    if not prompt_indexes:
        return ["[CK-IDX-01] 权威 prompt 的索引 token 集合为空"]
    unknown = sorted(prompt_indexes - design_indexes)
    if unknown:
        return ["[CK-IDX-01] prompt 索引不属于 design 集合: " + ", ".join(unknown)]
    return []

def _mermaid_edge_nodes(line: str) -> list[str]:
    if not MERMAID_EDGE_RE.search(line):
        return []
    without_labels = re.sub(r"\|[^|]*\|", "", line)
    nodes: list[str] = []
    for segment in MERMAID_EDGE_RE.split(without_labels):
        match = re.match(r"\s*([A-Za-z_][A-Za-z0-9_]*)", segment)
        if match:
            nodes.append(match.group(1))
    return nodes

def _check_mermaid_contracts(src: str) -> list[str]:
    problems: list[str] = []
    for block in _fenced_blocks(src):
        if block.language != "mermaid":
            continue
        block_line = src.count("\n", 0, block.start) + 1
        declared: set[str] = set()
        for offset, line in enumerate(block.body.splitlines(), 1):
            declared.update(MERMAID_NODE_DECL_RE.findall(line))
            for node in _mermaid_edge_nodes(line):
                if node not in declared:
                    problems.append(
                        f"[CK-MMD-01] L{block_line + offset}: 节点 {node} 在声明前被引用"
                    )

    return problems

def normalize(text: str) -> str:
    """Normalize only the forms admitted by section 5.4."""

    normalized = unicodedata.normalize("NFKC", text)
    for marker in MARKDOWN_MARKERS:
        normalized = normalized.replace(marker, "")
    return " ".join(normalized.split())

def _load_json(path: Path) -> dict[str, Any]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise LedgerError(f"cannot read ledger data {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise LedgerError("ledger data root must be an object")
    return value

def _version_key(version: str) -> tuple[int, int, int]:
    match = VERSION_RE.fullmatch(version)
    if match is None:
        raise LedgerError(f"unsupported version: {version!r}")
    return int(match.group(1)), int(match.group(2)), int(match.group(3) or 0)

def _validate_version_sequence(versions: tuple[str, ...]) -> None:
    keys = [_version_key(version) for version in versions]
    if len(set(keys)) != len(keys):
        raise LedgerError(f"version sequence contains duplicates: {versions}")
    for previous, current in zip(keys, keys[1:], strict=False):
        same_minor_patch = (
            current[0] == previous[0]
            and current[1] == previous[1]
            and current[2] == previous[2] + 1
        )
        next_minor = (
            current[0] == previous[0]
            and current[1] == previous[1] + 1
            and current[2] == 0
        )
        if not (same_minor_patch or next_minor):
            raise LedgerError(f"version sequence is not continuous: {versions}")

def _string_list(data: dict[str, Any], key: str) -> tuple[str, ...]:
    raw = data.get(key)
    if not isinstance(raw, list) or not raw or not all(isinstance(item, str) for item in raw):
        raise LedgerError(f"{key} must be a non-empty list of strings")
    return tuple(raw)

def _corpus_plan(data: dict[str, Any], repo_root: Path) -> tuple[tuple[str, Path], ...]:
    raw_dir = data.get("corpus_dir")
    raw_files = data.get("version_files")
    versions = _string_list(data, "version_sequence")
    if not isinstance(raw_dir, str) or not isinstance(raw_files, dict):
        raise LedgerError("corpus_dir/version_files configuration missing")
    if set(raw_files) != set(versions) or not all(
        isinstance(version, str) and isinstance(filename, str)
        for version, filename in raw_files.items()
    ):
        raise LedgerError("version_files keys must exactly equal version_sequence")

    _validate_version_sequence(versions)

    corpus_dir = repo_root / raw_dir
    return tuple((version, corpus_dir / str(raw_files[version])) for version in versions)

def _document_config(data: dict[str, Any]) -> tuple[tuple[str, ...], str]:
    raw_excluded = data.get("excluded_sections", [])
    dod_section = data.get("dod_section")
    if not isinstance(raw_excluded, list) or not all(
        isinstance(item, str) for item in raw_excluded
    ):
        raise LedgerError("excluded_sections must be a list of strings")
    if not isinstance(dod_section, str):
        raise LedgerError("dod_section must be a string")
    return tuple(raw_excluded), dod_section

def _load_versions(data: dict[str, Any], repo_root: Path) -> tuple[VersionDoc, ...]:
    raw_versions = data.get("version_corpus")
    if not isinstance(raw_versions, list):
        raise LedgerError("version_corpus must be a list")

    plan = _corpus_plan(data, repo_root)
    excluded_sections, dod_section = _document_config(data)
    if len(raw_versions) != len(plan):
        raise LedgerError("version_corpus length differs from configured version sequence")

    documents: list[VersionDoc] = []
    for raw, (configured_version, configured_path) in zip(raw_versions, plan, strict=True):
        if not isinstance(raw, dict):
            raise LedgerError("version_corpus entries must be objects")
        version = raw.get("version")
        raw_path = raw.get("path")
        expected_sha = raw.get("sha256")
        if not isinstance(version, str) or not isinstance(raw_path, str):
            raise LedgerError("version corpus entry lacks version/path")
        path = repo_root / raw_path
        if version != configured_version or path.resolve() != configured_path.resolve():
            raise LedgerError(
                "version corpus entry differs from configured sequence/path: "
                f"{version}:{path} != {configured_version}:{configured_path}"
            )
        try:
            content = path.read_bytes()
        except OSError as exc:
            raise LedgerError(f"missing version corpus file {path}: {exc}") from exc
        actual_sha = _sha256_bytes(content)
        if expected_sha != actual_sha:
            raise LedgerError(
                f"version corpus SHA mismatch for {version}: expected {expected_sha}, "
                f"actual {actual_sha}"
            )
        documents.append(
            VersionDoc(
                version,
                path,
                tuple(content.decode("utf-8").splitlines()),
                excluded_sections,
                dod_section,
            )
        )
    return tuple(documents)

def _raw_deleted_lines(
    documents: tuple[VersionDoc, ...],
) -> frozenset[tuple[str, int]]:
    """Read deleted line coordinates directly from raw diffs as the coverage anchor."""

    deleted: set[tuple[str, int]] = set()
    for old, new in zip(documents, documents[1:], strict=False):
        old_line_number: int | None = None
        for line in _raw_diff(old, new).splitlines():
            match = HUNK_RE.match(line)
            if match is not None:
                old_line_number = int(match.group("old_start"))
                continue
            if old_line_number is None:
                continue
            if line.startswith("-"):
                deleted.add((old.version, old_line_number))
                old_line_number += 1
            elif line.startswith(" "):
                old_line_number += 1
    return frozenset(deleted)

def _section_spans(lines: tuple[str, ...]) -> dict[str, tuple[int, int]]:
    headings: list[tuple[str, int, int]] = []
    for index, line in enumerate(lines, 1):
        match = HEADING_RE.match(line)
        if match is not None:
            headings.append((f"§{match.group('id')}", len(match.group("marks")), index))

    spans: dict[str, tuple[int, int]] = {}
    for position, (section_id, level, start) in enumerate(headings):
        end = len(lines)
        for _, next_level, next_start in headings[position + 1 :]:
            if next_level <= level:
                end = next_start - 1
                break
        if section_id in spans:
            raise LedgerError(f"duplicate section heading: {section_id}")
        spans[section_id] = (start, end)
    return spans

def _revision_span(lines: tuple[str, ...]) -> tuple[int, int] | None:
    starts = [
        index
        for index, line in enumerate(lines, 1)
        if line.startswith("> **v1.") or line.startswith("> **v2.")
    ]
    if not starts:
        return None
    start = starts[0]
    for index in range(start + 1, len(lines) + 1):
        if lines[index - 1] == "---":
            return start, index - 1
    raise LedgerError("revision block has no closing horizontal rule")

def _excluded_lines(doc: VersionDoc) -> frozenset[int]:
    excluded: set[int] = set()
    revision = _revision_span(doc.lines)
    if revision is not None:
        excluded.update(range(revision[0], revision[1] + 1))
    spans = _section_spans(doc.lines)
    for section_id in doc.excluded_sections:
        span = spans.get(section_id)
        if span is not None:
            excluded.update(range(span[0], span[1] + 1))
    return frozenset(excluded)

def _primary_sections(doc: VersionDoc) -> dict[str, str]:
    excluded = _excluded_lines(doc)
    result: dict[str, list[str]] = {"frontmatter": []}
    current = "frontmatter"
    for index, line in enumerate(doc.lines, 1):
        if index in excluded:
            continue
        match = re.match(r"^##\s+§(?P<id>[0-9]+)\b", line)
        if match is not None:
            current = f"§{match.group('id')}"
            result.setdefault(current, [])
        result[current].append(line)
    return {key: normalize("\n".join(value)) for key, value in result.items()}

def _section_text(doc: VersionDoc, section_id: str) -> str:
    span = _section_spans(doc.lines).get(section_id)
    if span is None:
        raise LedgerError(f"section {section_id} not found in v{doc.version}")
    return "\n".join(doc.lines[span[0] - 1 : span[1]])

def _dod_items(doc: VersionDoc) -> tuple[DodItem, ...]:
    span = _section_spans(doc.lines).get(doc.dod_section)
    if span is None:
        raise LedgerError(f"DoD section {doc.dod_section} not found in v{doc.version}")
    items: list[DodItem] = []
    current_lines: list[str] = []
    current_start = 0
    current_end = 0

    def finish() -> None:
        nonlocal current_lines, current_start, current_end
        if not current_lines:
            return
        items.append(
            DodItem(
                item_id=f"DOD-{len(items) + 1:02d}",
                text="\n".join(current_lines),
                line_start=current_start,
                line_end=current_end,
            )
        )
        current_lines = []

    for line_number in range(span[0] + 1, span[1] + 1):
        line = doc.lines[line_number - 1]
        if line == "---" or line.startswith("## "):
            break
        if line.startswith("- [ ] "):
            finish()
            current_start = line_number
            current_end = line_number
            current_lines = [line[6:]]
        elif current_lines:
            current_lines.append(line.strip())
            current_end = line_number
    finish()
    return tuple(items)

def finish() -> None:
        nonlocal current_lines, current_start, current_end
        if not current_lines:
            return
        items.append(
            DodItem(
                item_id=f"DOD-{len(items) + 1:02d}",
                text="\n".join(current_lines),
                line_start=current_start,
                line_end=current_end,
            )
        )
        current_lines = []

def _matches_by_section(pattern: str, doc: VersionDoc) -> dict[str, int]:
    if not pattern:
        return {}
    counts: dict[str, int] = {}
    for section_id, text in _primary_sections(doc).items():
        count = len(tuple(re.finditer(pattern, text)))
        if count:
            counts[section_id] = count
    return counts

def _candidate_map(documents: tuple[VersionDoc, ...], repo_root: Path) -> dict[str, DiffCandidate]:
    candidates: dict[str, DiffCandidate] = {}
    for old, new in zip(documents, documents[1:], strict=False):
        for candidate in _diff_candidates(old, new, repo_root):
            if candidate.candidate_id in candidates:
                raise LedgerError(f"duplicate candidate ID: {candidate.candidate_id}")
            candidates[candidate.candidate_id] = candidate
    return candidates

def _changed_sections(documents: tuple[VersionDoc, ...]) -> dict[str, str]:
    first_transition: dict[str, str] = {}
    for old, new in zip(documents, documents[1:], strict=False):
        old_spans = _section_spans(old.lines)
        new_spans = _section_spans(new.lines)
        for section_id in sorted(set(old_spans) | set(new_spans)):
            old_text = _section_text(old, section_id) if section_id in old_spans else ""
            new_text = _section_text(new, section_id) if section_id in new_spans else ""
            if normalize(old_text) != normalize(new_text):
                first_transition.setdefault(section_id, f"v{old.version}->v{new.version}")
    return first_transition

def _export_binding_candidates(
    documents: tuple[VersionDoc, ...], target: VersionDoc
) -> tuple[tuple[str, ...], dict[str, str]]:
    changed = _changed_sections(documents)
    dod_items = _dod_items(target)
    exported = {
        _binding_candidate_id(section_id, f"dod:{item.item_id}")
        for section_id in changed
        for item in dod_items
    }
    # This deliberate superset includes every possible normative section reference,
    # therefore every normalized snippet occurrence, without trusting a hand-written
    # snippet list to define its own completeness boundary.
    for definition_section in changed:
        for reference_id in _section_spans(target.lines):
            exported.add(_binding_candidate_id(definition_section, f"section:{reference_id}"))
    return tuple(sorted(exported)), changed

def _extract_reference_text(
    binding: dict[str, Any], doc: VersionDoc, dod_by_id: dict[str, DodItem]
) -> str:
    reference = binding.get("reference")
    if not isinstance(reference, dict):
        raise LedgerError(f"binding {binding.get('id')} lacks reference")
    kind = reference.get("kind")
    reference_id = reference.get("id")
    if not isinstance(reference_id, str):
        raise LedgerError(f"binding {binding.get('id')} has invalid reference id")
    if kind == "dod":
        item = dod_by_id.get(reference_id)
        if item is None:
            raise LedgerError(f"DoD item {reference_id} not found in v{doc.version}")
        text = item.text
    elif kind == "section":
        text = _section_text(doc, reference_id)
    else:
        raise LedgerError(f"binding {binding.get('id')} has unknown reference kind {kind}")
    selector = reference.get("selector")
    if selector is None:
        return text
    if not isinstance(selector, str):
        raise LedgerError(f"binding {binding.get('id')} reference selector is not a string")
    match = re.search(selector, text, flags=re.MULTILINE | re.DOTALL)
    if match is None:
        raise LedgerError(
            f"binding {binding.get('id')} reference selector did not match v{doc.version}"
        )
    return match.group(0)

def _chinese_number(value: str) -> int:
    if value.isdigit():
        return int(value)
    digits = {"一": 1, "二": 2, "三": 3, "四": 4, "五": 5, "六": 6, "七": 7, "八": 8, "九": 9}
    if value == "十":
        return 10
    if "十" in value:
        left, right = value.split("十", 1)
        return (digits.get(left, 1) * 10) + digits.get(right, 0)
    if value not in digits:
        raise LedgerError(f"unsupported Chinese numeral: {value}")
    return digits[value]

def _evaluate_binding_text(
    binding: dict[str, Any], definition_text: str, reference_text: str
) -> tuple[bool, str]:
    binding_id = binding.get("id")
    predicate = binding.get("predicate")
    snippets = binding.get("canonical_snippets", [])
    if not isinstance(snippets, list) or not all(isinstance(item, str) for item in snippets):
        raise LedgerError(f"binding {binding_id} canonical_snippets must be strings")

    if predicate == "TEXT_CONTAINS":
        if not snippets:
            raise LedgerError(f"TEXT_CONTAINS binding {binding_id} has no snippets")
        normalized_definition = normalize(definition_text)
        normalized_reference = normalize(reference_text)
        missing_definition = [
            item for item in snippets if normalize(item) not in normalized_definition
        ]
        missing_reference = [
            item for item in snippets if normalize(item) not in normalized_reference
        ]
        if missing_definition or missing_reference:
            return False, (
                f"missing_definition={missing_definition}, missing_reference={missing_reference}"
            )
        return True, f"snippets={len(snippets)}"

    if predicate == "COUNT_EQUAL":
        selector = binding.get("definition_selector")
        if not isinstance(selector, str):
            raise LedgerError(f"COUNT_EQUAL binding {binding_id} lacks definition_selector")
        definition_count = len(re.findall(selector, definition_text, flags=re.MULTILINE))
        compact_reference = re.sub(r"\s+", "", normalize(reference_text))
        number_matches = NUMBER_RE.findall(compact_reference)
        if len(number_matches) != 1:
            return False, f"reference_number_matches={number_matches}"
        reference_count = _chinese_number(number_matches[0][0])
        return (
            definition_count == reference_count,
            f"definition_count={definition_count}, reference_count={reference_count}",
        )

    if predicate == "REF_ONLY":
        if not snippets:
            raise LedgerError(f"REF_ONLY binding {binding_id} has no carrying snippets")
        normalized_definition = normalize(definition_text)
        normalized_reference = normalize(reference_text)
        missing_definition = [
            item for item in snippets if normalize(item) not in normalized_definition
        ]
        leaked = [item for item in snippets if normalize(item) in normalized_reference]
        refs = SECTION_REF_RE.findall(normalized_reference)
        target = binding.get("definition_section")
        passed = not missing_definition and not leaked and refs == [target]
        return passed, (
            f"missing_definition={missing_definition}, leaked_snippets={leaked}, "
            f"parsed_targets={refs}, expected={target}"
        )

    raise LedgerError(f"binding {binding_id} has unknown predicate: {predicate}")

def _evaluate_binding(binding: dict[str, Any], doc: VersionDoc) -> tuple[bool, str]:
    definition_section = binding.get("definition_section")
    if not isinstance(definition_section, str):
        raise LedgerError(f"binding {binding.get('id')} lacks definition_section")
    dod_by_id = {item.item_id: item for item in _dod_items(doc)}
    try:
        definition_text = _section_text(doc, definition_section)
        reference_text = _extract_reference_text(binding, doc, dod_by_id)
    except LedgerError as exc:
        return False, str(exc)
    return _evaluate_binding_text(binding, definition_text, reference_text)

def _binding_reference_key(binding: dict[str, Any]) -> str:
    reference = binding.get("reference")
    if not isinstance(reference, dict):
        raise LedgerError(f"binding {binding.get('id')} lacks reference")
    kind = reference.get("kind")
    reference_id = reference.get("id")
    if not isinstance(kind, str) or not isinstance(reference_id, str):
        raise LedgerError(f"binding {binding.get('id')} has malformed reference")
    return _binding_candidate_id(str(binding.get("definition_section")), f"{kind}:{reference_id}")

def _check_binding_inventory(
    data: dict[str, Any], documents: tuple[VersionDoc, ...]
) -> tuple[dict[str, dict[str, Any]], tuple[str, ...]]:
    target = documents[-1]
    exported, changed = _export_binding_candidates(documents, target)
    bindings_raw = data.get("bindings")
    ignored_raw = data.get("ignored_binding_candidates")
    process_raw = data.get("process_only")
    if not isinstance(bindings_raw, list) or not isinstance(ignored_raw, list):
        raise LedgerError("bindings and ignored_binding_candidates must be lists")
    if not isinstance(process_raw, list):
        raise LedgerError("process_only must be a list")

    bindings: dict[str, dict[str, Any]] = {}
    retained_keys: set[str] = set()
    for binding in bindings_raw:
        if not isinstance(binding, dict) or not isinstance(binding.get("id"), str):
            raise LedgerError("binding entries must be objects with string IDs")
        binding_id = binding["id"]
        if binding_id in bindings:
            raise LedgerError(f"duplicate binding id: {binding_id}")
        definition_section = binding.get("definition_section")
        if definition_section not in changed:
            raise LedgerError(
                f"binding {binding_id} definition section was not changed in corpus: "
                f"{definition_section}"
            )
        expected_transition = changed[str(definition_section)]
        if binding.get("source_transition") != expected_transition:
            raise LedgerError(
                f"binding {binding_id} source transition mismatch: "
                f"{binding.get('source_transition')} != {expected_transition}"
            )
        bindings[binding_id] = binding
        retained_keys.add(_binding_reference_key(binding))

    ignored = set(ignored_raw)
    if not all(isinstance(item, str) for item in ignored_raw):
        raise LedgerError("ignored binding candidate IDs must be strings")
    if len(ignored) != len(ignored_raw):
        raise LedgerError("ignored binding candidate IDs contain duplicates")
    stored_exported = data.get("binding_candidates")
    if not isinstance(stored_exported, list) or not all(
        isinstance(item, str) for item in stored_exported
    ):
        raise LedgerError("binding_candidates must be a list of strings")
    if stored_exported != list(exported):
        raise LedgerError("stored binding candidate export differs from generated export")
    if retained_keys & ignored:
        raise LedgerError("binding candidate retained/ignored sets overlap")
    if set(exported) != retained_keys | ignored:
        missing = sorted(set(exported) - retained_keys - ignored)
        added = sorted((retained_keys | ignored) - set(exported))
        raise LedgerError(
            f"binding candidate partition mismatch: missing={missing}, not_exported={added}"
        )

    dod_ids = {item.item_id for item in _dod_items(target)}
    bound_dod = {
        str(binding["reference"]["id"])
        for binding in bindings.values()
        if binding["reference"].get("kind") == "dod"
    }
    process_ids: set[str] = set()
    for entry in process_raw:
        if not isinstance(entry, dict) or not isinstance(entry.get("dod_id"), str):
            raise LedgerError("PROCESS_ONLY entries require dod_id")
        if not isinstance(entry.get("reason"), str) or not entry["reason"].strip():
            raise LedgerError(f"PROCESS_ONLY {entry.get('dod_id')} lacks a reason")
        process_ids.add(entry["dod_id"])
    if bound_dod & process_ids:
        raise LedgerError(
            f"DoD entries cannot be both bound and PROCESS_ONLY: {bound_dod & process_ids}"
        )
    if dod_ids != bound_dod | process_ids:
        raise LedgerError(
            f"DoD external-anchor mismatch: missing={sorted(dod_ids - bound_dod - process_ids)}, "
            f"unknown={sorted((bound_dod | process_ids) - dod_ids)}"
        )
    return bindings, exported

def _check_candidate_ledger(
    data: dict[str, Any], documents: tuple[VersionDoc, ...], repo_root: Path
) -> tuple[int, int, int]:
    generated = _candidate_map(documents, repo_root)
    ledger = data.get("candidate_ledger")
    if not isinstance(ledger, dict):
        raise LedgerError("candidate_ledger must be an object")
    retained_raw = ledger.get("retained")
    ignored_raw = ledger.get("ignored")
    if not isinstance(retained_raw, list) or not isinstance(ignored_raw, list):
        raise LedgerError("candidate retained/ignored entries must be lists")

    retained: dict[str, dict[str, Any]] = {}
    ignored: dict[str, dict[str, Any]] = {}
    for raw, target in ((item, retained) for item in retained_raw):
        if not isinstance(raw, dict):
            raise LedgerError("retained candidate entries must be objects")
        candidate = _candidate_from_data(raw)
        if candidate.candidate_id in target:
            raise LedgerError(f"duplicate retained candidate ID: {candidate.candidate_id}")
        target[candidate.candidate_id] = raw
    for raw, target in ((item, ignored) for item in ignored_raw):
        if not isinstance(raw, dict):
            raise LedgerError("ignored candidate entries must be objects")
        candidate = _candidate_from_data(raw)
        if candidate.candidate_id in target:
            raise LedgerError(f"duplicate ignored candidate ID: {candidate.candidate_id}")
        target[candidate.candidate_id] = raw

    retained_ids = set(retained)
    ignored_ids = set(ignored)
    if retained_ids & ignored_ids:
        raise LedgerError("candidate retained/ignored sets overlap")
    if set(generated) != retained_ids | ignored_ids:
        raise LedgerError(
            "candidate partition mismatch: "
            f"missing={sorted(set(generated) - retained_ids - ignored_ids)}, "
            f"not_exported={sorted((retained_ids | ignored_ids) - set(generated))}"
        )

    docs_by_version = {item.version: item for item in documents}
    raw_deleted = _raw_deleted_lines(documents)
    covered: set[tuple[str, int]] = set()
    for candidate in generated.values():
        stored = retained.get(candidate.candidate_id) or ignored.get(candidate.candidate_id)
        if stored is None:
            raise LedgerError(f"candidate omitted from partition: {candidate.candidate_id}")
        stored_candidate = _candidate_from_data(stored)
        if stored_candidate != candidate:
            raise LedgerError(f"candidate data drift: {candidate.candidate_id}")
        covered.update(
            (candidate.old_version, line_number)
            for line_number in stored_candidate.old_line_numbers
        )

    if raw_deleted != covered:
        raise LedgerError(f"raw deletion coverage mismatch: {sorted(raw_deleted - covered)}")

    for candidate_id, raw in ignored.items():
        candidate = generated[candidate_id]
        category = raw.get("category")
        if category not in IGNORED_CATEGORIES:
            raise LedgerError(f"ignored candidate {candidate_id} has invalid category {category}")
        old_doc = docs_by_version[candidate.old_version]
        excluded = _excluded_lines(old_doc)
        if category == "OUT_OF_SCOPE":
            if not candidate.old_line_numbers or not candidate.old_line_numbers <= excluded:
                raise LedgerError(f"OUT_OF_SCOPE span escapes exemption: {candidate_id}")
        elif category == "FORMAT_ONLY":
            if normalize("\n".join(candidate.old_lines)) != normalize(
                "\n".join(candidate.new_lines)
            ):
                raise LedgerError(f"FORMAT_ONLY normalization differs: {candidate_id}")
        elif category == "SUBSUMED":
            retained_id = raw.get("subsumed_by")
            if not isinstance(retained_id, str) or retained_id not in retained:
                raise LedgerError(f"SUBSUMED candidate has no retained source: {candidate_id}")
            retained_pattern = str(retained[retained_id]["pattern"])
            if re.search(retained_pattern, normalize("\n".join(candidate.old_lines))) is None:
                raise LedgerError(f"SUBSUMED predicate failed: {candidate_id}")
        print(
            f"DIFF_CANDIDATE | {candidate_id} | IGNORED:{category} | "
            f"span={candidate.old_start}-{candidate.old_end}"
        )

    expected_matches = data.get("expected_matches")
    if not isinstance(expected_matches, dict):
        raise LedgerError("expected_matches must be an object")
    target_doc = documents[-1]
    for candidate_id, raw in retained.items():
        candidate = generated[candidate_id]
        old_doc = docs_by_version[candidate.old_version]
        replay = _matches_by_section(candidate.pattern, old_doc)
        replay_count = sum(replay.values())
        if replay_count < 1:
            raise LedgerError(f"retained candidate has no checked-scope replay hit: {candidate_id}")
        if raw.get("replay_count") != replay_count:
            recorded_count = raw.get("replay_count")
            raise LedgerError(
                f"replay count drift for {candidate_id}: {recorded_count} != {replay_count}"
            )
        if raw.get("replay_sections") != replay:
            raise LedgerError(
                f"replay section drift for {candidate_id}: {raw.get('replay_sections')} != {replay}"
            )
        actual = _matches_by_section(candidate.pattern, target_doc)
        expected = expected_matches.get(candidate_id)
        if expected != actual:
            raise LedgerError(
                f"RESIDUAL_DRIFT({candidate_id}): expected={expected}, actual={actual}"
            )
        print(f"DRIFT_PATTERN | {candidate_id} | OK | replay={replay} | expected={actual}")
    if set(expected_matches) != retained_ids:
        raise LedgerError("expected match IDs do not equal retained candidate IDs")
    return len(generated), len(retained), len(ignored)

def _check_bindings(
    data: dict[str, Any], documents: tuple[VersionDoc, ...], target: VersionDoc
) -> tuple[int, tuple[str, ...]]:
    bindings, exported = _check_binding_inventory(data, documents)
    drifts: list[str] = []
    for binding_id, binding in sorted(bindings.items()):
        passed, detail = _evaluate_binding(binding, target)
        print(f"BINDING | {binding_id} | {'OK' if passed else 'DRIFT'} | {detail}")
        if not passed:
            drifts.append(binding_id)
    if drifts:
        raise LedgerError(f"BINDING_DRIFT={drifts}")
    return len(bindings), exported

def _admission(
    data_path: Path, repo_root: Path, *, required_snapshot: str | None = None
) -> int:
    data = _load_json(data_path)
    documents = _load_versions(data, repo_root)
    bindings, _ = _check_binding_inventory(data, documents)
    admission = data.get("admission")
    if not isinstance(admission, dict):
        raise LedgerError("admission must be an object")
    snapshot_version = admission.get("snapshot_version")
    required_raw = admission.get("required")
    minimum_drift_count = admission.get("minimum_drift_count", 1)
    if not isinstance(snapshot_version, str):
        raise LedgerError("admission.snapshot_version must be a string")
    if required_snapshot is not None and snapshot_version != required_snapshot:
        raise LedgerError(
            f"admission snapshot is v{snapshot_version}, not compatibility alias "
            f"v{required_snapshot}"
        )
    if not isinstance(required_raw, list) or not all(
        isinstance(item, str) for item in required_raw
    ):
        raise LedgerError("admission.required must be a list of binding IDs")
    if not isinstance(minimum_drift_count, int) or minimum_drift_count < 1:
        raise LedgerError("admission.minimum_drift_count must be a positive integer")
    snapshot = next(
        (item for item in documents if item.version == snapshot_version), None
    )
    if snapshot is None:
        raise LedgerError(f"admission snapshot v{snapshot_version} is not in version_sequence")
    drifts: list[str] = []
    for binding_id, binding in sorted(bindings.items()):
        passed, detail = _evaluate_binding(binding, snapshot)
        if not passed:
            drifts.append(binding_id)
            print(f"BINDING_DRIFT | {binding_id} | {detail}")
    required = set(required_raw)
    unknown_required = required - set(bindings)
    if unknown_required:
        raise LedgerError(f"admission requires unknown bindings: {sorted(unknown_required)}")
    if len(drifts) < minimum_drift_count or not required <= set(drifts):
        raise LedgerError(
            "admission falsification incomplete: "
            f"minimum={minimum_drift_count}, required={sorted(required)}, actual={drifts}"
        )
    label = "ADMISSION_V19" if required_snapshot == "1.9" else "ADMISSION"
    print(
        f"{label} | snapshot=v{snapshot_version} | BINDING_DRIFT={len(drifts)} | "
        f"required_known={len(required)} | RED_AS_EXPECTED"
    )
    return 1

def _negative_binding(data_path: Path, repo_root: Path, binding_id: str) -> int:
    data = _load_json(data_path)
    documents = _load_versions(data, repo_root)
    bindings, _ = _check_binding_inventory(data, documents)
    binding = bindings.get(binding_id)
    if binding is None:
        raise LedgerError(f"unknown binding: {binding_id}")
    target = _target_doc(data, repo_root)
    dod_by_id = {item.item_id: item for item in _dod_items(target)}
    definition_text = _section_text(target, str(binding["definition_section"]))
    reference_text = _extract_reference_text(binding, target, dod_by_id)
    passed, detail = _evaluate_binding_text(binding, definition_text, reference_text)
    if not passed:
        raise LedgerError(f"baseline binding is not green: {binding_id}: {detail}")

    predicate = binding.get("predicate")
    outcomes: list[tuple[str, bool]] = []
    if predicate == "TEXT_CONTAINS":
        for index, snippet in enumerate(binding["canonical_snippets"], 1):
            normalized_reference = normalize(reference_text)
            mutant = normalized_reference.replace(normalize(snippet), "")
            mutant_passed, _ = _evaluate_binding_text(binding, definition_text, mutant)
            outcomes.append((f"delete_snippet_{index}", mutant_passed))
    elif predicate == "COUNT_EQUAL":
        compact = re.sub(r"\s+", "", normalize(reference_text))
        match = NUMBER_RE.search(compact)
        if match is None:
            raise LedgerError(f"COUNT_EQUAL fixture cannot find numeral: {binding_id}")
        deleted = compact[: match.start(1)] + compact[match.end(1) :]
        changed = compact[: match.start(1)] + "99" + compact[match.end(1) :]
        outcomes.append(
            ("delete_numeral", _evaluate_binding_text(binding, definition_text, deleted)[0])
        )
        outcomes.append(
            ("change_count", _evaluate_binding_text(binding, definition_text, changed)[0])
        )
        covered = binding.get("covered_mutation")
        outside = binding.get("outside_mutation")
        if not isinstance(covered, str) or not isinstance(outside, str):
            raise LedgerError(f"COUNT_EQUAL binding {binding_id} lacks selector mutations")
        outcomes.append(
            (
                "definition_covered_add",
                _evaluate_binding_text(binding, definition_text + "\n" + covered, reference_text)[
                    0
                ],
            )
        )
        outside_passed = _evaluate_binding_text(
            binding, definition_text + "\n" + outside, reference_text
        )[0]
        print(
            f"NEGATIVE_BINDING | {binding_id} | "
            f"selector_outside_interference_exit={0 if outside_passed else 1}"
        )
        if not outside_passed:
            return 2
    elif predicate == "REF_ONLY":
        snippet = str(binding["canonical_snippets"][0])
        outcomes.append(
            (
                "inject_restated_snippet",
                _evaluate_binding_text(binding, definition_text, reference_text + "\n" + snippet)[
                    0
                ],
            )
        )
        target_ref = str(binding["definition_section"])
        wrong_reference_sections = _string_list(data, "negative_reference_sections")
        available_sections = set(_section_spans(target.lines))
        wrong_target = next(
            (
                section
                for section in wrong_reference_sections
                if section != target_ref and section in available_sections
            ),
            None,
        )
        if wrong_target is None:
            raise LedgerError(
                f"REF_ONLY fixture has no configured existing wrong section: {binding_id}"
            )
        wrong = reference_text.replace(target_ref, wrong_target)
        outcomes.append(
            (
                "point_to_existing_wrong_section",
                _evaluate_binding_text(binding, definition_text, wrong)[0],
            )
        )
    else:
        raise LedgerError(f"unsupported negative fixture predicate: {predicate}")

    unexpected_green = [name for name, mutant_passed in outcomes if mutant_passed]
    for name, mutant_passed in outcomes:
        print(f"NEGATIVE_BINDING | {binding_id} | {name} | gate_exit={0 if mutant_passed else 1}")
    if unexpected_green:
        print(f"NEGATIVE_BINDING_INVALID | {binding_id} | unexpected_green={unexpected_green}")
        return 2
    return 1

def main(argv: list[str] | None = None) -> int:
    args = _parse_args(sys.argv[1:] if argv is None else argv)
    repo_root = _repo_root()
    data_path = args.data.resolve()
    try:
        if args.action == "bootstrap":
            return _bootstrap(data_path, repo_root)
        if args.action == "check":
            return _run_check(data_path, repo_root)
        if args.action == "admission":
            return _admission(data_path, repo_root)
        if args.action == "admission-v19":
            return _admission(data_path, repo_root, required_snapshot="1.9")
        if args.action == "negative-binding":
            if args.value is None:
                raise LedgerError("negative-binding requires a binding ID")
            return _negative_binding(data_path, repo_root, args.value)
        if args.action == "negative-fixture":
            if args.value != "out-of-scope-misuse":
                raise LedgerError("negative-fixture requires out-of-scope-misuse")
            return _negative_out_of_scope(data_path, repo_root)
    except (LedgerError, OSError) as exc:
        print(f"DESIGN_DRIFT_LEDGER_ERROR: {exc}", file=sys.stderr)
        return 2
    raise AssertionError(f"unhandled action: {args.action}")

def _module_name(relative: str) -> str:
    path = Path(relative)
    parts = list(path.with_suffix("").parts)
    if parts[-1] == "__init__":
        parts.pop()
    return ".".join(parts)

def _top_level_symbols(tree: ast.Module) -> frozenset[str]:
    names: set[str] = set()
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            names.add(node.name)
        elif isinstance(node, (ast.Assign, ast.AnnAssign)):
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            for target in targets:
                if isinstance(target, ast.Name):
                    names.add(target.id)
    return frozenset(names)

def _load_sources(scripts_root: Path) -> tuple[SourceFile, ...]:
    sources: list[SourceFile] = []
    for path in sorted(scripts_root.rglob("*.py")):
        relative_path = path.relative_to(scripts_root)
        if "__pycache__" in relative_path.parts or "release-v1.4.0" in relative_path.parts:
            continue
        if "test" in relative_path.parts or "tests" in relative_path.parts:
            continue
        text = path.read_text(encoding="utf-8")
        tree = ast.parse(text, filename=str(path))
        relative = relative_path.as_posix()
        sources.append(
            SourceFile(
                path=path,
                relative=relative,
                module=_module_name(relative),
                text=text,
                tree=tree,
                top_level=_top_level_symbols(tree),
            )
        )
    return tuple(sources)

def _definition_line(source: SourceFile, symbol: str) -> int | None:
    for node in source.tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            if node.name == symbol:
                return node.lineno
        elif isinstance(node, ast.Assign):
            if any(isinstance(target, ast.Name) and target.id == symbol for target in node.targets):
                return node.lineno
        elif isinstance(node, ast.AnnAssign):
            if isinstance(node.target, ast.Name) and node.target.id == symbol:
                return node.lineno
    return None

def __init__(self, symbol: str) -> None:
        self.symbol = symbol
        self.lines: set[int] = set()

def visit_Name(self, node: ast.Name) -> None:
        if isinstance(node.ctx, ast.Load) and node.id == self.symbol:
            self.lines.add(node.lineno)

def visit_Attribute(self, node: ast.Attribute) -> None:
        if isinstance(node.ctx, ast.Load) and node.attr == self.symbol:
            self.lines.add(node.lineno)
        self.generic_visit(node)

def __init__(self, symbol: str) -> None:
        self.symbol = symbol
        self.scopes: dict[str, set[int]] = {}
        self._stack: list[str] = []

def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
        prefix = f"{self._stack[-1]}." if self._stack else ""
        self._enter(prefix + node.name, node)

def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef) -> None:
        prefix = f"{self._stack[-1]}." if self._stack else ""
        self._enter(prefix + node.name, node)

def _record(self, node: ast.AST) -> None:
        if self._stack:
            line = getattr(node, "lineno", None)
            if isinstance(line, int):
                self.scopes.setdefault(self._stack[-1], set()).add(line)

def visit_Name(self, node: ast.Name) -> None:
        if isinstance(node.ctx, ast.Load) and node.id == self.symbol:
            self._record(node)

def visit_Attribute(self, node: ast.Attribute) -> None:
        if isinstance(node.ctx, ast.Load) and node.attr == self.symbol:
            self._record(node)
        self.generic_visit(node)

def _expr_uses_names(expr: ast.AST, names: set[str]) -> bool:
    return any(
        (isinstance(node, ast.Name) and node.id in names)
        or (isinstance(node, ast.Attribute) and node.attr in names)
        for node in ast.walk(expr)
    )

def _marker_accesses(source: SourceFile, symbol: str) -> tuple[tuple[str, ...], tuple[str, ...]]:
    reads: set[str] = set()
    writes: set[str] = set()
    read_methods = {"exists", "is_file", "read_bytes", "read_text", "stat"}
    write_methods = {"rename", "replace", "touch", "unlink", "write_bytes", "write_text"}

    for node in ast.walk(source.tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        scope = node.name
        tainted = {symbol}
        if symbol == "MARKER_FILENAME" and scope == "_verify_cleanup_handle":
            tainted.add("marker_path")
        changed = True
        while changed:
            changed = False
            for child in ast.walk(node):
                if not isinstance(child, (ast.Assign, ast.AnnAssign)):
                    continue
                value = child.value
                if value is None or not _expr_uses_names(value, tainted):
                    continue
                targets = child.targets if isinstance(child, ast.Assign) else [child.target]
                for target in targets:
                    if isinstance(target, ast.Name) and target.id not in tainted:
                        tainted.add(target.id)
                        changed = True
        for child in ast.walk(node):
            if not isinstance(child, ast.Call):
                continue
            if isinstance(child.func, ast.Name) and child.func.id == "_read_marker":
                if child.args and _expr_uses_names(child.args[0], tainted):
                    reads.add(f"{scope}@{child.lineno}")
            if not isinstance(child.func, ast.Attribute):
                continue
            if not _expr_uses_names(child.func.value, tainted):
                continue
            if child.func.attr in read_methods:
                reads.add(f"{scope}@{child.lineno}")
            if child.func.attr in write_methods:
                writes.add(f"{scope}@{child.lineno}")

    return tuple(sorted(reads)), tuple(sorted(writes))

def _raw_evidence(sources: tuple[SourceFile, ...], spec: SymbolSpec) -> tuple[str, ...]:
    pattern = re.compile(rf"\b{re.escape(spec.name)}\b")
    evidence: list[str] = []
    for source in sources:
        for line_number, line in enumerate(source.text.splitlines(), start=1):
            if pattern.search(line):
                evidence.append(f"{source.relative}:{line_number}:{line.strip()}")
    return tuple(evidence)

def _import_from_module(source: SourceFile, node: ast.ImportFrom) -> str | None:
    if node.module is None:
        return None
    if node.level == 0:
        return node.module

    package_parts = source.module.split(".")
    if source.path.name != "__init__.py":
        package_parts.pop()
    parent_count = node.level - 1
    if parent_count > len(package_parts):
        return None
    base_parts = package_parts[: len(package_parts) - parent_count]
    return ".".join((*base_parts, *node.module.split(".")))

def _module_scope_import_bindings(source: SourceFile) -> tuple[_ImportBinding, ...]:
    bindings: list[_ImportBinding] = []
    # This deliberately covers only named module-scope ImportFrom bindings.
    # It does not cover ``import X; X.S`` attribute access, ImportFrom nodes
    # nested inside functions/classes, or ``from X import *``. Those known
    # limitations are intentional for this contract; do not "fix" them
    # without a new attribution design and matching fixtures.
    for node in source.tree.body:
        if not isinstance(node, ast.ImportFrom):
            continue
        source_module = _import_from_module(source, node)
        if source_module is None:
            continue
        for alias in node.names:
            if alias.name == "*":
                continue
            bindings.append(
                _ImportBinding(
                    source_module=source_module,
                    source_symbol=alias.name,
                    local_name=alias.asname or alias.name,
                )
            )
    return tuple(bindings)

def _resolve_import_origin(
    binding: _ImportBinding,
    sources_by_module: dict[str, SourceFile],
    bindings_by_module: dict[str, tuple[_ImportBinding, ...]],
    *,
    seen: frozenset[tuple[str, str]] = frozenset(),
) -> tuple[str, str]:
    key = (binding.source_module, binding.source_symbol)
    if key in seen:
        return key
    source = sources_by_module.get(binding.source_module)
    if source is None or binding.source_symbol in source.top_level:
        return key

    reexports = tuple(
        candidate
        for candidate in bindings_by_module.get(binding.source_module, ())
        if candidate.local_name == binding.source_symbol
    )
    if len(reexports) != 1:
        return key
    return _resolve_import_origin(
        reexports[0],
        sources_by_module,
        bindings_by_module,
        seen=seen | {key},
    )

def _legacy_actual_consumers(
    sources: tuple[SourceFile, ...],
    definition_source: SourceFile,
    symbol: str,
) -> tuple[str, ...]:
    consumers: set[str] = set()
    for source in sources:
        if source.relative == definition_source.relative:
            continue
        if symbol in source.top_level:
            # Known limit: this twin guard intentionally skips a module that
            # shadows a name even if it also imports the original definition.
            # That over-skip is deliberate; do not "fix" it without a new
            # attribution design and a fixture for the ambiguous import.
            continue
        visitor = _ReferenceVisitor(symbol)
        visitor.visit(source.tree)
        if visitor.lines:
            consumers.add(source.module)
    return tuple(sorted(consumers))

def _actual_consumers(
    sources: tuple[SourceFile, ...],
    definition_source: SourceFile,
    symbol: str,
) -> tuple[str, ...]:
    consumers: set[str] = set()
    sources_by_module = {source.module: source for source in sources}
    bindings_by_module = {
        source.module: _module_scope_import_bindings(source) for source in sources
    }
    target = (definition_source.module, symbol)

    for source in sources:
        if source.relative == definition_source.relative:
            continue
        if symbol in source.top_level:
            # Known limit: this twin guard intentionally skips a module that
            # shadows a name even if it also imports the original definition.
            # That over-skip is deliberate; do not "fix" it without a new
            # attribution design and a fixture for the ambiguous import.
            continue

        bindings_by_local_name = {
            binding.local_name: binding
            for binding in bindings_by_module[source.module]
        }
        origins_by_local_name = {
            local_name: _resolve_import_origin(
                binding,
                sources_by_module,
                bindings_by_module,
            )
            for local_name, binding in bindings_by_local_name.items()
        }
        matched = False
        for local_name, origin in origins_by_local_name.items():
            if origin != target:
                continue
            visitor = _ReferenceVisitor(local_name)
            visitor.visit(source.tree)
            if visitor.lines:
                matched = True
                break

        # Preserve name-only attribution for code without a named ImportFrom
        # binding. When the name is bound, its measured origin is authoritative.
        if not matched and symbol not in origins_by_local_name:
            visitor = _ReferenceVisitor(symbol)
            visitor.visit(source.tree)
            matched = bool(visitor.lines)
        if matched:
            consumers.add(source.module)
    return tuple(sorted(consumers))

def _internal_references(source: SourceFile, symbol: str) -> tuple[str, ...]:
    visitor = _ScopedReferenceVisitor(symbol)
    visitor.visit(source.tree)
    return tuple(
        f"{scope}@{','.join(str(line) for line in sorted(lines))}"
        for scope, lines in sorted(visitor.scopes.items())
        if scope != symbol
    )

def _type_closure_reasons(
    sources: tuple[SourceFile, ...],
    source: SourceFile,
    symbol: str,
) -> tuple[str, ...]:
    """Reject shared/types dataclass fields that reference higher repo types."""

    repo_types: dict[str, set[str]] = {}
    for candidate in sources:
        for node in candidate.tree.body:
            if isinstance(node, ast.ClassDef):
                repo_types.setdefault(node.name, set()).add(candidate.relative)

    class_node = next(
        (
            node
            for node in source.tree.body
            if isinstance(node, ast.ClassDef) and node.name == symbol
        ),
        None,
    )
    if class_node is None:
        return ()

    reasons: list[str] = []
    for field in class_node.body:
        if not isinstance(field, ast.AnnAssign) or not isinstance(field.target, ast.Name):
            continue
        referenced_names = {
            node.id for node in ast.walk(field.annotation) if isinstance(node, ast.Name)
        }
        for referenced in sorted(referenced_names):
            external_definitions = repo_types.get(referenced, set()) - {source.relative}
            if external_definitions:
                locations = ",".join(sorted(external_definitions))
                reasons.append(
                    "type-closure escapes L-1: "
                    f"{symbol}.{field.target.id} references {referenced} from {locations}"
                )
    return tuple(reasons)

def _skill_layer_reasons(
    owner: str,
    consumers: set[str],
    *,
    registered_skill_roots: dict[str, str] = REGISTERED_SKILL_ROOTS,
) -> tuple[str, ...]:
    """Enforce root-layers ownership for a registered skill API.

    The owner module itself is an internal consumer, not a cross-boundary
    dependency. Every other consumer must be in the higher ci_triage layer.
    A shared consumer is an uplink; a peer skill consumer is a same-layer edge.
    """

    if not owner.startswith("skill/"):
        return ()
    owner_root = registered_skill_roots.get(owner)
    if owner_root is None:
        return (f"skill owner {owner} is not registered in root-layers",)

    known_skill_roots = set(registered_skill_roots.values())
    reasons: list[str] = []
    for consumer in sorted(consumers):
        consumer_root = _module_root(consumer)
        if consumer_root == owner_root:
            continue
        if consumer_root == "ci_triage":
            continue
        if consumer_root == "tizen_ci_shared":
            reasons.append(
                f"skill owner {owner} is above shared consumer {consumer}"
            )
        elif consumer_root in known_skill_roots:
            reasons.append(
                f"skill owner {owner} has same-layer skill consumer {consumer}"
            )
        else:
            reasons.append(
                f"consumer {consumer} is outside registered root-layers "
                f"{ROOT_LAYERS_HIGH_TO_LOW}"
            )
    return tuple(reasons)

def _audit_one(
    sources: tuple[SourceFile, ...],
    specs_by_key: dict[SpecKey, SymbolSpec],
    spec: SymbolSpec,
    *,
    consumer_finder: ConsumerFinder = _actual_consumers,
) -> AuditResult:
    by_relative = {source.relative: source for source in sources}
    evidence = _raw_evidence(sources, spec)
    if spec.status == "to-be-created":
        planned_reasons: tuple[str, ...]
        if spec.expected_owner is None:
            planned_reasons = ("to-be-created expected_owner must be declared",)
        elif spec.owner == spec.expected_owner:
            planned_reasons = ()
        else:
            planned_reasons = (
                f"to-be-created owner must be {spec.expected_owner}",
            )
        return AuditResult(
            spec,
            "TO_BE_CREATED",
            (),
            (),
            (),
            (),
            planned_reasons,
            evidence,
        )
    if spec.status != "existing":
        return AuditResult(
            spec,
            "INVALID_STATUS",
            (),
            (),
            (),
            (),
            (f"unsupported inventory status {spec.status}",),
            evidence,
        )

    source = by_relative.get(spec.definition)
    if source is None:
        return AuditResult(
            spec,
            "NOT_FOUND",
            (),
            (),
            (),
            (),
            (f"definition file {spec.definition} not found",),
            evidence,
        )

    line = _definition_line(source, spec.name)
    if line is None:
        return AuditResult(
            spec,
            "NOT_FOUND",
            (),
            (),
            (),
            (),
            (f"definition {spec.name} not found in {spec.definition}",),
            evidence,
        )

    consumers = consumer_finder(sources, source, spec.name)
    internal = _internal_references(source, spec.name)
    marker_reads: tuple[str, ...] = ()
    marker_writes: tuple[str, ...] = ()
    if spec.name in {"MARKER_FILENAME", "PROTECTED_FILENAME"}:
        marker_reads, marker_writes = _marker_accesses(source, spec.name)

    reasons: list[str] = []
    if spec.owner.startswith("UNRESOLVED"):
        reasons.append(f"declared owner is unresolved: {spec.owner}")

    if spec.owner.startswith("skill/"):
        skill_root = REGISTERED_SKILL_ROOTS.get(spec.owner)
        definition_root = Path(spec.definition).parts[0]
        if skill_root is None:
            reasons.append(
                f"skill owner {spec.owner} is not registered in root-layers"
            )
        elif definition_root != skill_root:
            reasons.append(
                "skill-owned symbol defined outside its registered root: "
                f"{spec.definition} is not under {skill_root}"
            )

    declared_consumers = set(spec.declared_consumers)
    measured_consumers = set(consumers)
    for missing in sorted(declared_consumers - measured_consumers):
        reasons.append(f"declared consumer {missing} not found")
    for extra in sorted(measured_consumers - declared_consumers):
        reasons.append(f"undeclared consumer {extra}")

    if spec.declared_internal:
        actual_internal = _scope_names(internal)
        declared_internal = set(spec.declared_internal)
        for missing in sorted(declared_internal - actual_internal):
            reasons.append(f"declared internal consumer {missing} not found")
        for extra in sorted(actual_internal - declared_internal):
            reasons.append(f"undeclared internal consumer {extra}")

    # Ownership is checked against the same ci_triage > registered skills >
    # tizen_ci_shared order as .importlinter's root-layers contract. Shared is
    # the bottom layer, so all consumer combinations remain valid. A skill API
    # may have one or many orchestration consumers, but no shared or peer-skill
    # consumer. Non-skill ci_triage owners retain the original single-consumer
    # attribution check.
    reasons.extend(_skill_layer_reasons(spec.owner, measured_consumers))
    if len(measured_consumers) > 1 and not (
        spec.owner.startswith("shared") or spec.owner.startswith("skill/")
    ):
        reasons.append("multiple consumers require lower-layer ownership")
    elif len(measured_consumers) == 1 and not (
        spec.owner.startswith("shared") or spec.owner.startswith("UNRESOLVED")
        or spec.owner.startswith("skill/")
    ):
        consumer = next(iter(measured_consumers))
        consumer_owner = MODULE_OWNERS.get(consumer)
        if consumer_owner is not None and consumer_owner != spec.owner:
            reasons.append(
                f"single consumer {consumer} belongs to {consumer_owner}, "
                f"not declared owner {spec.owner}"
            )
    if spec.format_authority and not spec.owner.startswith("shared"):
        reasons.append("format authority requires shared ownership")

    if spec.owner == "shared/types":
        reasons.extend(_type_closure_reasons(sources, source, spec.name))

    if not (spec.owner.startswith("shared") or spec.owner.startswith("UNRESOLVED")):
        for scope in sorted(_scope_names(internal)):
            caller_name = scope.split(".", 1)[0]
            caller_spec = specs_by_key.get((spec.definition, caller_name))
            if caller_spec is None:
                continue
            caller_owner = caller_spec.owner
            if caller_owner.startswith("shared") or caller_owner.startswith("UNRESOLVED"):
                continue
            if caller_owner != spec.owner:
                reasons.append(
                    f"cross-boundary internal access from {scope} "
                    f"owned by {caller_owner}"
                )

    return AuditResult(
        spec=spec,
        definition=f"{spec.definition}:{line}",
        consumers=consumers,
        internal=internal,
        marker_reads=marker_reads,
        marker_writes=marker_writes,
        reasons=tuple(reasons),
        evidence=evidence,
    )

def _public_surface(source: SourceFile) -> set[str]:
    result: set[str] = set()
    for node in source.tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            result.add(node.name)
        elif isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and re.fullmatch(r"[A-Z_][A-Z0-9_]*", target.id):
                    result.add(target.id)
        elif isinstance(node, ast.AnnAssign):
            target = node.target
            if isinstance(target, ast.Name) and re.fullmatch(r"[A-Z_][A-Z0-9_]*", target.id):
                result.add(target.id)
    return result

def _module_consumers(
    sources: tuple[SourceFile, ...],
    *,
    import_root: str,
) -> tuple[str, ...]:
    consumers: set[str] = set()
    for source in sources:
        if source.module == import_root or source.module.startswith(import_root + "."):
            continue
        for node in ast.walk(source.tree):
            if isinstance(node, ast.Import):
                matched = any(
                    alias.name == import_root or alias.name.startswith(import_root + ".")
                    for alias in node.names
                )
            elif isinstance(node, ast.ImportFrom) and node.module is not None:
                matched = node.module == import_root or node.module.startswith(
                    import_root + "."
                )
            else:
                matched = False
            if matched:
                consumers.add(source.module)
                break
    return tuple(sorted(consumers))

def _pure_reexport_reasons(source: SourceFile, import_root: str) -> tuple[str, ...]:
    reasons: list[str] = []
    for node in source.tree.body:
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant):
            if isinstance(node.value.value, str):
                continue
        if isinstance(node, ast.ImportFrom) and node.module == import_root:
            if all(alias.asname == alias.name for alias in node.names):
                continue
        reasons.append(
            f"legacy pure-shim contains non-re-export {type(node).__name__} "
            f"at {source.relative}:{getattr(node, 'lineno', '?')}"
        )
    return tuple(reasons)

def _audit_module_scope(
    repo_root: Path,
    sources: tuple[SourceFile, ...],
    symbol_specs: tuple[SymbolSpec, ...],
    spec: ModuleScopeSpec,
) -> ModuleScopeResult:
    by_relative = {source.relative: source for source in sources}
    reasons: list[str] = []
    source = by_relative.get(spec.definition)

    if not spec.definition.startswith("tizen_ci_shared/"):
        reasons.append("module-scope definition is outside tizen_ci_shared")
    if source is None:
        reasons.append(f"module-scope definition file {spec.definition} not found")
        covered_symbols: tuple[str, ...] = ()
    else:
        covered_symbols = tuple(sorted(_public_surface(source)))
        if len(covered_symbols) != spec.expected_top_level_count:
            reasons.append(
                "module-scope top-level count drift: "
                f"expected {spec.expected_top_level_count}, measured "
                f"{len(covered_symbols)}"
            )

    overlaps = sorted(
        symbol_spec.name
        for symbol_spec in symbol_specs
        if symbol_spec.definition == spec.definition
    )
    if overlaps:
        reasons.append(
            "module-scope conflicts with per-symbol inventory: " + ",".join(overlaps)
        )

    legacy_path = repo_root / spec.legacy_path
    if spec.legacy_mode == "deleted":
        tracked = subprocess.run(
            ["git", "ls-files", "--error-unmatch", spec.legacy_path],
            cwd=repo_root,
            check=False,
            capture_output=True,
            text=True,
        )
        if tracked.returncode == 0:
            reasons.append(f"legacy module remains tracked: {spec.legacy_path}")
        elif tracked.returncode != 1:
            detail = tracked.stderr.strip() or f"exit {tracked.returncode}"
            reasons.append(f"git ls-files failed for {spec.legacy_path}: {detail}")
        if legacy_path.exists():
            reasons.append(f"legacy module remains on disk: {spec.legacy_path}")
    elif spec.legacy_mode == "pure-shim":
        legacy_source = next(
            (candidate for candidate in sources if candidate.path == legacy_path),
            None,
        )
        if legacy_source is None:
            reasons.append(f"legacy shim {spec.legacy_path} not found")
        else:
            reasons.extend(_pure_reexport_reasons(legacy_source, spec.import_root))
    else:
        reasons.append(f"unsupported module-scope legacy mode {spec.legacy_mode}")

    consumers = _module_consumers(sources, import_root=spec.import_root)
    return ModuleScopeResult(spec, covered_symbols, consumers, tuple(reasons))

def _declared_text(spec: SymbolSpec) -> str:
    consumers = ",".join(spec.declared_consumers) or "-"
    internal = ",".join(spec.declared_internal) or "-"
    expected_owner = spec.expected_owner or "-"
    return (
        f"sections={'+'.join(spec.sections)}; status={spec.status}; owner={spec.owner}; "
        f"expected_owner={expected_owner}; consumers=[{consumers}]; "
        f"internal=[{internal}]"
    )

def _fixture_sources(repo_root: Path) -> tuple[SourceFile, ...]:
    roots = (
        repo_root / "tizen-ci-triage/scripts",
        repo_root / "tizen-ci-shared/scripts",
        repo_root / "tizen-convergence-judge/scripts",
        repo_root / "tizen-qb-discover/scripts",
        repo_root / "tizen-gerrit-fetch/scripts",
        repo_root / "tizen-build-verify/scripts",
        repo_root / "tizen-gerrit-submit/scripts",
        repo_root / "tizen-triage-report/scripts",
    )
    return tuple(
        source
        for root in roots
        if root.is_dir()
        for source in _load_sources(root)
    )

def _legacy_convergence_specs(
    specs: tuple[SymbolSpec, ...],
) -> tuple[SymbolSpec, ...]:
    legacy_consumers = {
        "_primary_fingerprint": ("ci_triage.campaign_state",),
        "_error_count": ("ci_triage.campaign_state",),
        "primary_fingerprint": (),
        "error_count": (),
    }
    return tuple(
        replace(spec, declared_consumers=legacy_consumers[spec.name])
        if spec.definition == SKILL_CONVERGENCE and spec.name in legacy_consumers
        else spec
        for spec in specs
    )

def _run_key_fixture(name: str) -> int:
    repo_root = Path(__file__).resolve().parents[3]
    sources = _fixture_sources(repo_root)
    source_spec, report_spec = _twin_specs(repo_root)
    specs = (source_spec,) if name == "source-twin-only" else (source_spec, report_spec)
    if name not in {"source-twin-only", "twin-both-binary-key"}:
        print(f"unknown key fixture: {name}")
        return 2
    specs_by_key = {(spec.definition, spec.name): spec for spec in specs}
    registered_here = (
        source_spec.owner not in REGISTERED_SKILL_ROOTS
        and source_spec.owner.startswith("skill/")
    )
    if registered_here:
        REGISTERED_SKILL_ROOTS[source_spec.owner] = "tizen_qb_discover"
    try:
        results = tuple(
            _audit_one(sources, specs_by_key, spec) for spec in specs
        )
    finally:
        if registered_here:
            del REGISTERED_SKILL_ROOTS[source_spec.owner]
    for result in results:
        print(
            f"KEY_FIXTURE | {name} | {result.spec.definition}:"
            f"{result.spec.name} | consumers={result.consumers} | "
            f"internal={result.internal} | {result.verdict}"
        )
    return 1 if any(result.reasons for result in results) else 0

def _run_surface_fixture(name: str) -> int:
    if name != "mixed-case-alias":
        print(f"unknown surface fixture: {name}")
        return 2
    source = _synthetic_source(
        "fixture.surface",
        "KNOWN = object()\nMixedCaseAlias = object()\n",
    )
    audited = {"KNOWN"}
    unexpected = sorted(_top_level_symbols(source.tree) - audited)
    if unexpected == ["MixedCaseAlias"]:
        print(
            "SURFACE_FIXTURE | mixed-case-alias | MISMATCH: "
            "present in source but not audited: MixedCaseAlias"
        )
        return 1
    print(f"SURFACE_FIXTURE | mixed-case-alias | unexpected={unexpected} | OK")
    return 0

def main() -> int:
    if len(sys.argv) == 3 and sys.argv[1] == "--negative-fixture":
        return _run_negative_fixture(sys.argv[2])
    if len(sys.argv) == 3 and sys.argv[1] == "--key-fixture":
        return _run_key_fixture(sys.argv[2])
    if len(sys.argv) == 3 and sys.argv[1] == "--binding-fixture":
        return _run_binding_fixture(sys.argv[2])
    if len(sys.argv) == 3 and sys.argv[1] == "--surface-fixture":
        return _run_surface_fixture(sys.argv[2])
    if len(sys.argv) != 1:
        print(
            "usage: symbol_audit.py "
            "[--negative-fixture skill-owner-shared-consumer|"
            "skill-owner-peer-skill-consumer|duplicate-spec-root-mismatch|"
            "twin-both-name-only|import-binding-legacy-alias|"
            "--key-fixture source-twin-only|twin-both-binary-key|"
            "--binding-fixture regression-lock|aliased-import|"
            "same-name-import|planned-run-git|"
            "--surface-fixture mixed-case-alias]"
        )
