    repo_root = Path(__file__).resolve().parents[3]
    return run(repo_root)

def _mapping_contract_reasons(
    mapping: Mapping[RelocationTriplet, RelocationTriplet],
    *,
    expected: Mapping[RelocationTriplet, RelocationTriplet] | None = None,
) -> tuple[str, ...]:
    destinations = tuple(mapping.values())
    reasons: list[str] = []
    if len(set(destinations)) != len(destinations):
        reasons.append("RELOCATION_NOT_BIJECTIVE: duplicate destination")
    if expected is not None and dict(mapping) != dict(expected):
        missing_sources = sorted(
            source for source in expected if source not in mapping
        )
        for source in missing_sources:
            reasons.append(f"UNMAPPED_SOURCE: production mapping omits {source}")
        reasons.append(
            "RELOCATION_MAPPING_NOT_EXACT: production mapping must contain "
            f"exactly {len(expected)} frozen pairs"
        )
    return tuple(reasons)

def _relocation_output_reasons(
    entries: dict[SpecKey, BodyEntry],
    consumed_sources: frozenset[RelocationTriplet],
    produced_destinations: frozenset[RelocationTriplet],
    mapping: Mapping[RelocationTriplet, RelocationTriplet],
) -> tuple[str, ...]:
    reasons: list[str] = []
    for source_triplet, destination_triplet in mapping.items():
        if source_triplet in consumed_sources and source_triplet[:2] in entries:
            reasons.append(f"SOURCE_REMAINS: {source_triplet}")
        if (
            destination_triplet in produced_destinations
            and destination_triplet[:2] not in entries
        ):
            reasons.append(f"DESTINATION_NOT_PRODUCED: {destination_triplet}")
    return tuple(reasons)

def _cells(raw_line: str) -> list[str]:
    stripped = raw_line.strip()
    if not stripped.startswith("|") or not stripped.endswith("|"):
        raise TableParseError(f"not a Markdown table row: {raw_line}")
    return [cell.strip() for cell in stripped[1:-1].split("|")]

def _symbol_names(cell: str, raw_line: str) -> tuple[str, ...]:
    code_spans = re.findall(r"`([^`]+)`", cell)
    candidates = code_spans or [cell.strip()]
    names: list[str] = []
    for candidate in candidates:
        match = re.match(r"([A-Za-z_][A-Za-z0-9_]*)", candidate)
        if match is None:
            raise TableParseError(f"cannot parse symbol cell: {raw_line}")
        names.append(match.group(1))
    if not names:
        raise TableParseError(f"empty symbol cell: {raw_line}")
    return tuple(names)

def _owner(cell: str, raw_line: str) -> str:
    normalized = cell.replace("**", "").replace("`", "").strip()
    normalized = normalized.split("(", 1)[0].strip()
    if not re.fullmatch(r"[A-Za-z][A-Za-z0-9_/-]*", normalized):
        raise TableParseError(f"cannot parse owner cell: {raw_line}")
    return normalized

def _module(cell: str, raw_line: str) -> str:
    code_spans = re.findall(r"`([^`]+)`", cell)
    candidate = code_spans[0] if len(code_spans) == 1 else cell.strip()
    if not re.fullmatch(r"[A-Za-z0-9_./-]+\.py", candidate):
        raise TableParseError(f"cannot parse module cell: {raw_line}")
    return candidate

def _first_table(lines: list[str], heading_index: int) -> tuple[int, int]:
    start: int | None = None
    for index in range(heading_index + 1, len(lines)):
        stripped = lines[index].strip()
        if stripped.startswith("#"):
            break
        if stripped.startswith("|"):
            start = index
            break
    if start is None:
        raise TableParseError(f"no attribution table after: {lines[heading_index]}")

    end = start
    while end < len(lines) and lines[end].strip().startswith("|"):
        end += 1
    return start, end

def parse_design_tables(
    design_path: Path,
    *,
    section_headings: tuple[str, ...] = SECTION_HEADINGS,
) -> dict[SpecKey, BodyEntry]:
    """Parse selected frozen attribution tables, rejecting ambiguous rows."""

    lines = design_path.read_text(encoding="utf-8").splitlines()
    heading_indexes: dict[str, int] = {}
    for heading in section_headings:
        matches = [index for index, line in enumerate(lines) if line.startswith(heading)]
        if len(matches) != 1:
            raise TableParseError(
                f"expected one heading starting {heading!r}, found {len(matches)}"
            )
        heading_indexes[heading] = matches[0]

    entries: dict[SpecKey, BodyEntry] = {}
    for heading, heading_index in heading_indexes.items():
        start, end = _first_table(lines, heading_index)
        header = _cells(lines[start])
        if start + 1 >= end or not _is_separator(_cells(lines[start + 1])):
            raise TableParseError(f"missing table separator: {lines[start]}")
        try:
            symbol_index = next(
                index for index, name in enumerate(header) if name in SYMBOL_COLUMNS
            )
            owner_index = next(
                index for index, name in enumerate(header) if name in OWNER_COLUMNS
            )
            definition_index = next(
                index for index, name in enumerate(header)
                if name in DEFINITION_COLUMNS
            )
        except StopIteration as exc:
            raise TableParseError(
                "table lacks symbol/definition/owner columns after "
                f"{heading!r}: {lines[start]}"
            ) from exc

        for index in range(start + 2, end):
            raw_line = lines[index]
            cells = _cells(raw_line)
            if len(cells) != len(header):
                raise TableParseError(f"column count mismatch: {raw_line}")
            owner = _owner(cells[owner_index], raw_line)
            definition = _module(cells[definition_index], raw_line)
            for symbol in _symbol_names(cells[symbol_index], raw_line):
                entry = BodyEntry(symbol, definition, owner, index + 1)
                key = (definition, symbol)
                previous = entries.get(key)
                if previous is not None and previous.owner != owner:
                    raise TableParseError(
                        f"conflicting owners for {definition}:{symbol}: "
                        f"line {previous.line_number} has {previous.owner}, "
                        f"line {entry.line_number} has {entry.owner}"
                    )
                entries[key] = entry
    return entries

def _merge_symbol_tables(
    *tables: dict[SpecKey, BodyEntry],
) -> dict[SpecKey, BodyEntry]:
    merged: dict[SpecKey, BodyEntry] = {}
    for table in tables:
        duplicates = sorted(merged.keys() & table.keys())
        if duplicates:
            rendered = ",".join(f"{definition}:{symbol}" for definition, symbol in duplicates)
            raise TableParseError(
                "symbol definitions appear in multiple attribution tables: " + rendered
            )
        merged.update(table)
    return merged

def parse_module_scope_table(design_path: Path) -> dict[str, BodyModuleEntry]:
    """Parse the frozen module-scope attribution table without inference."""

    lines = design_path.read_text(encoding="utf-8").splitlines()
    matches = [
        index for index, line in enumerate(lines) if line.startswith(MODULE_SCOPE_HEADING)
    ]
    if len(matches) != 1:
        raise TableParseError(
            f"expected one heading starting {MODULE_SCOPE_HEADING!r}, found {len(matches)}"
        )
    start, end = _first_table(lines, matches[0])
    header = _cells(lines[start])
    if start + 1 >= end or not _is_separator(_cells(lines[start + 1])):
        raise TableParseError(f"missing table separator: {lines[start]}")
    try:
        module_index = next(
            index for index, name in enumerate(header) if name in MODULE_COLUMNS
        )
        owner_index = next(
            index for index, name in enumerate(header) if name in OWNER_COLUMNS
        )
    except StopIteration as exc:
        raise TableParseError(
            f"module-scope table lacks module/owner columns: {lines[start]}"
        ) from exc

    entries: dict[str, BodyModuleEntry] = {}
    for index in range(start + 2, end):
        raw_line = lines[index]
        cells = _cells(raw_line)
        if len(cells) != len(header):
            raise TableParseError(f"column count mismatch: {raw_line}")
        module = _module(cells[module_index], raw_line)
        entry = BodyModuleEntry(module, _owner(cells[owner_index], raw_line), index + 1)
        if module in entries:
            raise TableParseError(f"duplicate module-scope row for {module}: {raw_line}")
        entries[module] = entry
    return entries

def _body_entry(triplet: RelocationTriplet, line_number: int = 1) -> BodyEntry:
    definition, symbol, owner = triplet
    return BodyEntry(symbol, definition, owner, line_number)

def _run_relocation_synthetic(name: str) -> int:
    a = ("old.py", "A", "old-owner")
    b = ("new.py", "B", "new-owner")
    c = ("old.py", "C", "old-owner")
    d = ("new.py", "D", "new-owner")
    x = ("other.py", "X", "other-owner")

    if name == "one":
        mapping = {a: b}
        result = apply_relocations(
            {a[:2]: _body_entry(a)},
            {b[:2]: _body_entry(b)},
            mapping,
        )
        passed = (
            result.consumed_sources == frozenset({a})
            and result.produced_destinations == frozenset({b})
            and set(result.entries) == {b[:2]}
            and not result.verdicts
        )
    elif name == "two":
        mapping = {a: b}
        result = apply_relocations(
            {x[:2]: _body_entry(x)},
            {b[:2]: _body_entry(b)},
            mapping,
        )
        passed = (
            result.consumed_sources == frozenset()
            and set(result.entries) == {x[:2]}
            and any("UNMAPPED_SOURCE" in verdict for verdict in result.verdicts)
        )
    elif name == "three":
        mapping = {a: b, c: d}
        result = apply_relocations(
            {a[:2]: _body_entry(a), x[:2]: _body_entry(x)},
            {b[:2]: _body_entry(b), d[:2]: _body_entry(d)},
            mapping,
        )
        passed = (
            result.consumed_sources == frozenset({a})
            and result.produced_destinations == frozenset({b})
            and set(result.entries) == {b[:2], x[:2]}
            and a[:2] not in result.entries
            and c[:2] not in result.entries
            and d[:2] not in result.entries
            and any("UNMAPPED_SOURCE" in verdict for verdict in result.verdicts)
        )
    else:
        print(f"unknown relocation synthetic fixture: {name}")
        return 2

    print(
        f"RELOCATION_SYNTHETIC | {name} | "
        f"consumed={sorted(result.consumed_sources)} | "
        f"produced={sorted(result.produced_destinations)} | "
        f"output={sorted(result.entries)} | verdicts={result.verdicts} | "
        f"{'OK' if passed else 'MISMATCH'}"
    )
    return 0 if passed else 1

def main() -> int:
    if len(sys.argv) == 3 and sys.argv[1] in {"--key-fixture", "--negative-fixture"}:
        return _run_key_fixture(sys.argv[2])
    if len(sys.argv) == 3 and sys.argv[1] == "--relocation-negative":
        return _run_relocation_negative_fixture(sys.argv[2])
    if len(sys.argv) == 3 and sys.argv[1] == "--relocation-synthetic":
        return _run_relocation_synthetic(sys.argv[2])
    if len(sys.argv) != 1:
        print(
            "usage: table_audit_bridge.py "
            "[--key-fixture twin-both-binary-key|"
            "--negative-fixture twin-both-name-only|"
            "--relocation-negative missing-destination|wrong-definition|"
            "wrong-owner|source-remains|mapping-contract|source-table-mismatch|"
            "--relocation-synthetic one|two|three]"
        )
        return 2
    return run(Path(__file__).resolve().parents[3])

def analyze(
        self,
        buildlog_path: str | Path,
        *,
        src_root: str | Path = "auto",
        max_tokens: int = 1800,
        timeout: int = 30,
    ) -> dict[str, Any]:
        """Return an Evidence Packet or a degraded error packet."""

        cmd = [
            *self.analyzer_path.split(),
            "analyze",
            str(buildlog_path),
            "--src-root",
            str(src_root),
            "--max-tokens",
            str(max_tokens),
            "--output-format",
            "json",
            "--output-dir",
            str(self.output_dir),
        ]
        try:
            subprocess.run(cmd, capture_output=True, timeout=timeout, check=True)
            packet_path = self.output_dir / "evidence_packet.json"
            return cast(dict[str, Any], json.loads(packet_path.read_text(encoding="utf-8")))
        except subprocess.TimeoutExpired:
            return _degraded_packet("analyzer_timeout")
        except subprocess.CalledProcessError as exc:
            return _degraded_packet(f"analyzer_exit_{exc.returncode}")
        except OSError as exc:
            return _degraded_packet(f"analyzer_os_error:{exc}")

def feed_to_llm(self, packet: dict[str, Any], llm_client: Any) -> str:
        """Use direct answers when available, otherwise send the packet prompt."""

        if packet.get("verdict") == "direct_answer":
            return str(packet.get("direct_answer", ""))
        prompt = packet.get("prompt")
        if not prompt:
            return "Analysis failed; please inspect the raw buildlog."
        return str(llm_client.complete(prompt))

def _degraded_packet(reason: str) -> dict[str, Any]:
    return {
        "schema_version": "evidence_packet/v1",
        "verdict": "needs_llm",
        "via": "wrapper_error",
        "degraded": True,
        "degraded_reasons": [reason],
        "prompt": None,
        "allowed_next_actions": [],
    }

def _parse_since(value: str | None, *, hours: int) -> datetime:
    if value:
        return datetime.fromisoformat(value)
    if hours <= 0:
        raise ValueError("--hours must be positive")
    return datetime.now() - timedelta(hours=hours)

def main(
    argv: list[str] | None = None,
    *,
    stderr: TextIO = sys.stderr,
    extra_pythonpath: tuple[Path, ...] = (),
) -> int:
    if argv is None:
        argv = sys.argv[1:]
    if argv and argv[0] == "build-verify":
        return _main_build_verify(argv[1:], stderr=stderr, extra_pythonpath=extra_pythonpath)
    if argv and argv[0] == "check-convergence":
        return _main_check_convergence(argv[1:], stderr=stderr)
    if argv and argv[0] == "gerrit-submit":
        return _main_gerrit_submit(argv[1:], stderr=stderr)
    if argv and argv[0] == "release-worktree":
        return _main_release_worktree(argv[1:], stderr=stderr)

    parser = build_parser()
    args = parser.parse_args(argv)
    paths = extra_pythonpath or discover_sibling_pythonpath(
        launcher_path=Path(__file__).resolve().parents[1] / "run_ci_triage.py"
    )
    result = run_triage(
        TriageOptions(
            build_id=args.build_id,
            output_root=args.output_root,
            cookie_path=args.cookie,
            spec_name=args.spec_name,
            arch=args.arch,
            extra_pythonpath=paths,
            git_ssh_command=args.git_ssh_command,
        )
    )
    print(f"ci_triage: status {result.status}", file=stderr)
    print(f"ci_triage: report written to {result.report_path}", file=stderr)
    if result.error:
        print(f"ci_triage: {result.error}", file=stderr)
    return EXIT_SUCCESS if result.exit_code == 0 else EXIT_FAILED

def _main_check_convergence(argv: list[str], *, stderr: TextIO) -> int:
    parser = check_convergence_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        if exc.code == 0:
            raise
        return EXIT_FAILED

    paths = [args.current_evidence]
    if args.previous_evidence is not None:
        paths.append(args.previous_evidence)
    if args.touched_files is not None:
        paths.append(args.touched_files)
    missing = [str(path) for path in paths if not path.is_file()]
    if missing:
        print("ci_triage check-convergence: missing file(s): " + ", ".join(missing), file=stderr)
        return EXIT_FILE_MISSING

    try:
        current = _read_json(args.current_evidence)
        previous = (
            _read_json(args.previous_evidence) if args.previous_evidence is not None else None
        )
        touched = (
            touched_files_from_json(args.touched_files) if args.touched_files is not None else None
        )
    except (JSONDecodeError, ValueError) as exc:
        print(f"ci_triage check-convergence: invalid JSON: {exc}", file=stderr)
        return EXIT_JSON_INVALID

    result = check_convergence(current, previous, touched_files=touched)
    write_convergence_result(result, args.output)
    print(json.dumps(result.to_dict(), sort_keys=True), file=stderr)
    print(f"ci_triage check-convergence: result written to {args.output}", file=stderr)
    return EXIT_SUCCESS

def _main_release_worktree(argv: list[str], *, stderr: TextIO) -> int:
    parser = release_worktree_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        if exc.code == 0:
            raise
        return EXIT_FAILED
    result = release_verified_worktree(StateDatabase(args.state_db), args.verification_id)
    if args.output is not None:
        write_release_result(result, args.output)
        print(f"ci_triage release-worktree: result written to {args.output}", file=stderr)
    print(json.dumps(result.to_dict(), sort_keys=True), file=stderr)
    return exit_code_for_release(result)

def _read_json(path: Path) -> dict[str, object]:
    raw = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise ValueError(f"{path} must contain a JSON object")
    return raw

def download_gbs_package_buildlog(
    package: GbsReportPackage,
    *,
    cookie_path: Path = DEFAULT_COOKIE_PATH,
    fetcher: HttpFetcher | None = None,
) -> str:
    """Download one per-package GBS build log from the GBS report link."""

    if not package.buildlog_url:
        raise QuickBuildError(
            "GBS_PACKAGE_LOG_MISSING",
            f"GBS report row has no failed buildlog URL for {package.spec_name}",
        )
    response = (fetcher or _urllib_fetch)(package.buildlog_url, load_cookie_jar(cookie_path))
    if response.status != 200:
        raise QuickBuildError(
            "GBS_PACKAGE_LOG_DOWNLOAD_FAILED",
            f"failed to download GBS package log {package.buildlog_url}: HTTP {response.status}",
        )
    return response.text

def parse_gbs_report_packages(
    html_text: str,
    *,
    build_id: str,
    arch: str,
    iframe_url: str,
) -> tuple[GbsReportPackage, ...]:
    """Parse Build Statis Details rows from a static GBS Reports HTML page."""

    parser = _ReportTableParser()
    parser.feed(html_text)
    packages: list[GbsReportPackage] = []
    for table in parser.tables:
        if not _looks_like_build_status_table(table):
            continue
        for row in table.rows:
            package = _row_to_package(row, build_id=build_id, arch=arch, iframe_url=iframe_url)
            if package is not None:
                packages.append(package)
    return tuple(packages)

def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.src: str | None = None

def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag != "iframe" or self.src is not None:
            return
        attrs_map = _attrs_to_map(attrs)
        src = attrs_map.get("src")
        if src:
            self.src = src

def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        attrs_map = _attrs_to_map(attrs)
        if tag == "table":
            if self._in_table:
                self._table_depth += 1
            else:
                self._in_table = True
                self._table_depth = 1
                self._current_rows = []
            return
        if not self._in_table:
            return
        if tag == "tr":
            self._current_cells = []
            return
        if tag in {"td", "th"} and self._current_cells is not None:
            self._current_cell = _CellBuilder()
            return
        if tag == "a" and self._current_cell is not None:
            self._current_anchor = _AnchorBuilder(
                class_names=_class_names(attrs_map),
                href=attrs_map.get("href"),
            )

def handle_endtag(self, tag: str) -> None:
        if not self._in_table:
            return
        if tag == "a" and self._current_anchor is not None and self._current_cell is not None:
            self._current_cell.anchors.append(
                _Anchor(
                    class_names=self._current_anchor.class_names,
                    href=self._current_anchor.href,
                    text=_normalize_text("".join(self._current_anchor.text_parts)),
                )
            )
            self._current_anchor = None
            return
        if (
            tag in {"td", "th"}
            and self._current_cell is not None
            and self._current_cells is not None
        ):
            self._current_cells.append(
                _Cell(
                    text=_normalize_text("".join(self._current_cell.text_parts)),
                    anchors=tuple(self._current_cell.anchors),
                )
            )
            self._current_cell = None
            return
        if tag == "tr" and self._current_cells is not None and self._current_rows is not None:
            if self._current_cells:
                self._current_rows.append(_Row(cells=tuple(self._current_cells)))
            self._current_cells = None
            return
        if tag == "table":
            self._table_depth -= 1
            if self._table_depth <= 0:
                if self._current_rows is not None:
                    self.tables.append(_Table(rows=tuple(self._current_rows)))
                self._in_table = False
                self._table_depth = 0
                self._current_rows = None

def handle_data(self, data: str) -> None:
        if self._current_cell is not None:
            self._current_cell.text_parts.append(data)
        if self._current_anchor is not None:
            self._current_anchor.text_parts.append(data)

def _looks_like_build_status_table(table: _Table) -> bool:
    has_status_anchor = any(
        len(row.cells) >= 3
        and any(
            "failed" in anchor.class_names or "succeeded" in anchor.class_names
            for anchor in row.cells[2].anchors
        )
        for row in table.rows
    )
    if has_status_anchor:
        return True
    header_text = " ".join(cell.text.lower() for row in table.rows[:2] for cell in row.cells)
    return (
        "package name" in header_text
        and "package path" in header_text
        and "build status" in header_text
    )

def _status_from_anchor(anchor: _Anchor) -> str | None:
    if "failed" in anchor.class_names:
        return "failed"
    if "succeeded" in anchor.class_names or "successful" in anchor.class_names:
        return "succeeded"
    text = anchor.text.lower()
    if text == "failed":
        return "failed"
    if text in {"succeeded", "successful"}:
        return "succeeded"
    return None

def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code

def parse_gerrit_query_output(output: str) -> list[dict[str, Any]]:
    """Parse JSON-lines output from Gerrit, excluding the stats row."""

    changes: list[dict[str, Any]] = []
    for line in output.splitlines():
        if not line.strip():
            continue
        obj = json.loads(line)
        if obj.get("type") == "stats":
            continue
        if isinstance(obj, dict):
            changes.append(obj)
    return changes

def find_patchset_by_revision(obj: dict[str, Any], target_hash: str) -> GerritPatchSet | None:
    """Return the patch set whose revision equals the build commit."""

    patchsets = obj.get("patchSets")
    if not isinstance(patchsets, list):
        return None
    for item in patchsets:
        if not isinstance(item, dict):
            continue
        if item.get("revision") != target_hash:
            continue
        ref = item.get("ref")
        revision = item.get("revision")
        if isinstance(ref, str) and isinstance(revision, str):
            return GerritPatchSet(
                number=_optional_int(item.get("number")),
                revision=revision,
                ref=ref,
            )
    return None

def _reset_generated_source_dir(path: Path) -> None:
    if path.exists() and path.is_symlink():
        raise GerritError("SOURCE_DIR_UNSAFE", f"source directory is a symlink: {path}")
    if path.is_dir():
        shutil.rmtree(path)
    elif path.exists():
        path.unlink()

def _optional_int(value: Any) -> int | None:
    if isinstance(value, int):
        return value
    if isinstance(value, str) and value.isdigit():
        return int(value)
    return None

def from_file(cls, path: Path, *, build: FailedBuild, now: str) -> BuildState:
        if not path.is_file():
            return cls(
                build_id=build.build_id,
                discovered_at=now,
                begin_date=build.begin_date.isoformat(sep=" ", timespec="seconds"),
            )
        try:
            raw = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return cls(
                build_id=build.build_id,
                discovered_at=now,
                begin_date=build.begin_date.isoformat(sep=" ", timespec="seconds"),
            )
        if not isinstance(raw, dict):
            return cls(
                build_id=build.build_id,
                discovered_at=now,
                begin_date=build.begin_date.isoformat(sep=" ", timespec="seconds"),
            )
        raw_packages = raw.get("packages")
        packages: dict[str, PackageState] = {}
        if isinstance(raw_packages, dict):
            for spec_name, value in raw_packages.items():
                if isinstance(spec_name, str):
                    packages[spec_name] = PackageState.from_dict(value)
        transitions = raw.get("transitions")
        return cls(
            build_id=_string(raw.get("build_id"), build.build_id),
            discovered_at=_string(raw.get("discovered_at"), now),
            begin_date=_string(
                raw.get("begin_date"),
                build.begin_date.isoformat(sep=" ", timespec="seconds"),
            ),
            state=_string(raw.get("state"), STATE_DISCOVERED),
            error=_optional_string(raw.get("error")),
            transitions=transitions if isinstance(transitions, list) else [],
            packages=packages,
        )

def to_dict(self) -> dict[str, Any]:
        return {
            "build_id": self.build_id,
            "discovered_at": self.discovered_at,
            "begin_date": self.begin_date,
            "state": self.state,
            "error": self.error,
            "transitions": self.transitions,
            "packages": {
                spec_name: package.to_dict()
                for spec_name, package in sorted(self.packages.items())
            },
        }

def _process_build(
        self,
        build: FailedBuild,
        build_state: BuildState,
        paths: _BatchPaths,
        processed: dict[str, dict[str, set[str]]],
        rows: list[BatchRunRecord],
        now: datetime,
    ) -> None:
        full_log = self.full_log_downloader(build.build_id, self.options.cookie_path)
        _transition_build(build_state, STATE_LOG_FETCHED, ok=True, error=None, now=now)

        pkg_to_commit_error: str | None
        try:
            pkg_to_commit = parse_build_pkg_list(full_log)
        except QuickBuildLogError as exc:
            pkg_to_commit_error = f"{exc.code}: {exc}"
            pkg_to_commit = {}
        else:
            pkg_to_commit_error = None

        discovered_any = False
        no_gbs_report_any = False
        for arch in self.options.arches:
            if _is_processed(processed, build.build_id, arch, NO_GBS_REPORT_SPEC_NAME):
                no_gbs_report_any = True
                package = _package_for(build_state, arch, NO_GBS_REPORT_SPEC_NAME)
                _transition_package(
                    package,
                    STATE_SKIPPED_PROCESSED,
                    ok=True,
                    error=None,
                    now=now,
                )
                rows.append(
                    _row_from_package(build.build_id, arch, NO_GBS_REPORT_SPEC_NAME, package)
                )
                continue
            try:
                failed_packages = self.gbs_report_discoverer(
                    build.build_id,
                    arch,
                    self.options.cookie_path,
                )
            except QuickBuildError as exc:
                if exc.code == "NO_GBS_REPORT":
                    no_gbs_report_any = True
                    package = _package_for(build_state, arch, NO_GBS_REPORT_SPEC_NAME)
                    _transition_package(
                        package,
                        STATE_REPORTED_NO_REPORT,
                        ok=True,
                        error=str(exc),
                        now=now,
                    )
                    _mark_processed(processed, build.build_id, arch, NO_GBS_REPORT_SPEC_NAME)
                    rows.append(
                        _row_from_package(build.build_id, arch, NO_GBS_REPORT_SPEC_NAME, package)
                    )
                    continue
                package = _package_for(build_state, arch, UNKNOWN_SPEC_NAME)
                package.retries += 1
                _transition_package(
                    package,
                    STATE_FAILED_LOG,
                    ok=False,
                    error=f"{exc.code}: {exc}",
                    now=now,
                )
                rows.append(_row_from_package(build.build_id, arch, UNKNOWN_SPEC_NAME, package))
                continue

            if failed_packages:
                discovered_any = True
            for failed_package in failed_packages:
                self._process_package(
                    build,
                    failed_package,
                    pkg_to_commit,
                    pkg_to_commit_error,
                    build_state,
                    paths,
                    processed,
                    rows,
                    now,
                )

        if not discovered_any and not no_gbs_report_any:
            package = _package_for(build_state, "unknown-arch", UNKNOWN_SPEC_NAME)
            _transition_package(
                package,
                STATE_NEEDS_INPUT,
                ok=False,
                error=(
                    "GBS Reports contained no failed package rows "
                    f"(scanned arches: {', '.join(self.options.arches)})"
                ),
                now=now,
            )
            rows.append(
                _row_from_package(build.build_id, "unknown-arch", UNKNOWN_SPEC_NAME, package)
            )

def _discover_failed_gbs_packages(
        build_id: str,
        arch: str,
        cookie_path: Path,
    ) -> tuple[GbsReportPackage, ...]:
        return fetch_gbs_report(build_id, arch, cookie_path=cookie_path).failed_packages

def _group_no_gbs_report_rows(rows: list[BatchRunRecord]) -> dict[str, list[BatchRunRecord]]:
    groups: dict[str, list[BatchRunRecord]] = {}
    for row in rows:
        if row.state == STATE_REPORTED_NO_REPORT:
            groups.setdefault(row.build_id, []).append(row)
    return groups

def _arch_summary(rows: list[BatchRunRecord], arch_order: tuple[str, ...]) -> str:
    ordered_arches = _ordered_arches(rows, arch_order)
    if len(ordered_arches) == 1:
        return ordered_arches[0]
    return f"{len(ordered_arches)} arches ({', '.join(ordered_arches)})"

def _ordered_arches(rows: list[BatchRunRecord], arch_order: tuple[str, ...]) -> list[str]:
    row_arches: list[str] = []
    for row in rows:
        if row.arch not in row_arches:
            row_arches.append(row.arch)

    ordered: list[str] = []
    row_arch_set = set(row_arches)
    for arch in arch_order:
        if arch in row_arch_set:
            ordered.append(arch)
    for arch in row_arches:
        if arch not in ordered:
            ordered.append(arch)
    return ordered

def _count_label(count: int, singular: str) -> str:
    suffix = "" if count == 1 else "s"
    return f"{count} {singular}{suffix}"

def _render_batch_manifest(paths: _BatchPaths, rows: list[BatchRunRecord], now: datetime) -> str:
    manifest = {
        "schema_version": BATCH_MANIFEST_SCHEMA,
        "generated_at": _timestamp(now),
        "run_date": paths.run_date,
        "packages": [_manifest_package(paths, row) for row in rows],
    }
    return json.dumps(manifest, indent=2, sort_keys=True) + "\n"

def _manifest_error(row: BatchRunRecord) -> dict[str, str] | None:
    if row.error:
        code, _, message = row.error.partition(":")
        if message and _looks_like_error_code(code):
            return {"code": code.strip() or row.state, "message": message.strip()}
        return {"code": row.state, "message": row.error}
    if row.state in {STATE_REPORTED, STATE_SKIPPED_PROCESSED}:
        return None
    if row.state.startswith("FAILED_") or row.state in {
        STATE_NEEDS_INPUT,
        STATE_REPORTED_NO_REPORT,
        STATE_FAILED_PERMANENT,
    }:
        return {"code": row.state, "message": row.state}
    # In-progress states such as LOG_FETCHED/ANALYZED are visible in the
    # manifest during partial runs, but they are not errors by themselves.
    return None

def _load_processed(path: Path) -> dict[str, dict[str, set[str]]]:
    if not path.is_file():
        return {}
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    if not isinstance(raw, dict):
        return {}
    processed: dict[str, dict[str, set[str]]] = {}
    for build_id, arches in raw.items():
        if not isinstance(build_id, str):
            continue
        if isinstance(arches, dict):
            processed[build_id] = {}
            for arch, spec_names in arches.items():
                if isinstance(arch, str) and isinstance(spec_names, list):
                    processed[build_id][arch] = {
                        item for item in spec_names if isinstance(item, str)
                    }
        elif isinstance(arches, list):
            processed[build_id] = {
                "unknown-arch": {item for item in arches if isinstance(item, str)}
            }
    return processed

def _save_processed(path: Path, processed: dict[str, dict[str, set[str]]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    serializable = {
        build_id: {
            arch: sorted(spec_names) for arch, spec_names in sorted(arches.items())
        }
        for build_id, arches in sorted(processed.items())
    }
    path.write_text(json.dumps(serializable, indent=2, sort_keys=True) + "\n", encoding="utf-8")

def _is_processed(
    processed: dict[str, dict[str, set[str]]],
    build_id: str,
    arch: str,
    spec_name: str,
) -> bool:
    return spec_name in processed.get(build_id, {}).get(arch, set())

def _save_build_state(path: Path, state: BuildState) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(state.to_dict(), indent=2, sort_keys=True) + "\n", encoding="utf-8")

def _package_for(build_state: BuildState, arch: str, spec_name: str) -> PackageState:
    key = _unit_key(arch, spec_name)
    package = build_state.packages.get(key)
    if package is None:
        package = PackageState(arch=arch, spec_name=spec_name)
        build_state.packages[key] = package
    return package

def _transition_package(
    package: PackageState,
    to_state: str,
    *,
    ok: bool,
    error: str | None,
    now: datetime,
) -> None:
    previous = package.state
    package.state = to_state
    package.error = error
    package.transitions.append(_transition(previous, to_state, ok=ok, error=error, now=now))

def _read_patch_status(meta_path: Path) -> str | None:
    try:
        raw = json.loads(meta_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(raw, dict):
        return None
    status = raw.get("status")
    return status if isinstance(status, str) else None

def _read_report_metadata(package: PackageState, report_path: Path) -> None:
    try:
        text = report_path.read_text(encoding="utf-8")
    except OSError:
        return
    status_match = re.search(r"^- Change status: `([^`]+)`", text, flags=re.MULTILINE)
    if status_match is not None:
        package.gerrit_status = status_match.group(1)
    patchset_match = re.search(r"^- Patch set ref: `([^`]+)`", text, flags=re.MULTILINE)
    if patchset_match is not None:
        package.patchset_ref = patchset_match.group(1)
    branch_match = re.search(r"^- Branch: `([^`]+)`", text, flags=re.MULTILINE)
    if branch_match is not None:
        package.branch = branch_match.group(1)

def _cell(value: str | None) -> str:
    if value is None or value == "":
        return "n/a"
    return value.replace("|", "\\|")

def _report_link(report_path: str | None) -> str:
    if not report_path:
        return "n/a"
    return f"[report]({report_path})"

def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code

def load_cookie_jar(cookie_path: Path = DEFAULT_COOKIE_PATH) -> dict[str, str]:
    """Load browser-exported QuickBuild cookies from a JSON file."""

    try:
        raw = json.loads(cookie_path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise QuickBuildError(
            "COOKIE_MISSING",
            f"QuickBuild cookie file is missing: {cookie_path}",
        ) from exc
    except json.JSONDecodeError as exc:
        raise QuickBuildError(
            "COOKIE_UNREADABLE",
            f"QuickBuild cookie file is not valid JSON: {cookie_path}",
        ) from exc

    if not isinstance(raw, list):
        raise QuickBuildError("COOKIE_UNREADABLE", "QuickBuild cookie JSON must be a list")

    cookies: dict[str, str] = {}
    for item in raw:
        if not isinstance(item, dict):
            continue
        name = item.get("name")
        value = item.get("value")
        domain = item.get("domain")
        if (
            isinstance(name, str)
            and isinstance(value, str)
            and (domain is None or "quickbuild.tizen.org" in str(domain))
        ):
            cookies[name] = value

    if not cookies:
        raise QuickBuildError(
            "COOKIE_EXPIRED",
            "QuickBuild cookie file has no quickbuild.tizen.org cookies; "
            "please log in and export cookies again.",
        )
    return cookies

def find_download_href(html_text: str) -> str | None:
    """Return the Wicket full-log download href from a build-log HTML page."""

    for match in re.finditer(r"""href\s*=\s*["']([^"']+)["']""", html_text, re.IGNORECASE):
        href = html.unescape(match.group(1))
        if DOWNLOAD_LINK_MARKER in href:
            return href
    return None

def download_package_buildlog(
    dest_file: str,
    *,
    fetcher: HttpFetcher | None = None,
) -> PackageBuildLog | None:
    """Download one failed package buildlog when QuickBuild exposes its dest_file."""

    url = derive_package_buildlog_url(dest_file)
    if url is None:
        return None
    response = (fetcher or _urllib_fetch)(url, {})
    if response.status != 200:
        raise QuickBuildError(
            "PACKAGE_BUILDLOG_DOWNLOAD_FAILED",
            f"failed to download package buildlog {url}: HTTP {response.status}",
        )
    return PackageBuildLog(url=url, text=response.text)

def _raise_if_login_page(response: HttpResponse, *, action: str) -> None:
    final_url = response.url.lower()
    text = response.text.lower()
    if (
        response.status in {401, 403}
        or "/signin" in final_url
        or "redirect-url-after-sign-in" in text
    ):
        raise QuickBuildError(
            "COOKIE_EXPIRED",
            f"QuickBuild cookie expired while trying to {action}; "
            f"please log in and export cookies to {DEFAULT_COOKIE_PATH}.",
        )

def _urllib_fetch(url: str, cookies: Mapping[str, str]) -> HttpResponse:
    url = normalize_quickbuild_url(url)
    cookie_header = "; ".join(f"{name}={value}" for name, value in cookies.items())
    request = Request(url, headers={"Cookie": cookie_header, "User-Agent": "ci-triage/0.1"})
    try:
        with urlopen(request, timeout=60) as response:
            return HttpResponse(
                status=response.status,
                url=response.geturl(),
                body=response.read(),
                content_type=response.headers.get("content-type"),
            )
    except HTTPError as exc:
        return HttpResponse(
            status=exc.code,
            url=exc.geturl(),
            body=exc.read(),
            content_type=exc.headers.get("content-type"),
        )
    except URLError as exc:
        raise QuickBuildError("QUICKBUILD_DOWNLOAD_FAILED", str(exc)) from exc

def normalize_quickbuild_url(url: str) -> str:
    """Idempotently quote QuickBuild URL paths that may contain raw spaces."""

    parts = urlsplit(url)
    path = quote(unquote(parts.path), safe="/@")
    return urlunsplit((parts.scheme, parts.netloc, path, parts.query, parts.fragment))

def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code

def parse_build_pkg_list(full_log: str) -> dict[str, str]:
    """Parse the Python-dict build_pkg_list_dic line into project -> commit."""

    for line in full_log.splitlines():
        if "build_pkg_list_dic:" not in line:
            continue
        raw = line.split("build_pkg_list_dic:", 1)[1].strip()
        try:
            parsed = ast.literal_eval(raw)
        except (SyntaxError, ValueError) as exc:
            raise QuickBuildLogError(
                "BUILD_PKG_LIST_UNREADABLE",
                "build_pkg_list_dic is not parseable as a Python literal dict",
            ) from exc
        if not isinstance(parsed, dict):
            raise QuickBuildLogError(
                "BUILD_PKG_LIST_UNREADABLE",
                "build_pkg_list_dic is not a dict",
            )
        result: dict[str, str] = {}
        for key, value in parsed.items():
            if isinstance(key, str) and isinstance(value, str):
                result[key] = value
        if not result:
            raise QuickBuildLogError("BUILD_PKG_LIST_UNREADABLE", "build_pkg_list_dic is empty")
        return result
    raise QuickBuildLogError("BUILD_PKG_LIST_MISSING", "full log has no build_pkg_list_dic line")

def parse_failed_packages(full_log: str) -> tuple[FailedPackage, ...]:
    """Return failed package entries using spec_name as the stable package key."""

    packages: list[FailedPackage] = []
    pattern = re.compile(
        r"fail_pkg:\s*(?P<fail_pkg>[^,]+),\s*"
        r"spec_name:\s*(?P<spec_name>[^,\s]+)"
        r"(?:,\s*dest_file:\s*(?P<dest_file>\S+))?"
    )
    seen: set[tuple[str, str]] = set()
    for match in pattern.finditer(full_log):
        fail_pkg = match.group("fail_pkg").strip()
        spec_name = match.group("spec_name").strip()
        key = (fail_pkg, spec_name)
        if key in seen:
            continue
        seen.add(key)
        packages.append(
            FailedPackage(
                fail_pkg=fail_pkg,
                spec_name=spec_name,
                dest_file=match.group("dest_file"),
            )
        )
    if not packages:
        raise QuickBuildLogError(
            "FAILED_PACKAGE_NOT_FOUND",
            "full log has no fail_pkg/spec_name entries",
        )
    return tuple(packages)

def select_failed_package(
    failed_packages: tuple[FailedPackage, ...],
    *,
    spec_name: str | None,
) -> FailedPackage:
    """Select one failed package for the vertical-slice MVP."""

    if spec_name is not None:
        matches = [package for package in failed_packages if package.spec_name == spec_name]
        if len(matches) == 1:
            return matches[0]
        if not matches:
            choices = ", ".join(package.spec_name for package in failed_packages)
            raise QuickBuildLogError(
                "FAILED_PACKAGE_NOT_FOUND",
                f"requested spec_name {spec_name!r} was not in failed packages: {choices}",
            )
        raise QuickBuildLogError(
            "FAILED_PACKAGE_AMBIGUOUS",
            f"requested spec_name {spec_name!r} matched multiple failed package rows",
        )

    if len(failed_packages) == 1:
        return failed_packages[0]

    choices = ", ".join(package.spec_name for package in failed_packages)
    raise QuickBuildLogError(
        "NEEDS_PACKAGE_SELECTION",
        f"build has multiple failed packages; rerun with --spec-name. Candidates: {choices}",
    )

def match_pkg_key(spec_name: str, pkg_to_commit: dict[str, str]) -> tuple[str, str]:
    """Map a spec_name like 'multi-assistant' to one project key and commit."""

    matches = _exact_project_matches(spec_name, pkg_to_commit)
    if len(matches) == 1:
        key = matches[0]
        return key, pkg_to_commit[key]

    if not matches:
        matches = _tizen_prefix_project_matches(spec_name, pkg_to_commit)

    if len(matches) == 1:
        key = matches[0]
        return key, pkg_to_commit[key]
    if not matches:
        raise QuickBuildLogError(
            "PROJECT_COMMIT_NOT_FOUND",
            f"no build_pkg_list_dic key matched spec_name {spec_name!r}",
        )
    raise QuickBuildLogError(
        "PROJECT_COMMIT_AMBIGUOUS",
        f"multiple build_pkg_list_dic keys matched {spec_name!r}: {', '.join(matches)}",
    )

def _tizen_prefix_project_matches(spec_name: str, pkg_to_commit: dict[str, str]) -> list[str]:
    rules = (
        ("hal-api-", "/hal/api/"),
        ("capi-ui-", "/api/"),
        ("capi-", "/api/"),
    )
    for prefix, required_segment in rules:
        if not spec_name.startswith(prefix):
            continue
        project_name = spec_name.removeprefix(prefix)
        return [
            key
            for key in pkg_to_commit
            if required_segment in f"/{key}/" and _project_basename(key) == project_name
        ]
    return []

def render_report(data: TriageReportData) -> str:
    """Render a human-readable single-build report."""

    lines = [
        f"# CI Triage Report: QuickBuild {data.build_id}",
        "",
        "## QuickBuild",
        f"- Build id: `{data.build_id}`",
        f"- Log page: {data.quickbuild_log_url}",
    ]
    if data.full_log_path is not None:
        lines.append(f"- Full log: `{data.full_log_path}`")
    if data.analyzed_buildlog_path is not None:
        lines.append(f"- Analyzer input: `{data.analyzed_buildlog_path}`")
    if data.package_buildlog_url is not None:
        lines.append(f"- Package buildlog URL: {data.package_buildlog_url}")

    lines.extend(["", "## Failed Package"])
    if data.selected_package is None:
        lines.append("- Selected package: n/a")
    else:
        lines.extend(
            [
                f"- spec_name: `{data.selected_package.spec_name}`",
                f"- fail_pkg: `{data.selected_package.fail_pkg}`",
            ]
        )
        if data.selected_package.dest_file:
            lines.append(f"- buildlog path: `{data.selected_package.dest_file}`")
    if data.project_key is not None:
        lines.append(f"- Gerrit project: `{data.project_key}`")
    if data.commit_hash is not None:
        lines.append(f"- Commit: `{data.commit_hash}`")

    lines.extend(["", "## Gerrit Source"])
    if data.source_fetch is None:
        lines.append("- Source checkout: not attempted")
    else:
        source = data.source_fetch
        lines.append(f"- Status: `{source.status}`")
        lines.append(f"- Remote: `{source.remote_url}`")
        lines.append(f"- Source root: `{source.src_root}`")
        if source.change is not None:
            change = source.change
            lines.append(f"- Change status: `{change.status}`")
            lines.append(f"- Branch: `{change.branch}`")
            if change.number is not None:
                lines.append(f"- Change: `{change.number}`")
            if change.matching_patchset is not None:
                lines.append(f"- Patch set ref: `{change.matching_patchset.ref}`")
        if source.error:
            lines.append(f"- Error: {source.error}")

    lines.extend(["", "## Analyzer"])
    if data.evidence_packet_path is not None:
        lines.append(f"- Evidence packet: `{data.evidence_packet_path}`")
    if data.analyzer_output_dir is not None:
        lines.append(f"- Analyzer output: `{data.analyzer_output_dir}`")
    if data.primary_error:
        lines.append(f"- Primary kind: `{data.primary_error.get('kind', 'unknown')}`")
        location = _primary_location(data.primary_error)
        lines.append(f"- Primary location: `{location}`")
        lines.append(f"- Message: {data.primary_error.get('message', 'n/a')}")

    lines.extend(["", "## Patch Suggest"])
    if data.patch_context_dir is not None:
        lines.append(f"- Patch context: `{data.patch_context_dir}`")
    if data.patch_context_status is not None:
        lines.append(f"- Status: `{data.patch_context_status}`")
    if data.patch_context_meta_path is not None:
        lines.append(f"- Meta: `{data.patch_context_meta_path}`")
    lines.append("- Gerrit duplicate lookup: not implemented in this MVP")

    if data.warnings:
        lines.extend(["", "## Warnings"])
        lines.extend(f"- {warning}" for warning in data.warnings)
    if data.errors:
        lines.extend(["", "## Errors"])
        lines.extend(f"- {error}" for error in data.errors)
    return "\n".join(lines) + "\n"

def _primary_location(error: dict[str, Any]) -> str:
    file_value = error.get("file")
    line = error.get("line")
    if isinstance(file_value, str) and line is not None:
        return f"{file_value}:{line}"
    if isinstance(file_value, str):
        return file_value
    return "n/a"

def run_triage(
    options: TriageOptions,
    *,
    subprocess_runner: SubprocessRunner = subprocess.run,
) -> TriageResult:
    """Run one build_id through full-log download, source checkout, analyzer, patch-suggest."""

    output_dir = options.output_dir or options.output_root / options.build_id
    output_dir.mkdir(parents=True, exist_ok=True)
    report_path = output_dir / "report.md"
    report = TriageReportData(
        build_id=options.build_id,
        quickbuild_log_url=f"https://quickbuild.tizen.org/build/{options.build_id}/log",
    )

    try:
        package_buildlog_text = options.package_buildlog_text
        package_buildlog_url = options.package_buildlog_url
        download = download_full_log(options.build_id, cookie_path=options.cookie_path)
        full_log_path = output_dir / "full_log.txt"
        full_log_path.write_text(download.full_log, encoding="utf-8")
        report.full_log_path = full_log_path

        if options.selected_package is not None:
            selected = options.selected_package
        elif options.arch is not None:
            selected, gbs_package = _select_gbs_report_package(
                options.build_id,
                options.arch,
                options.spec_name,
                cookie_path=options.cookie_path,
            )
            if options.package_buildlog_text is None:
                package_buildlog_text = download_gbs_package_buildlog(
                    gbs_package,
                    cookie_path=options.cookie_path,
                )
                package_buildlog_url = gbs_package.buildlog_url
        else:
            if options.spec_name is None:
                raise QuickBuildError(
                    "ARCH_REQUIRED",
                    "QuickBuild single-build triage now requires --arch for automatic "
                    "GBS report failed-package discovery, or --spec-name for the "
                    "legacy full-log fallback.",
                )
            try:
                failed_packages = parse_failed_packages(download.full_log)
            except QuickBuildLogError as exc:
                if exc.code != "FAILED_PACKAGE_NOT_FOUND" or options.spec_name is None:
                    raise
                report.warnings.append(
                    "full log has no fail_pkg/spec_name entries; using explicit "
                    f"--spec-name {options.spec_name!r} and full-log analyzer fallback"
                )
                failed_packages = (
                    FailedPackage(fail_pkg=options.spec_name, spec_name=options.spec_name),
                )
            selected = select_failed_package(failed_packages, spec_name=options.spec_name)
        report.selected_package = selected

        analyzer_input = full_log_path
        if package_buildlog_text is not None:
            analyzer_input = output_dir / f"{selected.spec_name}.buildlog.txt"
            analyzer_input.write_text(package_buildlog_text, encoding="utf-8")
            report.package_buildlog_url = package_buildlog_url
        elif selected.dest_file:
            try:
                package_log = download_package_buildlog(selected.dest_file)
            except QuickBuildError as exc:
                report.warnings.append(
                    f"{exc.code}: {exc}; falling back to full QuickBuild log for analyzer"
                )
            else:
                if package_log is not None:
                    analyzer_input = output_dir / f"{selected.spec_name}.buildlog.txt"
                    analyzer_input.write_text(package_log.text, encoding="utf-8")
                    report.package_buildlog_url = package_log.url
                else:
                    report.warnings.append(
                        "Could not derive package buildlog URL from dest_file; "
                        "falling back to full QuickBuild log for analyzer"
                    )
        report.analyzed_buildlog_path = analyzer_input

        if options.project_key is not None and options.commit_hash is not None:
            project_key = options.project_key
            commit_hash = options.commit_hash
        else:
            pkg_to_commit = parse_build_pkg_list(download.full_log)
            project_key, commit_hash = match_pkg_key(selected.spec_name, pkg_to_commit)
        report.project_key = project_key
        report.commit_hash = commit_hash

        source_fetch = fetch_source_for_commit(
            project_key,
            commit_hash,
            output_dir / "src" / _safe_pkg_dir(selected.spec_name),
            subprocess_runner=subprocess_runner,
            git_ssh_command=options.git_ssh_command or os.environ.get("CI_TRIAGE_GIT_SSH_COMMAND"),
        )
        report.source_fetch = source_fetch
        if source_fetch.status != "source_available":
            return _finish(
                report,
                report_path,
                output_dir,
                status=source_fetch.status,
                error=source_fetch.error or "source checkout failed",
            )

        analyzer_dir = output_dir / "analyzer_output"
        analyzer_result = _run_analyzer(
            analyzer_input,
            src_root=source_fetch.src_root,
            output_dir=analyzer_dir,
            package=selected.spec_name,
            python_executable=options.python_executable,
            subprocess_runner=subprocess_runner,
            extra_pythonpath=options.extra_pythonpath,
        )
        if analyzer_result is not None:
            return _finish(
                report,
                report_path,
                output_dir,
                status="ANALYZER_FAILED",
                error=analyzer_result,
            )

        analyzer_evidence_path = analyzer_dir / "evidence_packet.json"
        evidence_path = output_dir / "evidence_packet.json"
        shutil.copyfile(analyzer_evidence_path, evidence_path)
        report.analyzer_output_dir = analyzer_dir
        report.evidence_packet_path = evidence_path
        packet = _read_packet(evidence_path)
        report.primary_error = _primary_error(packet)

        patch_context_dir = output_dir / "patch_context"
        patch_error = _run_patch_suggest(
            evidence_path,
            src_root=source_fetch.src_root,
            output_dir=patch_context_dir,
            python_executable=options.python_executable,
            subprocess_runner=subprocess_runner,
            extra_pythonpath=options.extra_pythonpath,
        )
        report.patch_context_dir = patch_context_dir
        meta_path = patch_context_dir / "meta.json"
        if meta_path.is_file():
            report.patch_context_meta_path = meta_path
            report.patch_context_status = _read_patch_status(meta_path)
        if patch_error is not None:
            return _finish(
                report,
                report_path,
                output_dir,
                status="PATCH_SUGGEST_FAILED",
                error=patch_error,
            )

        return _finish(report, report_path, output_dir, status="success", error=None, exit_code=0)
    except QuickBuildError as exc:
        return _finish(report, report_path, output_dir, status=exc.code, error=str(exc))
    except QuickBuildLogError as exc:
        return _finish(report, report_path, output_dir, status=exc.code, error=str(exc))
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        return _finish(report, report_path, output_dir, status="TRIAGE_FAILED", error=str(exc))

def discover_sibling_pythonpath(*, launcher_path: Path | None = None) -> tuple[Path, ...]:
    """Return sibling analyzer/patch-suggest scripts paths for direct-folder usage."""

    if launcher_path is None:
        return ()
    triage_root = launcher_path.resolve().parents[1]
    root = triage_root.parent
    candidates = (
        root / "tizen-gbs-log-analysis" / "scripts",
        root / "tizen-gbs-patch-suggest" / "scripts",
    )
    return tuple(path for path in candidates if path.is_dir())

def _failed_package_from_gbs(package: GbsReportPackage) -> FailedPackage:
    return FailedPackage(
        fail_pkg=package.package_path,
        spec_name=package.spec_name,
    )

def _run_checked(
    command: list[str],
    subprocess_runner: SubprocessRunner,
    extra_pythonpath: Sequence[Path],
) -> str | None:
    env = _build_subprocess_env(extra_pythonpath)
    kwargs: dict[str, object] = {"check": True, "text": True}
    if env is not None:
        kwargs["env"] = env
    try:
        subprocess_runner(command, **kwargs)
    except subprocess.CalledProcessError as exc:
        return f"{command[0]} {' '.join(command[1:3])} exited with {exc.returncode}"
    return None

def _build_subprocess_env(extra_pythonpath: Sequence[Path]) -> dict[str, str] | None:
    if not extra_pythonpath:
        return None
    env = os.environ.copy()
    entries = [str(path) for path in extra_pythonpath]
    existing = env.get("PYTHONPATH")
    if existing:
        entries.append(existing)
    env["PYTHONPATH"] = os.pathsep.join(entries)
    return env

def _read_packet(evidence_path: Path) -> dict[str, Any]:
    raw = json.loads(evidence_path.read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise ValueError(f"evidence packet is not an object: {evidence_path}")
    return raw

def _primary_error(packet: dict[str, Any]) -> dict[str, Any] | None:
    value = packet.get("primary_error")
    return value if isinstance(value, dict) else None

def _read_patch_status(meta_path: Path) -> str | None:
    try:
        raw = json.loads(meta_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if isinstance(raw, dict):
        status = raw.get("status")
        return status if isinstance(status, str) else None
    return None

def discover(self, since: datetime) -> list[FailedBuild]:
        """Return failed builds with begin_date at or after since."""
        ...

def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        attrs_map = _attrs_to_map(attrs)
        if tag == "table":
            class_names = _class_names(attrs_map)
            if self._in_builds_table:
                self._table_depth += 1
            elif "builds" in class_names:
                self.saw_builds_table = True
                self._in_builds_table = True
                self._table_depth = 1
            return

        if not self._in_builds_table:
            return

        if tag == "tr":
            self._current_cells = []
            return
        if tag == "td" and self._current_cells is not None:
            self._current_cell = _CellBuilder(class_names=_class_names(attrs_map))
            return
        if tag == "a" and self._current_cell is not None:
            self._current_anchor = _AnchorBuilder(
                class_names=_class_names(attrs_map),
                href=attrs_map.get("href"),
            )

def handle_endtag(self, tag: str) -> None:
        if not self._in_builds_table:
            return

        if tag == "a" and self._current_anchor is not None and self._current_cell is not None:
            self._current_cell.anchors.append(
                _Anchor(
                    class_names=self._current_anchor.class_names,
                    href=self._current_anchor.href,
                    text=_normalize_text("".join(self._current_anchor.text_parts)),
                )
            )
            self._current_anchor = None
            return

        if tag == "td" and self._current_cell is not None and self._current_cells is not None:
            self._current_cells.append(
                _Cell(
                    class_names=self._current_cell.class_names,
                    text=_normalize_text("".join(self._current_cell.text_parts)),
                    anchors=tuple(self._current_cell.anchors),
                )
            )
            self._current_cell = None
            return

        if tag == "tr" and self._current_cells is not None:
            if self._current_cells:
                self.rows.append(_Row(cells=tuple(self._current_cells)))
            self._current_cells = None
            return

        if tag == "table":
            self._table_depth -= 1
            if self._table_depth <= 0:
                self._in_builds_table = False
                self._table_depth = 0

def handle_data(self, data: str) -> None:
        if self._current_cell is not None:
            self._current_cell.text_parts.append(data)
        if self._current_anchor is not None:
            self._current_anchor.text_parts.append(data)

def _parse_builds_table(html_text: str) -> _BuildsTable | None:
    parser = _BuildsTableParser()
    parser.feed(html_text)
    if not parser.saw_builds_table:
        return None
    return _BuildsTable(rows=tuple(parser.rows))

def _row_to_build(row: _Row, *, base_url: str) -> FailedBuild | None:
    if len(row.cells) < 4:
        return None
    id_cell = next((cell for cell in row.cells if "id" in cell.class_names), row.cells[0])
    build_id = id_cell.text.strip()
    if not build_id.isdigit():
        return None

    status_anchor = next(
        (
            anchor
            for cell in row.cells
            for anchor in cell.anchors
            if "build-status" in anchor.class_names
        ),
        None,
    )
    if status_anchor is None:
        return None
    status = _status_from_classes(status_anchor.class_names)
    if status is None:
        return None

    try:
        begin_date = datetime.strptime(row.cells[3].text, "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return None

    return FailedBuild(
        source="quickbuild",
        build_id=build_id,
        version=_strip_snapshot_prefix(status_anchor.text),
        begin_date=begin_date,
        status=status,
        quickbuild_url=f"{base_url.rstrip('/')}/build/{build_id}",
    )

def _status_from_classes(class_names: tuple[str, ...]) -> str | None:
    statuses = [name for name in class_names if name in _STATUS_CLASSES]
    return statuses[0] if len(statuses) == 1 else None

def _strip_snapshot_prefix(version: str) -> str:
    text = version.strip()
    prefix = "[Snapshot]"
    if text.startswith(prefix):
        return text[len(prefix) :].strip()
    return text

def get_verification_record(self, verification_id: str) -> dict[str, str] | None:
        """Fetch one verification record by ID."""

        conn = self.connect()
        try:
            row = conn.execute(
                f"SELECT {', '.join(_VERIFICATION_COLUMNS)} "
                "FROM verification_records WHERE verification_id = ?",
                (verification_id,),
            ).fetchone()
        finally:
            conn.close()
        if row is None:
            return None
        return {column: _row_string(row, column) for column in _VERIFICATION_COLUMNS}

def get_latest_status_row(self, unit_key: str) -> dict[str, str | None] | None:
        """Return the latest status row for one unit key."""

        conn = self.connect()
        try:
            row = conn.execute(
                "SELECT status, verification_id, timestamp FROM unit_status_log WHERE unit_key = ? "
                "ORDER BY timestamp DESC, log_id DESC LIMIT 1",
                (unit_key,),
            ).fetchone()
        finally:
            conn.close()
        if row is None:
            return None
        return {
            "status": _row_string(row, "status"),
            "verification_id": _row_optional_string(row, "verification_id"),
            "timestamp": _row_string(row, "timestamp"),
        }

def get_submission(self, submission_key: str) -> dict[str, str | None] | None:
        """Fetch one submitted Gerrit record by submission key."""

        conn = self.connect()
        try:
            row = conn.execute(
                "SELECT submission_key, verification_id, submitted_at, action, gerrit_change_id "
                "FROM submissions WHERE submission_key = ?",
                (submission_key,),
            ).fetchone()
        finally:
            conn.close()
        if row is None:
            return None
        return {
            "submission_key": _row_string(row, "submission_key"),
            "verification_id": _row_string(row, "verification_id"),
            "submitted_at": _row_string(row, "submitted_at"),
            "action": _row_string(row, "action"),
            "gerrit_change_id": _row_optional_string(row, "gerrit_change_id"),
        }

def get_status_log(self, unit_key: str) -> tuple[dict[str, str | None], ...]:
        """Read status rows for tests and audit views."""

        conn = self.connect()
        try:
            rows = conn.execute(
                "SELECT unit_key, status, timestamp, verification_id, reason "
                "FROM unit_status_log WHERE unit_key = ? ORDER BY timestamp ASC, log_id ASC",
                (unit_key,),
            ).fetchall()
        finally:
            conn.close()
        return tuple(
            {
                "unit_key": _row_string(row, "unit_key"),
                "status": _row_string(row, "status"),
                "timestamp": _row_string(row, "timestamp"),
                "verification_id": _row_optional_string(row, "verification_id"),
                "reason": _row_optional_string(row, "reason"),
            }
            for row in rows
        )

def _row_string(row: sqlite3.Row, key: str) -> str:
    value: Any = row[key]
    if not isinstance(value, str):
        raise TypeError(f"expected text value for {key}")
    return value

def _row_optional_string(row: sqlite3.Row, key: str) -> str | None:
    value: Any = row[key]
    if value is None:
        return None
    if not isinstance(value, str):
        raise TypeError(f"expected optional text value for {key}")
    return value

def build_submission_key(*, failure_key: str, verified_tree_sha: str) -> str:
    """Build the stable private key for one verified tree submitted for a failure."""

    raw_key = f"{failure_key}:{verified_tree_sha}"
    return hashlib.sha256(raw_key.encode("utf-8")).hexdigest()

def failure_key_sha12(failure_key: str) -> str:
    """Return a deterministic 12-character hash for compact Gerrit topics."""

    return hashlib.sha256(failure_key.encode("utf-8")).hexdigest()[:12]

def write_pass_record(db: StateDatabase, record: VerificationRecord) -> str:
    """Write a PASS record and mark the failure GERRIT_READY.

    This is the only public API that may produce a GERRIT_READY state. It ties the
    ready state to a concrete verification record in the same transaction.
    """

    if record.result != "PASS":
        raise ValueError("verification records currently support only PASS results")
    return db.insert_pass_record(_record_to_values(record))

def get_record(db: StateDatabase, verification_id: str) -> VerificationRecord | None:
    """Fetch one PASS verification record."""

    values = db.get_verification_record(verification_id)
    if values is None:
        return None
    return VerificationRecord(**values)

def get_latest_status(db: StateDatabase, unit_key: str) -> str | None:
    """Return the latest append-only status for one unit."""

    return db.get_latest_status(unit_key)

def get_latest_status_row(db: StateDatabase, unit_key: str) -> LatestStatusRow | None:
    """Return the latest append-only status row for one unit."""

    row = db.get_latest_status_row(unit_key)
    if row is None:
        return None
    status = row["status"]
    timestamp = row["timestamp"]
    if not isinstance(status, str) or not isinstance(timestamp, str):
        raise TypeError("latest status row is missing status or timestamp")
    return LatestStatusRow(
        status=status,
        verification_id=row["verification_id"],
        timestamp=timestamp,
    )

def _record_to_values(record: VerificationRecord) -> dict[str, str]:
    values = asdict(record)
    return {key: value for key, value in values.items() if isinstance(value, str)}

def _format_and_apply_patch(
    edit_spec_path: Path,
    *,
    src_root: Path,
    output_patch: Path,
    subprocess_runner: SubprocessRunner,
) -> _ApplyPatchResult:
    output_patch = output_patch.resolve()
    result = format_patch(
        FormatPatchOptions(
            src_root=src_root,
            edit_spec=edit_spec_path,
            output=output_patch,
            check=True,
        ),
        subprocess_runner=subprocess_runner,
    )
    if result.exit_code != 0:
        if result.error_code == "no_changes":
            return _ApplyPatchResult(no_changes=True)
        return _ApplyPatchResult(error=f"{result.error_code}: {result.error}")
    try:
        _run(
            ["git", "-C", str(src_root), "apply", str(output_patch)],
            subprocess_runner,
            check=True,
        )
    except subprocess.CalledProcessError as exc:
        return _ApplyPatchResult(error=f"git apply failed with exit {exc.returncode}")
    return _ApplyPatchResult()

def _run_gbs_build(
    options: BuildVerifyOptions,
    worktree: Path,
    subprocess_runner: SubprocessRunner,
) -> _BuildProcessResult:
    command = _gbs_command(options)
    try:
        completed = _run(
            command,
            subprocess_runner,
            cwd=worktree,
            timeout=options.wall_timeout,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        return _BuildProcessResult(
            returncode=124,
            stdout=_string_or_empty(exc.stdout),
            stderr=_string_or_empty(exc.stderr),
            timed_out=True,
            error=f"gbs build timed out after {options.wall_timeout}s",
        )
    return _BuildProcessResult(
        returncode=completed.returncode,
        stdout=completed.stdout or "",
        stderr=completed.stderr or "",
    )

def _allowed_paths(edit_spec: dict[str, Any]) -> set[str]:
    raw_edits = edit_spec.get("edits")
    if not isinstance(raw_edits, list):
        return set()
    paths: set[str] = set()
    for raw in raw_edits:
        if not isinstance(raw, dict):
            continue
        file_value = raw.get("file")
        if isinstance(file_value, str):
            normalized = os.path.normpath(file_value.replace("\\", "/")).replace("\\", "/")
            paths.add(normalized.strip("/"))
    return paths

def _run_git_diff_check(worktree: Path, subprocess_runner: SubprocessRunner) -> str | None:
    result = _run(
        ["git", "-C", str(worktree), "diff", "--check"],
        subprocess_runner,
        check=False,
    )
    if result.returncode == 0:
        return None
    return result.stdout or result.stderr or "git diff --check failed"

def _canonical_diff_sha256(
    worktree: Path,
    base_commit: str,
    verified_commit_sha: str,
    subprocess_runner: SubprocessRunner,
) -> str:
    diff = _git_stdout(
        worktree,
        ["diff", "--full-index", "--binary", f"{base_commit}..{verified_commit_sha}"],
        subprocess_runner,
        allow_empty=True,
    )
    return _sha256_text(diff)

def _git(
    worktree: Path,
    args: list[str],
    subprocess_runner: SubprocessRunner,
) -> None:
    _run(["git", "-C", str(worktree), *args], subprocess_runner, check=True)

def _read_json(path: Path) -> dict[str, Any]:
    raw = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise ValueError(f"expected JSON object: {path}")
    return raw

def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

def _build_subprocess_env(extra_pythonpath: Sequence[Path]) -> dict[str, str] | None:
    if not extra_pythonpath:
        return None
    env = os.environ.copy()
    entries = [str(path) for path in extra_pythonpath]
    existing = env.get("PYTHONPATH")
    if existing:
        entries.append(existing)
    env["PYTHONPATH"] = os.pathsep.join(entries)
    return env

def _string_or_empty(value: str | bytes | None) -> str:
    if value is None:
        return ""
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    return value

def build_verify_to_json(result: BuildVerifyResult, path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(result.to_dict(), indent=2, sort_keys=True) + "\n", encoding="utf-8")

def default_extra_pythonpath() -> tuple[Path, ...]:
    return discover_sibling_pythonpath(
        launcher_path=Path(__file__).resolve().parents[2] / "run_ci_triage.py"
    )

def to_dict(self) -> dict[str, str]:
        return {
            "normalized_file": self.normalized_file,
            "diagnostic_code": self.diagnostic_code,
            "anchor": self.anchor,
            "kind": self.kind,
            "message": self.message,
        }

def write_convergence_result(result: ConvergenceResult, output: Path) -> None:
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(
        json.dumps(result.to_dict(), indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )

def touched_files_from_json(path: Path) -> set[str]:
    raw = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise ValueError("touched-files JSON must be an object")
    files = raw.get("files")
    if not isinstance(files, list):
        raise ValueError("touched-files JSON must contain a files list")
    result: set[str] = set()
    for item in files:
        if not isinstance(item, str) or not item:
            raise ValueError("touched-files files entries must be non-empty strings")
        result.add(_normalize_file(item))
    return result

def _diagnostic_code(data: dict[str, Any]) -> str:
    for key in ("diagnostic_code", "warning_option", "semantic_class"):
        value = data.get(key)
        if isinstance(value, str) and value:
            return value
    message = _string(data.get("message"))
    for token in _WARNING_OPTION_RE.findall(message):
        if token != "-Werror":
            return str(token)
    return "<none>"

def _anchor(primary: dict[str, Any]) -> str:
    for key in ("source_anchor", "symbol"):
        value = primary.get(key)
        if isinstance(value, str) and value:
            return value
    snippet = primary.get("source_snippet")
    if isinstance(snippet, str) and snippet.strip():
        return _stable_hash(_normalize_message(snippet))
    message = _string(primary.get("message"))
    quoted = re.findall(r"[`']([A-Za-z_][A-Za-z0-9_]*)[`']", message)
    if quoted:
        return str(quoted[0])
    identifiers = [
        token
        for token in _IDENTIFIER_RE.findall(message)
        if token.lower() not in {"error", "warning", "werror", "deprecated"}
    ]
    if identifiers:
        return str(identifiers[0])
    return _stable_hash(_normalize_message(message))

def _regression_reason(
    current_evidence: dict[str, Any],
    previous_evidence: dict[str, Any],
    *,
    touched_files: set[str] | None,
) -> str | None:
    if not touched_files:
        return None
    previous_by_type: dict[tuple[str, tuple[str, ...], str], set[str]] = {}
    for cluster in _clusters(previous_evidence, touched_files=touched_files):
        previous_by_type.setdefault(cluster.type_key, set()).update(cluster.files)

    for cluster in _clusters(current_evidence, touched_files=touched_files):
        if not cluster.source_level:
            continue
        previous_files = previous_by_type.get(cluster.type_key)
        if previous_files is None:
            added_files = set(cluster.files)
            token = "new_source_cluster_in_touched"
        else:
            added_files = set(cluster.files) - previous_files
            token = "expanded_source_cluster_in_touched"
        touched_added = sorted(added_files & touched_files)
        if touched_added:
            return f"{token}:{','.join(touched_added)}"
    return None

def _regression_suspected(
    current_evidence: dict[str, Any],
    *,
    previous_error_count: int,
    current_error_count: int,
    touched_files: set[str] | None,
) -> bool:
    if not touched_files:
        return False
    if (
        current_error_count < previous_error_count * 2
        or current_error_count - previous_error_count < 20
    ):
        return False
    affected: set[str] = set()
    for cluster in _clusters(current_evidence, touched_files=touched_files):
        if cluster.source_level:
            affected.update(cluster.files)
    return bool(affected & touched_files)

def _clusters(evidence: dict[str, Any], *, touched_files: set[str] | None) -> list[_ClusterView]:
    raw = evidence.get("error_clusters")
    if not isinstance(raw, dict):
        return []
    raw_clusters = raw.get("clusters")
    if not isinstance(raw_clusters, list):
        return []
    result: list[_ClusterView] = []
    for item in raw_clusters:
        if not isinstance(item, dict):
            continue
        result.append(_cluster_view(item, touched_files=touched_files))
    return result

def _cluster_diagnostic_code(cluster: dict[str, Any]) -> str:
    for key in ("warning_option", "diagnostic_code", "semantic_class"):
        value = cluster.get(key)
        if isinstance(value, str) and value:
            return value
    for location in _location_dicts(cluster):
        code = _diagnostic_code(location)
        if code != "<none>":
            return code
    return "<none>"

def _cluster_files(cluster: dict[str, Any], *, touched_files: set[str] | None) -> set[str]:
    files = set()
    raw_files = cluster.get("files")
    if isinstance(raw_files, list):
        for item in raw_files:
            if isinstance(item, str) and item:
                files.add(_normalize_file(item, touched_files))
    for location in _location_dicts(cluster):
        file_value = location.get("file")
        if isinstance(file_value, str) and file_value:
            files.add(_normalize_file(file_value, touched_files))
    return files

def _location_dicts(cluster: dict[str, Any]) -> list[dict[str, Any]]:
    locations: list[dict[str, Any]] = []
    for key in ("locations_sample", "locations"):
        value = cluster.get(key)
        if not isinstance(value, list):
            continue
        for item in value:
            if isinstance(item, dict):
                locations.append(item)
    return locations

def _is_source_level_cluster(kind: str, diagnostic_kinds: tuple[str, ...]) -> bool:
    if kind in SOURCE_CLUSTER_KINDS:
        return True
    return bool(set(diagnostic_kinds) & SOURCE_DIAGNOSTIC_KINDS)

def _error_count(evidence: dict[str, Any] | None) -> int:
    if evidence is None:
        return 0
    clusters = _clusters(evidence, touched_files=None)
    if clusters:
        return sum(cluster.count for cluster in clusters if _is_error_cluster(cluster))
    primary = evidence.get("primary_error")
    return 1 if isinstance(primary, dict) else 0

def _normalize_file(path: str, touched_files: set[str] | None = None) -> str:
    value = path.replace("\\", "/").strip()
    value = re.sub(r"(:\d+){1,2}$", "", value)
    for prefix in sorted(DEFAULT_BUILD_PREFIXES, key=len, reverse=True):
        normalized_prefix = prefix.replace("\\", "/")
        if value.startswith(normalized_prefix):
            value = value[len(normalized_prefix) :]
            parts = [part for part in value.split("/") if part]
            if len(parts) > 1 and _BUILD_PACKAGE_RE.match(parts[0]):
                value = "/".join(parts[1:])
            break
    value = value.lstrip("./")
    if touched_files:
        for touched in sorted(touched_files, key=len, reverse=True):
            if value == touched or value.endswith("/" + touched):
                return touched
    return value

def _normalize_message(message: str) -> str:
    value = message.lower()
    value = re.sub(r"(:\d+){1,2}", ":#", value)
    value = re.sub(r"\b\d+\b", "#", value)
    value = re.sub(r"\s+", " ", value)
    return value.strip()

def _string_list(value: object) -> list[str]:
    if not isinstance(value, list):
        return []
    return [item for item in value if isinstance(item, str)]

def _validate_schema(edit_spec: dict[str, Any]) -> list[dict[str, Any]]:
    if edit_spec.get("schema_version") != EDIT_SPEC_SCHEMA:
        raise EditSpecViolation("unsupported edit_spec schema_version")
    patch_name = edit_spec.get("patch_name")
    if not isinstance(patch_name, str) or not patch_name:
        raise EditSpecViolation("edit_spec patch_name must be a non-empty string")
    edits = edit_spec.get("edits")
    if not isinstance(edits, list) or not edits:
        raise EditSpecViolation("edit_spec edits must be a non-empty list")
    validated: list[dict[str, Any]] = []
    for index, raw_edit in enumerate(edits):
        if not isinstance(raw_edit, dict):
            raise EditSpecViolation(f"edit {index} must be an object")
        for required in ("file", "old", "new"):
            if required not in raw_edit:
                raise EditSpecViolation(f"edit {index} missing required field: {required}")
        if not isinstance(raw_edit["file"], str) or not raw_edit["file"]:
            raise EditSpecViolation(f"edit {index} file must be a non-empty string")
        if not isinstance(raw_edit["old"], str) or raw_edit["old"] == "":
            raise EditSpecViolation(f"edit {index} old must be a non-empty string")
        if not isinstance(raw_edit["new"], str):
            raise EditSpecViolation(f"edit {index} new must be a string")
        line = raw_edit.get("line")
        if line is not None and (not isinstance(line, int) or line <= 0):
            raise EditSpecViolation(f"edit {index} line must be a positive integer")
        validated.append(raw_edit)
    return validated

def _validate_target_path(file_value: str, root: Path) -> Path:
    normalized = unicodedata.normalize("NFC", file_value)
    if normalized == "":
        raise EditSpecViolation("edit file path is empty")
    if normalized.startswith("/") or os.path.isabs(normalized):
        raise EditSpecViolation("absolute edit file paths are not allowed")

    norm = posixpath.normpath(normalized.replace("\\", "/"))
    if norm in ("", "."):
        raise EditSpecViolation("edit file path is empty")
    if norm == ".." or norm.startswith("../"):
        raise EditSpecViolation("edit file path escapes the worktree")
    parts = tuple(part for part in norm.split("/") if part and part != ".")
    if any(part == ".." for part in parts):
        raise EditSpecViolation("edit file path contains parent traversal")
    if ".git" in parts:
        raise EditSpecViolation("edit file path targets .git internals")

    current = root
    root_real = root.resolve()
    for part in parts:
        current = current / part
        if current.is_symlink():
            real = current.resolve()
            if not _is_relative_to(real, root_real):
                raise EditSpecViolation(f"edit file path symlink escapes worktree: {file_value}")

    if not _is_relative_to(current.resolve(), root_real):
        raise EditSpecViolation("edit file path escapes the worktree")
    if not current.exists():
        raise EditSpecViolation(f"edit target does not exist: {file_value}")
    if current.is_dir():
        raise EditSpecViolation(f"edit target is a directory: {file_value}")
    if not current.is_file():
        raise EditSpecViolation(f"edit target is not a regular file: {file_value}")
    return current

def _locate_edit(file_path: Path, old: str, line: object) -> _LocatedEdit:
    text = file_path.read_text(encoding="utf-8", errors="surrogateescape")
    if isinstance(line, int):
        start = _find_old_from_line(text, old, line)
    else:
        start = _find_unique_old(text, old)
    return _LocatedEdit(file_path=file_path, start=start, end=start + len(old))

def _find_old_from_line(text: str, old: str, line: int) -> int:
    line_starts = _line_starts(text)
    if line > len(line_starts):
        raise EditSpecViolation(f"edit line {line} is outside the target file")
    line_start = line_starts[line - 1]
    next_line_start = line_starts[line] if line < len(line_starts) else len(text)
    found = text.find(old, line_start)
    if found < 0:
        raise EditSpecViolation("edit old text was not found at or after the requested line")
    if "\n" not in old and found >= next_line_start:
        raise EditSpecViolation("edit old text was not found on the requested line")
    return found

def _find_unique_old(text: str, old: str) -> int:
    first = text.find(old)
    if first < 0:
        raise EditSpecViolation("edit old text was not found")
    second = text.find(old, first + 1)
    if second >= 0:
        raise EditSpecViolation("edit old text is not unique without a line anchor")
    return first

def _line_starts(text: str) -> list[int]:
    starts = [0]
    for index, char in enumerate(text):
        if char == "\n" and index + 1 < len(text):
            starts.append(index + 1)
    return starts

def _check_no_overlaps(file_path: Path, edits: list[_LocatedEdit]) -> None:
    sorted_edits = sorted(edits, key=lambda edit: edit.start)
    previous: _LocatedEdit | None = None
    for edit in sorted_edits:
        if previous is not None and edit.start < previous.end:
            raise EditSpecViolation(f"overlapping edits for {file_path}")
        previous = edit

def _is_relative_to(path: Path, root: Path) -> bool:
    try:
        path.relative_to(root)
    except ValueError:
        return False
    return True

def _primary_error(evidence: Mapping[str, Any]) -> Mapping[str, Any]:
    primary = evidence.get("primary_error")
    if isinstance(primary, Mapping):
        return primary
    return evidence

def _match_denylist(
    primary: Mapping[str, Any],
    build_log: str,
) -> FailureClassification | None:
    haystack = "\n".join(
        (
            _string(primary.get("message")),
            _string(primary.get("details")),
            build_log,
        )
    )
    for rule in DENYLIST_RULES:
        if rule.pattern.search(haystack):
            return FailureClassification(
                repair_allowed=REPAIR_DENIED,
                failure_class=rule.failure_class,
                confidence=1.0,
                matched_rule=f"denylist:{rule.rule_id}",
                reason=rule.reason,
            )
    return None

def _heuristic_classification(primary: Mapping[str, Any]) -> FailureClassification:
    kind = _kind(primary)
    if kind in SOURCE_KINDS:
        return _source_diagnostic_classification(primary)

    if kind.startswith("link") and _message_has_source_symbol(primary):
        return FailureClassification(
            repair_allowed=REPAIR_DENIED,
            failure_class="uncertain",
            confidence=0.7,
            matched_rule="heuristic:link_symbol",
            reason=(
                "linker error may be source-related, but confidence is below "
                "automatic repair gate"
            ),
        )

    return FailureClassification(
        repair_allowed=REPAIR_DENIED,
        failure_class="uncertain",
        confidence=0.2,
        matched_rule="heuristic:unsupported_kind",
        reason=f"unsupported or non-source analyzer kind: {kind or '<missing>'}",
    )

def _source_diagnostic_classification(primary: Mapping[str, Any]) -> FailureClassification:
    if not _has_source_location(primary):
        return FailureClassification(
            repair_allowed=REPAIR_DENIED,
            failure_class="source_unreachable",
            confidence=0.4,
            matched_rule="heuristic:missing_source_location",
            reason="source diagnostic has no reliable file/line location",
        )

    if not _source_reachable(primary):
        return FailureClassification(
            repair_allowed=REPAIR_DENIED,
            failure_class="source_unreachable",
            confidence=0.55,
            matched_rule="heuristic:source_unreachable",
            reason="source file could not be mapped to the local source root",
        )

    if not _source_owned(primary):
        return FailureClassification(
            repair_allowed=REPAIR_DENIED,
            failure_class="source_unreachable",
            confidence=0.55,
            matched_rule="heuristic:source_not_owned",
            reason="diagnostic path is not project-owned source",
        )

    if not _probably_fixable(primary):
        return FailureClassification(
            repair_allowed=REPAIR_NEEDS_CONFIRMATION,
            failure_class="source_repairable_unverified_type",
            confidence=0.65,
            matched_rule="heuristic:type_unknown",
            reason=(
                "source-located and source-owned, but the diagnostic type is not on the "
                "auto-fix whitelist; repair is possible with human confirmation of the fix"
            ),
        )

    return FailureClassification(
        repair_allowed=REPAIR_AUTO,
        failure_class="source_repairable",
        confidence=0.95,
        matched_rule="heuristic:source_werror_or_compile_error",
        reason="source-located, source-owned, probably-fixable compiler/werror diagnostic",
    )

def _has_source_location(primary: Mapping[str, Any]) -> bool:
    file_value = primary.get("file") or primary.get("normalized_file")
    line_value = primary.get("line")
    return (
        isinstance(file_value, str)
        and bool(file_value)
        and isinstance(line_value, int)
        and line_value > 0
    )

def _source_reachable(primary: Mapping[str, Any]) -> bool:
    value = primary.get("source_reachable")
    if isinstance(value, bool):
        return value
    status = primary.get("source_resolution_status")
    if isinstance(status, str):
        return status == "mapped_to_source_root"
    return _looks_project_source_path(_source_file(primary))

def _source_owned(primary: Mapping[str, Any]) -> bool:
    value = primary.get("source_owned")
    if isinstance(value, bool):
        return value
    status = primary.get("source_ownership_status")
    if isinstance(status, str):
        return status == "project_owned"
    return _looks_project_source_path(_source_file(primary))

def _probably_fixable(primary: Mapping[str, Any]) -> bool:
    for key in ("type_fixability", "provisional_fixability", "fixability"):
        value = primary.get(key)
        if isinstance(value, str):
            return value == "probably_fixable"
    message = _string(primary.get("message")).lower()
    return any(
        marker in message
        for marker in (
            "use of undeclared",
            "no member named",
            "invalid conversion",
            "deprecated",
            "[-werror",
        )
    )

def _looks_project_source_path(path: str | None) -> bool:
    if not path:
        return False
    lowered = path.replace("\\", "/").lower()
    if lowered.startswith(SYSTEM_PREFIXES):
        return False
    parts = {part for part in lowered.split("/") if part}
    return not bool(parts & SUSPECT_PATH_PARTS)

def _source_file(primary: Mapping[str, Any]) -> str | None:
    file_value = primary.get("normalized_file") or primary.get("file")
    if isinstance(file_value, str) and file_value:
        return file_value
    return None

def _message_has_source_symbol(primary: Mapping[str, Any]) -> bool:
    message = _string(primary.get("message"))
    return bool(re.search(r"`?[A-Za-z_][A-Za-z0-9_]*`?", message))

def gerrit_submit(
    options: GerritSubmitOptions,
    *,
    subprocess_runner: SubprocessRunner = subprocess.run,
) -> GerritSubmitResult:
    """Validate a verified worktree and return a dry-run Gerrit push command."""

    record = get_record(options.state_db, options.verification_id)
    if record is None:
        return _result(
            action="record_not_found",
            verification_id=options.verification_id,
            reason="verification record does not exist",
            options=options,
        )

    submission_key = build_submission_key(
        failure_key=record.failure_key,
        verified_tree_sha=record.verified_tree_sha,
    )
    latest = get_latest_status_row(options.state_db, record.failure_key)
    if latest is None or latest.status != GERRIT_READY:
        return _record_result(
            action="rejected_not_ready",
            record=record,
            submission_key=submission_key,
            options=options,
            reason="latest status is not GERRIT_READY",
        )
    if latest.verification_id != options.verification_id:
        return _record_result(
            action="rejected_not_ready",
            record=record,
            submission_key=submission_key,
            options=options,
            reason="latest GERRIT_READY belongs to a different verification_id",
        )

    worktree = Path(record.worktree_path)
    if not worktree.is_dir():
        return _record_result(
            action="rejected_worktree_missing",
            record=record,
            submission_key=submission_key,
            options=options,
            reason="verified worktree is missing; refusing to fall back to patch files",
        )

    mismatch = _verification_mismatch(record, worktree, subprocess_runner)
    if mismatch is not None:
        return _record_result(
            action="rejected_verification_mismatch",
            record=record,
            submission_key=submission_key,
            options=options,
            reason=mismatch,
        )
    dirty = _dirty_reason(worktree, subprocess_runner)
    if dirty is not None:
        return _record_result(
            action="rejected_worktree_dirty",
            record=record,
            submission_key=submission_key,
            options=options,
            reason=dirty,
        )

    warnings = _target_warnings(record, options, subprocess_runner)
    if options.submit_mode == "submit":
        return _record_result(
            action="rejected_submit_not_enabled",
            record=record,
            submission_key=submission_key,
            options=options,
            reason="Stage 1 submit mode is disabled; no git push was executed",
            warnings=warnings,
        )

    if options.state_db.get_submission(submission_key) is not None:
        return _record_result(
            action="skipped_duplicate",
            record=record,
            submission_key=submission_key,
            options=options,
            reason="submission key already exists",
            warnings=warnings,
        )

    command_argv = _push_command(record, options)
    remote_unknown = _target_head_unknown_warning(warnings)
    return _record_result(
        action="dry_run_unverified_remote" if remote_unknown else "dry_run",
        record=record,
        submission_key=submission_key,
        options=options,
        command_argv=command_argv,
        reason=(
            "remote state could not be verified "
            f"({remote_unknown}); duplicate/drift checks did not run"
            if remote_unknown
            else None
        ),
        warnings=[
            *warnings,
            (
                "verified worktree remains protected; run "
                "ci_triage release-worktree --verification-id "
                f"{options.verification_id} --state-db <path> when it is no longer needed"
            ),
        ],
    )

def _target_head_unknown_warning(warnings: list[str]) -> str | None:
    for warning in warnings:
        if warning.startswith("target_head_unknown:"):
            reason = warning.removeprefix("target_head_unknown:")
            if reason == "ls_remote_failed":
                return "ls-remote failed"
            return reason.replace("_", " ")
    return None

def release_verified_worktree(
    db: StateDatabase,
    verification_id: str,
) -> ReleaseWorktreeResult:
    """Release the protected worktree marker for one verification record."""

    record = get_record(db, verification_id)
    if record is None:
        return ReleaseWorktreeResult(
            action="record_not_found",
            verification_id=verification_id,
            worktree_path=None,
            released=False,
            reason="verification record does not exist",
        )
    released = release_worktree_protection(record.worktree_path)
    return ReleaseWorktreeResult(
        action="released" if released else "not_protected",
        verification_id=verification_id,
        worktree_path=record.worktree_path,
        released=released,
    )

def write_gerrit_submit_result(result: GerritSubmitResult, output: Path) -> None:
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(
        json.dumps(result.to_dict(), indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )

def write_release_result(result: ReleaseWorktreeResult, output: Path) -> None:
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(
        json.dumps(result.to_dict(), indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )

def exit_code_for_submit(result: GerritSubmitResult) -> int:
    if result.action == "record_not_found":
        return 2
    if result.action.startswith("rejected_"):
        return 3
    return 0

def _verification_mismatch(
    record: VerificationRecord,
    worktree: Path,
    subprocess_runner: SubprocessRunner,
) -> str | None:
    try:
        head = _git_stdout(worktree, ["rev-parse", "HEAD"], subprocess_runner)
        tree = _git_stdout(worktree, ["rev-parse", "HEAD^{tree}"], subprocess_runner)
    except subprocess.CalledProcessError as exc:
        return f"failed to read verified git object: exit {exc.returncode}"
    if head != record.verified_commit_sha:
        return "verified commit SHA does not match worktree HEAD"
    if tree != record.verified_tree_sha:
        return "verified tree SHA does not match worktree HEAD tree"
    return None

def _dirty_reason(worktree: Path, subprocess_runner: SubprocessRunner) -> str | None:
    tracked = _run_git(worktree, ["diff", "--quiet", "HEAD", "--"], subprocess_runner)
    if tracked.returncode != 0:
        return "tracked worktree changes exist after verified commit"
    staged = _run_git(worktree, ["diff", "--cached", "--quiet"], subprocess_runner)
    if staged.returncode != 0:
        return "staged changes exist after verified commit"
    return None

def _target_warnings(
    record: VerificationRecord,
    options: GerritSubmitOptions,
    subprocess_runner: SubprocessRunner,
) -> list[str]:
    branch = _target_branch(options.submit_target)
    if branch is None:
        return ["target_head_unknown:sandbox_target_not_checked"]
    remote = _remote_url(record, options)
    try:
        completed = subprocess_runner(
            ["git", "ls-remote", remote, f"refs/heads/{branch}"],
            check=False,
            text=True,
            capture_output=True,
            env=_subprocess_env(options.git_ssh_command),
        )
    except (OSError, subprocess.SubprocessError) as exc:
        return [f"target_head_unknown:{exc}"]
    if completed.returncode != 0:
        return ["target_head_unknown:ls_remote_failed"]
    first = (completed.stdout or "").splitlines()[0:1]
    if not first:
        return ["target_head_unknown:not_found"]
    target_head = first[0].split()[0]
    if target_head != record.base_commit:
        return [f"target_branch_drifted:{target_head}"]
    return []

def _target_branch(submit_target: str) -> str | None:
    if submit_target.startswith("refs/for/"):
        branch = submit_target.removeprefix("refs/for/")
        return branch.split("%", 1)[0]
    if submit_target.startswith("refs/drafts/"):
        return submit_target.removeprefix("refs/drafts/").split("%", 1)[0]
    if submit_target.startswith("refs/heads/sandbox/"):
        return None
    if submit_target.startswith("refs/heads/"):
        return submit_target.removeprefix("refs/heads/")
    return None

def _git_stdout(
    worktree: Path,
    args: list[str],
    subprocess_runner: SubprocessRunner,
) -> str:
    completed = _run_git(worktree, args, subprocess_runner, check=True)
    return (completed.stdout or "").strip()

def _run_git(
    worktree: Path,
    args: list[str],
    subprocess_runner: SubprocessRunner,
    *,
    check: bool = False,
) -> subprocess.CompletedProcess[str]:
    return subprocess_runner(
        ["git", "-C", str(worktree), *args],
        check=check,
        text=True,
        capture_output=True,
    )

def _build_id_from_failure_key(failure_key: str) -> str:
    parts = failure_key.split("/", 2)
    return parts[1] if len(parts) > 1 else ""

def is_protected(worktree_path: str | Path) -> bool:
    """Return whether a disposable worktree is protected from automatic cleanup."""

    return (Path(worktree_path) / PROTECTED_FILENAME).is_file()

def check_disk_and_maybe_cleanup(
    workspace_root: str,
    min_free_bytes: int = DEFAULT_MIN_FREE_BYTES,
) -> list[str]:
    """Clean oldest disposable worktrees when free space is below the threshold."""

    root = Path(workspace_root).resolve()
    warnings: list[str] = []
    if not root.exists():
        return warnings
    free = shutil.disk_usage(root).free
    if free >= min_free_bytes:
        return warnings

    skipped_protected: list[str] = []
    for handle in _oldest_worktrees(root):
        if is_protected(handle.path):
            skipped_protected.append(handle.path)
            continue
        try:
            cleanup_worktree(handle)
        except (OSError, WorkspaceViolation, subprocess.CalledProcessError) as exc:
            warnings.append(f"failed to clean {handle.path}: {exc}")
            continue
        warnings.append(f"cleaned disposable worktree {handle.path}")
        if shutil.disk_usage(root).free >= min_free_bytes:
            break
    if shutil.disk_usage(root).free < min_free_bytes:
        if skipped_protected:
            warnings.append(
                "disk_low_protected_worktrees_skipped: " + ", ".join(skipped_protected)
            )
        warnings.append(
            f"free space below threshold after cleanup: {shutil.disk_usage(root).free} bytes"
        )
    return warnings

def _verify_cleanup_handle(handle: DisposableWorktree) -> None:
    marker_path = Path(handle.marker_path)
    if not marker_path.is_file():
        raise WorkspaceViolation(f"missing disposable worktree marker: {marker_path}")

    marker = _read_marker(marker_path)
    handle_root = Path(handle.workspace_root).resolve()
    handle_path = Path(handle.path).resolve()
    marker_root = Path(str(marker.get("workspace_root", ""))).resolve()

    if marker_root != handle_root:
        raise WorkspaceViolation("marker workspace_root does not match handle workspace_root")
    if not _is_relative_to(handle_path, handle_root):
        raise WorkspaceViolation("worktree path is outside workspace_root")

def _oldest_worktrees(root: Path) -> list[DisposableWorktree]:
    handles: list[DisposableWorktree] = []
    for child in root.iterdir():
        if not child.is_dir() or not child.name.startswith("iter_"):
            continue
        marker_path = child / MARKER_FILENAME
        if not marker_path.is_file():
            continue
        try:
            marker = _read_marker(marker_path)
            baseline_repo = str(marker["baseline_repo"])
            base_commit = str(marker["base_commit"])
            iter_index = int(marker["iter_index"])
        except (KeyError, TypeError, ValueError, json.JSONDecodeError, OSError):
            continue
        handles.append(
            DisposableWorktree(
                path=str(child.resolve()),
                baseline_repo=baseline_repo,
                base_commit=base_commit,
                workspace_root=str(root),
                iter_index=iter_index,
                marker_path=str(marker_path),
            )
        )
    return sorted(handles, key=lambda handle: handle.iter_index)

def _read_marker(marker_path: Path) -> dict[str, Any]:
    raw = json.loads(marker_path.read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise WorkspaceViolation("disposable worktree marker is not a JSON object")
    return raw

def _is_relative_to(path: Path, root: Path) -> bool:
    try:
        path.relative_to(root)
    except ValueError:
        return False
    return True

def _exclude_private_files(worktree_path: Path) -> None:
    result = subprocess.run(
        ["git", "-C", str(worktree_path), "rev-parse", "--git-path", "info/exclude"],
        check=True,
        text=True,
        capture_output=True,
    )
    exclude_path = Path(result.stdout.strip())
    if not exclude_path.is_absolute():
        exclude_path = worktree_path / exclude_path
    exclude_path.parent.mkdir(parents=True, exist_ok=True)
    current = exclude_path.read_text(encoding="utf-8") if exclude_path.exists() else ""
    lines = set(current.splitlines())
    missing = [
        filename for filename in (MARKER_FILENAME, PROTECTED_FILENAME) if filename not in lines
    ]
    if missing:
        with exclude_path.open("a", encoding="utf-8") as handle:
            if current and not current.endswith("\n"):
                handle.write("\n")
            for filename in missing:
                handle.write(f"{filename}\n")

