def primary_error(packet: dict[str, Any]) -> dict[str, Any]:
    """Return the primary error object when present."""

    value = packet.get("primary_error")
    return value if isinstance(value, dict) else {}

def primary_kind(packet: dict[str, Any]) -> str:
    """Return the primary error kind."""

    return str(primary_error(packet).get("kind") or "")

def primary_message(packet: dict[str, Any]) -> str:
    """Return the primary error message."""

    return str(primary_error(packet).get("message") or "")

def primary_file_line(packet: dict[str, Any]) -> str:
    """Return a compact file:line location when available."""

    error = primary_error(packet)
    file_name = error.get("file")
    line = error.get("line")
    if file_name and line:
        return f"{file_name}:{line}"
    if file_name:
        return str(file_name)
    return "n/a"

def failed_phase(packet: dict[str, Any]) -> str:
    """Return the failed phase when available."""

    return str(packet.get("failed_phase") or "n/a")

def relative_path(path: Path, src_root: Path) -> str:
    """Return a user-facing path relative to src_root when possible."""

    try:
        return path.relative_to(src_root).as_posix()
    except ValueError:
        return path.as_posix()

def first_regex_group(patterns: list[str], text: str) -> str | None:
    """Return the first captured regex group from text."""

    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            return str(match.group(1)).strip()
    return None

def matches(self, packet: dict[str, Any]) -> bool:
        error = primary_error(packet)
        return error.get("kind") == "compiler"

def compile_semantic_class(packet: dict[str, Any]) -> str:
    """Return the analyzer semantic class for a compiler packet."""

    error = primary_error(packet)
    direct = error.get("semantic_class") or error.get("category")
    if direct:
        return str(direct)
    candidates = packet.get("root_cause_candidates")
    if isinstance(candidates, list) and candidates:
        first = candidates[0]
        if isinstance(first, dict) and first.get("semantic_class"):
            return str(first["semantic_class"])
    return "unknown"

def add_buildrequires_line(spec_text: str, dependency: str) -> str:
    """Add a BuildRequires line after the existing BuildRequires block."""

    lines = spec_text.splitlines(keepends=True)
    newline = _detect_newline(spec_text)
    insert_at: int | None = None
    for index, line in enumerate(lines):
        if re.match(r"^\s*BuildRequires\s*:", line):
            insert_at = index + 1
            continue
        if insert_at is not None and line.startswith((" ", "\t")):
            insert_at = index + 1
            continue
        if insert_at is not None:
            break

    if insert_at is None:
        insert_at = _first_section_index(lines)

    new_line = f"BuildRequires:  {dependency}{newline}"
    updated = lines[:insert_at] + [new_line] + lines[insert_at:]
    return "".join(updated)

def has_buildrequires_dependency(spec_text: str, dependency: str) -> bool:
    """Return true when the spec already declares the dependency."""

    normalized_dependency = _normalize_dependency(dependency)
    for line in _buildrequires_lines(spec_text):
        value = line.split(":", 1)[1] if ":" in line else line
        if _normalize_dependency(value) == normalized_dependency:
            return True
    return False

def make_git_diff(relative_path: Path, original_text: str, updated_text: str) -> str:
    """Return a git-apply compatible unified diff for a spec change."""

    path = relative_path.as_posix()
    diff_lines = list(
        difflib.unified_diff(
            original_text.splitlines(keepends=True),
            updated_text.splitlines(keepends=True),
            fromfile=f"a/{path}",
            tofile=f"b/{path}",
        )
    )
    return f"diff --git a/{path} b/{path}\n" + "".join(diff_lines)

def _first_section_index(lines: list[str]) -> int:
    for index, line in enumerate(lines):
        if re.match(r"^\s*%[A-Za-z]", line):
            return index
    return len(lines)

def _buildrequires_lines(spec_text: str) -> list[str]:
    return [
        line
        for line in spec_text.splitlines()
        if re.match(r"^\s*BuildRequires\s*:", line, re.IGNORECASE)
    ]

def matches(self, packet: dict[str, Any]) -> bool:
        kind = primary_kind(packet)
        return kind not in SUPPORTED_PRIMARY_KINDS

def matches(self, packet: dict[str, Any]) -> bool:
        primary_error = packet.get("primary_error")
        return isinstance(primary_error, dict) and primary_error.get("kind") == "linker_missing"

def parse_missing_library(packet: dict[str, Any]) -> str | None:
    """Extract a missing library token from the primary error message."""

    return first_regex_group(
        [
            r"cannot find\s+-l([A-Za-z0-9_+.-]+)",
            r"cannot find\s+(lib[A-Za-z0-9_+-]+)(?:\.so)?",
            r"library not found for\s+-l([A-Za-z0-9_+.-]+)",
        ],
        primary_message(packet),
    )

def matches(self, packet: dict[str, Any]) -> bool:
        primary_error = packet.get("primary_error")
        return isinstance(primary_error, dict) and primary_error.get("kind") == "linker_undef"

def parse_undefined_symbol(packet: dict[str, Any]) -> str | None:
    """Extract an undefined symbol from linker text."""

    return first_regex_group(
        [
            r"undefined reference to [`'\"]([^`'\"]+)[`'\"]",
            r"undefined reference to\s+([A-Za-z_][A-Za-z0-9_@.]*)",
        ],
        primary_message(packet),
    )

def matches(self, packet: dict[str, Any]) -> bool:
        primary_error = packet.get("primary_error")
        return isinstance(primary_error, dict) and primary_error.get("kind") == "patch"

def matches(self, packet: dict[str, Any]) -> bool:
        primary_error = packet.get("primary_error")
        return isinstance(primary_error, dict) and primary_error.get("kind") in SPEC_KINDS

def collect_suggestions(
    packet: dict[str, Any],
    src_root: Path,
    suggesters: Sequence[SuggesterBase],
) -> list[Suggestion]:
    """Run matching suggesters and return generated suggestions."""

    suggestions: list[Suggestion] = []
    for suggester in suggesters:
        if suggester.matches(packet):
            suggestions.extend(suggester.generate(packet, src_root))
    return suggestions

def filter_suggestions_for_patch_context(
    suggestions: Sequence[Suggestion],
    patch_context: PatchContextResult,
) -> list[Suggestion]:
    """Hide generic fallback once patch-suggest produced patch-ready context."""

    if not patch_context_has_patch_ready_context(patch_context):
        return list(suggestions)
    return [suggestion for suggestion in suggestions if suggestion.suggester != "fallback"]

def patch_context_has_patch_ready_context(patch_context: PatchContextResult) -> bool:
    """Return true only for patch-suggest statuses that contain patch-ready context."""

    return bool(patch_context.status and patch_context.status.endswith("_context_available"))

def maybe_write_patch_context(
    *,
    packet: dict[str, Any],
    evidence_packet_path: Path,
    src_root: Path,
    output_dir: Path,
    subprocess_runner: SubprocessRunner,
    python_executable: str,
    extra_pythonpath: Sequence[str | Path],
) -> PatchContextResult:
    """Run patch-suggest for source diagnostic packets as a non-fatal optional stage."""

    if primary_error_kind(packet) not in PATCH_CONTEXT_KINDS:
        return PatchContextResult(triggered=False)

    output_dir.mkdir(parents=True, exist_ok=True)
    command = [
        python_executable,
        "-m",
        "gbs_patch_suggest",
        "--evidence",
        str(evidence_packet_path),
        "--src-root",
        str(src_root),
        "--output-dir",
        str(output_dir),
    ]
    subprocess_kwargs: dict[str, object] = {"check": True, "text": True}
    patch_env = build_extra_pythonpath_env(extra_pythonpath)
    if patch_env is not None:
        subprocess_kwargs["env"] = patch_env

    try:
        subprocess_runner(command, **subprocess_kwargs)
    except subprocess.CalledProcessError as exc:
        return PatchContextResult(
            triggered=True,
            output_dir=output_dir,
            error=f"gbs_patch_suggest exited with {exc.returncode}",
        )

    context_path = output_dir / "context.md"
    if not context_path.is_file():
        return PatchContextResult(
            triggered=True,
            output_dir=output_dir,
            error="gbs_patch_suggest did not write patch_context/context.md",
        )
    return PatchContextResult(
        triggered=True,
        output_dir=output_dir,
        context_path=context_path,
        status=read_patch_context_status(output_dir),
    )

def read_patch_context_status(output_dir: Path) -> str | None:
    """Read patch-suggest meta status when available."""

    meta_path = output_dir / "meta.json"
    try:
        meta = json.loads(meta_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(meta, dict):
        return None
    status = meta.get("status")
    return str(status) if status else None

def primary_error_kind(packet: dict[str, Any]) -> str:
    """Return the primary error kind from an analyzer packet."""

    value = packet.get("primary_error")
    if not isinstance(value, dict):
        return ""
    return str(value.get("kind") or "")

def build_analyzer_subprocess_env(extra_pythonpath: Sequence[str | Path]) -> dict[str, str] | None:
    """Return a subprocess env with extra Python paths prepended for analyzer calls."""

    return build_extra_pythonpath_env(extra_pythonpath)

def estimate_workflow_downstream_tokens(
    *,
    summary_text: str,
    summary_path: Path,
    evidence_markdown_path: Path | None,
    suggestion_files: Sequence[Path],
    patch_context_path: Path | None,
    analyzer_output_dir: Path | None,
    estimator: TokenEstimator,
) -> dict[str, Any]:
    """Estimate markdown material that workflow recommends Claude read."""

    files: list[dict[str, Any]] = [
        {
            "path": str(summary_path),
            "role": "workflow_summary",
            "tokens": estimator.estimate_text(summary_text),
            "included_in_total": True,
        }
    ]
    if evidence_markdown_path is not None and evidence_markdown_path.is_file():
        files.append(
            {
                "path": str(evidence_markdown_path),
                "role": "evidence_packet_md",
                "tokens": _estimate_file_tokens(evidence_markdown_path, estimator),
                "included_in_total": True,
            }
        )
    for path in sorted(suggestion_files):
        if path.suffix == ".md" and path.is_file():
            files.append(
                {
                    "path": str(path),
                    "role": "suggestion_md",
                    "tokens": _estimate_file_tokens(path, estimator),
                    "included_in_total": True,
                }
            )
    if patch_context_path is not None and patch_context_path.is_file():
        files.append(
            {
                "path": str(patch_context_path),
                "role": "patch_context_md",
                "tokens": _estimate_file_tokens(patch_context_path, estimator),
                "included_in_total": True,
            }
        )

    total = sum(int(file["tokens"]) for file in files if file["included_in_total"])
    return {
        "scope": (
            "Estimated tokens of material this workflow feeds to Claude "
            "(recommended reading). Actual Claude consumption also includes any "
            "source files Claude reads on its own."
        ),
        "usage_note": (
            "Compare this baseline with Cline/client actual token usage; the "
            "difference approximates extra material Claude read outside workflow outputs."
        ),
        "estimate_method": estimator.method,
        "total_claude_facing_tokens": total,
        "source_snippets_tokens": _read_source_snippets_tokens(analyzer_output_dir),
        "files": files,
    }

def _estimate_file_tokens(path: Path, estimator: TokenEstimator) -> int:
    try:
        return estimator.estimate_text(path.read_text(encoding="utf-8", errors="replace"))
    except OSError:
        return 0

def _read_source_snippets_tokens(analyzer_output_dir: Path | None) -> int | None:
    if analyzer_output_dir is None:
        return None
    perf_path = analyzer_output_dir / "perf_report.json"
    try:
        report = json.loads(perf_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    value = (
        report.get("tokens", {})
        .get("by_section", {})
        .get("source_snippets")
    )
    return int(value) if isinstance(value, int) else None

def _env_skill_scripts(env_name: str, package_dir: str) -> Path | None:
    import os

    raw = os.environ.get(env_name)
    if not raw:
        return None
    root = Path(raw).expanduser().resolve()
    candidates = [root / "scripts", root] if root.name != "scripts" else [root]
    for candidate in candidates:
        if (candidate / package_dir).is_dir():
            return candidate
    raise RuntimeError(f"{env_name} must point to a skill root or scripts directory")

def _sibling_skill_scripts(skill_name: str, package_dir: str) -> Path | None:
    workflow_root = Path(__file__).resolve().parents[1]
    candidate = workflow_root.parent / skill_name / "scripts"
    if (candidate / package_dir).is_dir():
        return candidate
    return None

def _dependency_scripts(
    *,
    env_name: str,
    skill_name: str,
    package_dir: str,
) -> Path:
    env_path = _env_skill_scripts(env_name, package_dir)
    if env_path is not None:
        return env_path
    sibling_path = _sibling_skill_scripts(skill_name, package_dir)
    if sibling_path is not None:
        return sibling_path
    raise RuntimeError(MISSING_DEPENDENCY_MESSAGE)

def _optional_dependency_scripts(
    *,
    env_name: str,
    skill_name: str,
    package_dir: str,
) -> Path | None:
    try:
        env_path = _env_skill_scripts(env_name, package_dir)
    except RuntimeError:
        env_path = None
    if env_path is not None:
        return env_path
    return _sibling_skill_scripts(skill_name, package_dir)

def _load_main() -> tuple[Callable[..., int], tuple[Path, ...]]:
    added_paths: list[Path] = []
    own_scripts = Path(__file__).resolve().parent

    while True:
        try:
            from gbs_workflow.workflow import main

            return main, tuple(added_paths)
        except ModuleNotFoundError as exc:
            if exc.name == "gbs_workflow":
                added = _add_python_path(own_scripts, added_paths)
            elif exc.name == "gbs_build_skill":
                added = _add_python_path(
                    _dependency_scripts(
                        env_name=BUILD_SKILL_ENV,
                        skill_name="tizen-gbs-build",
                        package_dir="gbs_build_skill",
                    ),
                    added_paths,
                )
            elif exc.name == "gbs_analyzer":
                added = _add_python_path(
                    _dependency_scripts(
                        env_name=ANALYZER_SKILL_ENV,
                        skill_name="tizen-gbs-log-analysis",
                        package_dir="gbs_analyzer",
                    ),
                    added_paths,
                )
            else:
                raise
            if not added:
                raise RuntimeError(MISSING_DEPENDENCY_MESSAGE) from exc

def _has_broken_build_root(compiler_log: Path) -> bool:
    """Return whether `compiler_log` contains GBS's broken build-root marker."""

    try:
        text = compiler_log.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return False
    return BROKEN_BUILD_ROOT_MARKER in text

def _extract_failure_log_path(compiler_log: Path) -> tuple[Path | None, str | None]:
    """Return GBS's structured failure log path and package name, when present."""

    try:
        text = compiler_log.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return None, None

    matches = list(GBS_FAILURE_LOG_PATTERN.finditer(text))
    if not matches:
        return None, None

    last = matches[-1]
    candidate = Path(last.group("path"))
    if not candidate.is_file():
        return None, None
    return candidate, last.group("pkg")

def _print_summary(result: BuildResult, timeout: int) -> None:
    status = "succeeded" if result.exit_code == 0 else "failed"
    print(f"gbs_build_skill: build {status} (exit {result.exit_code})", file=sys.stderr)
    print(f"gbs_build_skill: compiler log written to {result.log_path}", file=sys.stderr)
    if result.timed_out:
        print(f"gbs_build_skill: timed out after {timeout}s", file=sys.stderr)
    if result.exit_code == 0:
        return
    if result.failure_log_path is None:
        print("gbs_build_skill: failure log: not found in compiler log", file=sys.stderr)
        print(
            f"gbs_build_skill: recommended for analysis: {result.log_path} (compiler log only)",
            file=sys.stderr,
        )
        return
    print(f"gbs_build_skill: failure log: {result.failure_log_path}", file=sys.stderr)
    print(
        f"gbs_build_skill: recommended for analysis: {result.analysis_log_path}",
        file=sys.stderr,
    )
    if result.package_name is not None:
        print(f"gbs_build_skill: package: {result.package_name}", file=sys.stderr)

def _resolve_src_dir(src_dir: Path | None) -> Path | None:
    if src_dir is None:
        return None
    resolved = src_dir.resolve()
    if not resolved.is_dir():
        return None
    return resolved

def _stream_process_output(process: subprocess.Popen[str], log_file: TextIO) -> None:
    if process.stdout is None:
        return
    for chunk in process.stdout:
        log_file.write(chunk)
        log_file.flush()

def _load_main() -> Callable[[list[str] | None], int]:
    try:
        from gbs_build_skill.runner import main

        return main
    except ModuleNotFoundError as exc:
        if exc.name != "gbs_build_skill":
            raise

    scripts_dir = Path(__file__).resolve().parent
    sys.path.insert(0, str(scripts_dir))
    from gbs_build_skill.runner import main

    return main

def join_backslash_continuations(argv_line: str) -> str:
    """Join shell-style backslash continuations into one command line."""

    lines = argv_line.splitlines()
    if not lines:
        return ""

    parts: list[str] = []
    for line in lines:
        stripped = line.rstrip()
        if stripped.endswith("\\"):
            parts.append(stripped[:-1].strip())
        else:
            parts.append(stripped.strip())
    return " ".join(part for part in parts if part)

def read_rsp(path: str | Path, max_rsp_tokens: int = 200) -> str:
    """Read an rsp file and cap the raw token count used by downstream extraction."""

    content = Path(path).read_text(encoding="utf-8", errors="replace")
    return " ".join(content.split()[:max_rsp_tokens])

def extract_relevant_flags(rsp_content: str) -> dict[str, list[str]]:
    """Extract the flag classes required by v0.5 §3.1."""

    flags = shlex.split(rsp_content, posix=True)
    return {
        "libraries": [flag for flag in flags if flag.startswith("-l")],
        "library_paths": [flag for flag in flags if flag.startswith("-L")],
        "other_significant": [
            flag for flag in flags if flag in ("-Werror", "-fPIC", "-shared")
        ],
        "include_paths": [flag for flag in flags if flag.startswith("-I")][:10],
        "defines": [flag for flag in flags if flag.startswith("-D")][:20],
        "objects": [flag for flag in flags if flag.endswith((".o", ".a"))][:30],
    }

def parse_command(argv_line: str, cwd: str | Path, max_rsp_tokens: int = 200) -> dict[str, Any]:
    """Parse a scanner command line and expand relevant rsp flags when available."""

    joined = join_backslash_continuations(argv_line)
    rsp_files = RSP_PATTERN.findall(joined)
    rsp_content: dict[str, dict[str, list[str]] | None] = {}
    cwd_path = Path(cwd)

    for rsp_path in rsp_files:
        full_path = Path(rsp_path) if os.path.isabs(rsp_path) else cwd_path / rsp_path
        if full_path.exists():
            rsp_content[rsp_path] = extract_relevant_flags(read_rsp(full_path, max_rsp_tokens))
        else:
            rsp_content[rsp_path] = None

    return {
        "argv_short": shorten_argv(joined),
        "argv_full": joined if len(joined) < 500 else None,
        "rsp_expanded": rsp_content,
        "command_degraded": any(value is None for value in rsp_content.values()),
    }

def as_dict(self) -> dict[str, Any]:
        return {
            "path": self.path,
            "start_line": self.start_line,
            "end_line": self.end_line,
            "text": self.text,
            "extraction_method": self.extraction_method,
            "degraded": self.degraded,
        }

def _context_from_ctags(
    source_path: Path,
    lines: list[str],
    *,
    line: int | None,
    symbol: str | None,
    runner: CtagsRunner | None,
) -> SourceContext | None:
    active_runner = runner or default_ctags_runner
    try:
        tags = [_parse_tag(raw) for raw in active_runner(source_path).splitlines() if raw.strip()]
    except (OSError, subprocess.CalledProcessError, json.JSONDecodeError):
        return None

    candidates = [tag for tag in tags if tag is not None and tag.get("line")]
    if symbol:
        candidates = [tag for tag in candidates if tag.get("name") == symbol] or candidates
    if line is not None:
        before_line = [tag for tag in candidates if int(tag["line"]) <= line]
        if before_line:
            candidates = [max(before_line, key=lambda tag: int(tag["line"]))]
    if not candidates:
        return None

    start = max(1, int(candidates[0]["line"]))
    end = _brace_end(lines, start) or min(len(lines), start + 30)
    return _slice(source_path, lines, start, end, "ctags")

def _parse_tag(raw: str) -> dict[str, Any] | None:
    parsed = json.loads(raw)
    return parsed if isinstance(parsed, dict) else None

def _context_from_regex(
    source_path: Path,
    lines: list[str],
    *,
    line: int | None,
    symbol: str | None,
) -> SourceContext | None:
    functions: list[tuple[int, int, str]] = []
    for index, text in enumerate(lines, start=1):
        match = FUNCTION_RE.match(text)
        if not match:
            continue
        end = _brace_end(lines, index)
        if end is not None:
            functions.append((index, end, match.group("name")))

    for start, end, name in functions:
        if symbol and name == symbol:
            return _slice(source_path, lines, start, end, "regex_brace")
        if line is not None and start <= line <= end:
            return _slice(source_path, lines, start, end, "regex_brace")
    return None

def _brace_end(lines: list[str], start_line: int) -> int | None:
    depth = 0
    saw_open = False
    for index in range(start_line, len(lines) + 1):
        text = lines[index - 1]
        depth += text.count("{")
        if "{" in text:
            saw_open = True
        depth -= text.count("}")
        if saw_open and depth <= 0:
            return index
    return None

def _context_from_window(
    source_path: Path,
    lines: list[str],
    *,
    line: int | None,
    window: int,
) -> SourceContext:
    center = line if line is not None else 1
    start = max(1, center - window)
    end = min(len(lines), center + window)
    return _slice(source_path, lines, start, end, "line_window", degraded=True)

def __init__(self, rules: list[_SemanticRule]) -> None:
        self.rules = rules
        self.by_name = {rule.name: rule for rule in rules}

def from_file(cls, path: str | Path = DEFAULT_SEMANTICS_PATH) -> SemanticClassifier:
        raw = yaml.safe_load(Path(path).read_text(encoding="utf-8"))
        if not isinstance(raw, dict) or raw.get("schema_version") != 1:
            raise ValueError("error semantics schema_version must be 1")
        classes = raw.get("semantic_classes", {})
        if not isinstance(classes, dict):
            raise ValueError("semantic_classes must be a mapping")

        rules: list[_SemanticRule] = []
        for name, spec in classes.items():
            if not isinstance(spec, dict):
                raise ValueError(f"{name}: semantic class spec must be a mapping")
            rules.append(
                _SemanticRule(
                    name=str(name),
                    base_confidence=float(spec["base_confidence"]),
                    gated_base_confidence=(
                        float(spec["gated_base_confidence"])
                        if spec.get("gated_base_confidence") is not None
                        else None
                    ),
                    cascade_probability=float(spec["cascade_probability"]),
                    default_level=spec.get("default_level"),
                    patterns=tuple(
                        re.compile(str(pattern), re.IGNORECASE)
                        for pattern in spec.get("patterns", [])
                    ),
                )
            )
        return cls(rules)

def classify(self, event: dict[str, Any], scan_result: dict[str, Any]) -> SemanticClass:
        kind = event.get("kind")
        if kind == "linker_undef":
            return self._semantic("undefined_reference")
        if kind == "linker_missing":
            return self._semantic("missing_lib")

        message = str(event.get("message", ""))
        for rule in self.rules:
            if rule.name in {"generic_error", "undefined_reference", "missing_lib"}:
                continue
            if any(pattern.search(message) for pattern in rule.patterns):
                return self._semantic(rule.name)

        return self._generic(event, scan_result)

def _semantic(self, name: str, *, context_satisfied: bool = False) -> SemanticClass:
        rule = self.by_name[name]
        return SemanticClass(
            name=rule.name,
            base_confidence=rule.base_confidence,
            cascade_probability=rule.cascade_probability,
            default_level=rule.default_level,
            context_satisfied=context_satisfied,
        )

def classify_event(
    event: dict[str, Any],
    scan_result: dict[str, Any],
    classifier: SemanticClassifier | None = None,
) -> SemanticClass:
    """Classify one scanner event with the default semantic classifier."""

    active = classifier or SemanticClassifier.from_file()
    return active.classify(event, scan_result)

def strip_ext(filename: str) -> str:
    path = Path(filename)
    return path.name[: -len(path.suffix)] if path.suffix else path.name

def candidates_for_source(src_path: str) -> set[str]:
    """Return object suffix candidates for a compiler diagnostic source path."""

    base = Path(src_path).name
    stem = strip_ext(base)
    return {f"{stem}.o", f"{base}.o"}

def build_suffix_index(source_to_event: dict[str, str]) -> dict[str, set[str]]:
    """Create a suffix -> event id map from source path -> event id."""

    index: dict[str, set[str]] = {}
    for src_path, event_id in source_to_event.items():
        if not is_supported_source(src_path):
            continue
        for suffix in candidates_for_source(src_path):
            index.setdefault(suffix, set()).add(event_id)
    return index

def match_make_target(target_in_log: str, suffix_index: dict[str, set[str]]) -> str | None:
    """Return a unique parent event id when the make target ends with one suffix."""

    matches: set[str] = set()
    for suffix, event_ids in suffix_index.items():
        if target_in_log.endswith(suffix):
            matches.update(event_ids)
    return next(iter(matches)) if len(matches) == 1 else None

def _timed(state: PipelineState, layer: str, func: Callable[[], T]) -> T:
    start = time.perf_counter()
    try:
        return func()
    finally:
        state.timings_ms[layer] = (time.perf_counter() - start) * 1000

def _top_candidate(rank_result: RankResult | None) -> dict[str, Any] | None:
    if rank_result is None:
        return None
    candidates = rank_result.as_dict()["root_cause_candidates"]
    return candidates[0] if candidates else None

def _run_full_match(
    scan_result: ScanResult | None,
    candidate: dict[str, Any] | None,
    evidence: Evidence | None,
) -> FullMatchResult | None:
    if scan_result is None or candidate is None or evidence is None:
        return None
    return full_match(scan_result, candidate, evidence)

def _resolve_src_root(src_root: str, buildlog_path: Path) -> Path | None:
    if src_root in {"", "auto"}:
        return buildlog_path.resolve().parent
    return Path(src_root)

def _find_spec_path(package: str, src_root: Path | None) -> Path | None:
    if src_root is None:
        return None
    try:
        return SpecMinimalParser.find_spec_file(package, src_root)
    except (FileNotFoundError, ValueError):
        return None

def _level_for_preferred(preferred: int) -> int:
    if preferred >= 900:
        return 3
    if preferred >= 600:
        return 2
    return 1

def build_error_clusters(scan_result: ScanResult | dict[str, Any]) -> ErrorClusterResult:
    """Return additive error cluster metadata for an analyzer scan result."""

    scan_data = _scan_as_dict(scan_result)
    events = [event for event in scan_data.get("events", []) if isinstance(event, dict)]
    truncation_signals = _truncation_signals(events)
    grouped: dict[str, list[dict[str, Any]]] = {}
    for event in events:
        warning_option = extract_warning_option(event)
        if warning_option is None:
            continue
        grouped.setdefault(warning_option, []).append(event)

    clusters: list[dict[str, Any]] = []
    sidecar_clusters: list[dict[str, Any]] = []
    for warning_option, cluster_events in grouped.items():
        if len(cluster_events) < 3:
            continue
        cluster_id = f"CL{len(clusters) + 1:03d}"
        cluster = _cluster_summary(
            cluster_id,
            warning_option,
            cluster_events,
            truncated=bool(truncation_signals),
        )
        clusters.append(cluster)
        sidecar_clusters.append(
            {
                "id": cluster_id,
                "warning_option": warning_option,
                "locations": [_sidecar_location(event) for event in cluster_events],
            }
        )

    if not clusters and not truncation_signals:
        return ErrorClusterResult(summary=None, sidecar=None)

    summary = {
        "schema_version": ERROR_CLUSTERS_SCHEMA,
        "truncated": bool(truncation_signals),
        "truncation_signals": truncation_signals,
        "full_locations_path": SIDECAR_NAME if clusters else None,
        "clusters": clusters,
    }
    sidecar = (
        {
            "schema_version": ERROR_CLUSTER_LOCATIONS_SCHEMA,
            "clusters": sidecar_clusters,
        }
        if clusters
        else None
    )
    return ErrorClusterResult(summary=summary, sidecar=sidecar)

def extract_warning_option(event: dict[str, Any]) -> str | None:
    """Return the concrete warning option key for a source diagnostic event."""

    if event.get("kind") not in _SOURCE_DIAGNOSTIC_KINDS:
        return None
    message = str(event.get("message") or "")
    for block in _WARNING_BLOCK_PATTERN.findall(message):
        for raw_token in block.split(","):
            token: str = raw_token.strip()
            if not token.startswith("-W"):
                continue
            if token == "-Werror":
                continue
            return token
    return None

def _ordered_files(events: list[dict[str, Any]]) -> list[str]:
    seen: set[str] = set()
    files: list[str] = []
    for event in events:
        file = event.get("file")
        if not isinstance(file, str) or not file or file in seen:
            continue
        seen.add(file)
        files.append(file)
    return files

def _locations_sample(events: list[dict[str, Any]], *, limit: int = 10) -> list[dict[str, Any]]:
    selected_indices: list[int] = []
    selected_set: set[int] = set()
    seen_files: set[str] = set()
    for index, event in enumerate(events):
        file = event.get("file")
        if not isinstance(file, str) or not file or file in seen_files:
            continue
        selected_indices.append(index)
        selected_set.add(index)
        seen_files.add(file)
        if len(selected_indices) >= limit:
            break
    if len(selected_indices) < limit:
        for index, _event in enumerate(events):
            if index in selected_set:
                continue
            selected_indices.append(index)
            if len(selected_indices) >= limit:
                break
    return [events[index] for index in selected_indices]

def _packet_location(event: dict[str, Any]) -> dict[str, Any]:
    data: dict[str, Any] = {
        "event_id": event.get("id"),
        "file": event.get("file"),
        "line": event.get("line"),
        "column": event.get("column"),
    }
    return {key: value for key, value in data.items() if value is not None}

def _sidecar_location(event: dict[str, Any]) -> dict[str, Any]:
    data: dict[str, Any] = {
        "event_id": event.get("id"),
        "kind": event.get("kind"),
        "file": event.get("file"),
        "line": event.get("line"),
        "column": event.get("column"),
        "line_no": event.get("line_no"),
        "message": event.get("message"),
    }
    return {key: value for key, value in data.items() if value is not None}

def _truncation_signals(events: list[dict[str, Any]], *, limit: int = 5) -> list[dict[str, Any]]:
    signals: list[dict[str, Any]] = []
    for event in events:
        message = str(event.get("message") or "")
        if TRUNCATION_MARKER not in message.lower():
            continue
        signals.append(
            {
                "line_no": event.get("line_no"),
                "message": message,
            }
        )
        if len(signals) >= limit:
            break
    return signals

def _advisory(*, large_scale: bool, truncated: bool) -> str:
    if large_scale:
        advisory = (
            "Large repeated source diagnostic cluster. Patching only the primary error "
            "is likely incomplete; consider a class-wide fix strategy."
        )
    else:
        advisory = (
            "Repeated source diagnostic cluster. Review all listed locations before "
            "assuming a one-off patch is complete."
        )
    if truncated:
        advisory += " Compiler output was truncated; actual occurrences may be higher."
    return advisory

def _scan_as_dict(scan_result: ScanResult | dict[str, Any]) -> dict[str, Any]:
    if isinstance(scan_result, ScanResult):
        return scan_result.as_dict()
    return scan_result

def command_summary(command: dict[str, Any] | None) -> dict[str, Any] | None:
    if command is None:
        return None
    return {
        "id": command.get("id"),
        "phase": command.get("phase"),
        "argv_short": command.get("argv_short"),
        "argv_full": command.get("argv_full"),
        "rsp_expanded": command.get("rsp_expanded"),
        "command_degraded": command.get("command_degraded", False),
    }

def source_path(src_root: Path | None, event: dict[str, Any]) -> Path | None:
    file_value = event.get("file")
    if not isinstance(file_value, str) or not file_value:
        return None
    path = Path(file_value)
    if path.is_absolute():
        return path
    if src_root is None:
        return None
    return src_root / path

def quoted_symbol(message: str) -> str | None:
    match = re.search(r"[`'\"](?P<symbol>[A-Za-z_]\w*)[`'\"]", message)
    return match.group("symbol") if match else None

def search_header_declarations(src_root: Path | None, symbol: str | None) -> list[dict[str, Any]]:
    if src_root is None or not symbol:
        return []
    declarations: list[dict[str, Any]] = []
    pattern = re.compile(rf"\b{re.escape(symbol)}\b")
    for path in sorted(src_root.rglob("*")):
        if path.suffix not in {".h", ".hh", ".hpp", ".hxx"}:
            continue
        for line_no, text in enumerate(
            path.read_text(encoding="utf-8", errors="replace").splitlines(),
            start=1,
        ):
            if pattern.search(text):
                declarations.append(
                    {"path": str(path), "line": line_no, "text": text.strip()}
                )
                break
        if len(declarations) >= 5:
            break
    return declarations

def parse_missing_dependency(message: str) -> dict[str, str | None]:
    match = re.search(r"nothing provides\s+(?P<dep>.+?)(?:\s+needed by\s+(?P<pkg>\S+))?$", message)
    if not match:
        return {"dependency": message.strip(), "needed_by": None}
    return {
        "dependency": match.group("dep").strip(),
        "needed_by": match.group("pkg"),
    }

def profile_hint(scan_result: dict[str, Any]) -> str | None:
    buildlog_path = scan_result.get("buildlog_path")
    if isinstance(buildlog_path, str) and "profile" in buildlog_path.lower():
        return Path(buildlog_path).stem
    return None

def event_for(self, candidate: dict[str, Any]) -> dict[str, Any]:
        event_id = candidate.get("event_id") or candidate.get("id")
        for event in self.scan_result.get("events", []):
            if isinstance(event, dict) and event.get("id") == event_id:
                return event
        if candidate.get("kind"):
            return candidate
        return {}

def command_for(self, event: dict[str, Any]) -> dict[str, Any] | None:
        command_id = event.get("command_id")
        for command in self.scan_result.get("commands", []):
            if isinstance(command, dict) and command.get("id") == command_id:
                return command
        return None

def level_for_budget(granted_budget: int) -> int:
    if granted_budget >= 900:
        return 3
    if granted_budget >= 600:
        return 2
    return 1

def estimate(self, candidate: dict[str, Any]) -> dict[str, Any]:
        del candidate
        return default_estimate()

def estimate(self, candidate: dict[str, Any]) -> dict[str, Any]:
        del candidate
        return default_estimate()

def collect(self, candidate: dict[str, Any], granted_budget: int) -> Evidence:
        event = self.event_for(candidate)
        level = level_for_budget(granted_budget)
        data: dict[str, Any] = {
            "primary_error": event,
            "missing_dependency": parse_missing_dependency(str(event.get("message", ""))),
            "profile_hint": profile_hint(self.scan_result),
        }
        contains = {"primary_error", "missing_dependency"}
        warnings: list[str] = []
        degraded = False

        if level >= 2:
            if self.spec_path is not None and self.spec_path.exists():
                parser = SpecMinimalParser(self.spec_path)
                data["spec_buildrequires"] = parser.extract_buildrequires()
                data["spec_parse_status"] = parser.get_parse_status()
                contains.add("spec_buildrequires")
            else:
                warnings.append("spec_file_unavailable")
                degraded = True

        return Evidence(
            collector=self.collector_name,
            level=level,
            granted_budget=granted_budget,
            data=data,
            contains=contains,
            degraded=degraded,
            warnings=warnings,
        )

def estimate(self, candidate: dict[str, Any]) -> dict[str, Any]:
        del candidate
        return default_estimate()

def _find_symbol_context(src_root: Path, symbol: str, ctags_runner: Any | None) -> Any | None:
    for path in sorted(src_root.rglob("*")):
        if path.suffix not in {".c", ".cc", ".cpp", ".cxx", ".S", ".cu", ".h", ".hpp"}:
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        if symbol not in text:
            continue
        return extract_source_context(path, symbol=symbol, ctags_runner=ctags_runner)
    return None

def collector_for_candidate(
    candidate: dict[str, Any],
    scan_result: ScanResult | dict[str, Any],
    *,
    src_root: str | Path | None = None,
    spec_path: str | Path | None = None,
    buildlog_path: str | Path | None = None,
    ctags_runner: Any | None = None,
) -> EvidenceCollector | None:
    """Return the MVP collector for a ranked candidate or scanner event."""

    scan_data = scan_result.as_dict() if isinstance(scan_result, ScanResult) else scan_result
    event = _event_for_candidate(candidate, scan_data)
    kind = event.get("kind") or candidate.get("kind")

    kwargs = {
        "src_root": src_root,
        "spec_path": spec_path,
        "buildlog_path": buildlog_path,
        "ctags_runner": ctags_runner,
    }
    if kind in {"compiler", "werror"}:
        return CompileEvidenceCollector(scan_data, **kwargs)
    if kind in {"linker_undef", "linker_missing"}:
        return LinkEvidenceCollector(scan_data, **kwargs)
    if kind in {"spec_script", "rpm_phase"}:
        return SpecEvidenceCollector(scan_data, **kwargs)
    if kind == "depsolve":
        return DepsEvidenceCollector(scan_data, **kwargs)
    return None

