) -> dict[str, Any] | None:
    command_id = event.get("command_id")
    for command in scan_data.get("commands", []):
        if isinstance(command, dict) and command.get("id") == command_id:
            return command
    return None

def _rank_candidates(
    rank_result: RankResult | dict[str, Any] | list[dict[str, Any]],
) -> list[dict[str, Any]]:
    if isinstance(rank_result, RankResult):
        candidates = rank_result.as_dict()["root_cause_candidates"]
        return [item for item in candidates if isinstance(item, dict)]
    if isinstance(rank_result, dict):
        candidates = rank_result.get("root_cause_candidates", [])
        return [item for item in candidates if isinstance(item, dict)]
    return [item for item in rank_result if isinstance(item, dict)]

def _copy_candidate_int_field(
    candidate: dict[str, Any],
    event: dict[str, Any],
    key: str,
) -> None:
    value = event.get(key)
    if isinstance(value, int):
        candidate[key] = value

def _evidence_as_dict(evidence: Evidence | dict[str, Any] | None) -> dict[str, Any] | None:
    if evidence is None:
        return None
    if isinstance(evidence, Evidence):
        return evidence.as_dict()
    return evidence

def _full_match_as_dict(
    full_match_result: FullMatchResult | dict[str, Any] | None,
) -> dict[str, Any]:
    if full_match_result is None:
        return {"verdict": "needs_llm"}
    if isinstance(full_match_result, FullMatchResult):
        return full_match_result.as_dict()
    if "verdict" in full_match_result:
        return full_match_result
    verdict = full_match_result.get("full_match_verdict")
    if verdict in {Verdict.DIRECT_TIER1.value, Verdict.DIRECT_TIER2.value}:
        return {**full_match_result, "verdict": "direct_answer"}
    return {**full_match_result, "verdict": "needs_llm"}

def _matched_patterns_from_match_data(match_data: dict[str, Any]) -> list[Any]:
    matched_patterns = match_data.get("matched_patterns")
    if isinstance(matched_patterns, list):
        return matched_patterns
    pattern_id = match_data.get("pattern_id")
    return [pattern_id] if pattern_id else []

def _scan_as_dict(scan_result: ScanResult | dict[str, Any]) -> dict[str, Any]:
    if isinstance(scan_result, ScanResult):
        return scan_result.as_dict()
    return scan_result

def from_file(cls, path: str | Path = DEFAULT_PATTERN_PATH) -> QuickFilter:
        library = (
            _load_default_pattern_library()
            if Path(path) == DEFAULT_PATTERN_PATH
            else load_pattern_library(path)
        )
        return cls(library["patterns"])

def evaluate(self, scan_result: ScanResult | dict[str, Any]) -> QuickFilterResult:
        scan_data = _scan_as_dict(scan_result)
        events = scan_data.get("events", [])
        commands = {
            command["id"]: command
            for command in scan_data.get("commands", [])
            if isinstance(command, dict) and "id" in command
        }
        evaluated = 0

        for event in events:
            if not isinstance(event, dict):
                continue
            for pattern in self.patterns:
                evaluated += 1
                captures = _match_pattern(pattern, event, events, commands)
                if captures is None:
                    continue
                direct_answer = _render_fix(pattern.fix_template, captures)
                match = QuickFilterMatch(
                    pattern_id=pattern.id,
                    category=pattern.category,
                    event_id=str(event["id"]),
                    confidence=pattern.confidence,
                    captures=captures,
                    direct_answer=direct_answer,
                    minimal_packet=_minimal_packet(scan_data, event, pattern, direct_answer),
                )
                return QuickFilterResult(hit=True, match=match, evaluated_patterns=evaluated)

        return QuickFilterResult(hit=False, evaluated_patterns=evaluated)

def load_pattern_library(path: str | Path = DEFAULT_PATTERN_PATH) -> dict[str, Any]:
    raw = yaml.safe_load(Path(path).read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise PatternValidationError("pattern library must be a mapping")
    return {
        "schema_version": raw.get("schema_version"),
        "tier1_allowed_categories": tuple(raw.get("tier1_allowed_categories", [])),
        "tier1_forbidden_categories": tuple(raw.get("tier1_forbidden_categories", [])),
        "patterns": _compile_patterns(raw),
    }

def _compile_patterns(raw: dict[str, Any]) -> list[QuickPattern]:
    if raw.get("schema_version") != 2:
        raise PatternValidationError("pattern library schema_version must be 2")

    allowed = set(raw.get("tier1_allowed_categories", []))
    forbidden = set(raw.get("tier1_forbidden_categories", []))
    patterns = raw.get("patterns", [])
    if not isinstance(patterns, list):
        raise PatternValidationError("patterns must be a list")

    compiled: list[QuickPattern] = []
    for item in patterns:
        if not isinstance(item, dict):
            raise PatternValidationError("each pattern must be a mapping")
        if item.get("tier") != "tier1":
            continue
        _validate_tier1_pattern(item, allowed, forbidden)
        match = item["match"]
        compiled.append(
            QuickPattern(
                id=str(item["id"]),
                category=str(item["category"]),
                tier=str(item["tier"]),
                event_kinds=tuple(str(kind) for kind in item["event_kinds"]),
                regex=tuple(
                    re.compile(str(pattern), re.IGNORECASE) for pattern in match["regex"]
                ),
                required_context=dict(match.get("required_context", {})),
                negative_patterns=tuple(
                    re.compile(str(pattern), re.IGNORECASE)
                    for pattern in match.get("negative_patterns", [])
                ),
                confidence=float(item["confidence"]),
                terminal=bool(item["terminal"]),
                fix_template=str(item["fix_template"]),
            )
        )
    return compiled

def _validate_tier1_pattern(
    item: dict[str, Any], allowed: set[str], forbidden: set[str]
) -> None:
    pattern_id = item.get("id", "<unknown>")
    category = item.get("category")
    tier = item.get("tier")
    fix_template = str(item.get("fix_template", ""))

    if tier != "tier1":
        raise PatternValidationError(f"{pattern_id}: only tier1 patterns are allowed in M2")
    if category not in allowed:
        raise PatternValidationError(f"{pattern_id}: category is not tier1-allowed")
    if category in forbidden:
        raise PatternValidationError(f"{pattern_id}: category is tier1-forbidden")
    if not item.get("terminal"):
        raise PatternValidationError(f"{pattern_id}: tier1 pattern must be terminal")
    if float(item.get("confidence", 0.0)) < 0.95:
        raise PatternValidationError(f"{pattern_id}: tier1 confidence must be >= 0.95")
    limit = 150 if category == "patch_failed" else 300
    if len(fix_template) > limit:
        raise PatternValidationError(f"{pattern_id}: fix_template exceeds {limit} chars")
    if not any(word in fix_template for word in UNCERTAIN_WORDS):
        raise PatternValidationError(f"{pattern_id}: fix_template must be conservative")
    if "expand" not in fix_template:
        raise PatternValidationError(f"{pattern_id}: fix_template must mention expand")

def _match_pattern(
    pattern: QuickPattern,
    event: dict[str, Any],
    all_events: list[Any],
    commands: dict[str, dict[str, Any]],
) -> dict[str, str] | None:
    if event.get("kind") not in pattern.event_kinds:
        return None
    if not _passes_required_context(pattern.required_context, event, all_events, commands):
        return None

    message = str(event.get("message", ""))
    if any(negative.search(message) for negative in pattern.negative_patterns):
        return None

    for regex in pattern.regex:
        match = regex.search(message)
        if match:
            return {
                key: value
                for key, value in match.groupdict().items()
                if value is not None
            }
    return None

def _passes_required_context(
    context: dict[str, Any],
    event: dict[str, Any],
    all_events: list[Any],
    commands: dict[str, dict[str, Any]],
) -> bool:
    phases = context.get("phase")
    if phases is not None and event.get("phase") not in phases:
        return False

    severities = context.get("severity")
    if severities is not None and event.get("severity") not in severities:
        return False

    tools = context.get("tool_in")
    if tools is not None and _event_tool(event, commands) not in tools:
        return False

    if context.get("not_in_warning_block") and is_in_warning_block(event, all_events):
        return False

    return True

def _event_tool(event: dict[str, Any], commands: dict[str, dict[str, Any]]) -> str | None:
    command_id = event.get("command_id")
    if command_id is None:
        return None
    command = commands.get(str(command_id))
    if command is None:
        return None
    argv_short = str(command.get("argv_short", ""))
    try:
        parts = shlex.split(argv_short)
    except ValueError:
        parts = argv_short.split()
    if not parts:
        return None
    return Path(parts[0]).name

def _scan_as_dict(scan_result: ScanResult | dict[str, Any]) -> dict[str, Any]:
    if isinstance(scan_result, ScanResult):
        return scan_result.as_dict()
    return scan_result

def quick_filter(scan_result: ScanResult | dict[str, Any]) -> QuickFilterResult:
    """Evaluate the default pattern library against a scan result."""

    return QuickFilter.from_file().evaluate(scan_result)

def as_dict(self) -> dict[str, Any]:
        return {
            "root_cause_candidates": [
                candidate.as_dict() for candidate in self.root_cause_candidates
            ]
        }

def rank_score(
    event: dict[str, Any],
    all_events: list[Any],
    semantic: SemanticClass | None = None,
    *,
    failed_phase: str | None = None,
) -> tuple[float, list[dict[str, Any]]]:
    """Return the v0.5 ranking score and structured confidence reasons."""

    if event.get("kind") == "make_cascade" and event.get("parent"):
        return 0.1, [
            {"factor": "make_cascade_parent", "value": event.get("parent"), "score": 0.1}
        ]

    sem = semantic or SemanticClassifier.from_file().classify(event, {"failed_phase": None})
    reasons: list[dict[str, Any]] = [
        {"factor": "semantic_class", "value": sem.name, "base": sem.base_confidence}
    ]
    score = sem.base_confidence

    if event.get("kind") == "linker_undef":
        reasons.append({"factor": "linker_undef_no_cascade_penalty", "delta": "+0.00"})
    else:
        cascade_delta = -(sem.cascade_probability * 0.3)
        score += cascade_delta
        reasons.append(
            {
                "factor": "cascade_probability",
                "probability": sem.cascade_probability,
                "delta": _format_delta(cascade_delta),
            }
        )

    if event.get("command_id"):
        score += 0.05
        reasons.append({"factor": "has_command", "delta": "+0.05"})

    if event.get("file") and event.get("line"):
        score += 0.05
        reasons.append({"factor": "has_location", "delta": "+0.05"})

    if event.get("kind") == "patch" and event.get("phase") == failed_phase:
        score += 0.1
        reasons.append({"factor": "patch_failed_phase", "delta": "+0.10"})

    if is_in_warning_block(event, all_events):
        score -= 0.3
        reasons.append({"factor": "warning_block", "delta": "-0.30"})

    if event.get("parent"):
        score -= 0.4
        reasons.append({"factor": "parent_cascade", "delta": "-0.40"})

    clamped = clamp(score, 0.0, 1.0)
    if clamped != score:
        reasons.append({"factor": "clamp", "from": round(score, 4), "to": clamped})
    if sem.name == "generic_error":
        reasons.append(
            {
                "factor": "generic_context_satisfied",
                "value": sem.context_satisfied,
            }
        )
    return clamped, reasons

def confidence_band(score: float) -> str:
    if score >= 0.85:
        return "high"
    if score >= 0.70:
        return "medium_high"
    if score >= 0.50:
        return "medium"
    return "low"

def _summary(event: dict[str, Any], sem: SemanticClass) -> str:
    location = ""
    if event.get("file") and event.get("line"):
        location = f" at {event['file']}:{event['line']}"
    message = str(event.get("message", "")).strip()
    return f"{event.get('kind')} {sem.name}{location} - {message}"

def _candidate_severity(event: dict[str, Any]) -> str | None:
    severity = event.get("severity")
    if severity is None:
        return None
    normalized = str(severity).strip().lower()
    return normalized or None

def _score_bucket(score: float) -> int:
    """Bucket close scores so severity can break near-ties without lifting cascades."""

    return int((score + (_SCORE_BUCKET_SIZE / 2)) / _SCORE_BUCKET_SIZE)

def _line_no(event: dict[str, Any]) -> int:
    try:
        return int(event.get("line_no", 0))
    except (TypeError, ValueError):
        return 0

def _scan_as_dict(scan_result: ScanResult | dict[str, Any]) -> dict[str, Any]:
    if isinstance(scan_result, ScanResult):
        return scan_result.as_dict()
    return scan_result

def trace(self, level: str, event: str, **fields: Any) -> None:
        if self.trace_logger is not None:
            self.trace_logger.emit(level, "L0_scan", event, **fields)

def _add_event(self, event: DiagnosticEvent, line: LogLine | None = None) -> None:
        if event.kind == "rpm_phase":
            phase = str(event.details.get("phase") or event.phase or "")
            patch_parent = self._last_patch_event_by_phase.get(phase)
            if phase == "%prep" and patch_parent is not None:
                event.parent = patch_parent
                event.details["derived_from"] = "patch_failed"

        if event.kind == "make_cascade" and event.target is not None:
            suffix_index = build_suffix_index(self._source_to_event)
            event.parent = match_make_target(event.target, suffix_index)
            if event.parent is not None:
                self.trace(
                    "INFO",
                    "cascade_associated",
                    event_id=event.id,
                    parent=event.parent,
                    target=event.target,
                )

        self.events.append(event)
        if event.kind == "patch" and event.phase is not None:
            self._last_patch_event_by_phase[event.phase] = event.id
        if event.file is not None and is_supported_source(event.file):
            self._source_to_event[event.file] = event.id
        if event.kind != "make_cascade":
            self.failed_phase = event.phase or self.failed_phase
        trace_fields: dict[str, Any] = {
            "event_id": event.id,
            "kind": event.kind,
            "phase": event.phase,
            "line_no": event.line_no,
            "offset": event.raw_offset,
        }
        if line is not None:
            trace_fields.update(
                {
                    "text": line.text,
                    "raw_text": line.raw_text,
                    "gbs_seconds": line.gbs_seconds,
                }
            )
        self.trace("INFO", "diagnostic_detected", **trace_fields)

def _extract_event(self, line: LogLine) -> DiagnosticEvent | None:
        event_id = f"E{len(self.events) + 1:03d}"
        text = line.text
        lowered = text.lower()
        if not _may_contain_diagnostic(lowered):
            return None

        if "nothing provides" in lowered:
            return self._event(event_id, "depsolve", "error", text, line)

        patch_details = _match_patch(text)
        if patch_details is not None:
            message = str(patch_details.pop("_message", text))
            return self._event(event_id, "patch", "error", message, line, details=patch_details)

        if "file not found:" in lowered or "installed (but unpackaged) file(s) found" in lowered:
            return self._event(event_id, "install_missing", "error", text, line)

        unknown_warning_option = _match_unknown_warning_option(text)
        if unknown_warning_option is not None:
            return self._unknown_warning_option_event(event_id, line, unknown_warning_option)

        compiler_match = COMPILER_PATTERN.search(text)
        if compiler_match and "-werror" in lowered:
            return self._werror_event(event_id, line, compiler_match)

        if "all warnings being treated as errors" in lowered:
            return self._event(event_id, "werror", "error", text, line)

        if _looks_like_werror_diagnostic(text):
            return self._event(event_id, "werror", "error", text, line)

        linker_missing = LINKER_MISSING_PATTERN.search(text)
        if linker_missing:
            return self._event(
                event_id,
                "linker_missing",
                "error",
                text,
                line,
                details={"library": linker_missing.group("library")},
            )

        linker_undef = LINKER_UNDEF_PATTERN.search(text)
        if linker_undef:
            return self._event(
                event_id,
                "linker_undef",
                "error",
                text,
                line,
                details={"symbol": linker_undef.group("symbol")},
            )

        if compiler_match:
            return self._compiler_event(event_id, line, compiler_match)

        rpm_phase = RPM_PHASE_PATTERN.search(text)
        if rpm_phase:
            return self._event(
                event_id,
                "rpm_phase",
                "error",
                text,
                line,
                details={"phase": rpm_phase.group("phase")},
            )

        make_cascade = MAKE_CASCADE_PATTERN.search(text)
        if make_cascade:
            return self._event(
                event_id,
                "make_cascade",
                "error",
                text,
                line,
                target=make_cascade.group("target"),
            )

        if "spec file" in lowered and "error" in lowered:
            return self._event(event_id, "spec_script", "error", text, line)

        if _looks_like_raw_error(lowered):
            return self._event(event_id, "raw_error", "error", text, line)

        return None

def _compiler_event(
        self, event_id: str, line: LogLine, match: re.Match[str]
    ) -> DiagnosticEvent:
        column = match.group("column")
        file_path = match.group("file")
        details: dict[str, Any] = {"is_assembler": _is_assembler_source(file_path)}
        tool = self._current_command_tool()
        if tool is not None:
            details["tool"] = tool
        return self._event(
            event_id,
            "compiler",
            _normalize_severity(match.group("severity")),
            match.group("message"),
            line,
            file=file_path,
            diagnostic_line=int(match.group("line")),
            column=int(column) if column is not None else None,
            details=details,
        )

def _unknown_warning_option_event(
        self, event_id: str, line: LogLine, match: re.Match[str]
    ) -> DiagnosticEvent:
        return self._event(
            event_id,
            "werror",
            "error",
            line.text,
            line,
            details={
                "diagnostic_type": "unknown_warning_option",
                "warning_option": match.group("option"),
            },
        )

def _current_command_tool(self) -> str | None:
        if self.current_command_id is None:
            return None
        for command in reversed(self.commands):
            if command.id == self.current_command_id:
                return _tool_from_command(command.argv_short)
        return None

def scan_buildlog(
    buildlog_path: str | Path,
    *,
    cwd: str | Path | None = None,
    trace_logger: TraceLogger | None = None,
) -> ScanResult:
    """Scan a buildlog using the M1 Layer 0+1 scanner."""

    return BuildLogScanner(cwd=cwd, trace_logger=trace_logger).scan(buildlog_path)

def _iter_log_lines(path: Path) -> Iterator[LogLine]:
    if path.suffix == ".gz":
        yield from _iter_gzip_lines(path)
        return
    yield from _iter_mmap_lines(path)

def _normalize_log_text(raw_text: str) -> tuple[str, int | None]:
    text = ANSI_ESCAPE_PATTERN.sub("", raw_text)
    timestamp = GBS_TIMESTAMP_PATTERN.match(text)
    if timestamp is None:
        return text, None
    return text[timestamp.end() :], int(timestamp.group("seconds"))

def _match_phase_marker(text: str) -> str | None:
    phase_match = PHASE_PATTERN.match(text)
    if phase_match:
        return phase_match.group("phase").split()[0]
    executing_match = EXECUTING_PHASE_PATTERN.match(text)
    if executing_match:
        return executing_match.group("phase")
    return None

def _match_patch(text: str) -> dict[str, str] | None:
    for pattern in PATCH_PATTERNS:
        match = pattern.search(text)
        if match:
            details = {
                key: value
                for key, value in match.groupdict().items()
                if value is not None
            }
            if "can't find file to patch" in text.lower():
                details["_message"] = f"error: patch failed: {text}"
            elif (
                "hunk" in text.lower()
                and "ignored" in text.lower()
                and not text.lower().startswith("hunk")
            ):
                details["_message"] = f"Hunk #{details.get('num', '1')} FAILED: {text}"
            return details
    return None

def _normalize_severity(severity: str) -> str:
    normalized = severity.lower()
    return "error" if normalized == "fatal error" else normalized

def _tool_from_command(command_line: str) -> str | None:
    try:
        parts = shlex.split(command_line)
    except ValueError:
        parts = command_line.split()
    if not parts:
        return None
    return Path(parts[0]).name

def _match_unknown_warning_option(text: str) -> re.Match[str] | None:
    if "-wunknown-warning-option" not in text.lower():
        return None
    return UNKNOWN_WARNING_OPTION_PATTERN.search(text)

def build_source_candidate_observation(
    *,
    packet: dict[str, Any],
    scan_result: ScanResult | dict[str, Any],
    buildlog_path: Path,
    source_candidate_sidecar: dict[str, Any] | None,
    error_cluster_sidecar: dict[str, Any] | None,
) -> dict[str, Any]:
    """Return an observation report without changing analyzer or patch outputs."""

    scan_data = _scan_as_dict(scan_result)
    main_candidates = _source_candidates(source_candidate_sidecar)
    excluded = _excluded_source_diagnostics(source_candidate_sidecar)
    sidecar_items = [
        _coverage_item(candidate, source="source_candidates")
        for candidate in main_candidates
    ]
    sidecar_by_identity = {item.identity: item for item in sidecar_items}
    excluded_by_identity = {
        _identity(excluded_item): excluded_item
        for excluded_item in excluded
        if _identity(excluded_item) is not None
    }
    scan_events_by_identity = {
        _identity(event): event
        for event in _events(scan_data)
        if _identity(event) is not None
    }

    old_coverage, old_decision = _old_path_coverage(
        packet=packet,
        error_cluster_sidecar=error_cluster_sidecar,
    )
    old_by_identity = {item.identity: item for item in old_coverage}

    missed = [
        item
        for item in sidecar_items
        if item.identity not in old_by_identity
    ]
    extra = [
        _extra_item(
            item,
            excluded_by_identity.get(item.identity),
            scan_events_by_identity.get(item.identity),
        )
        for item in old_coverage
        if item.identity not in sidecar_by_identity
    ]

    scanner_gap = _scanner_coverage_gap(
        buildlog_path=buildlog_path,
        scan_data=scan_data,
    )
    type_source_stats = _type_source_stats(main_candidates)

    return {
        "schema_version": OBSERVATION_SCHEMA,
        "scope": (
            "Observation-only report. It does not alter Evidence Packet ranking, "
            "patch-suggest output, or source_candidate sidecar contents."
        ),
        "coverage_diff": {
            "sidecar_diagnostics": [_summarize(item.diagnostic) for item in sidecar_items],
            "old_path_covered": [_summarize(item.diagnostic) for item in old_coverage],
            "missed_by_old": [_summarize(item.diagnostic) for item in missed],
            "extra_by_old": extra,
            "counts": {
                "sidecar_diagnostics": len(sidecar_items),
                "old_path_covered": len(old_coverage),
                "missed_by_old": len(missed),
                "extra_by_old": len(extra),
            },
            "old_path_decision": old_decision,
        },
        "scanner_coverage_gap": scanner_gap,
        "type_source_stats": type_source_stats,
    }

def _old_path_coverage(
    *,
    packet: dict[str, Any],
    error_cluster_sidecar: dict[str, Any] | None,
) -> tuple[list[_CoverageItem], dict[str, Any]]:
    fallback_reasons: dict[str, str] = {}
    sidecar_readable: bool | None = None

    cluster_items, cluster_reason, sidecar_readable = _cluster_old_coverage(
        packet,
        error_cluster_sidecar,
    )
    if cluster_items is not None:
        return cluster_items, {
            "selected_branch": "cluster",
            "fallback_reasons": fallback_reasons,
            "sidecar_readable": sidecar_readable,
        }
    fallback_reasons["cluster"] = cluster_reason

    multi_items, multi_reason = _multi_old_coverage(packet)
    if multi_items is not None:
        return multi_items, {
            "selected_branch": "multi",
            "fallback_reasons": fallback_reasons,
            "sidecar_readable": sidecar_readable,
        }
    fallback_reasons["multi"] = multi_reason

    single_items, single_reason = _single_old_coverage(packet)
    if single_items is not None:
        return single_items, {
            "selected_branch": "single",
            "fallback_reasons": fallback_reasons,
            "sidecar_readable": sidecar_readable,
        }
    fallback_reasons["single"] = single_reason
    return [], {
        "selected_branch": "none",
        "fallback_reasons": fallback_reasons,
        "sidecar_readable": sidecar_readable,
    }

def _cluster_old_coverage(
    packet: dict[str, Any],
    error_cluster_sidecar: dict[str, Any] | None,
) -> tuple[list[_CoverageItem] | None, str, bool | None]:
    summary = packet.get("error_clusters")
    if not isinstance(summary, dict):
        return None, "no_error_clusters", None
    clusters = [cluster for cluster in summary.get("clusters", []) if isinstance(cluster, dict)]
    if not clusters:
        return None, "no_clusters", None
    selected = [cluster for cluster in clusters if _is_large_scale_source_cluster(cluster)]
    if not selected:
        if any(cluster.get("large_scale") is False for cluster in clusters):
            return None, "large_scale_false", None
        return None, "no_large_scale_source_cluster", None
    if (
        not isinstance(error_cluster_sidecar, dict)
        or error_cluster_sidecar.get("schema_version") != "error_clusters_locations/v1"
    ):
        return None, "sidecar_unreadable", False
    sidecar_by_id = {
        str(cluster.get("id")): cluster
        for cluster in error_cluster_sidecar.get("clusters", [])
        if isinstance(cluster, dict) and cluster.get("id") is not None
    }
    items: list[_CoverageItem] = []
    for summary_cluster in selected:
        cluster_id = str(summary_cluster.get("id"))
        warning_option = str(summary_cluster.get("warning_option") or "")
        sidecar_cluster = sidecar_by_id.get(cluster_id)
        if not isinstance(sidecar_cluster, dict):
            continue
        for raw_location in sidecar_cluster.get("locations", []):
            if not isinstance(raw_location, dict):
                continue
            file_value = raw_location.get("file")
            line_value = raw_location.get("line")
            if not isinstance(file_value, str) or not isinstance(line_value, int):
                continue
            location = dict(raw_location)
            location.setdefault("warning_option", warning_option)
            location.setdefault("source_cluster_id", cluster_id)
            item = _coverage_item(location, source="old_cluster")
            items.append(item)
    if not items:
        return None, "sidecar_no_usable_locations", True
    return items, "", True

def _multi_old_coverage(packet: dict[str, Any]) -> tuple[list[_CoverageItem] | None, str]:
    raw_candidates = packet.get("root_cause_candidates")
    if not isinstance(raw_candidates, list):
        return None, "no_root_cause_candidates"
    eligible = [
        candidate
        for candidate in raw_candidates
        if isinstance(candidate, dict) and _is_multi_eligible(candidate)
    ]
    if len(eligible) < 2:
        return None, "candidates_lt_2"
    return [
        _coverage_item(candidate, source="old_multi")
        for candidate in eligible
    ], ""

def _single_old_coverage(packet: dict[str, Any]) -> tuple[list[_CoverageItem] | None, str]:
    primary = packet.get("primary_error")
    if not isinstance(primary, dict) or not primary:
        return None, "no_primary_error"
    return [_coverage_item(primary, source="old_single")], ""

def _is_large_scale_source_cluster(cluster: dict[str, Any]) -> bool:
    if not cluster.get("large_scale"):
        return False
    if cluster.get("kind") != "source_warning_option":
        return False
    diagnostic_kinds = cluster.get("diagnostic_kinds")
    if not isinstance(diagnostic_kinds, list) or not diagnostic_kinds:
        return False
    kinds = {kind for kind in diagnostic_kinds if isinstance(kind, str)}
    return bool(kinds) and kinds.issubset(SOURCE_DIAGNOSTIC_KINDS)

def _is_multi_eligible(candidate: dict[str, Any]) -> bool:
    if candidate.get("is_terminal") is not True:
        return False
    if candidate.get("kind") not in SOURCE_DIAGNOSTIC_KINDS:
        return False
    if not isinstance(candidate.get("file"), str) or not candidate.get("file"):
        return False
    line_value = candidate.get("line")
    if not isinstance(line_value, int) or line_value <= 0:
        return False
    return isinstance(candidate.get("message"), str) and bool(candidate.get("message"))

def _coverage_item(diagnostic: dict[str, Any], *, source: str) -> _CoverageItem:
    identity = _identity(diagnostic)
    if identity is None:
        identity = f"fallback:{_fallback_identity(diagnostic)}"
    data = dict(diagnostic)
    data["coverage_source"] = source
    data["identity"] = identity
    return _CoverageItem(identity=identity, diagnostic=data, source=source)

def _identity(diagnostic: dict[str, Any]) -> str | None:
    event_id = diagnostic.get("event_id") or diagnostic.get("id")
    if isinstance(event_id, str) and event_id:
        return f"event_id:{event_id}"
    dedupe_key = diagnostic.get("dedupe_key")
    if isinstance(dedupe_key, str) and dedupe_key:
        return f"dedupe:{dedupe_key}"
    return None

def _fallback_identity(diagnostic: dict[str, Any]) -> str:
    warning_option = diagnostic.get("warning_option")
    if not isinstance(warning_option, str) or not warning_option:
        warning_option = extract_warning_option(diagnostic) or "<none>"
    parts = [
        f"file={diagnostic.get('normalized_file') or diagnostic.get('file') or '<unknown>'}",
        (
            f"line={diagnostic.get('line')}"
            if isinstance(diagnostic.get("line"), int)
            else "line=<unknown>"
        ),
        (
            f"column={diagnostic.get('column')}"
            if isinstance(diagnostic.get("column"), int)
            else "column=<unknown>"
        ),
        f"warning_option={warning_option}",
        f"semantic_class={diagnostic.get('semantic_class') or '<unknown>'}",
        f"message={_message_fingerprint(str(diagnostic.get('message') or ''))}",
        f"command_id={diagnostic.get('command_id') or '<unknown>'}",
        f"kind={diagnostic.get('kind') or '<unknown>'}",
    ]
    return "|".join(parts)

def _extra_item(
    item: _CoverageItem,
    excluded: dict[str, Any] | None,
    scan_event: dict[str, Any] | None,
) -> dict[str, Any]:
    data = {
        "diagnostic": _summarize(item.diagnostic),
        "new_sidecar_location": "not_present",
        "exclusion_reason": None,
    }
    if excluded is not None:
        data["new_sidecar_location"] = "excluded_source_diagnostics"
        data["exclusion_reason"] = excluded.get("exclusion_reason")
        data["excluded_diagnostic"] = _summarize(excluded)
    elif scan_event is not None:
        data["new_sidecar_location"] = "not_source_candidate_eligible"
        data["exclusion_reason"] = _source_candidate_gate_exclusion_reason(scan_event)
        data["scan_event"] = _summarize(scan_event)
    return data

def _source_candidate_gate_exclusion_reason(event: dict[str, Any]) -> str:
    if event.get("kind") not in SOURCE_DIAGNOSTIC_KINDS:
        return "non_source_kind"
    if not isinstance(event.get("file"), str) or not event.get("file"):
        return "missing_file"
    line_value = event.get("line")
    if not isinstance(line_value, int) or line_value <= 0:
        return "missing_line"
    if event.get("parent") is not None:
        return "explicit_parent"
    if not _is_structured_source_diagnostic(event):
        return "not_fatal_or_werror"
    return "not_present_in_source_candidate_sidecar"

def _scanner_coverage_gap(
    *,
    buildlog_path: Path,
    scan_data: dict[str, Any],
) -> dict[str, Any]:
    raw = _raw_source_diagnostics(buildlog_path)
    structured = [
        event
        for event in _events(scan_data)
        if _is_structured_source_diagnostic(event)
    ]
    structured_keys = {_raw_match_key(event) for event in structured}
    unmatched = [
        item
        for item in raw
        if _raw_match_key(item) not in structured_keys
    ]
    return {
        "scope": (
            "Heuristic observation only. Raw diagnostic-like lines are not converted "
            "into source_candidates."
        ),
        "raw_diagnostic_like_line_count": len(raw),
        "structured_event_count": len(structured),
        "unmatched_diagnostic_like_line_count": len(unmatched),
        "unmatched_diagnostic_like_line_samples": [
            _summarize(item) for item in unmatched[:10]
        ],
        "unmatched_categories": _unmatched_categories(unmatched),
    }

def _raw_source_diagnostics(buildlog_path: Path) -> list[dict[str, Any]]:
    try:
        lines = buildlog_path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return []
    diagnostics: list[dict[str, Any]] = []
    for line_no, line in enumerate(lines, start=1):
        match = RAW_DIAGNOSTIC_PATTERN.search(_strip_gbs_prefix(line))
        if match is None:
            continue
        level = match.group("level").lower()
        message = match.group("message").strip()
        if level == "warning" and "-Werror" not in message:
            continue
        diagnostics.append(
            {
                "line_no": line_no,
                "file": match.group("file"),
                "line": int(match.group("line")),
                "column": _optional_int(match.group("column")),
                "severity": "error" if level in {"error", "fatal error"} else "warning",
                "message": message,
                "warning_option": _warning_option_from_message(message),
            }
        )
    return diagnostics

def _is_structured_source_diagnostic(event: dict[str, Any]) -> bool:
    if event.get("kind") not in SOURCE_DIAGNOSTIC_KINDS:
        return False
    if not isinstance(event.get("file"), str) or not isinstance(event.get("line"), int):
        return False
    if str(event.get("severity") or "").lower() == "error":
        return True
    if event.get("kind") == "werror":
        return True
    return "-Werror" in str(event.get("message") or "")

def _raw_match_key(diagnostic: dict[str, Any]) -> tuple[Any, ...]:
    return (
        diagnostic.get("file"),
        diagnostic.get("line"),
        diagnostic.get("column"),
        diagnostic.get("warning_option") or _warning_option_from_message(
            str(diagnostic.get("message") or "")
        ),
    )

def _warning_option_from_message(message: str) -> str | None:
    for block in WARNING_BLOCK_PATTERN.findall(message):
        for raw_token in block.split(","):
            token = raw_token.strip()
            if token.startswith("-W") and token != "-Werror":
                return str(token)
    return None

def _unmatched_categories(unmatched: list[dict[str, Any]]) -> dict[str, int]:
    categories = {
        "werror_promoted": 0,
        "source_error": 0,
        "truncation_signal": 0,
    }
    for item in unmatched:
        message = str(item.get("message") or "")
        if "-Werror" in message:
            categories["werror_promoted"] += 1
        else:
            categories["source_error"] += 1
        if TRUNCATION_MARKER in message.lower():
            categories["truncation_signal"] += 1
    return {key: value for key, value in categories.items() if value}

def _type_source_stats(candidates: list[dict[str, Any]]) -> dict[str, Any]:
    type_unknown_by_reason: dict[str, int] = {}
    source_unreachable_by_status: dict[str, int] = {}
    source_not_owned_by_status: dict[str, int] = {}
    for candidate in candidates:
        if candidate.get("type_fixability") == "unknown":
            _increment(type_unknown_by_reason, candidate.get("type_fixability_reason"))
        if candidate.get("source_reachable") is not True:
            _increment(source_unreachable_by_status, candidate.get("source_resolution_status"))
        if candidate.get("source_owned") is not True:
            _increment(source_not_owned_by_status, candidate.get("source_ownership_status"))
    return {
        "type_unknown_by_reason": type_unknown_by_reason,
        "source_unreachable_by_status": source_unreachable_by_status,
        "source_not_owned_by_status": source_not_owned_by_status,
    }

def _increment(counter: dict[str, int], key: object) -> None:
    label = str(key) if key else "<unknown>"
    counter[label] = counter.get(label, 0) + 1

def _source_candidates(sidecar: dict[str, Any] | None) -> list[dict[str, Any]]:
    if not isinstance(sidecar, dict):
        return []
    candidates = sidecar.get("candidates")
    if not isinstance(candidates, list):
        return []
    return [candidate for candidate in candidates if isinstance(candidate, dict)]

def _excluded_source_diagnostics(sidecar: dict[str, Any] | None) -> list[dict[str, Any]]:
    if not isinstance(sidecar, dict):
        return []
    diagnostics = sidecar.get("excluded_source_diagnostics")
    if not isinstance(diagnostics, list):
        return []
    return [diagnostic for diagnostic in diagnostics if isinstance(diagnostic, dict)]

def _message_fingerprint(message: str) -> str:
    normalized = re.sub(r"\s+", " ", message.strip().lower())
    return hashlib.sha1(normalized.encode("utf-8", errors="replace")).hexdigest()[
        :MESSAGE_FINGERPRINT_LEN
    ]

def _scan_as_dict(scan_result: ScanResult | dict[str, Any]) -> dict[str, Any]:
    if isinstance(scan_result, ScanResult):
        return scan_result.as_dict()
    return scan_result

def _excluded_parent(event: dict[str, Any], file_value: str) -> dict[str, Any]:
    data = {
        "event_id": event.get("id"),
        "file": file_value,
        "line": event.get("line"),
        "parent": event.get("parent"),
        "exclusion_reason": "explicit_parent",
    }
    return {key: value for key, value in data.items() if value is not None}

def _excluded_missing_location(
    event: dict[str, Any],
    *,
    missing_file: bool,
    missing_line: bool,
) -> dict[str, Any]:
    if missing_file and missing_line:
        reason = "missing_file_and_line"
    elif missing_file:
        reason = "missing_file"
    else:
        reason = "missing_line"
    data = {
        "event_id": event.get("id"),
        "file": event.get("file"),
        "line": event.get("line"),
        "exclusion_reason": reason,
    }
    return {key: value for key, value in data.items() if value is not None}

def _fatal_detection_source(event: dict[str, Any]) -> str | None:
    if str(event.get("severity") or "").strip().lower() == "error":
        return "severity"
    if event.get("kind") == "werror":
        return "kind"
    if "-Werror" in str(event.get("message") or ""):
        return "werror_message_fallback"
    return None

def _type_fixability(
    *,
    warning_option: str | None,
    semantic_class: str,
    message: str,
) -> tuple[str, str]:
    if warning_option in PROBABLY_FIXABLE_WARNING_OPTIONS:
        return "probably_fixable", f"whitelisted_warning_option:{warning_option}"
    if _is_unused_field(semantic_class=semantic_class, message=message):
        return "probably_fixable", "unused_field_message_rule"
    return "unknown", "no_matching_fixability_rule"

def _is_unused_field(*, semantic_class: str, message: str) -> bool:
    lowered = message.lower()
    if semantic_class in {"unused_field", "unused_private_field"}:
        return True
    return (
        "unused" in lowered and "field" in lowered
    ) or "private field" in lowered and "not used" in lowered

def _source_path_info(file_value: str, src_root: str | Path | None) -> _SourcePathInfo:
    raw_normalized = _normalize_raw_file(file_value)
    if _is_system_path(raw_normalized):
        return _SourcePathInfo(
            normalized_file=raw_normalized,
            source_reachable=False,
            source_resolution_status=_unreachable_status(src_root),
            source_owned=False,
            source_ownership_status="system_or_toolchain_path",
        )

    mapped = _mapped_source_path(file_value, src_root)
    if mapped is not None:
        assert src_root is not None
        normalized = _relative_posix(mapped, Path(src_root).resolve())
        if _has_suspect_part(normalized):
            return _SourcePathInfo(
                normalized_file=normalized,
                source_reachable=True,
                source_resolution_status="mapped_to_source_root",
                source_owned=False,
                source_ownership_status="generated_or_vendor",
            )
        return _SourcePathInfo(
            normalized_file=normalized,
            source_reachable=True,
            source_resolution_status="mapped_to_source_root",
            source_owned=True,
            source_ownership_status="project_owned",
        )

    if _has_suspect_part(raw_normalized):
        return _SourcePathInfo(
            normalized_file=raw_normalized,
            source_reachable=False,
            source_resolution_status=_unreachable_status(src_root),
            source_owned=False,
            source_ownership_status="generated_or_vendor",
        )
    if src_root is None:
        return _SourcePathInfo(
            normalized_file=raw_normalized,
            source_reachable=False,
            source_resolution_status="source_root_unavailable",
            source_owned=False,
            source_ownership_status="unknown",
        )
    return _SourcePathInfo(
        normalized_file=raw_normalized,
        source_reachable=False,
        source_resolution_status="source_mapping_unavailable",
        source_owned=False,
        source_ownership_status="unknown",
    )

def _mapped_source_path(file_value: str, src_root: str | Path | None) -> Path | None:
    if src_root is None:
        return None
    root = Path(src_root)
    if not root.is_dir():
        return None
    candidates = _resolve_candidate_paths(file_value, root)
    return candidates[0] if len(candidates) == 1 else None

def _resolve_candidate_paths(file_value: str, src_root: Path) -> list[Path]:
    root = src_root.resolve()
    requested = Path(file_value)
    if requested.is_absolute():
        candidate = requested.resolve()
        if candidate.is_file():
            try:
                candidate.relative_to(root)
            except ValueError:
                pass
            else:
                return [candidate]
        parts = requested.parts
        for start in range(1, len(parts)):
            candidates = _suffix_candidates(root, parts[start:])
            if candidates:
                return candidates
        return []
    return _suffix_candidates(root, requested.parts)

def _suffix_candidates(root: Path, requested_parts: tuple[str, ...]) -> list[Path]:
    if not requested_parts:
        return []
    basename = requested_parts[-1]
    candidates: list[Path] = []
    for path in _iter_files_by_basename(root, basename):
        try:
            relative_parts = path.relative_to(root).parts
        except ValueError:
            continue
        if len(relative_parts) >= len(requested_parts) and (
            relative_parts[-len(requested_parts) :] == requested_parts
        ):
            candidates.append(path)
    return sorted(candidates)

def _iter_files_by_basename(root: Path, basename: str) -> list[Path]:
    matches: list[Path] = []
    pending = [root]
    while pending:
        current = pending.pop()
        try:
            children = sorted(current.iterdir(), key=lambda item: item.name)
        except OSError:
            continue
        for child in children:
            if child.is_dir():
                if _should_skip_dir(child):
                    continue
                pending.append(child)
            elif child.is_file() and child.name == basename:
                matches.append(child)
    return matches

def _is_system_path(normalized_file: str) -> bool:
    return any(
        normalized_file == prefix or normalized_file.startswith(prefix + "/")
        for prefix in SYSTEM_PREFIXES
    )

def _has_suspect_part(normalized_file: str) -> bool:
    parts = [part.lower() for part in normalized_file.split("/") if part]
    return any(part in SUSPECT_PATH_PARTS for part in parts)

def _message_fingerprint(message: str) -> str:
    normalized = re.sub(r"\s+", " ", message.strip().lower())
    return hashlib.sha1(normalized.encode("utf-8", errors="replace")).hexdigest()[
        :MESSAGE_FINGERPRINT_LEN
    ]

def _candidate_counts(candidates: list[dict[str, Any]]) -> dict[str, int]:
    counts = {
        "type_probably_fixable": 0,
        "type_unknown": 0,
        "type_not_fixable": 0,
        "source_reachable": 0,
        "source_owned": 0,
        "patch_ready": 0,
    }
    for candidate in candidates:
        value = candidate.get("type_fixability")
        if value == "probably_fixable":
            counts["type_probably_fixable"] += 1
        elif value == "not_fixable":
            counts["type_not_fixable"] += 1
        else:
            counts["type_unknown"] += 1
        if candidate.get("source_reachable") is True:
            counts["source_reachable"] += 1
        if candidate.get("source_owned") is True:
            counts["source_owned"] += 1
        if (
            value == "probably_fixable"
            and candidate.get("source_reachable") is True
            and candidate.get("source_owned") is True
        ):
            counts["patch_ready"] += 1
    return counts

def _scan_as_dict(scan_result: ScanResult | dict[str, Any]) -> dict[str, Any]:
    if isinstance(scan_result, ScanResult):
        return scan_result.as_dict()
    return scan_result

def __init__(
        self,
        spec_path: str | Path,
        *,
        buildlog_path: str | Path | None = None,
        buildlog_text: str | None = None,
    ) -> None:
        self.spec_path = Path(spec_path)
        self.spec_text = self.spec_path.read_text(encoding="utf-8")
        self._logical_lines = _join_continuations(self.spec_text.splitlines())
        if buildlog_text is not None:
            self.buildlog_text = buildlog_text
        elif buildlog_path is not None:
            self.buildlog_text = Path(buildlog_path).read_text(encoding="utf-8")
        else:
            self.buildlog_text = ""

def find_spec_file(package: str, src_root: str | Path) -> Path:
        """Return the package spec path from a source root.

        Exact `<package>.spec` matches win. If there is only one spec file in the
        tree, it is accepted as a fallback. Ambiguous source roots raise a
        `ValueError` rather than guessing.
        """

        root = Path(src_root)
        if not root.exists():
            raise FileNotFoundError(f"src_root does not exist: {root}")

        specs = sorted(root.rglob("*.spec"))
        exact = [path for path in specs if path.name == f"{package}.spec"]
        if len(exact) == 1:
            return exact[0]
        if len(exact) > 1:
            raise ValueError(f"ambiguous spec files for package {package}: {exact}")
        if len(specs) == 1:
            return specs[0]
        if not specs:
            raise FileNotFoundError(f"no spec file found under {root}")
        raise ValueError(f"ambiguous spec files under {root}: {specs}")

def extract_patches(self) -> list[dict[str, Any]]:
        """Return Patch tags as raw spec declarations."""

        patches: list[dict[str, Any]] = []
        for tag, value in self._iter_tags("Patch"):
            patches.append(_tag_dict(tag, value))
        return patches

def extract_sources(self) -> list[dict[str, Any]]:
        """Return Source tags as raw spec declarations."""

        sources: list[dict[str, Any]] = []
        for tag, value in self._iter_tags("Source"):
            sources.append(_tag_dict(tag, value))
        return sources

def extract_section(self, name: str) -> str:
        """Return the body of the first matching spec section."""

        target = _normalize_section_name(name)
        lines = self.spec_text.splitlines()
        start: int | None = None
        for index, line in enumerate(lines):
            match = SECTION_RE.match(line)
            if match and match.group("name").lower() == target:
                start = index + 1
                break
        if start is None:
            return ""

        end = len(lines)
        for index in range(start, len(lines)):
            match = SECTION_RE.match(lines[index])
            if match and _is_top_level_section(match.group("name")):
                end = index
                break
        return "\n".join(lines[start:end]).strip("\n")

def extract_section_failure_context(self, phase: str) -> dict[str, str]:
        """Locate the last shell command and its output within a failed phase."""

        section_text = self.extract_section(phase)
        if not self.buildlog_text:
            return {
                "last_command": "",
                "last_command_output": "",
                "spec_section_text": section_text,
            }

        phase_lines = _phase_window(self.buildlog_text.splitlines(), _normalize_section_name(phase))
        command_index: int | None = None
        last_command = ""
        for index, line in enumerate(phase_lines):
            command_match = SHELL_COMMAND_RE.match(line)
            if not command_match or _phase_marker_match(line):
                continue
            command_index = index
            last_command = command_match.group("command")

        if command_index is None:
            output_lines: list[str] = []
        else:
            output_lines = []
            for line in phase_lines[command_index + 1 :]:
                if SHELL_COMMAND_RE.match(line):
                    break
                output_lines.append(line)

        return {
            "last_command": last_command,
            "last_command_output": "\n".join(output_lines).strip("\n"),
            "spec_section_text": section_text,
        }

def get_parse_status(self) -> dict[str, Any]:
        """Return v0.5 uncertainty markers for the minimal spec parser."""

        return {
            "macro_expanded": False,
            "condition_evaluated": False,
            "subpackage_resolved": False,
            "confidence": "partial",
            "warnings": self._collect_warnings(),
        }

def _iter_tags(self, prefix: str) -> list[tuple[str, str]]:
        matches: list[tuple[str, str]] = []
        for line in self._logical_lines:
            cleaned = _strip_comment(line)
            if not cleaned:
                continue
            match = TAG_RE.match(cleaned)
            if match and match.group("tag").lower().startswith(prefix.lower()):
                matches.append((match.group("tag"), match.group("value").strip()))
        return matches

def _collect_warnings(self) -> list[str]:
        warnings: list[str] = []
        if "%{" in self.spec_text:
            warnings.append("macros_present_not_expanded")
        if any(re.match(r"^\s*%if", line) for line in self.spec_text.splitlines()):
            warnings.append("conditionals_present_not_evaluated")
        if any(re.match(r"^\s*%package\b", line) for line in self.spec_text.splitlines()):
            warnings.append("subpackages_present_not_resolved")
        return warnings

def _join_continuations(lines: list[str]) -> list[str]:
    logical: list[str] = []
    current = ""
    for line in lines:
        stripped = line.rstrip()
        if stripped.endswith("\\"):
            current += stripped[:-1].rstrip() + " "
            continue
        logical.append((current + stripped).strip())
        current = ""
    if current:
        logical.append(current.strip())
    return logical

def _strip_comment(line: str) -> str:
    stripped = line.strip()
    if not stripped or stripped.startswith("#"):
        return ""
    return re.sub(r"\s+#.*$", "", stripped).strip()

def _tag_dict(tag: str, value: str) -> dict[str, Any]:
    suffix = tag.removeprefix("Patch").removeprefix("Source")
    index = int(suffix) if suffix.isdigit() else None
    return {"tag": tag, "index": index, "value": value}

def _phase_window(lines: list[str], phase: str) -> list[str]:
    start = 0
    for index, line in enumerate(lines):
        match = _phase_marker_match(line)
        if match and match.group("phase").lower() == phase:
            start = index + 1
            break
    else:
        return lines

    end = len(lines)
    for index in range(start, len(lines)):
        if _phase_marker_match(lines[index]):
            end = index
            break
    return lines[start:end]

def _phase_marker_match(line: str) -> re.Match[str] | None:
    match = PHASE_MARKER_RE.match(line)
    if match and _is_top_level_section(match.group("phase")):
        return match
    return None

def as_dict(self) -> dict[str, Any]:
        return {
            "ts": self.ts,
            "level": self.level,
            "layer": self.layer,
            "event": self.event,
            **self.fields,
        }

def close(self) -> None:
        if self._closed:
            return
        self._text_file.close()
        self._jsonl_file.close()
        self._closed = True

def _format_text_record(record: dict[str, Any]) -> str:
    base = f"{record['ts']} {record['level']} {record['layer']} {record['event']}"
    details = {
        key: value
        for key, value in record.items()
        if key not in {"ts", "level", "layer", "event"}
    }
    if not details:
        return base
    return f"{base} {json.dumps(details, ensure_ascii=False, sort_keys=True)}"

def setup_tracing(output_dir: Path | str, *, trace: bool = False) -> TraceLogger:
    """Create a trace logger using DEBUG level when ``trace`` is enabled."""

    return TraceLogger(output_dir, debug=trace)

def estimate_buildlog_tokens(size_bytes: int) -> int:
    """Use a deterministic size heuristic for large logs."""

    return max(1, int(size_bytes / 4))

def _evidence_section_tokens(packet: dict[str, Any], estimator: TokenEstimator) -> int:
    evidence = packet.get("evidence", {})
    if not isinstance(evidence, dict):
        return 1
    snippet_keys = {"source_snippet", "symbol_context", "failure_context", "fallback_context"}
    snippet_data = {
        key: value
        for key, value in evidence.items()
        if key in snippet_keys or key.endswith("_snippet")
    }
    return estimator.estimate_obj(snippet_data or evidence)

def _command_section_tokens(packet: dict[str, Any], estimator: TokenEstimator) -> int:
    evidence = packet.get("evidence", {})
    if not isinstance(evidence, dict):
        return 1
    command_data = {
        key: value
        for key, value in evidence.items()
        if key in {"command_summary", "link_command", "current_command_summary"}
    }
    return estimator.estimate_obj(command_data)

def _header_section_tokens(packet: dict[str, Any], estimator: TokenEstimator) -> int:
    evidence = packet.get("evidence", {})
    if not isinstance(evidence, dict):
        return 1
    return estimator.estimate_obj(evidence.get("header_declarations", []))

def _downgrade_reason(packet: dict[str, Any]) -> str | None:
    reasons = packet.get("degraded_reasons", [])
    if isinstance(reasons, list) and reasons:
        return str(reasons[0])
    return None

def _load_main() -> Callable[[list[str] | None], int]:
    try:
        from gbs_analyzer.analyze import main

        return main
    except ModuleNotFoundError as exc:
        if exc.name != "gbs_analyzer":
            raise

    scripts_dir = Path(__file__).resolve().parent
    sys.path.insert(0, str(scripts_dir))
    from gbs_analyzer.analyze import main

    return main

def run_analyzer_for_buildlog(
    buildlog_path: Path,
    *,
    output_dir: Path,
    src_root: Path | None = None,
    python_executable: str = sys.executable,
    subprocess_runner: SubprocessRunner = subprocess.run,
    extra_pythonpath: Sequence[str | Path] = (),
) -> AnalyzerRunResult:
    """Run analyzer CLI and return the generated evidence path."""

    if not buildlog_path.is_file():
        return AnalyzerRunResult(
            exit_code=3,
            output_dir=output_dir,
            evidence_path=output_dir / "evidence_packet.json",
            error=f"buildlog is not readable: {buildlog_path}",
        )

    output_dir.mkdir(parents=True, exist_ok=True)
    command = [
        python_executable,
        "-m",
        "gbs_analyzer",
        "analyze",
        str(buildlog_path),
        "--output-dir",
        str(output_dir),
    ]
    if src_root is not None:
        command.extend(["--src-root", str(src_root)])

    env = build_analyzer_subprocess_env(extra_pythonpath)
    kwargs: dict[str, object] = {"check": True, "text": True}
    if env is not None:
        kwargs["env"] = env

    try:
        subprocess_runner(command, **kwargs)
    except subprocess.CalledProcessError as exc:
        return AnalyzerRunResult(
            exit_code=1,
            output_dir=output_dir,
            evidence_path=output_dir / "evidence_packet.json",
            error=f"gbs_analyzer exited with {exc.returncode}",
        )

    evidence_path = output_dir / "evidence_packet.json"
    if not evidence_path.is_file():
        return AnalyzerRunResult(
            exit_code=3,
            output_dir=output_dir,
            evidence_path=evidence_path,
            error=f"gbs_analyzer did not write evidence_packet.json: {evidence_path}",
        )
    return AnalyzerRunResult(exit_code=0, output_dir=output_dir, evidence_path=evidence_path)

def discover_analyzer_pythonpath(*, launcher_path: Path | None = None) -> tuple[Path, ...]:
    """Return analyzer sibling scripts path when available for direct-folder usage."""

    env_path = _env_skill_scripts(ANALYZER_SKILL_ENV, ANALYZER_PACKAGE_DIR)
    if env_path is not None:
        return (env_path,)
    sibling_path = _sibling_skill_scripts(
        ANALYZER_SKILL_NAME,
        ANALYZER_PACKAGE_DIR,
        launcher_path=launcher_path,
    )
    if sibling_path is not None:
        return (sibling_path,)
    return ()

def _env_skill_scripts(env_name: str, package_dir: str) -> Path | None:
    raw = os.environ.get(env_name)
    if not raw:
        return None
    root = Path(raw).expanduser().resolve()
    candidates = [root / "scripts", root] if root.name != "scripts" else [root]
    for candidate in candidates:
        if (candidate / package_dir).is_dir():
            return candidate
    raise RuntimeError(f"{env_name} must point to a skill root or scripts directory")

def _sibling_skill_scripts(
    skill_name: str,
    package_dir: str,
    *,
    launcher_path: Path | None,
) -> Path | None:
    if launcher_path is None:
        return None
    skill_root = launcher_path.resolve().parents[1]
    candidate = skill_root.parent / skill_name / "scripts"
    if (candidate / package_dir).is_dir():
        return candidate
    return None

def _clean_mode_context_dirs(output_dir: Path) -> None:
    """Remove stale mode-specific generated context directories before writing output."""

    for name in MODE_CONTEXT_DIRS:
        path = output_dir / name
        if path.is_dir() and not path.is_symlink():
            shutil.rmtree(path)
        elif path.exists():
            path.unlink()

def ingest_large_scale_clusters(
    packet: dict[str, Any],
    *,
    evidence_path: Path,
) -> ClusterIngestResult:
    """Return large-scale source diagnostic clusters exposed by analyzer evidence."""

    summary = packet.get("error_clusters")
    if not isinstance(summary, dict):
        return ClusterIngestResult()

    selected_summaries = [
        cluster
        for cluster in _cluster_summaries(summary)
        if _is_large_scale_source_cluster(cluster)
    ]
    if not selected_summaries:
        return ClusterIngestResult()

    sidecar_ref = summary.get("full_locations_path")
    if not isinstance(sidecar_ref, str) or not sidecar_ref:
        return ClusterIngestResult(advisory="cluster_sidecar_unavailable: missing path")

    sidecar_path = evidence_path.parent / sidecar_ref
    try:
        sidecar = json.loads(sidecar_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return ClusterIngestResult(advisory=f"cluster_sidecar_unavailable: {exc}")

    if (
        not isinstance(sidecar, dict)
        or sidecar.get("schema_version") != ERROR_CLUSTER_LOCATIONS_SCHEMA
    ):
        return ClusterIngestResult(advisory="cluster_sidecar_unavailable: schema mismatch")

    sidecar_by_id = {
        str(cluster.get("id")): cluster
        for cluster in sidecar.get("clusters", [])
        if isinstance(cluster, dict) and cluster.get("id") is not None
    }
    clusters: list[LargeScaleCluster] = []
    for summary_cluster in selected_summaries:
        cluster_id = str(summary_cluster.get("id"))
        sidecar_cluster = sidecar_by_id.get(cluster_id)
        if not isinstance(sidecar_cluster, dict):
            continue
        locations = tuple(_parse_locations(sidecar_cluster.get("locations", [])))
        if not locations:
            continue
        clusters.append(
            LargeScaleCluster(
                id=cluster_id,
                warning_option=str(summary_cluster.get("warning_option") or ""),
                diagnostic_kinds=tuple(
                    str(kind)
                    for kind in summary_cluster.get("diagnostic_kinds", [])
                    if isinstance(kind, str)
                ),
                truncated=bool(summary.get("truncated")),
                locations=locations,
            )
        )

    if not clusters:
        return ClusterIngestResult(advisory="cluster_sidecar_unavailable: no usable locations")
    return ClusterIngestResult(clusters=tuple(clusters))

def _cluster_summaries(summary: dict[str, Any]) -> list[dict[str, Any]]:
    clusters = summary.get("clusters")
    if not isinstance(clusters, list):
        return []
    return [cluster for cluster in clusters if isinstance(cluster, dict)]

def _is_large_scale_source_cluster(cluster: dict[str, Any]) -> bool:
    if not cluster.get("large_scale"):
        return False
    if cluster.get("kind") != "source_warning_option":
        return False
    diagnostic_kinds = cluster.get("diagnostic_kinds")
    if not isinstance(diagnostic_kinds, list) or not diagnostic_kinds:
        return False
    kinds = {kind for kind in diagnostic_kinds if isinstance(kind, str)}
    return bool(kinds) and kinds.issubset(SOURCE_DIAGNOSTIC_KINDS)

def _parse_locations(raw_locations: object) -> list[ClusterLocation]:
    if not isinstance(raw_locations, list):
        return []
    locations: list[ClusterLocation] = []
    for raw in raw_locations:
        if not isinstance(raw, dict):
            continue
        file = raw.get("file")
        line = raw.get("line")
        if not isinstance(file, str) or not file or not isinstance(line, int) or line <= 0:
            continue
        locations.append(
            ClusterLocation(
                event_id=_optional_str(raw.get("event_id")),
                kind=_optional_str(raw.get("kind")),
                file=file,
                line=line,
                column=raw.get("column") if isinstance(raw.get("column"), int) else None,
                line_no=raw.get("line_no") if isinstance(raw.get("line_no"), int) else None,
                message=str(raw.get("message") or ""),
            )
        )
    return locations

