def resolve_fix_all(
    ingest: FixAllIngestResult,
    *,
    src_root: Path | None,
) -> ResolvedFixAllContext:
    """Resolve patch-ready source candidates into per-file contexts."""

    patch_ready = ingest.patch_ready_candidates
    if not patch_ready:
        return ResolvedFixAllContext(
            candidates=ingest.candidates,
            patch_ready_candidates=(),
            file_contexts=(),
        )

    cluster = LargeScaleCluster(
        id=FIX_ALL_CLUSTER_ID,
        warning_option="source_candidates",
        diagnostic_kinds=tuple(
            sorted({candidate.kind for candidate in patch_ready if candidate.kind})
        ),
        truncated=False,
        locations=tuple(candidate.as_location() for candidate in patch_ready),
    )
    resolved = resolve_clusters((cluster,), src_root=src_root)
    file_contexts = resolved[0].file_contexts if resolved else ()
    return ResolvedFixAllContext(
        candidates=ingest.candidates,
        patch_ready_candidates=patch_ready,
        file_contexts=file_contexts,
    )

def format_patch(
    options: FormatPatchOptions,
    *,
    subprocess_runner: SubprocessRunner = subprocess.run,
) -> FormatPatchResult:
    """Format an explicit edit spec into a git-apply-compatible patch."""

    try:
        spec = load_edit_spec(options.edit_spec)
        patch_text = build_patch_text(
            spec,
            src_root=options.src_root,
            git_binary=options.git_binary,
            temp_parent=options.temp_parent,
            subprocess_runner=subprocess_runner,
        )
        if options.check:
            _run_git_apply_check(
                patch_text,
                src_root=options.src_root,
                git_binary=options.git_binary,
                subprocess_runner=subprocess_runner,
            )
        options.output.parent.mkdir(parents=True, exist_ok=True)
        options.output.write_text(patch_text, encoding="utf-8")
    except FormatterError as exc:
        return FormatPatchResult(
            exit_code=EXIT_FORMATTER_ERROR,
            output_path=options.output,
            error=exc.message,
            error_code=exc.code,
        )
    except OSError as exc:
        return FormatPatchResult(
            exit_code=EXIT_FORMATTER_ERROR,
            output_path=options.output,
            error=str(exc),
            error_code="io_error",
        )

    return FormatPatchResult(
        exit_code=EXIT_SUCCESS,
        output_path=options.output,
        check_passed=options.check,
    )

def load_edit_spec(path: Path) -> EditSpec:
    """Load and validate an edit spec JSON file."""

    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise FormatterError("invalid_json", f"edit spec is not valid JSON: {exc}") from exc
    if not isinstance(data, dict):
        raise FormatterError("invalid_schema", "edit spec root must be an object")

    schema_version = _required_str(data, "schema_version")
    if schema_version != EDIT_SPEC_SCHEMA:
        raise FormatterError(
            "unsupported_schema",
            f"unsupported edit spec schema: {schema_version}",
        )
    raw_edits = data.get("edits")
    if not isinstance(raw_edits, list) or not raw_edits:
        raise FormatterError("missing_edits", "edit spec must contain at least one edit")

    edits = tuple(_parse_edit(raw_edit, index) for index, raw_edit in enumerate(raw_edits, start=1))
    return EditSpec(
        schema_version=schema_version,
        patch_name=_optional_str(data, "patch_name"),
        description=_optional_str(data, "description"),
        edits=edits,
    )

def _parse_edit(raw: object, index: int) -> Edit:
    if not isinstance(raw, dict):
        raise FormatterError("invalid_edit", f"edit #{index} must be an object")
    file = _required_str(raw, "file")
    operation = _optional_str(raw, "operation") or "replace"
    line = raw.get("line")
    if line is not None and (not isinstance(line, int) or line <= 0):
        raise FormatterError("invalid_line", f"edit #{index} line must be a positive integer")
    if operation == "replace":
        old = _required_str(raw, "old")
        if old == "":
            raise FormatterError("empty_old", f"edit #{index} old text must not be empty")
        new = _required_str(raw, "new")
        return Edit(
            file=file,
            operation=operation,
            old=old,
            new=new,
            line=line,
            before=_optional_str(raw, "before"),
            after=_optional_str(raw, "after"),
        )
    if operation == "insert_after":
        if line is None:
            raise FormatterError(
                "missing_line",
                f"edit #{index} insert_after requires a positive line",
            )
        anchor = _required_str(raw, "anchor")
        if anchor == "":
            raise FormatterError("empty_anchor", f"edit #{index} anchor must not be empty")
        insert = _required_str(raw, "insert")
        if insert == "":
            raise FormatterError("empty_insert", f"edit #{index} insert must not be empty")
        return Edit(
            file=file,
            operation=operation,
            line=line,
            anchor=anchor,
            insert=insert,
        )
    raise FormatterError("unsupported_operation", f"unsupported edit operation: {operation}")

def _required_str(data: dict[str, object], key: str) -> str:
    value = data.get(key)
    if not isinstance(value, str):
        raise FormatterError("invalid_schema", f"{key} must be a string")
    return value

def _optional_str(data: dict[str, object], key: str) -> str | None:
    value = data.get(key)
    if value is None:
        return None
    if not isinstance(value, str):
        raise FormatterError("invalid_schema", f"{key} must be a string")
    return value

def _resolve_src_root(src_root: Path) -> Path:
    resolved = src_root.resolve()
    if not resolved.is_dir():
        raise FormatterError("src_root_not_found", f"src-root is not a directory: {src_root}")
    return resolved

def _resolve_edits(
    edits: tuple[Edit, ...],
    src_root: Path,
) -> dict[Path, tuple[_ResolvedEdit, ...]]:
    grouped: dict[Path, list[_ResolvedEdit]] = defaultdict(list)
    for edit in edits:
        source_path, relative_path = _resolve_source_path(edit.file, src_root)
        grouped[relative_path].append(
            _ResolvedEdit(
                edit=edit,
                source_path=source_path,
                relative_path=relative_path,
                start=-1,
                end=-1,
            )
        )
    return {path: tuple(path_edits) for path, path_edits in grouped.items()}

def _resolve_source_path(file_name: str, src_root: Path) -> tuple[Path, Path]:
    raw_path = Path(file_name)
    candidate = raw_path.resolve() if raw_path.is_absolute() else (src_root / raw_path).resolve()
    try:
        relative_path = candidate.relative_to(src_root)
    except ValueError as exc:
        raise FormatterError(
            "file_outside_src_root",
            f"edit file escapes src-root: {file_name}",
        ) from exc
    if not candidate.is_file():
        raise FormatterError("file_not_found", f"edit file is not readable: {file_name}")
    if not relative_path.parts:
        raise FormatterError("invalid_file", f"edit file is invalid: {file_name}")
    return candidate, relative_path

def _locate_file_edits(
    original_text: str,
    edits: tuple[_ResolvedEdit, ...],
) -> tuple[_ResolvedEdit, ...]:
    located: list[_ResolvedEdit] = []
    for resolved_edit in edits:
        match = _locate_edit(original_text, resolved_edit.edit)
        located.append(
            _ResolvedEdit(
                edit=resolved_edit.edit,
                source_path=resolved_edit.source_path,
                relative_path=resolved_edit.relative_path,
                start=match.start,
                end=match.end,
            )
        )
    _ensure_non_overlapping(located)
    return tuple(located)

def _locate_edit(text: str, edit: Edit) -> _Match:
    if edit.operation == "insert_after":
        return _locate_insert_after(text, edit)
    assert edit.old is not None
    if edit.before is not None or edit.after is not None:
        before = edit.before or ""
        after = edit.after or ""
        anchor = f"{before}{edit.old}{after}"
        matches = _find_matches(text, anchor, offset=len(before), old_length=len(edit.old))
        if not matches:
            raise FormatterError(
                "context_not_found",
                f"context anchor did not match for {edit.file}",
            )
        if len(matches) > 1:
            raise FormatterError(
                "context_not_unique",
                f"context anchor matched multiple locations for {edit.file}: "
                f"{_candidate_lines(matches)}",
            )
        return matches[0]

    matches = _find_matches(text, edit.old)
    if not matches:
        raise FormatterError("old_not_found", f"old text did not match for {edit.file}")
    if len(matches) == 1:
        return matches[0]
    if edit.line is None:
        raise FormatterError(
            "old_not_unique",
            f"old text matched multiple locations for {edit.file}: {_candidate_lines(matches)}",
        )
    return _disambiguate_by_line(edit, matches)

def _disambiguate_by_line(edit: Edit, matches: list[_Match]) -> _Match:
    assert edit.line is not None
    covering = [
        match for match in matches if match.start_line <= edit.line <= match.end_line
    ]
    if len(covering) == 1:
        return covering[0]
    if len(covering) > 1:
        raise FormatterError(
            "old_not_unique",
            f"old text matched multiple locations covering line {edit.line} for {edit.file}: "
            f"{_candidate_lines(covering)}",
        )

    nearest_distance = min(abs(match.start_line - edit.line) for match in matches)
    nearest = [
        match for match in matches if abs(match.start_line - edit.line) == nearest_distance
    ]
    if len(nearest) == 1:
        return nearest[0]
    raise FormatterError(
        "old_not_unique",
        f"old text matched multiple equally near locations for {edit.file}: "
        f"{_candidate_lines(nearest)}",
    )

def _locate_insert_after(text: str, edit: Edit) -> _Match:
    assert edit.line is not None
    assert edit.anchor is not None
    lines = text.splitlines(keepends=True)
    if edit.line > len(lines):
        raise FormatterError(
            "insert_out_of_range",
            f"insert_after line {edit.line} is outside {edit.file}",
        )
    line_text = lines[edit.line - 1].removesuffix("\n").removesuffix("\r")
    if line_text != edit.anchor:
        raise FormatterError(
            "anchor_not_found",
            f"insert_after anchor did not match line {edit.line} for {edit.file}",
        )
    end = sum(len(line) for line in lines[: edit.line])
    return _Match(start=end, end=end, start_line=edit.line + 1, end_line=edit.line + 1)

def _ensure_non_overlapping(edits: list[_ResolvedEdit]) -> None:
    sorted_edits = sorted(edits, key=lambda item: item.start)
    previous: _ResolvedEdit | None = None
    for current in sorted_edits:
        if previous is not None and previous.end > current.start:
            raise FormatterError(
                "overlapping_edits",
                f"edits overlap in {current.relative_path.as_posix()}",
            )
        previous = current

def _apply_resolved_edits(text: str, edits: tuple[_ResolvedEdit, ...]) -> str:
    modified = text
    for resolved_edit in sorted(edits, key=lambda item: item.start, reverse=True):
        replacement = _replacement_text(resolved_edit.edit)
        modified = (
            modified[: resolved_edit.start]
            + replacement
            + modified[resolved_edit.end :]
        )
    return modified

def _replacement_text(edit: Edit) -> str:
    if edit.operation == "insert_after":
        assert edit.insert is not None
        return edit.insert if edit.insert.endswith("\n") else edit.insert + "\n"
    assert edit.new is not None
    return edit.new

def _run_git_diff_no_index(
    orig_file: Path,
    mod_file: Path,
    *,
    relative_path: Path,
    git_binary: str,
    subprocess_runner: SubprocessRunner,
) -> str:
    try:
        completed = subprocess_runner(
            [git_binary, "diff", "--no-index", "--", str(orig_file), str(mod_file)],
            check=False,
            capture_output=True,
            text=True,
        )
    except FileNotFoundError as exc:
        raise FormatterError("git_not_found", f"git command not found: {git_binary}") from exc
    if completed.returncode not in (0, 1):
        raise FormatterError(
            "git_diff_failed",
            f"git diff --no-index failed: {completed.stderr.strip()}",
        )
    if completed.returncode == 0:
        return ""
    if not completed.stdout:
        raise FormatterError("git_diff_failed", "git diff --no-index produced no output")
    return _rewrite_diff_headers(completed.stdout, relative_path)

def _rewrite_diff_headers(diff_text: str, relative_path: Path) -> str:
    rel = relative_path.as_posix()
    rewritten: list[str] = []
    for line in diff_text.splitlines():
        if line.startswith("diff --git "):
            rewritten.append(f"diff --git a/{rel} b/{rel}")
        elif line.startswith("--- "):
            rewritten.append(f"--- a/{rel}")
        elif line.startswith("+++ "):
            rewritten.append(f"+++ b/{rel}")
        else:
            rewritten.append(line)
    return "\n".join(rewritten) + "\n"

def _run_git_apply_check(
    patch_text: str,
    *,
    src_root: Path,
    git_binary: str,
    subprocess_runner: SubprocessRunner,
) -> None:
    try:
        completed = subprocess_runner(
            [git_binary, "-C", str(src_root), "apply", "--check", "-"],
            input=patch_text,
            check=False,
            capture_output=True,
            text=True,
        )
    except FileNotFoundError as exc:
        raise FormatterError("git_not_found", f"git command not found: {git_binary}") from exc
    if completed.returncode != 0:
        raise FormatterError(
            "git_apply_check_failed",
            f"git apply --check failed: {completed.stderr.strip()}",
        )

def extract_first_diagnostic(packet: dict[str, Any]) -> CompileErrorEvidence:
    """Extract the primary analyzer diagnostic and semantic class."""

    primary = packet.get("primary_error")
    if not isinstance(primary, dict):
        primary = {}

    evidence = packet.get("evidence")
    if not isinstance(evidence, dict):
        evidence = {}
    source_snippet = evidence.get("source_snippet")
    if not isinstance(source_snippet, dict):
        source_snippet = None

    return CompileErrorEvidence(
        kind=_string(primary.get("kind"), default="unknown"),
        message=_string(primary.get("message"), default=""),
        semantic_class=_semantic_class(packet, primary),
        file=_optional_string(primary.get("file")),
        line=_optional_int(primary.get("line")),
        column=_optional_int(primary.get("column")),
        source_snippet=source_snippet,
        raw_primary_error=primary,
    )

def _semantic_class(packet: dict[str, Any], primary: dict[str, Any]) -> str:
    direct = primary.get("semantic_class") or primary.get("category")
    if direct:
        return str(direct)
    candidates = packet.get("root_cause_candidates")
    if isinstance(candidates, list) and candidates:
        first = candidates[0]
        if isinstance(first, dict) and first.get("semantic_class"):
            return str(first["semantic_class"])
    return "unknown"

def ingest_terminal_source_candidates(packet: dict[str, Any]) -> MultiCandidateIngestResult:
    """Select independent terminal compiler/Werror candidates from analyzer evidence."""

    raw_candidates = packet.get("root_cause_candidates")
    if not isinstance(raw_candidates, list):
        return MultiCandidateIngestResult()

    eligible: list[MultiCandidateDiagnostic] = []
    skipped: list[SkippedCandidate] = []
    for raw in raw_candidates:
        if not isinstance(raw, dict):
            continue
        reason = _skip_reason(raw)
        if reason is not None:
            skipped.append(_skipped(raw, reason))
            continue
        eligible.append(_diagnostic(len(eligible) + 1, raw, packet))

    if len(eligible) < 2:
        return MultiCandidateIngestResult(skipped=tuple(skipped))
    return MultiCandidateIngestResult(
        candidates=tuple(eligible),
        skipped=tuple(skipped),
    )

def _skip_reason(candidate: dict[str, Any]) -> str | None:
    if candidate.get("is_terminal") is not True:
        return "not_terminal_cascade"
    kind = candidate.get("kind")
    if kind not in SOURCE_DIAGNOSTIC_KINDS:
        return "not_source_diagnostic"
    file_value = candidate.get("file")
    message = candidate.get("message")
    line = candidate.get("line")
    if not isinstance(file_value, str) or not file_value:
        return "missing_file"
    if not isinstance(line, int) or line <= 0:
        return "missing_line"
    if not isinstance(message, str) or not message:
        return "missing_message"
    return None

def _skipped(candidate: dict[str, Any], reason: str) -> SkippedCandidate:
    return SkippedCandidate(
        event_id=str(candidate["event_id"]) if candidate.get("event_id") is not None else None,
        kind=str(candidate["kind"]) if candidate.get("kind") is not None else None,
        rank=_optional_int(candidate.get("rank")),
        reason=reason,
        summary=str(candidate["summary"]) if isinstance(candidate.get("summary"), str) else None,
    )

def _write_edit_spec_skeleton(
    candidate: ResolvedCandidateContext,
    *,
    edit_specs_dir: Path,
) -> tuple[Path | None, bool, str | None]:
    source = candidate.resolved.source_context
    evidence = candidate.resolved.evidence
    if source is None or evidence.file is None or evidence.line is None:
        return None, False, None
    line_text = _line_text(source.text, source.start_line, evidence.line)
    if line_text is None:
        return None, True, None
    suppressed_reason = should_suppress_skeleton(line_text, evidence.message)
    if suppressed_reason is not None:
        return None, False, suppressed_reason
    path = edit_specs_dir / _edit_spec_name(candidate.diagnostic)
    data = {
        "schema_version": EDIT_SPEC_SCHEMA,
        "patch_name": _patch_name(candidate.diagnostic),
        "description": "Fill new for this independent source diagnostic.",
        "edits": [
            {
                "file": evidence.file,
                "line": evidence.line,
                "old": line_text,
                "new": FILL_REPLACEMENT_LINE,
            }
        ],
    }
    path.write_text(
        json.dumps(data, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    return path, False, None

def _line_text(text: str, start_line: int, target_line: int) -> str | None:
    index = target_line - start_line
    if index < 0:
        return None
    lines = text.splitlines()
    if index >= len(lines):
        return None
    return lines[index]

def _file_slug(file_value: str | None) -> str:
    if not file_value:
        return "unknown"
    return _slug(Path(file_value).name)

def _location(file: str | None, line: int | None, column: int | None) -> str:
    if not file:
        return "n/a"
    if line is None:
        return file
    if column is None:
        return f"{file}:{line}"
    return f"{file}:{line}:{column}"

def _relative(path: Path, root: Path) -> str:
    try:
        return path.relative_to(root).as_posix()
    except ValueError:
        return path.as_posix()

def _location(file: str | None, line: int | None, column: int | None) -> str:
    if not file:
        return "n/a"
    if line is None:
        return file
    if column is None:
        return f"{file}:{line}"
    return f"{file}:{line}:{column}"

def _patch_guidance_not_applicable() -> str:
    return "\n".join(
        [
            "## How to proceed",
            "",
            "This skill only prepares patch context for compiler and Werror source "
            "diagnostics. Use the workflow suggester for this fault class instead of "
            "generating a source patch here.",
        ]
    )

def resolve_context(
    evidence: CompileErrorEvidence,
    *,
    src_root: Path | None = None,
    window: int = DEFAULT_CONTEXT_WINDOW,
) -> ResolvedContext:
    """Resolve A/B/C source context levels without failing on missing source."""

    if not evidence.is_source_diagnostic:
        return ResolvedContext(
            status="not_applicable",
            level="not_applicable",
            evidence=evidence,
            advisory=(
                f"primary_error.kind is `{evidence.kind}`, so this skill is not applicable. "
                "This skill only prepares patch context for compiler and Werror source "
                "diagnostics. Use the workflow suggester for this fault class."
            ),
        )

    if evidence.source_snippet is not None:
        return ResolvedContext(
            status="source_context_available",
            level="A",
            evidence=evidence,
            source_context=_context_from_evidence(evidence.source_snippet),
        )

    if evidence.file and evidence.line:
        candidate_paths = resolve_candidate_paths(evidence.file, src_root)
        if len(candidate_paths) == 1:
            return ResolvedContext(
                status="source_context_available",
                level="A",
                evidence=evidence,
                source_context=_context_from_file(
                    candidate_paths[0],
                    evidence.line,
                    window=window,
                ),
            )
        if len(candidate_paths) > 1:
            return ResolvedContext(
                status="source_context_ambiguous",
                level="B",
                evidence=evidence,
                advisory=(
                    f"Multiple source files match `{evidence.file}` under the provided "
                    "source root. Ask the outer assistant or user to disambiguate before "
                    "generating a patch."
                ),
                candidates=tuple(str(path) for path in candidate_paths[:10]),
            )
        return ResolvedContext(
            status="source_context_unavailable",
            level="B",
            evidence=evidence,
            advisory=(
                f"Source context for `{evidence.file}:{evidence.line}` is unavailable to "
                "this skill. Ask the outer assistant to open that file and inspect the "
                "reported line before generating a patch."
            ),
        )

    return ResolvedContext(
        status="diagnostic_only",
        level="C",
        evidence=evidence,
        advisory=(
            "The source diagnostic has no usable file and line number. Provide only "
            "diagnostic context; do not guess a source patch without inspecting the tree."
        ),
    )

def resolve_candidate_paths(file_value: str, src_root: Path | None) -> list[Path]:
    """Return source candidates inside src_root using path-segment suffix matching."""

    if src_root is None or not src_root.is_dir():
        return []
    root = src_root.resolve()
    requested = Path(file_value)
    if requested.is_absolute():
        return _absolute_candidate(requested, root)

    requested_parts = _strip_leading_dot_segments(requested.parts)
    if not requested_parts:
        return []
    return _suffix_candidates(root, requested_parts)

def _strip_leading_dot_segments(parts: tuple[str, ...]) -> tuple[str, ...]:
    index = 0
    while index < len(parts) and parts[index] in {".", ".."}:
        index += 1
    return parts[index:]

def _suffix_candidates(root: Path, requested_parts: tuple[str, ...]) -> list[Path]:
    if not requested_parts:
        return []
    basename = requested_parts[-1]
    candidates: list[Path] = []
    for path in _iter_files_by_basename(root, basename):
        try:
            relative_parts = path.relative_to(root).parts
        except ValueError:
            continue
        if len(relative_parts) >= len(requested_parts) and (
            relative_parts[-len(requested_parts) :] == requested_parts
        ):
            candidates.append(path)
    return sorted(candidates)

def _context_from_evidence(snippet: dict[str, Any]) -> SourceContext:
    return SourceContext(
        path=str(snippet.get("path", "")),
        start_line=_int_or_default(snippet.get("start_line"), 1),
        end_line=_int_or_default(snippet.get("end_line"), 1),
        text=str(snippet.get("text", "")),
        origin="evidence",
    )

def _context_from_file(path: Path, line: int, *, window: int) -> SourceContext:
    lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    start = max(1, line - window)
    end = min(len(lines), line + window)
    return SourceContext(
        path=str(path),
        start_line=start,
        end_line=end,
        text="\n".join(lines[start - 1 : end]),
        origin="src_root_suffix_search",
    )

def _absolute_candidate(path: Path, root: Path) -> list[Path]:
    if _is_system_absolute_path(path):
        return []

    candidate = path.resolve()
    if candidate.is_file():
        try:
            candidate.relative_to(root)
        except ValueError:
            pass
        else:
            return [candidate]

    parts = path.parts
    for start in range(1, len(parts)):
        suffix = parts[start:]
        candidates = _suffix_candidates(root, suffix)
        if candidates:
            return candidates
    return []

def _is_system_absolute_path(path: Path) -> bool:
    parts = path.parts
    return any(parts[: len(prefix)] == prefix for prefix in SYSTEM_ABSOLUTE_PREFIXES)

def _iter_files_by_basename(root: Path, basename: str) -> list[Path]:
    matches: list[Path] = []
    pending = [root]
    while pending:
        current = pending.pop()
        try:
            children = sorted(current.iterdir(), key=lambda item: item.name)
        except OSError:
            continue
        for child in children:
            if child.is_dir():
                if _should_skip_dir(child):
                    continue
                pending.append(child)
            elif child.is_file() and child.name == basename:
                matches.append(child)
    return matches

def should_suppress_skeleton(old: str, message: str) -> str | None:
    """Return why an edit-spec skeleton row would be misleading, if known."""

    old_compact = "".join(old.strip().split())
    if old_compact in STRUCTURAL_ONLY_LINE_COMPACTS:
        return "structural_closing_line"

    tokens = tuple(_source_like_message_tokens(message))
    if tokens and not any(token in old for token in tokens):
        return "no_message_symbol_in_line"
    return None

def _source_like_message_tokens(message: str) -> tuple[str, ...]:
    tokens: list[str] = []
    for token in IDENTIFIER_RE.findall(message):
        if token in MESSAGE_TOKEN_STOPWORDS:
            continue
        if token.startswith("W"):
            continue
        if _looks_like_source_symbol(token):
            tokens.append(token)
    return tuple(dict.fromkeys(tokens))

def _looks_like_source_symbol(token: str) -> bool:
    # Conservative on purpose: lowercase words are often prose, so B/advisory covers them.
    return "_" in token or any(char.isupper() for char in token)

def ingest_spec_toolchain_flags(packet: dict[str, Any]) -> SpecToolchainFlagDiagnostic:
    """Return unknown warning options visible in analyzer evidence."""

    messages = tuple(_iter_candidate_messages(packet))
    options: list[str] = []
    seen: set[str] = set()
    for message in messages:
        if WARNING_OPTION_MARKER not in message and "unknown warning option" not in message:
            continue
        for match in UNKNOWN_WARNING_RE.finditer(message):
            option = match.group("option")
            if option not in seen:
                seen.add(option)
                options.append(option)
    return SpecToolchainFlagDiagnostic(options=tuple(options), messages=messages)

def _iter_candidate_messages(packet: dict[str, Any]) -> list[str]:
    messages: list[str] = []
    primary = packet.get("primary_error")
    if isinstance(primary, dict):
        message = primary.get("message")
        if isinstance(message, str):
            messages.append(message)
    candidates = packet.get("root_cause_candidates")
    if isinstance(candidates, list):
        for candidate in candidates:
            if not isinstance(candidate, dict):
                continue
            message = candidate.get("message")
            if isinstance(message, str):
                messages.append(message)
    return messages

def _render_edit_spec(resolved: SpecToolchainFlagResolution) -> dict[str, Any]:
    assert resolved.spec_relative_path is not None
    assert resolved.insert_after_line is not None
    assert resolved.anchor is not None
    assert resolved.insert is not None
    return {
        "schema_version": EDIT_SPEC_SCHEMA,
        "patch_name": "candidate_spec_toolchain_flags.patch",
        "description": "Insert Clang-only stripping for warning options unsupported by Clang.",
        "edits": [
            {
                "operation": "insert_after",
                "file": resolved.spec_relative_path,
                "line": resolved.insert_after_line,
                "anchor": resolved.anchor,
                "insert": resolved.insert,
            }
        ],
    }

def _relative(path: Path, base: Path) -> str:
    try:
        return path.relative_to(base).as_posix()
    except ValueError:
        return path.as_posix()

def resolve_spec_toolchain_flags(
    diagnostic: SpecToolchainFlagDiagnostic,
    *,
    src_root: Path | None,
) -> SpecToolchainFlagResolution:
    """Find a safe .spec insertion point for Clang-only flag stripping."""

    if not diagnostic.options:
        return SpecToolchainFlagResolution(status="not_applicable", options=())
    if src_root is None:
        return _advisory(diagnostic.options, "source root unavailable; cannot inspect .spec")
    try:
        spec_path = _find_single_spec(src_root)
    except (FileNotFoundError, ValueError) as exc:
        return _advisory(diagnostic.options, str(exc))

    lines = spec_path.read_text(encoding="utf-8", errors="surrogateescape").splitlines()
    section = _build_section_bounds(lines)
    if section is None:
        return _advisory(diagnostic.options, "no %build section found in .spec")
    start, end = section
    source_lines = _flag_source_lines(lines, start, end, diagnostic.options)
    if not source_lines:
        return _advisory(
            diagnostic.options,
            "unknown options were not found in %build CFLAGS/CXXFLAGS lines",
        )
    consumer_line = _first_consumer_line(lines, start, end)
    if consumer_line is None:
        return _advisory(diagnostic.options, "no flag consumer found in %build section")
    last_source_line = max(source_lines)
    if last_source_line >= consumer_line:
        return _advisory(
            diagnostic.options,
            "CFLAGS/CXXFLAGS option source appears after the first flag consumer",
        )

    try:
        existing_block = _existing_safe_clang_block(lines, last_source_line, consumer_line)
    except UnsafeSpecLayout as exc:
        return _advisory(diagnostic.options, str(exc))
    if existing_block is not None:
        insert_after, existing_lines = existing_block
        insert = _render_strip_block(diagnostic.options, wrap=False, existing_lines=existing_lines)
        if not insert:
            return _advisory(
                diagnostic.options,
                "existing clang toolchain block already strips the unknown options",
            )
    else:
        insert_after = last_source_line
        insert = _render_strip_block(diagnostic.options, wrap=True)
    anchor = lines[insert_after - 1]
    spec_relative = spec_path.resolve().relative_to(src_root.resolve()).as_posix()
    return SpecToolchainFlagResolution(
        status="spec_toolchain_flag_context_available",
        options=diagnostic.options,
        spec_path=spec_path,
        spec_relative_path=spec_relative,
        insert_after_line=insert_after,
        anchor=anchor,
        insert=insert,
    )

def _advisory(options: tuple[str, ...], reason: str) -> SpecToolchainFlagResolution:
    return SpecToolchainFlagResolution(
        status="spec_toolchain_flag_advisory",
        options=options,
        advisory=reason,
    )

def _find_single_spec(src_root: Path) -> Path:
    root = src_root.resolve()
    specs = sorted(
        path
        for path in root.rglob("*.spec")
        if ".git" not in path.parts and not any(part.startswith("GBS-ROOT") for part in path.parts)
    )
    if not specs:
        raise FileNotFoundError(f"no spec file found under {src_root}")
    if len(specs) > 1:
        raise ValueError(f"ambiguous spec files under {src_root}: {specs}")
    return specs[0]

def _build_section_bounds(lines: list[str]) -> tuple[int, int] | None:
    start: int | None = None
    for index, line in enumerate(lines, start=1):
        if BUILD_SECTION_RE.match(line):
            start = index + 1
            break
    if start is None:
        return None
    end = len(lines) + 1
    for index in range(start, len(lines) + 1):
        if TOP_LEVEL_SECTION_RE.match(lines[index - 1]):
            end = index
            break
    return start, end

def _flag_source_lines(
    lines: list[str],
    start: int,
    end: int,
    options: tuple[str, ...],
) -> list[int]:
    matches: list[int] = []
    for index in range(start, end):
        line = lines[index - 1]
        if "${CFLAGS/" in line or "${CXXFLAGS/" in line:
            continue
        if not FLAG_ASSIGN_RE.search(line):
            continue
        if any(option in line for option in options):
            matches.append(index)
    return matches

def _first_consumer_line(lines: list[str], start: int, end: int) -> int | None:
    for index in range(start, end):
        if CONSUMER_RE.match(lines[index - 1]):
            return index
    return None

def _existing_safe_clang_block(
    lines: list[str],
    last_source_line: int,
    consumer_line: int,
) -> tuple[int, set[str]] | None:
    for index in range(last_source_line + 1, consumer_line):
        if not CLANG_IF_RE.match(lines[index - 1]):
            continue
        block_end = _matching_endif(lines, index, consumer_line)
        if block_end is None:
            raise UnsafeSpecLayout(
                "existing clang toolchain block is not safely closed before the flag consumer"
            )
        existing_lines = {line.strip() for line in lines[index:block_end - 1]}
        return block_end - 1, existing_lines
    return None

def _matching_endif(lines: list[str], clang_if_line: int, consumer_line: int) -> int | None:
    depth = 0
    for index in range(clang_if_line, consumer_line):
        line = lines[index - 1]
        if line.lstrip().startswith("%if"):
            depth += 1
        elif ENDIF_RE.match(line):
            depth -= 1
            if depth == 0:
                return index
    return None

def _render_strip_block(
    options: tuple[str, ...],
    *,
    wrap: bool,
    existing_lines: set[str] | None = None,
) -> str:
    lines: list[str] = []
    if wrap:
        lines.extend(["%{?_toolchain:", "%if %{toolchain_is clang}"])
    existing = existing_lines or set()
    for option in options:
        line = f"CFLAGS=${{CFLAGS/{option}/}}"
        if line not in existing:
            lines.append(line)
    for option in options:
        line = f"CXXFLAGS=${{CXXFLAGS/{option}/}}"
        if line not in existing:
            lines.append(line)
    if wrap:
        lines.extend(["%endif", "}"])
    return "\n".join(lines)

