def write_buildlog(path: Path, events: list[dict[str, object]]) -> None:
    lines = [
        (
            f"{item['file']}:{item['line']}:{item['column']}: error: "
            f"{item['message']}"
        )
        for item in events
        if item.get("file") and item.get("line") and item.get("column")
    ]
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")

