def _validate_schema(edit_spec: dict[str, Any]) -> list[dict[str, Any]]:
    if edit_spec.get("schema_version") != EDIT_SPEC_SCHEMA:
        raise EditSpecViolation("unsupported edit_spec schema_version")
    patch_name = edit_spec.get("patch_name")
    if not isinstance(patch_name, str) or not patch_name:
        raise EditSpecViolation("edit_spec patch_name must be a non-empty string")
    edits = edit_spec.get("edits")
    if not isinstance(edits, list) or not edits:
        raise EditSpecViolation("edit_spec edits must be a non-empty list")
    validated: list[dict[str, Any]] = []
    for index, raw_edit in enumerate(edits):
        if not isinstance(raw_edit, dict):
            raise EditSpecViolation(f"edit {index} must be an object")
        for required in ("file", "old", "new"):
            if required not in raw_edit:
                raise EditSpecViolation(f"edit {index} missing required field: {required}")
        if not isinstance(raw_edit["file"], str) or not raw_edit["file"]:
            raise EditSpecViolation(f"edit {index} file must be a non-empty string")
        if not isinstance(raw_edit["old"], str) or raw_edit["old"] == "":
            raise EditSpecViolation(f"edit {index} old must be a non-empty string")
        if not isinstance(raw_edit["new"], str):
            raise EditSpecViolation(f"edit {index} new must be a string")
        line = raw_edit.get("line")
        if line is not None and (not isinstance(line, int) or line <= 0):
            raise EditSpecViolation(f"edit {index} line must be a positive integer")
        validated.append(raw_edit)
    return validated

def _validate_target_path(file_value: str, root: Path) -> Path:
    normalized = unicodedata.normalize("NFC", file_value)
    if normalized == "":
        raise EditSpecViolation("edit file path is empty")
    if normalized.startswith("/") or os.path.isabs(normalized):
        raise EditSpecViolation("absolute edit file paths are not allowed")

    norm = posixpath.normpath(normalized.replace("\\", "/"))
    if norm in ("", "."):
        raise EditSpecViolation("edit file path is empty")
    if norm == ".." or norm.startswith("../"):
        raise EditSpecViolation("edit file path escapes the worktree")
    parts = tuple(part for part in norm.split("/") if part and part != ".")
    if any(part == ".." for part in parts):
        raise EditSpecViolation("edit file path contains parent traversal")
    if ".git" in parts:
        raise EditSpecViolation("edit file path targets .git internals")

    current = root
    root_real = root.resolve()
    for part in parts:
        current = current / part
        if current.is_symlink():
            real = current.resolve()
            if not _is_relative_to(real, root_real):
                raise EditSpecViolation(f"edit file path symlink escapes worktree: {file_value}")

    if not _is_relative_to(current.resolve(), root_real):
        raise EditSpecViolation("edit file path escapes the worktree")
    if not current.exists():
        raise EditSpecViolation(f"edit target does not exist: {file_value}")
    if current.is_dir():
        raise EditSpecViolation(f"edit target is a directory: {file_value}")
    if not current.is_file():
        raise EditSpecViolation(f"edit target is not a regular file: {file_value}")
    return current

def _locate_edit(file_path: Path, old: str, line: object) -> _LocatedEdit:
    text = file_path.read_text(encoding="utf-8", errors="surrogateescape")
    if isinstance(line, int):
        start = _find_old_from_line(text, old, line)
    else:
        start = _find_unique_old(text, old)
    return _LocatedEdit(file_path=file_path, start=start, end=start + len(old))

def _find_old_from_line(text: str, old: str, line: int) -> int:
    line_starts = _line_starts(text)
    if line > len(line_starts):
        raise EditSpecViolation(f"edit line {line} is outside the target file")
    line_start = line_starts[line - 1]
    next_line_start = line_starts[line] if line < len(line_starts) else len(text)
    found = text.find(old, line_start)
    if found < 0:
        raise EditSpecViolation("edit old text was not found at or after the requested line")
    if "\n" not in old and found >= next_line_start:
        raise EditSpecViolation("edit old text was not found on the requested line")
    return found

def _find_unique_old(text: str, old: str) -> int:
    first = text.find(old)
    if first < 0:
        raise EditSpecViolation("edit old text was not found")
    second = text.find(old, first + 1)
    if second >= 0:
        raise EditSpecViolation("edit old text is not unique without a line anchor")
    return first

def _line_starts(text: str) -> list[int]:
    starts = [0]
    for index, char in enumerate(text):
        if char == "\n" and index + 1 < len(text):
            starts.append(index + 1)
    return starts

def _check_no_overlaps(file_path: Path, edits: list[_LocatedEdit]) -> None:
    sorted_edits = sorted(edits, key=lambda edit: edit.start)
    previous: _LocatedEdit | None = None
    for edit in sorted_edits:
        if previous is not None and edit.start < previous.end:
            raise EditSpecViolation(f"overlapping edits for {file_path}")
        previous = edit

def _is_relative_to(path: Path, root: Path) -> bool:
    try:
        path.relative_to(root)
    except ValueError:
        return False
    return True

def check_disk_and_maybe_cleanup(
    workspace_root: str,
    min_free_bytes: int = DEFAULT_MIN_FREE_BYTES,
) -> list[str]:
    """Clean oldest disposable worktrees when free space is below the threshold."""

    root = Path(workspace_root).resolve()
    warnings: list[str] = []
    if not root.exists():
        return warnings
    free = shutil.disk_usage(root).free
    if free >= min_free_bytes:
        return warnings

    skipped_protected: list[str] = []
    for handle in _oldest_worktrees(root):
        if is_protected(handle.path):
            skipped_protected.append(handle.path)
            continue
        try:
            cleanup_worktree(handle)
        except (OSError, WorkspaceViolation, subprocess.CalledProcessError) as exc:
            warnings.append(f"failed to clean {handle.path}: {exc}")
            continue
        warnings.append(f"cleaned disposable worktree {handle.path}")
        if shutil.disk_usage(root).free >= min_free_bytes:
            break
    if shutil.disk_usage(root).free < min_free_bytes:
        if skipped_protected:
            warnings.append(
                "disk_low_protected_worktrees_skipped: " + ", ".join(skipped_protected)
            )
        warnings.append(
            f"free space below threshold after cleanup: {shutil.disk_usage(root).free} bytes"
        )
    return warnings

def _primary_error(evidence: Mapping[str, Any]) -> Mapping[str, Any]:
    primary = evidence.get("primary_error")
    if isinstance(primary, Mapping):
        return primary
    return evidence

def _match_denylist(
    primary: Mapping[str, Any],
    build_log: str,
) -> FailureClassification | None:
    haystack = "\n".join(
        (
            _string(primary.get("message")),
            _string(primary.get("details")),
            build_log,
        )
    )
    for rule in DENYLIST_RULES:
        if rule.pattern.search(haystack):
            return FailureClassification(
                repair_allowed=REPAIR_DENIED,
                failure_class=rule.failure_class,
                confidence=1.0,
                matched_rule=f"denylist:{rule.rule_id}",
                reason=rule.reason,
            )
    return None

def _heuristic_classification(primary: Mapping[str, Any]) -> FailureClassification:
    kind = _kind(primary)
    if kind in SOURCE_KINDS:
        return _source_diagnostic_classification(primary)

    if kind.startswith("link") and _message_has_source_symbol(primary):
        return FailureClassification(
            repair_allowed=REPAIR_DENIED,
            failure_class="uncertain",
            confidence=0.7,
            matched_rule="heuristic:link_symbol",
            reason=(
                "linker error may be source-related, but confidence is below "
                "automatic repair gate"
            ),
        )

    return FailureClassification(
        repair_allowed=REPAIR_DENIED,
        failure_class="uncertain",
        confidence=0.2,
        matched_rule="heuristic:unsupported_kind",
        reason=f"unsupported or non-source analyzer kind: {kind or '<missing>'}",
    )

def _source_diagnostic_classification(primary: Mapping[str, Any]) -> FailureClassification:
    if not _has_source_location(primary):
        return FailureClassification(
            repair_allowed=REPAIR_DENIED,
            failure_class="source_unreachable",
            confidence=0.4,
            matched_rule="heuristic:missing_source_location",
            reason="source diagnostic has no reliable file/line location",
        )

    if not _source_reachable(primary):
        return FailureClassification(
            repair_allowed=REPAIR_DENIED,
            failure_class="source_unreachable",
            confidence=0.55,
            matched_rule="heuristic:source_unreachable",
            reason="source file could not be mapped to the local source root",
        )

    if not _source_owned(primary):
        return FailureClassification(
            repair_allowed=REPAIR_DENIED,
            failure_class="source_unreachable",
            confidence=0.55,
            matched_rule="heuristic:source_not_owned",
            reason="diagnostic path is not project-owned source",
        )

    if not _probably_fixable(primary):
        return FailureClassification(
            repair_allowed=REPAIR_NEEDS_CONFIRMATION,
            failure_class="source_repairable_unverified_type",
            confidence=0.65,
            matched_rule="heuristic:type_unknown",
            reason=(
                "source-located and source-owned, but the diagnostic type is not on the "
                "auto-fix whitelist; repair is possible with human confirmation of the fix"
            ),
        )

    return FailureClassification(
        repair_allowed=REPAIR_AUTO,
        failure_class="source_repairable",
        confidence=0.95,
        matched_rule="heuristic:source_werror_or_compile_error",
        reason="source-located, source-owned, probably-fixable compiler/werror diagnostic",
    )

def _has_source_location(primary: Mapping[str, Any]) -> bool:
    file_value = primary.get("file") or primary.get("normalized_file")
    line_value = primary.get("line")
    return (
        isinstance(file_value, str)
        and bool(file_value)
        and isinstance(line_value, int)
        and line_value > 0
    )

def _source_reachable(primary: Mapping[str, Any]) -> bool:
    value = primary.get("source_reachable")
    if isinstance(value, bool):
        return value
    status = primary.get("source_resolution_status")
    if isinstance(status, str):
        return status == "mapped_to_source_root"
    return _looks_project_source_path(_source_file(primary))

def _source_owned(primary: Mapping[str, Any]) -> bool:
    value = primary.get("source_owned")
    if isinstance(value, bool):
        return value
    status = primary.get("source_ownership_status")
    if isinstance(status, str):
        return status == "project_owned"
    return _looks_project_source_path(_source_file(primary))

def _probably_fixable(primary: Mapping[str, Any]) -> bool:
    for key in ("type_fixability", "provisional_fixability", "fixability"):
        value = primary.get(key)
        if isinstance(value, str):
            return value == "probably_fixable"
    message = _string(primary.get("message")).lower()
    return any(
        marker in message
        for marker in (
            "use of undeclared",
            "no member named",
            "invalid conversion",
            "deprecated",
            "[-werror",
        )
    )

def _looks_project_source_path(path: str | None) -> bool:
    if not path:
        return False
    lowered = path.replace("\\", "/").lower()
    if lowered.startswith(SYSTEM_PREFIXES):
        return False
    parts = {part for part in lowered.split("/") if part}
    return not bool(parts & SUSPECT_PATH_PARTS)

def _source_file(primary: Mapping[str, Any]) -> str | None:
    file_value = primary.get("normalized_file") or primary.get("file")
    if isinstance(file_value, str) and file_value:
        return file_value
    return None

def _message_has_source_symbol(primary: Mapping[str, Any]) -> bool:
    message = _string(primary.get("message"))
    return bool(re.search(r"`?[A-Za-z_][A-Za-z0-9_]*`?", message))

def discover_sibling_pythonpath(*, launcher_path: Path | None = None) -> tuple[Path, ...]:
    """Return sibling analyzer/patch-suggest scripts paths for direct-folder usage."""

    if launcher_path is None:
        return ()
    triage_root = launcher_path.resolve().parents[1]
    root = triage_root.parent
    candidates = (
        root / "tizen-gbs-log-analysis" / "scripts",
        root / "tizen-gbs-patch-suggest" / "scripts",
    )
    return tuple(path for path in candidates if path.is_dir())

def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code

def load_cookie_jar(cookie_path: Path = DEFAULT_COOKIE_PATH) -> dict[str, str]:
    """Load browser-exported QuickBuild cookies from a JSON file."""

    try:
        raw = json.loads(cookie_path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise QuickBuildError(
            "COOKIE_MISSING",
            f"QuickBuild cookie file is missing: {cookie_path}",
        ) from exc
    except json.JSONDecodeError as exc:
        raise QuickBuildError(
            "COOKIE_UNREADABLE",
            f"QuickBuild cookie file is not valid JSON: {cookie_path}",
        ) from exc

    if not isinstance(raw, list):
        raise QuickBuildError("COOKIE_UNREADABLE", "QuickBuild cookie JSON must be a list")

    cookies: dict[str, str] = {}
    for item in raw:
        if not isinstance(item, dict):
            continue
        name = item.get("name")
        value = item.get("value")
        domain = item.get("domain")
        if (
            isinstance(name, str)
            and isinstance(value, str)
            and (domain is None or "quickbuild.tizen.org" in str(domain))
        ):
            cookies[name] = value

    if not cookies:
        raise QuickBuildError(
            "COOKIE_EXPIRED",
            "QuickBuild cookie file has no quickbuild.tizen.org cookies; "
            "please log in and export cookies again.",
        )
    return cookies

def find_download_href(html_text: str) -> str | None:
    """Return the Wicket full-log download href from a build-log HTML page."""

    for match in re.finditer(r"""href\s*=\s*["']([^"']+)["']""", html_text, re.IGNORECASE):
        href = html.unescape(match.group(1))
        if DOWNLOAD_LINK_MARKER in href:
            return href
    return None

def download_package_buildlog(
    dest_file: str,
    *,
    fetcher: HttpFetcher | None = None,
) -> PackageBuildLog | None:
    """Download one failed package buildlog when QuickBuild exposes its dest_file."""

    url = derive_package_buildlog_url(dest_file)
    if url is None:
        return None
    response = (fetcher or _urllib_fetch)(url, {})
    if response.status != 200:
        raise QuickBuildError(
            "PACKAGE_BUILDLOG_DOWNLOAD_FAILED",
            f"failed to download package buildlog {url}: HTTP {response.status}",
        )
    return PackageBuildLog(url=url, text=response.text)

def _raise_if_login_page(response: HttpResponse, *, action: str) -> None:
    final_url = response.url.lower()
    text = response.text.lower()
    if (
        response.status in {401, 403}
        or "/signin" in final_url
        or "redirect-url-after-sign-in" in text
    ):
        raise QuickBuildError(
            "COOKIE_EXPIRED",
            f"QuickBuild cookie expired while trying to {action}; "
            f"please log in and export cookies to {DEFAULT_COOKIE_PATH}.",
        )

def _urllib_fetch(url: str, cookies: Mapping[str, str]) -> HttpResponse:
    url = normalize_quickbuild_url(url)
    cookie_header = "; ".join(f"{name}={value}" for name, value in cookies.items())
    request = Request(url, headers={"Cookie": cookie_header, "User-Agent": "ci-triage/0.1"})
    try:
        with urlopen(request, timeout=60) as response:
            return HttpResponse(
                status=response.status,
                url=response.geturl(),
                body=response.read(),
                content_type=response.headers.get("content-type"),
            )
    except HTTPError as exc:
        return HttpResponse(
            status=exc.code,
            url=exc.geturl(),
            body=exc.read(),
            content_type=exc.headers.get("content-type"),
        )
    except URLError as exc:
        raise QuickBuildError("QUICKBUILD_DOWNLOAD_FAILED", str(exc)) from exc

def normalize_quickbuild_url(url: str) -> str:
    """Idempotently quote QuickBuild URL paths that may contain raw spaces."""

    parts = urlsplit(url)
    path = quote(unquote(parts.path), safe="/@")
    return urlunsplit((parts.scheme, parts.netloc, path, parts.query, parts.fragment))

def get_verification_record(self, verification_id: str) -> dict[str, str] | None:
        """Fetch one verification record by ID."""

        conn = self.connect()
        try:
            row = conn.execute(
                f"SELECT {', '.join(_VERIFICATION_COLUMNS)} "
                "FROM verification_records WHERE verification_id = ?",
                (verification_id,),
            ).fetchone()
        finally:
            conn.close()
        if row is None:
            return None
        return {column: _row_string(row, column) for column in _VERIFICATION_COLUMNS}

def get_latest_status_row(self, unit_key: str) -> dict[str, str | None] | None:
        """Return the latest status row for one unit key."""

        conn = self.connect()
        try:
            row = conn.execute(
                "SELECT status, verification_id, timestamp FROM unit_status_log WHERE unit_key = ? "
                "ORDER BY timestamp DESC, log_id DESC LIMIT 1",
                (unit_key,),
            ).fetchone()
        finally:
            conn.close()
        if row is None:
            return None
        return {
            "status": _row_string(row, "status"),
            "verification_id": _row_optional_string(row, "verification_id"),
            "timestamp": _row_string(row, "timestamp"),
        }

def get_submission(self, submission_key: str) -> dict[str, str | None] | None:
        """Fetch one submitted Gerrit record by submission key."""

        conn = self.connect()
        try:
            row = conn.execute(
                "SELECT submission_key, verification_id, submitted_at, action, gerrit_change_id "
                "FROM submissions WHERE submission_key = ?",
                (submission_key,),
            ).fetchone()
        finally:
            conn.close()
        if row is None:
            return None
        return {
            "submission_key": _row_string(row, "submission_key"),
            "verification_id": _row_string(row, "verification_id"),
            "submitted_at": _row_string(row, "submitted_at"),
            "action": _row_string(row, "action"),
            "gerrit_change_id": _row_optional_string(row, "gerrit_change_id"),
        }

def get_status_log(self, unit_key: str) -> tuple[dict[str, str | None], ...]:
        """Read status rows for tests and audit views."""

        conn = self.connect()
        try:
            rows = conn.execute(
                "SELECT unit_key, status, timestamp, verification_id, reason "
                "FROM unit_status_log WHERE unit_key = ? ORDER BY timestamp ASC, log_id ASC",
                (unit_key,),
            ).fetchall()
        finally:
            conn.close()
        return tuple(
            {
                "unit_key": _row_string(row, "unit_key"),
                "status": _row_string(row, "status"),
                "timestamp": _row_string(row, "timestamp"),
                "verification_id": _row_optional_string(row, "verification_id"),
                "reason": _row_optional_string(row, "reason"),
            }
            for row in rows
        )

def _row_string(row: sqlite3.Row, key: str) -> str:
    value: Any = row[key]
    if not isinstance(value, str):
        raise TypeError(f"expected text value for {key}")
    return value

def _row_optional_string(row: sqlite3.Row, key: str) -> str | None:
    value: Any = row[key]
    if value is None:
        return None
    if not isinstance(value, str):
        raise TypeError(f"expected optional text value for {key}")
    return value

def build_submission_key(*, failure_key: str, verified_tree_sha: str) -> str:
    """Build the stable private key for one verified tree submitted for a failure."""

    raw_key = f"{failure_key}:{verified_tree_sha}"
    return hashlib.sha256(raw_key.encode("utf-8")).hexdigest()

def failure_key_sha12(failure_key: str) -> str:
    """Return a deterministic 12-character hash for compact Gerrit topics."""

    return hashlib.sha256(failure_key.encode("utf-8")).hexdigest()[:12]

def write_pass_record(db: StateDatabase, record: VerificationRecord) -> str:
    """Write a PASS record and mark the failure GERRIT_READY.

    This is the only public API that may produce a GERRIT_READY state. It ties the
    ready state to a concrete verification record in the same transaction.
    """

    if record.result != "PASS":
        raise ValueError("verification records currently support only PASS results")
    return db.insert_pass_record(_record_to_values(record))

def get_record(db: StateDatabase, verification_id: str) -> VerificationRecord | None:
    """Fetch one PASS verification record."""

    values = db.get_verification_record(verification_id)
    if values is None:
        return None
    return VerificationRecord(**values)

def get_latest_status(db: StateDatabase, unit_key: str) -> str | None:
    """Return the latest append-only status for one unit."""

    return db.get_latest_status(unit_key)

def get_latest_status_row(db: StateDatabase, unit_key: str) -> LatestStatusRow | None:
    """Return the latest append-only status row for one unit."""

    row = db.get_latest_status_row(unit_key)
    if row is None:
        return None
    status = row["status"]
    timestamp = row["timestamp"]
    if not isinstance(status, str) or not isinstance(timestamp, str):
        raise TypeError("latest status row is missing status or timestamp")
    return LatestStatusRow(
        status=status,
        verification_id=row["verification_id"],
        timestamp=timestamp,
    )

def _record_to_values(record: VerificationRecord) -> dict[str, str]:
    values = asdict(record)
    return {key: value for key, value in values.items() if isinstance(value, str)}

def is_protected(worktree_path: str | Path) -> bool:
    """Return whether a disposable worktree is protected from automatic cleanup."""

    return (Path(worktree_path) / PROTECTED_FILENAME).is_file()

def _verify_cleanup_handle(handle: DisposableWorktree) -> None:
    marker_path = Path(handle.marker_path)
    if not marker_path.is_file():
        raise WorkspaceViolation(f"missing disposable worktree marker: {marker_path}")

    marker = _read_marker(marker_path)
    handle_root = Path(handle.workspace_root).resolve()
    handle_path = Path(handle.path).resolve()
    marker_root = Path(str(marker.get("workspace_root", ""))).resolve()

    if marker_root != handle_root:
        raise WorkspaceViolation("marker workspace_root does not match handle workspace_root")
    if not _is_relative_to(handle_path, handle_root):
        raise WorkspaceViolation("worktree path is outside workspace_root")

def _oldest_worktrees(root: Path) -> list[DisposableWorktree]:
    handles: list[DisposableWorktree] = []
    for child in root.iterdir():
        if not child.is_dir() or not child.name.startswith("iter_"):
            continue
        marker_path = child / MARKER_FILENAME
        if not marker_path.is_file():
            continue
        try:
            marker = _read_marker(marker_path)
            baseline_repo = str(marker["baseline_repo"])
            base_commit = str(marker["base_commit"])
            iter_index = int(marker["iter_index"])
        except (KeyError, TypeError, ValueError, json.JSONDecodeError, OSError):
            continue
        handles.append(
            DisposableWorktree(
                path=str(child.resolve()),
                baseline_repo=baseline_repo,
                base_commit=base_commit,
                workspace_root=str(root),
                iter_index=iter_index,
                marker_path=str(marker_path),
            )
        )
    return sorted(handles, key=lambda handle: handle.iter_index)

def _read_marker(marker_path: Path) -> dict[str, Any]:
    raw = json.loads(marker_path.read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise WorkspaceViolation("disposable worktree marker is not a JSON object")
    return raw

def _is_relative_to(path: Path, root: Path) -> bool:
    try:
        path.relative_to(root)
    except ValueError:
        return False
    return True

def _exclude_private_files(worktree_path: Path) -> None:
    result = subprocess.run(
        ["git", "-C", str(worktree_path), "rev-parse", "--git-path", "info/exclude"],
        check=True,
        text=True,
        capture_output=True,
    )
    exclude_path = Path(result.stdout.strip())
    if not exclude_path.is_absolute():
        exclude_path = worktree_path / exclude_path
    exclude_path.parent.mkdir(parents=True, exist_ok=True)
    current = exclude_path.read_text(encoding="utf-8") if exclude_path.exists() else ""
    lines = set(current.splitlines())
    missing = [
        filename for filename in (MARKER_FILENAME, PROTECTED_FILENAME) if filename not in lines
    ]
    if missing:
        with exclude_path.open("a", encoding="utf-8") as handle:
            if current and not current.endswith("\n"):
                handle.write("\n")
            for filename in missing:
                handle.write(f"{filename}\n")

def _parse_since(value: str | None, *, hours: int) -> datetime:
    if value:
        return datetime.fromisoformat(value)
    if hours <= 0:
        raise ValueError("--hours must be positive")
    return datetime.now() - timedelta(hours=hours)

def campaign_repair_step(
    options: CampaignRepairStepOptions,
    *,
    build_verify_fn: BuildVerifyFn = build_verify,
    convergence_fn: ConvergenceFn = check_convergence,
    subprocess_runner: SubprocessRunner = subprocess.run,
) -> CampaignRepairStepOutcome:
    """Run the frozen lock-to-link repair sequence for one unit and architecture."""

    arch_norm = ARCH_RAW_TO_NORM.get(options.arch_raw, "")
    try:
        if not arch_norm:
            raise _StepError(
                REJECTED_IDENTITY_MISMATCH,
                f"arch is not in the verified whitelist: {options.arch_raw!r}",
                EXIT_REJECTED,
            )
        config = _load_config(options.config_path, options.wall_timeout)
        workspace_root = _workspace_root(config, options.campaign_unit_key, arch_norm)
        with _repair_step_lock(workspace_root):
            unit, reproduce = _read_only_identity(options, arch_norm)
            return _run_locked(
                options,
                unit=unit,
                reproduce=reproduce,
                config=config,
                arch_norm=arch_norm,
                workspace_root=workspace_root,
                build_verify_fn=build_verify_fn,
                convergence_fn=convergence_fn,
                subprocess_runner=subprocess_runner,
            )
    except _StepError as exc:
        return _error_outcome(options, arch_norm, exc)
    except BlockingIOError:
        return _error_outcome(
            options,
            arch_norm,
            _StepError(CAMPAIGN_STATE_BUSY, "repair-step lock is already held", EXIT_TOOLING),
        )
    except CampaignStateBusy as exc:
        return _error_outcome(
            options,
            arch_norm,
            _StepError(CAMPAIGN_STATE_BUSY, str(exc), EXIT_TOOLING),
        )
    except CampaignStateError as exc:
        return _error_outcome(
            options,
            arch_norm,
            _StepError(REJECTED_STATE_INCONSISTENT, str(exc), EXIT_REJECTED),
        )
    except OSError as exc:
        return _error_outcome(
            options,
            arch_norm,
            _StepError("BASELINE_TOOLING_FAILED", str(exc), EXIT_TOOLING),
        )
    except Exception as exc:
        return _error_outcome(
            options,
            arch_norm,
            _StepError(
                "BASELINE_TOOLING_FAILED",
                f"unexpected campaign repair-step failure: {type(exc).__name__}: {exc}",
                EXIT_TOOLING,
            ),
        )

def _read_only_identity(
    options: CampaignRepairStepOptions,
    arch_norm: str,
) -> tuple[Unit, dict[str, object]]:
    if options.round_index < 1:
        raise _StepError("INVALID_ARGS", "round-index must be positive", EXIT_INVALID_ARGS)
    unit = get_unit(options.state_db, options.campaign_unit_key)
    if unit is None:
        raise _StepError(
            REJECTED_IDENTITY_MISMATCH,
            f"campaign unit does not exist: {options.campaign_unit_key}",
            EXIT_REJECTED,
        )
    status = latest_status(options.state_db, options.campaign_unit_key)
    if status not in _EXECUTABLE_UNIT_STATUSES:
        raise _StepError(
            REJECTED_STATE_INCONSISTENT,
            f"campaign unit status is not executable: {status!r}",
            EXIT_REJECTED,
        )
    _read_edit_spec(options.edit_spec_path)
    reproduce = latest_reproduce(
        options.state_db,
        options.campaign_unit_key,
        arch_norm=arch_norm,
    )
    if reproduce is None:
        raise _StepError(
            REJECTED_IDENTITY_MISMATCH,
            f"REPRODUCE metadata is missing for arch {arch_norm}",
            EXIT_REJECTED,
        )
    payload = reproduce.get("payload")
    if not isinstance(payload, dict) or payload.get("arch_norm") != arch_norm:
        raise _StepError(
            REJECTED_IDENTITY_MISMATCH,
            "REPRODUCE metadata does not match requested architecture",
            EXIT_REJECTED,
        )
    if payload.get("ci_evidence_sha256_used") != unit.ci_evidence_sha256:
        raise _StepError(
            REJECTED_IDENTITY_MISMATCH,
            "REPRODUCE metadata does not match the unit CI evidence identity",
            EXIT_REJECTED,
        )
    return unit, reproduce

def _validate_source_identity(
    src_clean: Path,
    unit: Unit,
    *,
    subprocess_runner: SubprocessRunner,
) -> None:
    try:
        head = _git_stdout(src_clean, ["rev-parse", "HEAD"], subprocess_runner)
        origin = _git_stdout(src_clean, ["remote", "get-url", "origin"], subprocess_runner)
    except (OSError, subprocess.CalledProcessError) as exc:
        raise _StepError(
            REJECTED_IDENTITY_MISMATCH,
            f"source identity could not be read: {exc}",
            EXIT_REJECTED,
        ) from exc
    if head != unit.base_commit or _normalize_project(origin) != unit.project:
        raise _StepError(
            REJECTED_IDENTITY_MISMATCH,
            "source HEAD or origin does not match campaign unit",
            EXIT_REJECTED,
        )
    marker = src_clean / ".campaign_clone"
    try:
        marker_value: Any = json.loads(marker.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise _StepError(
            REJECTED_IDENTITY_MISMATCH,
            f"campaign clone marker is unreadable: {exc}",
            EXIT_REJECTED,
        ) from exc
    expected = {
        "unit_key": unit.campaign_unit_key,
        "project": unit.project,
        "base_commit": unit.base_commit,
    }
    if marker_value != expected:
        raise _StepError(
            REJECTED_IDENTITY_MISMATCH,
            "campaign clone marker does not match campaign unit",
            EXIT_REJECTED,
        )

def _load_current_evidence(path_value: str | None) -> ResolvedEvidence | MissingEvidence:
    if not path_value:
        return MissingEvidence("build failure did not produce analyzer evidence")
    path = Path(path_value)
    try:
        raw = path.read_bytes()
        value: Any = json.loads(raw)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        return MissingEvidence(f"current evidence is unreadable: {exc}")
    if not isinstance(value, dict):
        return MissingEvidence("current evidence must be a JSON object")
    return ResolvedEvidence(
        evidence=value,
        basis="prev_build",
        evidence_path=str(path),
        evidence_sha256=hashlib.sha256(raw).hexdigest(),
    )

def _append_verdict_status(options: CampaignRepairStepOptions, verdict: str) -> None:
    statuses = {"denied": DENIED, "stalled": STALLED, "regressed": REGRESSED}
    status = statuses.get(verdict)
    if status is not None:
        append_status(options.state_db, options.campaign_unit_key, status, verdict)

def _non_substantive_reason(result: BuildVerifyResult) -> str | None:
    stage = result.failure_stage or ""
    if stage in {"apply_failed", "apply_unexpected_paths", "no_effective_changes"}:
        return "apply_failed"
    if stage in {"analyzer_failed"} or (stage == "gbs_build_failed" and not result.evidence):
        return "analyzer_failed"
    if stage in {
        "build_timeout",
        "build_mutated_source",
        "infrastructure_failed",
        "toolchain_failed",
    }:
        return "toolchain_failed"
    return None

def _serialize_reconciliation(
    value: ReconcileResult,
) -> tuple[dict[str, list[object]], list[dict[str, str]]]:
    relinks: list[object] = [
        {
            "round_index": round_index,
            "verification_id": verification_id,
            "invocation_event_id": invocation_event_id,
        }
        for round_index, verification_id, invocation_event_id in sorted(
            value.other_round_relinks,
            key=lambda item: (item[0], item[1], item[2]),
        )
    ]
    non_campaign = sorted(set(value.non_campaign_verification_ids))
    warnings = [
        {"code": "non_campaign_verification", "verification_id": verification_id}
        for verification_id in non_campaign
    ]
    return (
        {
            "other_round_relinks": relinks,
            "non_campaign_verification_ids": list(non_campaign),
        },
        warnings,
    )

def _safe_invocations_used(options: CampaignRepairStepOptions) -> int:
    try:
        return invocations_used(options.state_db, options.campaign_unit_key)
    except Exception:
        return 0

def _read_edit_spec(path: Path) -> tuple[bytes, str]:
    try:
        real_path = Path(os.path.realpath(path))
        raw = real_path.read_bytes()
        value: Any = json.loads(raw)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise _StepError(
            REJECTED_IDENTITY_MISMATCH,
            f"edit_spec is unreadable or invalid JSON: {exc}",
            EXIT_REJECTED,
        ) from exc
    if not isinstance(value, dict):
        raise _StepError(
            REJECTED_IDENTITY_MISMATCH,
            "edit_spec must be a JSON object",
            EXIT_REJECTED,
        )
    return raw, hashlib.sha256(raw).hexdigest()

def _verify_canonical_edit_spec(path: Path, digest: str) -> None:
    if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != digest:
        raise _StepError(
            REJECTED_IDENTITY_MISMATCH,
            f"canonical edit_spec conflicts with round output: {path}",
            EXIT_REJECTED,
        )

def _revalidate_round(
    options: CampaignRepairStepOptions,
    canonical_edit_spec: Path,
    edit_sha: str,
) -> None:
    round_row = get_round(options.state_db, options.campaign_unit_key, options.round_index)
    if (
        round_row is None
        or round_row.edit_spec_sha256 != edit_sha
        or round_row.edit_spec_ref != os.path.realpath(canonical_edit_spec)
    ):
        raise _StepError(
            REJECTED_IDENTITY_MISMATCH,
            "stored round identity does not match this invocation",
            EXIT_REJECTED,
        )

def _load_config(path: Path, wall_timeout_override: int | None) -> _CampaignConfig:
    try:
        raw: Any = yaml.safe_load(path.read_text(encoding="utf-8"))
    except (OSError, yaml.YAMLError) as exc:
        raise _StepError(
            "INVALID_ARGS",
            f"campaign config is unreadable: {exc}",
            EXIT_INVALID_ARGS,
        ) from exc
    if not isinstance(raw, Mapping):
        raise _StepError("INVALID_ARGS", "campaign config must be a mapping", EXIT_INVALID_ARGS)
    workspace = raw.get("campaign_workspace")
    conf = raw.get("clang_conf_path")
    if not isinstance(workspace, str) or not workspace or not isinstance(conf, str) or not conf:
        raise _StepError(
            "INVALID_ARGS",
            "config requires campaign_workspace and clang_conf_path",
            EXIT_INVALID_ARGS,
        )
    configured_timeout = raw.get("wall_timeout", 3600)
    timeout = wall_timeout_override if wall_timeout_override is not None else configured_timeout
    if not isinstance(timeout, int) or isinstance(timeout, bool) or timeout <= 0:
        raise _StepError("INVALID_ARGS", "wall timeout must be positive", EXIT_INVALID_ARGS)
    return _CampaignConfig(
        campaign_workspace=Path(workspace).expanduser().resolve(),
        clang_conf_path=Path(conf).expanduser().resolve(),
        wall_timeout=timeout,
    )

def _failure_key(unit: Unit, arch_raw: str) -> str:
    return build_failure_key(
        ci_system=unit.ci_system,
        build_id=unit.source_build_id,
        project=unit.project,
        branch=unit.branch,
        arch=arch_raw,
        spec_name=unit.spec_name,
        base_commit=unit.base_commit,
    )

def _git_stdout(
    cwd: Path,
    args: list[str],
    subprocess_runner: SubprocessRunner,
) -> str:
    completed = subprocess_runner(
        ["git", "-C", str(cwd), *args],
        check=True,
        capture_output=True,
        text=True,
    )
    return (completed.stdout or "").strip()

def _normalize_project(remote: str) -> str:
    value = remote.strip()
    if "://" in value:
        path = urlsplit(value).path
    elif ":" in value and "@" in value.split(":", 1)[0]:
        path = value.split(":", 1)[1]
    else:
        path = value
    normalized = path.strip("/")
    if normalized.startswith("git/"):
        normalized = normalized[4:]
    return normalized.removesuffix(".git")

def get_unit(state_db: StateDatabase, campaign_unit_key: str) -> Unit | None:
    conn = _connect(state_db)
    try:
        row = conn.execute(
            "SELECT * FROM campaign_units WHERE campaign_unit_key = ?",
            (campaign_unit_key,),
        ).fetchone()
    finally:
        conn.close()
    return _unit_from_row(row) if row is not None else None

def append_event(
    state_db: StateDatabase,
    campaign_unit_key: str,
    event_type: str,
    payload: Mapping[str, object],
) -> int:
    """Validate and append one gate event.

    Budget events and secondary-target adoption have stronger transactional APIs
    and cannot be written through this general entry point.
    """

    if event_type == "BUILD_INVOCATION":
        raise PayloadSchemaError("BUILD_INVOCATION must be written by consume_build_invocation")
    if event_type == "SECONDARY_TARGET_ADOPTED":
        raise PayloadSchemaError(
            "SECONDARY_TARGET_ADOPTED must be written by the atomic adoption API"
        )
    if event_type == "CONVERGENCE" and payload.get("result") == "PASS":
        raise PayloadSchemaError(
            "PASS CONVERGENCE must be written by link_verification_with_convergence"
        )
    conn = _connect(state_db)
    try:
        with _immediate_transaction(conn):
            return _append_event_on_connection(conn, campaign_unit_key, event_type, payload)
    except sqlite3.IntegrityError as exc:
        raise StateInconsistent(f"event append violated campaign constraints: {exc}") from exc
    finally:
        conn.close()

def append_status(
    state_db: StateDatabase,
    campaign_unit_key: str,
    status: str,
    reason: str | None = None,
    arch_norm: str | None = None,
) -> None:
    if not status:
        raise PayloadSchemaError("status must be non-empty")
    if arch_norm is not None:
        _require_arch_norm(arch_norm)
    if status == HELD_FOR_INVESTIGATION and reason not in _HELD_REASONS:
        raise PayloadSchemaError(f"invalid HELD reason: {reason!r}")
    if (
        status == HELD_FOR_INVESTIGATION
        and reason in _ARCH_SCOPED_HELD_REASONS
        and arch_norm is None
    ):
        raise PayloadSchemaError(f"HELD reason {reason!r} requires arch_norm")
    conn = _connect(state_db)
    try:
        with _immediate_transaction(conn):
            _require_unit(conn, campaign_unit_key)
            _insert_status_row(conn, campaign_unit_key, status, reason, arch_norm)
    finally:
        conn.close()

def _run_git_text(worktree: Path, *args: str) -> str | None:
    try:
        completed = subprocess.run(
            ["git", "-C", str(worktree), *args],
            check=False,
            capture_output=True,
            text=True,
        )
    except OSError:
        return None
    if completed.returncode != 0:
        return None
    return completed.stdout.strip()

def _git_changed_paths(
    worktree: Path,
    base_commit: str,
    verified_commit_sha: str,
) -> list[str] | None:
    try:
        completed = subprocess.run(
            [
                "git",
                "-C",
                str(worktree),
                "diff",
                "--name-only",
                "--no-renames",
                "-z",
                base_commit,
                verified_commit_sha,
                "--",
            ],
            check=False,
            capture_output=True,
        )
    except OSError:
        return None
    if completed.returncode != 0:
        return None
    paths: list[str] = []
    for raw_path in completed.stdout.split(b"\0"):
        if not raw_path:
            continue
        try:
            path = raw_path.decode("utf-8")
        except UnicodeDecodeError:
            return None
        normalized = PurePosixPath(path)
        if normalized.is_absolute() or any(part in {".", ".."} for part in normalized.parts):
            return None
        paths.append(normalized.as_posix())
    return sorted(paths)

def append_qb_event(
    state_db: StateDatabase,
    *,
    request_seq: int,
    event_type: str,
    qb_build_id: str | None = None,
    status: str | None = None,
    accepted: bool | None = None,
    sbs_target_echo: str | None = None,
    per_arch_status_json: str | None = None,
    qb_result_sha256: str | None = None,
    qb_result_ref: str | None = None,
    degraded: bool = False,
) -> int:
    if event_type == "SUBMITTED":
        raise PayloadSchemaError("SUBMITTED can only be written by create_qb_request")
    if event_type not in {"BUILD_BOUND", "RESULT"}:
        raise PayloadSchemaError(f"unsupported QB event_type: {event_type!r}")
    conn = _connect(state_db)
    try:
        with _immediate_transaction(conn):
            request = conn.execute(
                "SELECT request_seq FROM campaign_qb_requests WHERE request_seq = ?",
                (request_seq,),
            ).fetchone()
            if request is None:
                raise StateInconsistent("QB event references a missing request")
            if event_type == "BUILD_BOUND":
                if not qb_build_id:
                    raise PayloadSchemaError("BUILD_BOUND requires qb_build_id")
                if any(
                    value is not None
                    for value in (
                        status,
                        accepted,
                        sbs_target_echo,
                        per_arch_status_json,
                        qb_result_sha256,
                        qb_result_ref,
                    )
                ):
                    raise PayloadSchemaError("BUILD_BOUND may not contain result fields")
                existing_ids = {
                    _text(row, "qb_build_id")
                    for row in conn.execute(
                        "SELECT qb_build_id FROM campaign_qb_events "
                        "WHERE request_seq = ? AND event_type = 'BUILD_BOUND'",
                        (request_seq,),
                    ).fetchall()
                }
                if existing_ids and existing_ids != {qb_build_id}:
                    raise StateInconsistent("QB request is already bound to another build")
            else:
                if not status or not sbs_target_echo or not qb_result_sha256:
                    raise PayloadSchemaError(
                        "RESULT requires status, sbs_target_echo, and qb_result_sha256"
                    )
                bound = conn.execute(
                    "SELECT 1 FROM campaign_qb_events WHERE request_seq = ? "
                    "AND event_type = 'BUILD_BOUND' AND (? IS NULL OR qb_build_id = ?) LIMIT 1",
                    (request_seq, qb_build_id, qb_build_id),
                ).fetchone()
                if bound is None:
                    raise StateInconsistent("RESULT requires an existing valid build binding")
            cursor = conn.execute(
                "INSERT INTO campaign_qb_events "
                "(request_seq, event_type, qb_build_id, status, accepted, "
                "sbs_target_echo, per_arch_status_json, qb_result_sha256, qb_result_ref, "
                "degraded, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (
                    request_seq,
                    event_type,
                    qb_build_id,
                    status,
                    int(accepted) if accepted is not None else None,
                    sbs_target_echo,
                    per_arch_status_json,
                    qb_result_sha256,
                    qb_result_ref,
                    int(degraded),
                    _now_iso8601(),
                ),
            )
            return _lastrowid(cursor)
    finally:
        conn.close()

def find_unit_by_request_id(state_db: StateDatabase, request_id: str) -> str | None:
    conn = _connect(state_db)
    try:
        row = conn.execute(
            "SELECT campaign_unit_key FROM campaign_qb_requests WHERE request_id = ?",
            (request_id,),
        ).fetchone()
    finally:
        conn.close()
    return _text(row, "campaign_unit_key") if row is not None else None

def latest_qb_result(
    state_db: StateDatabase,
    campaign_unit_key: str,
) -> dict[str, object] | None:
    conn = _connect(state_db)
    try:
        row = conn.execute(
            "SELECT ev.* FROM campaign_qb_requests AS req "
            "JOIN campaign_qb_events AS ev ON ev.request_seq = req.request_seq "
            "WHERE req.campaign_unit_key = ? "
            "AND req.request_seq = (SELECT MAX(request_seq) FROM campaign_qb_requests "
            "WHERE campaign_unit_key = ?) AND ev.event_type = 'RESULT' "
            "ORDER BY ev.event_id DESC LIMIT 1",
            (campaign_unit_key, campaign_unit_key),
        ).fetchone()
    finally:
        conn.close()
    if row is None:
        return None
    return {key: row[key] for key in row.keys()}

def _immediate_transaction(conn: sqlite3.Connection) -> Iterator[None]:
    try:
        conn.execute("BEGIN IMMEDIATE")
    except sqlite3.OperationalError as exc:
        if _is_busy_error(exc):
            raise CampaignStateBusy("CAMPAIGN_STATE_BUSY") from exc
        raise
    try:
        yield
    except Exception:
        conn.rollback()
        raise
    else:
        conn.commit()

def _savepoint(conn: sqlite3.Connection, name: str) -> Iterator[None]:
    conn.execute(f"SAVEPOINT {name}")
    try:
        yield
    except Exception:
        conn.execute(f"ROLLBACK TO SAVEPOINT {name}")
        conn.execute(f"RELEASE SAVEPOINT {name}")
        raise
    else:
        conn.execute(f"RELEASE SAVEPOINT {name}")

def _is_busy_error(exc: sqlite3.OperationalError) -> bool:
    message = str(exc).lower()
    return "locked" in message or "busy" in message

def _canonical_failed_arches(arches: Sequence[str]) -> tuple[str, ...]:
    if isinstance(arches, (str, bytes)):
        raise ValueError("failed_arches must be a sequence of arch names")
    values = set(arches)
    if any(not isinstance(value, str) or not value for value in values):
        raise ValueError("failed_arches entries must be non-empty strings")
    rank = {arch: index for index, arch in enumerate(_FAILED_ARCH_ORDER)}
    return tuple(sorted(values, key=lambda value: (rank.get(value, len(rank)), value)))

def _require_unit(conn: sqlite3.Connection, campaign_unit_key: str) -> Unit:
    row = conn.execute(
        "SELECT * FROM campaign_units WHERE campaign_unit_key = ?", (campaign_unit_key,)
    ).fetchone()
    if row is None:
        raise StateInconsistent(f"campaign unit not found: {campaign_unit_key}")
    return _unit_from_row(row)

def _round_from_row(row: sqlite3.Row) -> Round:
    return Round(
        campaign_unit_key=_text(row, "campaign_unit_key"),
        round_index=int(row["round_index"]),
        edit_spec_ref=_text(row, "edit_spec_ref"),
        edit_spec_sha256=_text(row, "edit_spec_sha256"),
        created_at=_text(row, "created_at"),
    )

def _round_on_connection(
    conn: sqlite3.Connection,
    campaign_unit_key: str,
    round_index: int,
) -> Round | None:
    row = conn.execute(
        "SELECT * FROM campaign_rounds WHERE campaign_unit_key = ? AND round_index = ?",
        (campaign_unit_key, round_index),
    ).fetchone()
    return _round_from_row(row) if row is not None else None

def _append_event_on_connection(
    conn: sqlite3.Connection,
    campaign_unit_key: str,
    event_type: str,
    payload: Mapping[str, object],
) -> int:
    _require_unit(conn, campaign_unit_key)
    _validate_event_payload(conn, campaign_unit_key, event_type, payload)
    if event_type == "ORPHAN_PASS":
        verification_id = str(payload["verification_id"])
        rows = conn.execute(
            "SELECT payload_json FROM campaign_gate_events "
            "WHERE campaign_unit_key = ? AND event_type = 'ORPHAN_PASS'",
            (campaign_unit_key,),
        ).fetchall()
        for row in rows:
            existing = json.loads(_text(row, "payload_json"))
            if isinstance(existing, dict) and existing.get("verification_id") == verification_id:
                event = conn.execute(
                    "SELECT event_id FROM campaign_gate_events "
                    "WHERE campaign_unit_key = ? AND event_type = 'ORPHAN_PASS' "
                    "AND payload_json = ? ORDER BY event_id DESC LIMIT 1",
                    (campaign_unit_key, _canonical_json(existing)),
                ).fetchone()
                if event is not None:
                    return int(event["event_id"])
    _validate_immutable_derive_fields(conn, campaign_unit_key, event_type, payload)
    return _insert_event_row(conn, campaign_unit_key, event_type, payload)

def _require_known_event_type(event_type: str) -> None:
    if event_type not in _KNOWN_EVENT_TYPES:
        raise UnknownEventType(f"unregistered campaign event type: {event_type!r}")

def _validate_policy(payload: Mapping[str, object]) -> None:
    _require_keys(
        payload,
        {
            "round_index",
            "verdict",
            "hits",
            "fix_strategy_initial",
            "fix_strategy_final",
            "edit_source_kind",
        },
    )
    _require_round_index(payload)
    if not isinstance(payload["hits"], list):
        raise PayloadSchemaError("POLICY hits must be a list")
    if payload["edit_source_kind"] not in {"t1_cherry_pick", "generated", "suppress"}:
        raise PayloadSchemaError("invalid POLICY edit_source_kind")

def _validate_push(payload: Mapping[str, object]) -> None:
    _require_keys(payload, {"ref", "ref_class", "pushed_sha", "result", "url", "at"})
    _require_nonempty_strings(payload, ("ref", "pushed_sha", "at"))
    if payload["ref_class"] not in {"sandbox", "review"}:
        raise PayloadSchemaError("invalid PUSH ref_class")
    if payload["result"] not in {"ok", "failed"}:
        raise PayloadSchemaError("invalid PUSH result")
    if payload["url"] is not None and not isinstance(payload["url"], str):
        raise PayloadSchemaError("PUSH url must be string or null")

def _validate_kb(payload: Mapping[str, object]) -> None:
    _require_keys(payload, {"kb_id", "dedupe_hit", "status", "at"})
    _require_nonempty_strings(payload, ("kb_id", "at"))
    if not isinstance(payload["dedupe_hit"], bool) or payload["status"] != "NEW":
        raise PayloadSchemaError("invalid KB payload")

def _validate_review(payload: Mapping[str, object]) -> None:
    _require_keys(payload, {"outcome", "review_url", "degraded", "qb_event_id", "at"})
    if payload["outcome"] not in {"pushed", "manual", "ineligible"}:
        raise PayloadSchemaError("invalid REVIEW outcome")
    if not isinstance(payload["degraded"], bool):
        raise PayloadSchemaError("REVIEW degraded must be bool")
    if payload["outcome"] == "manual" and payload["degraded"] is not True:
        raise PayloadSchemaError("manual REVIEW must be degraded")
    if payload["review_url"] is not None and not isinstance(payload["review_url"], str):
        raise PayloadSchemaError("REVIEW review_url must be string or null")
    if payload["qb_event_id"] is not None and not isinstance(payload["qb_event_id"], int):
        raise PayloadSchemaError("REVIEW qb_event_id must be int or null")
    _require_nonempty_strings(payload, ("at",))

def _validate_convergence_shape(payload: Mapping[str, object]) -> None:
    _require_keys(
        payload,
        {
            "round_index",
            "arch_norm",
            "invocation_event_id",
            "result",
            "verdict",
            "reason",
            "evidence_path",
            "evidence_sha256",
            "verification_id",
            "actual_changed_paths",
            "previous_basis",
            "at",
        },
    )
    _require_round_index(payload)
    _require_arch_norm(_payload_str(payload, "arch_norm"))
    reason = _payload_str(payload, "reason")
    result = _payload_str(payload, "result")
    verdict = _payload_str(payload, "verdict")
    invocation_id = payload["invocation_event_id"]
    if reason == "rebaselined" and invocation_id is not None:
        raise PayloadSchemaError("rebaselined convergence must omit invocation_event_id")
    if verdict not in {"advance", "stalled", "regressed", "denied", "n_a"}:
        raise PayloadSchemaError("invalid CONVERGENCE verdict")
    if payload["previous_basis"] not in {"reproduce", "prev_build", "synthetic_zero", "none"}:
        raise PayloadSchemaError("invalid CONVERGENCE previous_basis")
    if not isinstance(payload["actual_changed_paths"], list) or not all(
        isinstance(item, str) for item in payload["actual_changed_paths"]
    ):
        raise PayloadSchemaError("actual_changed_paths must be a string list")
    if invocation_id is None:
        if reason != "rebaselined" or result != "n_a" or verdict != "n_a":
            raise PayloadSchemaError(
                "only rebaselined n_a convergence may omit invocation_event_id"
            )
    elif not isinstance(invocation_id, int) or isinstance(invocation_id, bool):
        raise PayloadSchemaError("invocation_event_id must be int or null")
    if reason in _CONVERGENCE_NA_REASONS:
        if result != "n_a" or verdict != "n_a":
            raise PayloadSchemaError("non-build convergence reasons require result/verdict n_a")
    elif result not in {"PASS", "FAIL"}:
        raise PayloadSchemaError("build outcome convergence requires PASS or FAIL")
    if result == "PASS":
        if verdict != "n_a" or not isinstance(payload["verification_id"], str):
            raise PayloadSchemaError("PASS convergence requires n_a and verification_id")
        if payload["evidence_path"] is not None or payload["evidence_sha256"] is not None:
            raise PayloadSchemaError("PASS convergence evidence fields must be null")
    elif result == "FAIL":
        if verdict == "n_a":
            raise PayloadSchemaError("FAIL build outcome requires a substantive verdict")
        if not isinstance(payload["evidence_path"], str) or not isinstance(
            payload["evidence_sha256"], str
        ):
            raise PayloadSchemaError("FAIL convergence requires evidence path and hash")
        if payload["verification_id"] is not None:
            raise PayloadSchemaError("FAIL convergence verification_id must be null")
    else:
        if payload["evidence_path"] is not None or payload["evidence_sha256"] is not None:
            raise PayloadSchemaError("n_a convergence evidence fields must be null")
        if payload["verification_id"] is not None:
            raise PayloadSchemaError("n_a convergence verification_id must be null")
    _require_nonempty_strings(payload, ("reason", "at"))

def _validate_adoption(payload: Mapping[str, object]) -> None:
    _require_keys(
        payload,
        {
            "arch_norm",
            "adopted_fingerprint",
            "baseline_error_count",
            "current_error_count",
            "baseline_truncated",
            "current_truncated",
            "expected_reproduce_event_id",
            "at",
        },
    )
    _require_arch_norm(_payload_str(payload, "arch_norm"))
    if not isinstance(payload["adopted_fingerprint"], dict):
        raise PayloadSchemaError("adopted_fingerprint must be an object")
    for key in ("baseline_error_count", "current_error_count", "expected_reproduce_event_id"):
        if not isinstance(payload[key], int) or isinstance(payload[key], bool):
            raise PayloadSchemaError(f"{key} must be int")
    if payload["baseline_truncated"] is not False or payload["current_truncated"] is not False:
        raise PayloadSchemaError("adoption requires untruncated evidence")

def _validate_workspace_event(payload: Mapping[str, object]) -> None:
    _require_keys(payload, {"paths", "reason"})
    if not isinstance(payload["paths"], list) or not all(
        isinstance(item, str) for item in payload["paths"]
    ):
        raise PayloadSchemaError("workspace paths must be a string list")
    _require_nonempty_strings(payload, ("reason",))
    if "confirmed_by" in payload and not isinstance(payload["confirmed_by"], str):
        raise PayloadSchemaError("confirmed_by must be a string")

def _validate_invocation_binding(
    conn: sqlite3.Connection,
    campaign_unit_key: str,
    payload: Mapping[str, object],
) -> None:
    invocation_id = payload.get("invocation_event_id")
    if invocation_id is None:
        return
    row = conn.execute(
        "SELECT campaign_unit_key, event_type, round_index, arch_norm "
        "FROM campaign_gate_events WHERE event_id = ?",
        (invocation_id,),
    ).fetchone()
    if row is None:
        raise StateInconsistent("invocation_event_id does not exist")
    if _text(row, "event_type") != "BUILD_INVOCATION":
        raise StateInconsistent("invocation_event_id is not BUILD_INVOCATION")
    if _text(row, "campaign_unit_key") != campaign_unit_key:
        raise StateInconsistent("invocation_event_id belongs to another unit")
    if row["round_index"] != payload.get("round_index") or row["arch_norm"] != payload.get(
        "arch_norm"
    ):
        raise StateInconsistent("invocation_event_id round or arch mismatch")

def _validate_immutable_derive_fields(
    conn: sqlite3.Connection,
    campaign_unit_key: str,
    event_type: str,
    payload: Mapping[str, object],
) -> None:
    if event_type != "DERIVE":
        return
    rows = conn.execute(
        "SELECT payload_json FROM campaign_gate_events "
        "WHERE campaign_unit_key = ? AND event_type = 'DERIVE' ORDER BY event_id",
        (campaign_unit_key,),
    ).fetchall()
    immutable = ("message_brief", "author_identity", "author_date", "committer_date")
    for row in rows:
        existing = json.loads(_text(row, "payload_json"))
        if not isinstance(existing, dict):
            raise StateInconsistent("stored DERIVE payload is not an object")
        if any(existing.get(key) != payload.get(key) for key in immutable):
            raise StateInconsistent("DERIVE first-write identity fields changed")

def _require_keys(payload: Mapping[str, object], required: set[str]) -> None:
    missing = sorted(required - set(payload))
    if missing:
        raise PayloadSchemaError(f"payload missing required fields: {missing}")

def _require_nonempty_strings(
    payload: Mapping[str, object],
    keys: Sequence[str],
) -> None:
    for key in keys:
        if not isinstance(payload.get(key), str) or not payload[key]:
            raise PayloadSchemaError(f"payload field {key} must be a non-empty string")

def _require_round_index(payload: Mapping[str, object]) -> None:
    value = payload.get("round_index")
    if not isinstance(value, int) or isinstance(value, bool) or value < 1:
        raise PayloadSchemaError("round_index must be a positive integer")

def _require_arch_norm(arch_norm: str) -> None:
    if arch_norm not in ARCH_NORMS:
        raise PayloadSchemaError(f"unsupported arch_norm: {arch_norm!r}")

def _require_equal(payload: Mapping[str, object], key: str, expected: object) -> None:
    if payload.get(key) != expected:
        raise StateInconsistent(f"convergence {key} does not match link input")

def _payload_str(payload: Mapping[str, object], key: str) -> str:
    value = payload.get(key)
    if not isinstance(value, str):
        raise PayloadSchemaError(f"payload field {key} must be a string")
    return value

def _canonical_json(payload: Mapping[str, object]) -> str:
    try:
        return json.dumps(payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
    except (TypeError, ValueError) as exc:
        raise PayloadSchemaError(f"payload is not JSON serializable: {exc}") from exc

def _text(row: sqlite3.Row, key: str) -> str:
    value: Any = row[key]
    if not isinstance(value, str):
        raise StateInconsistent(f"expected text value for {key}")
    return value

def _optional_text(row: sqlite3.Row, key: str) -> str | None:
    value: Any = row[key]
    if value is None:
        return None
    if not isinstance(value, str):
        raise StateInconsistent(f"expected optional text value for {key}")
    return value

def _payload_from_row(row: sqlite3.Row) -> dict[str, object]:
    payload: Any = json.loads(_text(row, "payload_json"))
    if not isinstance(payload, dict):
        raise StateInconsistent("stored event payload is not an object")
    return payload

def _load_bound_evidence(path_value: object, digest_value: object) -> dict[str, Any] | None:
    if not isinstance(path_value, str) or not isinstance(digest_value, str):
        return None
    path = Path(path_value)
    try:
        raw = path.read_bytes()
    except OSError:
        return None
    if hashlib.sha256(raw).hexdigest() != digest_value:
        return None
    try:
        value: Any = json.loads(raw)
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None
    return value if isinstance(value, dict) else None

def _evidence_truncated(evidence: Mapping[str, object]) -> bool:
    if evidence.get("truncated") is True:
        return True
    clusters = evidence.get("error_clusters")
    if not isinstance(clusters, dict):
        return False
    if clusters.get("truncated") is True:
        return True
    raw_clusters = clusters.get("clusters")
    if not isinstance(raw_clusters, list):
        return False
    return any(
        isinstance(cluster, dict) and cluster.get("locations_truncated") is True
        for cluster in raw_clusters
    )

def _lastrowid(cursor: sqlite3.Cursor) -> int:
    if cursor.lastrowid is None:
        raise StateInconsistent("SQLite insert did not return a row id")
    return cursor.lastrowid

def main(
    argv: list[str] | None = None,
    *,
    stdout: TextIO = sys.stdout,
    stderr: TextIO = sys.stderr,
    extra_pythonpath: tuple[Path, ...] = (),
) -> int:
    if argv is None:
        argv = sys.argv[1:]
    if argv and argv[0] == "build-verify":
        return _main_build_verify(argv[1:], stderr=stderr, extra_pythonpath=extra_pythonpath)
    if argv and argv[0] == "check-convergence":
        return _main_check_convergence(argv[1:], stderr=stderr)
    if argv and argv[0] == "gerrit-submit":
        return _main_gerrit_submit(argv[1:], stderr=stderr)
    if argv and argv[0] == "release-worktree":
        return _main_release_worktree(argv[1:], stderr=stderr)
    if argv and argv[0] == "campaign-repair-step":
        return _main_campaign_repair_step(
            argv[1:],
            stdout=stdout,
            extra_pythonpath=extra_pythonpath,
        )

    parser = build_parser()
    args = parser.parse_args(argv)
    paths = extra_pythonpath or discover_sibling_pythonpath(
        launcher_path=Path(__file__).resolve().parents[1] / "run_ci_triage.py"
    )
    result = run_triage(
        TriageOptions(
            build_id=args.build_id,
            output_root=args.output_root,
            cookie_path=args.cookie,
            spec_name=args.spec_name,
            arch=args.arch,
            extra_pythonpath=paths,
            git_ssh_command=args.git_ssh_command,
        )
    )
    print(f"ci_triage: status {result.status}", file=stderr)
    print(f"ci_triage: report written to {result.report_path}", file=stderr)
    if result.error:
        print(f"ci_triage: {result.error}", file=stderr)
    return EXIT_SUCCESS if result.exit_code == 0 else EXIT_FAILED

def _main_check_convergence(argv: list[str], *, stderr: TextIO) -> int:
    parser = check_convergence_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        if exc.code == 0:
            raise
        return EXIT_FAILED

    paths = [args.current_evidence]
    if args.previous_evidence is not None:
        paths.append(args.previous_evidence)
    if args.touched_files is not None:
        paths.append(args.touched_files)
    missing = [str(path) for path in paths if not path.is_file()]
    if missing:
        print("ci_triage check-convergence: missing file(s): " + ", ".join(missing), file=stderr)
        return EXIT_FILE_MISSING

    try:
        current = _read_json(args.current_evidence)
        previous = (
            _read_json(args.previous_evidence) if args.previous_evidence is not None else None
        )
        touched = (
            touched_files_from_json(args.touched_files) if args.touched_files is not None else None
        )
    except (JSONDecodeError, ValueError) as exc:
        print(f"ci_triage check-convergence: invalid JSON: {exc}", file=stderr)
        return EXIT_JSON_INVALID

    result = check_convergence(current, previous, touched_files=touched)
    write_convergence_result(result, args.output)
    print(json.dumps(result.to_dict(), sort_keys=True), file=stderr)
    print(f"ci_triage check-convergence: result written to {args.output}", file=stderr)
    return EXIT_SUCCESS

def _main_release_worktree(argv: list[str], *, stderr: TextIO) -> int:
    parser = release_worktree_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        if exc.code == 0:
            raise
        return EXIT_FAILED
    result = release_verified_worktree(StateDatabase(args.state_db), args.verification_id)
    if args.output is not None:
        write_release_result(result, args.output)
        print(f"ci_triage release-worktree: result written to {args.output}", file=stderr)
    print(json.dumps(result.to_dict(), sort_keys=True), file=stderr)
    return exit_code_for_release(result)

def _read_json(path: Path) -> dict[str, object]:
    raw = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise ValueError(f"{path} must contain a JSON object")
    return raw

def from_file(cls, path: Path, *, build: FailedBuild, now: str) -> BuildState:
        if not path.is_file():
            return cls(
                build_id=build.build_id,
                discovered_at=now,
                begin_date=build.begin_date.isoformat(sep=" ", timespec="seconds"),
            )
        try:
            raw = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return cls(
                build_id=build.build_id,
                discovered_at=now,
                begin_date=build.begin_date.isoformat(sep=" ", timespec="seconds"),
            )
        if not isinstance(raw, dict):
            return cls(
                build_id=build.build_id,
                discovered_at=now,
                begin_date=build.begin_date.isoformat(sep=" ", timespec="seconds"),
            )
        raw_packages = raw.get("packages")
        packages: dict[str, PackageState] = {}
        if isinstance(raw_packages, dict):
            for spec_name, value in raw_packages.items():
                if isinstance(spec_name, str):
                    packages[spec_name] = PackageState.from_dict(value)
        transitions = raw.get("transitions")
        return cls(
            build_id=_string(raw.get("build_id"), build.build_id),
            discovered_at=_string(raw.get("discovered_at"), now),
            begin_date=_string(
                raw.get("begin_date"),
                build.begin_date.isoformat(sep=" ", timespec="seconds"),
            ),
            state=_string(raw.get("state"), STATE_DISCOVERED),
            error=_optional_string(raw.get("error")),
            transitions=transitions if isinstance(transitions, list) else [],
            packages=packages,
        )

def to_dict(self) -> dict[str, Any]:
        return {
            "build_id": self.build_id,
            "discovered_at": self.discovered_at,
            "begin_date": self.begin_date,
            "state": self.state,
            "error": self.error,
            "transitions": self.transitions,
            "packages": {
                spec_name: package.to_dict()
                for spec_name, package in sorted(self.packages.items())
            },
        }

def _process_build(
        self,
        build: FailedBuild,
        build_state: BuildState,
        paths: _BatchPaths,
        processed: dict[str, dict[str, set[str]]],
        rows: list[BatchRunRecord],
        now: datetime,
    ) -> None:
        full_log = self.full_log_downloader(build.build_id, self.options.cookie_path)
        _transition_build(build_state, STATE_LOG_FETCHED, ok=True, error=None, now=now)

        pkg_to_commit_error: str | None
        try:
            pkg_to_commit = parse_build_pkg_list(full_log)
        except QuickBuildLogError as exc:
            pkg_to_commit_error = f"{exc.code}: {exc}"
            pkg_to_commit = {}
        else:
            pkg_to_commit_error = None

        discovered_any = False
        no_gbs_report_any = False
        for arch in self.options.arches:
            if _is_processed(processed, build.build_id, arch, NO_GBS_REPORT_SPEC_NAME):
                no_gbs_report_any = True
                package = _package_for(build_state, arch, NO_GBS_REPORT_SPEC_NAME)
                _transition_package(
                    package,
                    STATE_SKIPPED_PROCESSED,
                    ok=True,
                    error=None,
                    now=now,
                )
                rows.append(
                    _row_from_package(build.build_id, arch, NO_GBS_REPORT_SPEC_NAME, package)
                )
                continue
            try:
                failed_packages = self.gbs_report_discoverer(
                    build.build_id,
                    arch,
                    self.options.cookie_path,
                )
            except QuickBuildError as exc:
                if exc.code == "NO_GBS_REPORT":
                    no_gbs_report_any = True
                    package = _package_for(build_state, arch, NO_GBS_REPORT_SPEC_NAME)
                    _transition_package(
                        package,
                        STATE_REPORTED_NO_REPORT,
                        ok=True,
                        error=str(exc),
                        now=now,
                    )
                    _mark_processed(processed, build.build_id, arch, NO_GBS_REPORT_SPEC_NAME)
                    rows.append(
                        _row_from_package(build.build_id, arch, NO_GBS_REPORT_SPEC_NAME, package)
                    )
                    continue
                package = _package_for(build_state, arch, UNKNOWN_SPEC_NAME)
                package.retries += 1
                _transition_package(
                    package,
                    STATE_FAILED_LOG,
                    ok=False,
                    error=f"{exc.code}: {exc}",
                    now=now,
                )
                rows.append(_row_from_package(build.build_id, arch, UNKNOWN_SPEC_NAME, package))
                continue

            if failed_packages:
                discovered_any = True
            for failed_package in failed_packages:
                self._process_package(
                    build,
                    failed_package,
                    pkg_to_commit,
                    pkg_to_commit_error,
                    build_state,
                    paths,
                    processed,
                    rows,
                    now,
                )

        if not discovered_any and not no_gbs_report_any:
            package = _package_for(build_state, "unknown-arch", UNKNOWN_SPEC_NAME)
            _transition_package(
                package,
                STATE_NEEDS_INPUT,
                ok=False,
                error=(
                    "GBS Reports contained no failed package rows "
                    f"(scanned arches: {', '.join(self.options.arches)})"
                ),
                now=now,
            )
            rows.append(
                _row_from_package(build.build_id, "unknown-arch", UNKNOWN_SPEC_NAME, package)
            )

def _discover_failed_gbs_packages(
        build_id: str,
        arch: str,
        cookie_path: Path,
    ) -> tuple[GbsReportPackage, ...]:
        return fetch_gbs_report(build_id, arch, cookie_path=cookie_path).failed_packages

def _group_no_gbs_report_rows(rows: list[BatchRunRecord]) -> dict[str, list[BatchRunRecord]]:
    groups: dict[str, list[BatchRunRecord]] = {}
    for row in rows:
        if row.state == STATE_REPORTED_NO_REPORT:
            groups.setdefault(row.build_id, []).append(row)
    return groups

def _arch_summary(rows: list[BatchRunRecord], arch_order: tuple[str, ...]) -> str:
    ordered_arches = _ordered_arches(rows, arch_order)
    if len(ordered_arches) == 1:
        return ordered_arches[0]
    return f"{len(ordered_arches)} arches ({', '.join(ordered_arches)})"

def _ordered_arches(rows: list[BatchRunRecord], arch_order: tuple[str, ...]) -> list[str]:
    row_arches: list[str] = []
    for row in rows:
        if row.arch not in row_arches:
            row_arches.append(row.arch)

    ordered: list[str] = []
    row_arch_set = set(row_arches)
    for arch in arch_order:
        if arch in row_arch_set:
            ordered.append(arch)
    for arch in row_arches:
        if arch not in ordered:
            ordered.append(arch)
    return ordered

def _count_label(count: int, singular: str) -> str:
    suffix = "" if count == 1 else "s"
    return f"{count} {singular}{suffix}"

def _render_batch_manifest(paths: _BatchPaths, rows: list[BatchRunRecord], now: datetime) -> str:
    manifest = {
        "schema_version": BATCH_MANIFEST_SCHEMA,
        "generated_at": _timestamp(now),
        "run_date": paths.run_date,
        "packages": [_manifest_package(paths, row) for row in rows],
    }
    return json.dumps(manifest, indent=2, sort_keys=True) + "\n"

def _manifest_error(row: BatchRunRecord) -> dict[str, str] | None:
    if row.error:
        code, _, message = row.error.partition(":")
        if message and _looks_like_error_code(code):
            return {"code": code.strip() or row.state, "message": message.strip()}
        return {"code": row.state, "message": row.error}
    if row.state in {STATE_REPORTED, STATE_SKIPPED_PROCESSED}:
        return None
    if row.state.startswith("FAILED_") or row.state in {
        STATE_NEEDS_INPUT,
        STATE_REPORTED_NO_REPORT,
        STATE_FAILED_PERMANENT,
    }:
        return {"code": row.state, "message": row.state}
    # In-progress states such as LOG_FETCHED/ANALYZED are visible in the
    # manifest during partial runs, but they are not errors by themselves.
    return None

def _load_processed(path: Path) -> dict[str, dict[str, set[str]]]:
    if not path.is_file():
        return {}
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    if not isinstance(raw, dict):
        return {}
    processed: dict[str, dict[str, set[str]]] = {}
    for build_id, arches in raw.items():
        if not isinstance(build_id, str):
            continue
        if isinstance(arches, dict):
            processed[build_id] = {}
            for arch, spec_names in arches.items():
                if isinstance(arch, str) and isinstance(spec_names, list):
                    processed[build_id][arch] = {
                        item for item in spec_names if isinstance(item, str)
                    }
        elif isinstance(arches, list):
            processed[build_id] = {
                "unknown-arch": {item for item in arches if isinstance(item, str)}
            }
    return processed

def _save_processed(path: Path, processed: dict[str, dict[str, set[str]]]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    serializable = {
        build_id: {
            arch: sorted(spec_names) for arch, spec_names in sorted(arches.items())
        }
        for build_id, arches in sorted(processed.items())
    }
    path.write_text(json.dumps(serializable, indent=2, sort_keys=True) + "\n", encoding="utf-8")

def _is_processed(
    processed: dict[str, dict[str, set[str]]],
    build_id: str,
    arch: str,
    spec_name: str,
) -> bool:
    return spec_name in processed.get(build_id, {}).get(arch, set())

def _save_build_state(path: Path, state: BuildState) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(state.to_dict(), indent=2, sort_keys=True) + "\n", encoding="utf-8")

def _package_for(build_state: BuildState, arch: str, spec_name: str) -> PackageState:
    key = _unit_key(arch, spec_name)
    package = build_state.packages.get(key)
    if package is None:
        package = PackageState(arch=arch, spec_name=spec_name)
        build_state.packages[key] = package
    return package

def _transition_package(
    package: PackageState,
    to_state: str,
    *,
    ok: bool,
    error: str | None,
    now: datetime,
) -> None:
    previous = package.state
    package.state = to_state
    package.error = error
    package.transitions.append(_transition(previous, to_state, ok=ok, error=error, now=now))

def _read_patch_status(meta_path: Path) -> str | None:
    try:
        raw = json.loads(meta_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(raw, dict):
        return None
    status = raw.get("status")
    return status if isinstance(status, str) else None

def _read_report_metadata(package: PackageState, report_path: Path) -> None:
    try:
        text = report_path.read_text(encoding="utf-8")
    except OSError:
        return
    status_match = re.search(r"^- Change status: `([^`]+)`", text, flags=re.MULTILINE)
    if status_match is not None:
        package.gerrit_status = status_match.group(1)
    patchset_match = re.search(r"^- Patch set ref: `([^`]+)`", text, flags=re.MULTILINE)
    if patchset_match is not None:
        package.patchset_ref = patchset_match.group(1)
    branch_match = re.search(r"^- Branch: `([^`]+)`", text, flags=re.MULTILINE)
    if branch_match is not None:
        package.branch = branch_match.group(1)

def _cell(value: str | None) -> str:
    if value is None or value == "":
        return "n/a"
    return value.replace("|", "\\|")

def _report_link(report_path: str | None) -> str:
    if not report_path:
        return "n/a"
    return f"[report]({report_path})"

def resolve(
    state_db: StateDatabase,
    campaign_unit_key: str,
    *,
    arch_norm: str,
) -> PreviousEvidence:
    """Resolve previous evidence using the frozen campaign history semantics.

    Both the pre-build check and the post-build TOCTOU check call this function.
    A substantive event whose bound file is missing or has a mismatched digest is
    never downgraded to an empty previous result.
    """

    reproduce = latest_reproduce(state_db, campaign_unit_key, arch_norm=arch_norm)
    if reproduce is None:
        return MissingEvidence("latest REPRODUCE event is missing")

    events = _convergence_payloads(state_db, campaign_unit_key, arch_norm)
    if events is None:
        return MissingEvidence("stored CONVERGENCE payload is invalid")
    if not events:
        return _from_reproduce(reproduce)

    for payload in events:
        if payload.get("result") == "PASS":
            return ResolvedEvidence(
                evidence=_synthetic_zero_evidence(),
                basis="synthetic_zero",
                evidence_path=None,
                evidence_sha256=None,
            )
        if payload.get("verdict") != "n_a":
            return _from_payload(payload, basis="prev_build")

        reason = payload.get("reason")
        if reason == "rebaselined":
            event_id = payload.get("__event_id")
            if not isinstance(event_id, int):
                return MissingEvidence("rebaselined convergence event id is invalid")
            anchored = _reproduce_before(
                state_db,
                campaign_unit_key,
                arch_norm=arch_norm,
                event_id=event_id,
            )
            return (
                _from_reproduce(anchored)
                if anchored is not None
                else MissingEvidence("rebaselined convergence has no preceding REPRODUCE anchor")
            )
        if reason not in _SKIP_NA_REASONS:
            return MissingEvidence(f"latest n_a convergence has unsupported reason {reason!r}")

    return _from_reproduce(reproduce)

def _convergence_payloads(
    state_db: StateDatabase,
    campaign_unit_key: str,
    arch_norm: str,
) -> list[dict[str, object]] | None:
    conn = state_db.connect()
    try:
        rows = conn.execute(
            "SELECT event_id, payload_json FROM campaign_gate_events "
            "WHERE campaign_unit_key = ? AND event_type = 'CONVERGENCE' "
            "AND arch_norm = ? ORDER BY event_id DESC",
            (campaign_unit_key, arch_norm),
        ).fetchall()
    finally:
        conn.close()
    result: list[dict[str, object]] = []
    for row in rows:
        try:
            value: Any = json.loads(str(row["payload_json"]))
        except json.JSONDecodeError:
            return None
        if not isinstance(value, dict):
            return None
        value["__event_id"] = int(row["event_id"])
        result.append(value)
    return result

def _reproduce_before(
    state_db: StateDatabase,
    campaign_unit_key: str,
    *,
    arch_norm: str,
    event_id: int,
) -> dict[str, object] | None:
    conn = state_db.connect()
    try:
        row = conn.execute(
            "SELECT * FROM campaign_gate_events "
            "WHERE campaign_unit_key = ? AND event_type = 'REPRODUCE' "
            "AND arch_norm = ? AND event_id < ? ORDER BY event_id DESC LIMIT 1",
            (campaign_unit_key, arch_norm, event_id),
        ).fetchone()
    finally:
        conn.close()
    if row is None:
        return None
    try:
        payload: Any = json.loads(str(row["payload_json"]))
    except json.JSONDecodeError:
        return None
    if not isinstance(payload, dict):
        return None
    return {"event_id": int(row["event_id"]), "payload": payload}

def _from_reproduce(event: dict[str, object]) -> PreviousEvidence:
    payload = event.get("payload")
    if not isinstance(payload, dict):
        return MissingEvidence("latest REPRODUCE payload is invalid")
    return _from_payload(payload, basis="reproduce", path_key="evidence_local")

def _from_payload(
    payload: dict[str, object],
    *,
    basis: str,
    path_key: str = "evidence_path",
) -> PreviousEvidence:
    path_value = payload.get(path_key)
    digest_value = payload.get("evidence_sha256")
    if not isinstance(path_value, str) or not isinstance(digest_value, str):
        return MissingEvidence(f"{basis} evidence binding is incomplete")
    path = Path(path_value)
    try:
        raw = path.read_bytes()
    except OSError as exc:
        return MissingEvidence(f"{basis} evidence is unreadable: {exc}")
    if hashlib.sha256(raw).hexdigest() != digest_value:
        return MissingEvidence(f"{basis} evidence sha256 mismatch")
    try:
        value: Any = json.loads(raw)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        return MissingEvidence(f"{basis} evidence is invalid JSON: {exc}")
    if not isinstance(value, dict):
        return MissingEvidence(f"{basis} evidence must be a JSON object")
    return ResolvedEvidence(
        evidence=value,
        basis=basis,
        evidence_path=str(path),
        evidence_sha256=digest_value,
    )

def _synthetic_zero_evidence() -> dict[str, Any]:
    # Return a fresh object so convergence callers cannot mutate shared state.
    return deepcopy(_SYNTHETIC_ZERO_EVIDENCE)

def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code

def parse_build_pkg_list(full_log: str) -> dict[str, str]:
    """Parse the Python-dict build_pkg_list_dic line into project -> commit."""

    for line in full_log.splitlines():
        if "build_pkg_list_dic:" not in line:
            continue
        raw = line.split("build_pkg_list_dic:", 1)[1].strip()
        try:
            parsed = ast.literal_eval(raw)
        except (SyntaxError, ValueError) as exc:
            raise QuickBuildLogError(
                "BUILD_PKG_LIST_UNREADABLE",
                "build_pkg_list_dic is not parseable as a Python literal dict",
            ) from exc
        if not isinstance(parsed, dict):
            raise QuickBuildLogError(
                "BUILD_PKG_LIST_UNREADABLE",
                "build_pkg_list_dic is not a dict",
            )
        result: dict[str, str] = {}
        for key, value in parsed.items():
            if isinstance(key, str) and isinstance(value, str):
                result[key] = value
        if not result:
            raise QuickBuildLogError("BUILD_PKG_LIST_UNREADABLE", "build_pkg_list_dic is empty")
        return result
    raise QuickBuildLogError("BUILD_PKG_LIST_MISSING", "full log has no build_pkg_list_dic line")

def parse_failed_packages(full_log: str) -> tuple[FailedPackage, ...]:
    """Return failed package entries using spec_name as the stable package key."""

    packages: list[FailedPackage] = []
    pattern = re.compile(
        r"fail_pkg:\s*(?P<fail_pkg>[^,]+),\s*"
        r"spec_name:\s*(?P<spec_name>[^,\s]+)"
        r"(?:,\s*dest_file:\s*(?P<dest_file>\S+))?"
    )
    seen: set[tuple[str, str]] = set()
    for match in pattern.finditer(full_log):
        fail_pkg = match.group("fail_pkg").strip()
        spec_name = match.group("spec_name").strip()
        key = (fail_pkg, spec_name)
        if key in seen:
            continue
        seen.add(key)
        packages.append(
            FailedPackage(
                fail_pkg=fail_pkg,
                spec_name=spec_name,
                dest_file=match.group("dest_file"),
            )
        )
    if not packages:
        raise QuickBuildLogError(
            "FAILED_PACKAGE_NOT_FOUND",
            "full log has no fail_pkg/spec_name entries",
        )
    return tuple(packages)

def select_failed_package(
    failed_packages: tuple[FailedPackage, ...],
    *,
    spec_name: str | None,
) -> FailedPackage:
    """Select one failed package for the vertical-slice MVP."""

    if spec_name is not None:
        matches = [package for package in failed_packages if package.spec_name == spec_name]
        if len(matches) == 1:
            return matches[0]
        if not matches:
            choices = ", ".join(package.spec_name for package in failed_packages)
            raise QuickBuildLogError(
                "FAILED_PACKAGE_NOT_FOUND",
                f"requested spec_name {spec_name!r} was not in failed packages: {choices}",
            )
        raise QuickBuildLogError(
            "FAILED_PACKAGE_AMBIGUOUS",
            f"requested spec_name {spec_name!r} matched multiple failed package rows",
        )

    if len(failed_packages) == 1:
        return failed_packages[0]

    choices = ", ".join(package.spec_name for package in failed_packages)
    raise QuickBuildLogError(
        "NEEDS_PACKAGE_SELECTION",
        f"build has multiple failed packages; rerun with --spec-name. Candidates: {choices}",
    )

def match_pkg_key(spec_name: str, pkg_to_commit: dict[str, str]) -> tuple[str, str]:
    """Map a spec_name like 'multi-assistant' to one project key and commit."""

    matches = _exact_project_matches(spec_name, pkg_to_commit)
    if len(matches) == 1:
        key = matches[0]
        return key, pkg_to_commit[key]

    if not matches:
        matches = _tizen_prefix_project_matches(spec_name, pkg_to_commit)

    if len(matches) == 1:
        key = matches[0]
        return key, pkg_to_commit[key]
    if not matches:
        raise QuickBuildLogError(
            "PROJECT_COMMIT_NOT_FOUND",
            f"no build_pkg_list_dic key matched spec_name {spec_name!r}",
        )
    raise QuickBuildLogError(
        "PROJECT_COMMIT_AMBIGUOUS",
        f"multiple build_pkg_list_dic keys matched {spec_name!r}: {', '.join(matches)}",
    )

def _tizen_prefix_project_matches(spec_name: str, pkg_to_commit: dict[str, str]) -> list[str]:
    rules = (
        ("hal-api-", "/hal/api/"),
        ("capi-ui-", "/api/"),
        ("capi-", "/api/"),
    )
    for prefix, required_segment in rules:
        if not spec_name.startswith(prefix):
            continue
        project_name = spec_name.removeprefix(prefix)
        return [
            key
            for key in pkg_to_commit
            if required_segment in f"/{key}/" and _project_basename(key) == project_name
        ]
    return []

def run_triage(
    options: TriageOptions,
    *,
    subprocess_runner: SubprocessRunner = subprocess.run,
) -> TriageResult:
    """Run one build_id through full-log download, source checkout, analyzer, patch-suggest."""

    output_dir = options.output_dir or options.output_root / options.build_id
    output_dir.mkdir(parents=True, exist_ok=True)
    report_path = output_dir / "report.md"
    report = TriageReportData(
        build_id=options.build_id,
        quickbuild_log_url=f"https://quickbuild.tizen.org/build/{options.build_id}/log",
    )

    try:
        package_buildlog_text = options.package_buildlog_text
        package_buildlog_url = options.package_buildlog_url
        download = download_full_log(options.build_id, cookie_path=options.cookie_path)
        full_log_path = output_dir / "full_log.txt"
        full_log_path.write_text(download.full_log, encoding="utf-8")
        report.full_log_path = full_log_path

        if options.selected_package is not None:
            selected = options.selected_package
        elif options.arch is not None:
            selected, gbs_package = _select_gbs_report_package(
                options.build_id,
                options.arch,
                options.spec_name,
                cookie_path=options.cookie_path,
            )
            if options.package_buildlog_text is None:
                package_buildlog_text = download_gbs_package_buildlog(
                    gbs_package,
                    cookie_path=options.cookie_path,
                )
                package_buildlog_url = gbs_package.buildlog_url
        else:
            if options.spec_name is None:
                raise QuickBuildError(
                    "ARCH_REQUIRED",
                    "QuickBuild single-build triage now requires --arch for automatic "
                    "GBS report failed-package discovery, or --spec-name for the "
                    "legacy full-log fallback.",
                )
            try:
                failed_packages = parse_failed_packages(download.full_log)
            except QuickBuildLogError as exc:
                if exc.code != "FAILED_PACKAGE_NOT_FOUND" or options.spec_name is None:
                    raise
                report.warnings.append(
                    "full log has no fail_pkg/spec_name entries; using explicit "
                    f"--spec-name {options.spec_name!r} and full-log analyzer fallback"
                )
                failed_packages = (
                    FailedPackage(fail_pkg=options.spec_name, spec_name=options.spec_name),
                )
            selected = select_failed_package(failed_packages, spec_name=options.spec_name)
        report.selected_package = selected

        analyzer_input = full_log_path
        if package_buildlog_text is not None:
            analyzer_input = output_dir / f"{selected.spec_name}.buildlog.txt"
            analyzer_input.write_text(package_buildlog_text, encoding="utf-8")
            report.package_buildlog_url = package_buildlog_url
        elif selected.dest_file:
            try:
                package_log = download_package_buildlog(selected.dest_file)
            except QuickBuildError as exc:
                report.warnings.append(
                    f"{exc.code}: {exc}; falling back to full QuickBuild log for analyzer"
                )
            else:
                if package_log is not None:
                    analyzer_input = output_dir / f"{selected.spec_name}.buildlog.txt"
                    analyzer_input.write_text(package_log.text, encoding="utf-8")
                    report.package_buildlog_url = package_log.url
                else:
                    report.warnings.append(
                        "Could not derive package buildlog URL from dest_file; "
                        "falling back to full QuickBuild log for analyzer"
                    )
        report.analyzed_buildlog_path = analyzer_input

        if options.project_key is not None and options.commit_hash is not None:
            project_key = options.project_key
            commit_hash = options.commit_hash
        else:
            pkg_to_commit = parse_build_pkg_list(download.full_log)
            project_key, commit_hash = match_pkg_key(selected.spec_name, pkg_to_commit)
        report.project_key = project_key
        report.commit_hash = commit_hash

        source_fetch = fetch_source_for_commit(
            project_key,
            commit_hash,
            output_dir / "src" / _safe_pkg_dir(selected.spec_name),
            subprocess_runner=subprocess_runner,
            git_ssh_command=options.git_ssh_command or os.environ.get("CI_TRIAGE_GIT_SSH_COMMAND"),
        )
        report.source_fetch = source_fetch
        if source_fetch.status != "source_available":
            return _finish(
                report,
                report_path,
                output_dir,
                status=source_fetch.status,
                error=source_fetch.error or "source checkout failed",
            )

        analyzer_dir = output_dir / "analyzer_output"
        analyzer_result = _run_analyzer(
            analyzer_input,
            src_root=source_fetch.src_root,
            output_dir=analyzer_dir,
            package=selected.spec_name,
            python_executable=options.python_executable,
            subprocess_runner=subprocess_runner,
            extra_pythonpath=options.extra_pythonpath,
        )
        if analyzer_result is not None:
            return _finish(
                report,
                report_path,
                output_dir,
                status="ANALYZER_FAILED",
                error=analyzer_result,
            )

        analyzer_evidence_path = analyzer_dir / "evidence_packet.json"
        evidence_path = output_dir / "evidence_packet.json"
        shutil.copyfile(analyzer_evidence_path, evidence_path)
        report.analyzer_output_dir = analyzer_dir
        report.evidence_packet_path = evidence_path
        packet = _read_packet(evidence_path)
        report.primary_error = _primary_error(packet)

        patch_context_dir = output_dir / "patch_context"
        patch_error = _run_patch_suggest(
            evidence_path,
            src_root=source_fetch.src_root,
            output_dir=patch_context_dir,
            python_executable=options.python_executable,
            subprocess_runner=subprocess_runner,
            extra_pythonpath=options.extra_pythonpath,
        )
        report.patch_context_dir = patch_context_dir
        meta_path = patch_context_dir / "meta.json"
        if meta_path.is_file():
            report.patch_context_meta_path = meta_path
            report.patch_context_status = _read_patch_status(meta_path)
        if patch_error is not None:
            return _finish(
                report,
                report_path,
                output_dir,
                status="PATCH_SUGGEST_FAILED",
                error=patch_error,
            )

        return _finish(report, report_path, output_dir, status="success", error=None, exit_code=0)
    except QuickBuildError as exc:
        return _finish(report, report_path, output_dir, status=exc.code, error=str(exc))
    except QuickBuildLogError as exc:
        return _finish(report, report_path, output_dir, status=exc.code, error=str(exc))
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        return _finish(report, report_path, output_dir, status="TRIAGE_FAILED", error=str(exc))

def _failed_package_from_gbs(package: GbsReportPackage) -> FailedPackage:
    return FailedPackage(
        fail_pkg=package.package_path,
        spec_name=package.spec_name,
    )

def _run_checked(
    command: list[str],
    subprocess_runner: SubprocessRunner,
    extra_pythonpath: Sequence[Path],
) -> str | None:
    env = _build_subprocess_env(extra_pythonpath)
    kwargs: dict[str, object] = {"check": True, "text": True}
    if env is not None:
        kwargs["env"] = env
    try:
        subprocess_runner(command, **kwargs)
    except subprocess.CalledProcessError as exc:
        return f"{command[0]} {' '.join(command[1:3])} exited with {exc.returncode}"
    return None

def _build_subprocess_env(extra_pythonpath: Sequence[Path]) -> dict[str, str] | None:
    if not extra_pythonpath:
        return None
    env = os.environ.copy()
    entries = [str(path) for path in extra_pythonpath]
    existing = env.get("PYTHONPATH")
    if existing:
        entries.append(existing)
    env["PYTHONPATH"] = os.pathsep.join(entries)
    return env

def _read_packet(evidence_path: Path) -> dict[str, Any]:
    raw = json.loads(evidence_path.read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise ValueError(f"evidence packet is not an object: {evidence_path}")
    return raw

def _primary_error(packet: dict[str, Any]) -> dict[str, Any] | None:
    value = packet.get("primary_error")
    return value if isinstance(value, dict) else None

def _read_patch_status(meta_path: Path) -> str | None:
    try:
        raw = json.loads(meta_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if isinstance(raw, dict):
        status = raw.get("status")
        return status if isinstance(status, str) else None
    return None

def _load_main() -> Callable[[list[str] | None], int]:
