def source_path(src_root: Path | None, event: dict[str, Any]) -> Path | None:
    file_value = event.get("file")
    if not isinstance(file_value, str) or not file_value:
        return None
    path = Path(file_value)
    if path.is_absolute():
        return path
    if src_root is None:
        return None
    return src_root / path

def quoted_symbol(message: str) -> str | None:
    match = re.search(r"[`'\"](?P<symbol>[A-Za-z_]\w*)[`'\"]", message)
    return match.group("symbol") if match else None

def search_header_declarations(src_root: Path | None, symbol: str | None) -> list[dict[str, Any]]:
    if src_root is None or not symbol:
        return []
    declarations: list[dict[str, Any]] = []
    pattern = re.compile(rf"\b{re.escape(symbol)}\b")
    for path in sorted(src_root.rglob("*")):
        if path.suffix not in {".h", ".hh", ".hpp", ".hxx"}:
            continue
        for line_no, text in enumerate(
            path.read_text(encoding="utf-8", errors="replace").splitlines(),
            start=1,
        ):
            if pattern.search(text):
                declarations.append(
                    {"path": str(path), "line": line_no, "text": text.strip()}
                )
                break
        if len(declarations) >= 5:
            break
    return declarations

def parse_missing_dependency(message: str) -> dict[str, str | None]:
    match = re.search(r"nothing provides\s+(?P<dep>.+?)(?:\s+needed by\s+(?P<pkg>\S+))?$", message)
    if not match:
        return {"dependency": message.strip(), "needed_by": None}
    return {
        "dependency": match.group("dep").strip(),
        "needed_by": match.group("pkg"),
    }

def profile_hint(scan_result: dict[str, Any]) -> str | None:
    buildlog_path = scan_result.get("buildlog_path")
    if isinstance(buildlog_path, str) and "profile" in buildlog_path.lower():
        return Path(buildlog_path).stem
    return None

def event_for(self, candidate: dict[str, Any]) -> dict[str, Any]:
        event_id = candidate.get("event_id") or candidate.get("id")
        for event in self.scan_result.get("events", []):
            if isinstance(event, dict) and event.get("id") == event_id:
                return event
        if candidate.get("kind"):
            return candidate
        return {}

def command_for(self, event: dict[str, Any]) -> dict[str, Any] | None:
        command_id = event.get("command_id")
        for command in self.scan_result.get("commands", []):
            if isinstance(command, dict) and command.get("id") == command_id:
                return command
        return None

def level_for_budget(granted_budget: int) -> int:
    if granted_budget >= 900:
        return 3
    if granted_budget >= 600:
        return 2
    return 1

def estimate(self, candidate: dict[str, Any]) -> dict[str, Any]:
        del candidate
        return default_estimate()

def estimate(self, candidate: dict[str, Any]) -> dict[str, Any]:
        del candidate
        return default_estimate()

def collect(self, candidate: dict[str, Any], granted_budget: int) -> Evidence:
        event = self.event_for(candidate)
        level = level_for_budget(granted_budget)
        data: dict[str, Any] = {
            "primary_error": event,
            "missing_dependency": parse_missing_dependency(str(event.get("message", ""))),
            "profile_hint": profile_hint(self.scan_result),
        }
        contains = {"primary_error", "missing_dependency"}
        warnings: list[str] = []
        degraded = False

        if level >= 2:
            if self.spec_path is not None and self.spec_path.exists():
                parser = SpecMinimalParser(self.spec_path)
                data["spec_buildrequires"] = parser.extract_buildrequires()
                data["spec_parse_status"] = parser.get_parse_status()
                contains.add("spec_buildrequires")
            else:
                warnings.append("spec_file_unavailable")
                degraded = True

        return Evidence(
            collector=self.collector_name,
            level=level,
            granted_budget=granted_budget,
            data=data,
            contains=contains,
            degraded=degraded,
            warnings=warnings,
        )

def estimate(self, candidate: dict[str, Any]) -> dict[str, Any]:
        del candidate
        return default_estimate()

def _find_symbol_context(src_root: Path, symbol: str, ctags_runner: Any | None) -> Any | None:
    for path in sorted(src_root.rglob("*")):
        if path.suffix not in {".c", ".cc", ".cpp", ".cxx", ".S", ".cu", ".h", ".hpp"}:
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        if symbol not in text:
            continue
        return extract_source_context(path, symbol=symbol, ctags_runner=ctags_runner)
    return None

def collector_for_candidate(
    candidate: dict[str, Any],
    scan_result: ScanResult | dict[str, Any],
    *,
    src_root: str | Path | None = None,
    spec_path: str | Path | None = None,
    buildlog_path: str | Path | None = None,
    ctags_runner: Any | None = None,
) -> EvidenceCollector | None:
    """Return the MVP collector for a ranked candidate or scanner event."""

    scan_data = scan_result.as_dict() if isinstance(scan_result, ScanResult) else scan_result
    event = _event_for_candidate(candidate, scan_data)
    kind = event.get("kind") or candidate.get("kind")

    kwargs = {
        "src_root": src_root,
        "spec_path": spec_path,
        "buildlog_path": buildlog_path,
        "ctags_runner": ctags_runner,
    }
    if kind in {"compiler", "werror"}:
        return CompileEvidenceCollector(scan_data, **kwargs)
    if kind in {"linker_undef", "linker_missing"}:
        return LinkEvidenceCollector(scan_data, **kwargs)
    if kind in {"spec_script", "rpm_phase"}:
        return SpecEvidenceCollector(scan_data, **kwargs)
    if kind == "depsolve":
        return DepsEvidenceCollector(scan_data, **kwargs)
    return None

