    return template.format_map(_SafeFormat(captures))

def __post_init__(self) -> None:
        self.reserved = {
            "primary_error": HardReserve(200),
            "command_summary": HardReserve(120),
            "metadata": HardReserve(80),
            "cascade_summary": SoftReserve(50),
            "top_k_text_summaries": SoftReserve(200),
            "raw_excerpt": SoftReserve(100),
        }
        initial = self.total - self.hard_reserved - self.soft_reserved
        if initial < 0:
            raise ValueError("reserved budget exceeds total")
        self.evidence_pool = initial

def hard_reserved(self) -> int:
        return sum(
            reserve.amount for reserve in self.reserved.values() if isinstance(reserve, HardReserve)
        )

def soft_reserved(self) -> int:
        return sum(
            reserve.amount for reserve in self.reserved.values() if isinstance(reserve, SoftReserve)
        )

def reclaimed(self) -> int:
        total = 0
        for name, actual in self.soft_used.items():
            reserve = self.reserved[name]
            if isinstance(reserve, SoftReserve):
                total += max(0, reserve.amount - actual)
        return total

def _refresh_partial_grant(self, collector_name: str) -> None:
        preferred = self.preferred_grants.get(collector_name, 0)
        granted = self.grants.get(collector_name, 0)
        if preferred > 0 and granted < preferred:
            self.partial_grants[collector_name] = True
        else:
            self.clear_partial(collector_name)

def conservation_total(self) -> int:
        soft_used = sum(self.soft_used.values())
        soft_pending = sum(
            reserve.amount
            for name, reserve in self.reserved.items()
            if isinstance(reserve, SoftReserve) and name not in self.soft_used
        )
        return (
            self.hard_reserved + soft_used + soft_pending + self.evidence_pool + self.granted_total
        )

def __init__(self, *, use_tiktoken: bool = True) -> None:
        self.method = "fallback"
        self._encoder: Any | None = None
        if use_tiktoken and tiktoken is not None:
            self._encoder = tiktoken.get_encoding("cl100k_base")
            self.method = "tiktoken"

def estimate_text(self, text: str) -> int:
        if self._encoder is not None:
            return len(self._encoder.encode(text))
        return fallback_token_estimate(text)

def truncate_text(self, text: str, max_tokens: int) -> str:
        if max_tokens <= 0:
            return ""
        current = self.estimate_text(text)
        if current <= max_tokens:
            return text
        ratio = max_tokens / max(current, 1)
        keep = max(1, math.floor(len(text) * ratio))
        truncated = text[:keep].rstrip()
        while truncated and self.estimate_text(truncated) > max_tokens:
            next_length = max(0, len(truncated) - 16)
            if next_length == len(truncated):
                next_length -= 1
            truncated = truncated[:next_length].rstrip()
        return truncated + "\n[truncated]"

def __init__(
        self,
        *,
        workspace_root: str | Path | None = None,
        hostname: str | None = None,
    ) -> None:
        self.workspace_root = None
        if workspace_root is not None:
            resolved_workspace = str(Path(workspace_root).resolve())
            if len(resolved_workspace) > 1 and resolved_workspace not in {"", ".", "/"}:
                self.workspace_root = resolved_workspace
        self.hostname = hostname or socket.gethostname()

def redact_for_llm(self, text: str) -> str:
        redacted = text
        if self.workspace_root:
            redacted = redacted.replace(self.workspace_root, "<WORKSPACE>")
        redacted = re.sub(r"/home/[^/\s]+/", "/home/<USER>/", redacted)
        if self.hostname:
            redacted = redacted.replace(self.hostname, "<HOST>")
        return redacted

def redact_obj_for_llm(self, obj: Any) -> Any:
        if isinstance(obj, str):
            return self.redact_for_llm(obj)
        if isinstance(obj, list):
            return [self.redact_obj_for_llm(item) for item in obj]
        if isinstance(obj, dict):
            return {key: self.redact_obj_for_llm(value) for key, value in obj.items()}
        return obj

def _refresh_prompt(packet: dict[str, Any], redactor: MinimalRedactor) -> None:
    if packet.get("verdict") == "needs_llm":
        packet["prompt"] = redactor.redact_for_llm(_render_prompt(packet))

def _mark_packet_truncated(packet: dict[str, Any]) -> None:
    reasons = packet.setdefault("degraded_reasons", [])
    if isinstance(reasons, list) and "packet_truncated_to_token_budget" not in reasons:
        reasons.append("packet_truncated_to_token_budget")
    packet["degraded"] = True

def _mark_packet_unable_to_truncate(packet: dict[str, Any]) -> None:
    reasons = packet.setdefault("degraded_reasons", [])
    if isinstance(reasons, list) and "packet_could_not_truncate_to_budget" not in reasons:
        reasons.append("packet_could_not_truncate_to_budget")
    packet["degraded"] = True

def _fallback_context(packet: dict[str, Any]) -> dict[str, Any] | None:
    evidence = packet.get("evidence")
    if not isinstance(evidence, dict):
        return None
    fallback = evidence.get("fallback_context")
    return fallback if isinstance(fallback, dict) else None

def _limit_fallback_lines(packet: dict[str, Any], field: str, *, max_lines: int) -> bool:
    fallback = _fallback_context(packet)
    if fallback is None:
        return False
    value = fallback.get(field)
    if not isinstance(value, str):
        return False
    lines = value.splitlines()
    if len(lines) <= max_lines:
        return False
    fallback[field] = "\n".join(lines[-max_lines:]) + "\n[truncated]"
    return True

def _clear_fallback_field(packet: dict[str, Any], field: str) -> bool:
    fallback = _fallback_context(packet)
    if fallback is None:
        return False
    value = fallback.get(field)
    if not isinstance(value, str) or not value:
        return False
    fallback[field] = ""
    return True

def _truncate_snippet_texts(
    packet: dict[str, Any],
    estimator: TokenEstimator,
    *,
    max_tokens: int,
) -> bool:
    evidence = packet.get("evidence")
    if not isinstance(evidence, dict):
        return False
    return _truncate_text_fields(evidence, estimator, max_tokens=max_tokens)

def _truncate_fallback_text(
    packet: dict[str, Any],
    estimator: TokenEstimator,
    *,
    max_tokens: int,
) -> bool:
    fallback = _fallback_context(packet)
    if fallback is None:
        return False
    changed = False
    for field_name in ("primary_error_excerpt", "extra_log_window"):
        value = fallback.get(field_name)
        if not isinstance(value, str) or not value:
            continue
        truncated = estimator.truncate_text(value, max_tokens)
        if truncated != value:
            fallback[field_name] = truncated
            changed = True
    return changed

def _truncate_text_fields(
    value: Any,
    estimator: TokenEstimator,
    *,
    max_tokens: int,
) -> bool:
    changed = False
    if isinstance(value, dict):
        for key, child in value.items():
            if key == "text" and isinstance(child, str):
                truncated = estimator.truncate_text(child, max_tokens)
                if truncated != child:
                    value[key] = truncated
                    changed = True
            else:
                changed = (
                    _truncate_text_fields(
                        child,
                        estimator,
                        max_tokens=max_tokens,
                    )
                    or changed
                )
    elif isinstance(value, list):
        for child in value:
            changed = (
                _truncate_text_fields(
                    child,
                    estimator,
                    max_tokens=max_tokens,
                )
                or changed
            )
    return changed

def _keep_top_candidate(packet: dict[str, Any]) -> bool:
    candidates = packet.get("root_cause_candidates")
    if not isinstance(candidates, list) or len(candidates) <= 1:
        return False
    packet["root_cause_candidates"] = candidates[:1]
    return True

def _safe_int(value: Any, *, default: int) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return default

def format_cascade_summary(scan_result: ScanResult | dict[str, Any]) -> str:
    scan_data = _scan_as_dict(scan_result)
    cascades = [
        event
        for event in scan_data.get("events", [])
        if isinstance(event, dict) and event.get("kind") == "make_cascade"
    ]
    if not cascades:
        return ""
    parts = []
    for event in cascades:
        target = event.get("target") or "<unknown>"
        parent = event.get("parent") or "unlinked"
        parts.append(f"{target} -> {parent}")
    return "make cascade: " + "; ".join(parts)

def _read_log_window(
    event: dict[str, Any],
    scan_data: dict[str, Any],
    *,
    before: int = 30,
    after: int = 20,
) -> str:
    path = Path(str(scan_data.get("buildlog_path", "")))
    if not path.exists():
        return str(event.get("message", ""))
    lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    line_no = event.get("line_no")
    if not isinstance(line_no, int):
        line_no = 1
    start = max(1, line_no - before)
    end = min(len(lines), line_no + after)
    return "\n".join(lines[start - 1 : end])

def _first_prompt_candidate(candidates: Any) -> Any:
    if not isinstance(candidates, list):
        return {}
    for candidate in candidates:
        if isinstance(candidate, dict):
            return {
                key: candidate.get(key)
                for key in ("rank", "event_id", "kind", "semantic_class", "confidence")
                if key in candidate
            }
    return {}

def _collect_prompt_paths(value: Any, paths: list[str]) -> None:
    if isinstance(value, dict):
        path = value.get("path") or value.get("file")
        if isinstance(path, str) and path not in paths:
            paths.append(path)
        for child in value.values():
            _collect_prompt_paths(child, paths)
    elif isinstance(value, list):
        for child in value:
            _collect_prompt_paths(child, paths)

def _top_event(candidates: list[dict[str, Any]], scan_data: dict[str, Any]) -> dict[str, Any]:
    if candidates:
        event = _event_for_id(candidates[0].get("event_id"), scan_data)
        if event:
            return event
    events = [event for event in scan_data.get("events", []) if isinstance(event, dict)]
    return events[0] if events else {}

def _event_for_id(event_id: Any, scan_data: dict[str, Any]) -> dict[str, Any] | None:
    for event in scan_data.get("events", []):
        if isinstance(event, dict) and event.get("id") == event_id:
            return event
    return None

def _command_for_event(
    event: dict[str, Any],
    scan_data: dict[str, Any],
) -> dict[str, Any] | None:
    command_id = event.get("command_id")
    for command in scan_data.get("commands", []):
        if isinstance(command, dict) and command.get("id") == command_id:
            return command
    return None

def _rank_candidates(
    rank_result: RankResult | dict[str, Any] | list[dict[str, Any]],
) -> list[dict[str, Any]]:
    if isinstance(rank_result, RankResult):
        candidates = rank_result.as_dict()["root_cause_candidates"]
        return [item for item in candidates if isinstance(item, dict)]
    if isinstance(rank_result, dict):
        candidates = rank_result.get("root_cause_candidates", [])
        return [item for item in candidates if isinstance(item, dict)]
    return [item for item in rank_result if isinstance(item, dict)]

def _copy_candidate_int_field(
    candidate: dict[str, Any],
    event: dict[str, Any],
    key: str,
) -> None:
    value = event.get(key)
    if isinstance(value, int):
        candidate[key] = value

def _evidence_as_dict(evidence: Evidence | dict[str, Any] | None) -> dict[str, Any] | None:
    if evidence is None:
        return None
    if isinstance(evidence, Evidence):
        return evidence.as_dict()
    return evidence

def _full_match_as_dict(
    full_match_result: FullMatchResult | dict[str, Any] | None,
) -> dict[str, Any]:
    if full_match_result is None:
        return {"verdict": "needs_llm"}
    if isinstance(full_match_result, FullMatchResult):
        return full_match_result.as_dict()
    if "verdict" in full_match_result:
        return full_match_result
    verdict = full_match_result.get("full_match_verdict")
    if verdict in {Verdict.DIRECT_TIER1.value, Verdict.DIRECT_TIER2.value}:
        return {**full_match_result, "verdict": "direct_answer"}
    return {**full_match_result, "verdict": "needs_llm"}

def _matched_patterns_from_match_data(match_data: dict[str, Any]) -> list[Any]:
    matched_patterns = match_data.get("matched_patterns")
    if isinstance(matched_patterns, list):
        return matched_patterns
    pattern_id = match_data.get("pattern_id")
    return [pattern_id] if pattern_id else []

def _scan_as_dict(scan_result: ScanResult | dict[str, Any]) -> dict[str, Any]:
    if isinstance(scan_result, ScanResult):
        return scan_result.as_dict()
    return scan_result

def from_file(cls, path: str | Path = DEFAULT_PATTERN_PATH) -> QuickFilter:
        library = (
            _load_default_pattern_library()
            if Path(path) == DEFAULT_PATTERN_PATH
            else load_pattern_library(path)
        )
        return cls(library["patterns"])

def evaluate(self, scan_result: ScanResult | dict[str, Any]) -> QuickFilterResult:
        scan_data = _scan_as_dict(scan_result)
        events = scan_data.get("events", [])
        commands = {
            command["id"]: command
            for command in scan_data.get("commands", [])
            if isinstance(command, dict) and "id" in command
        }
        evaluated = 0

        for event in events:
            if not isinstance(event, dict):
                continue
            for pattern in self.patterns:
                evaluated += 1
                captures = _match_pattern(pattern, event, events, commands)
                if captures is None:
                    continue
                direct_answer = _render_fix(pattern.fix_template, captures)
                match = QuickFilterMatch(
                    pattern_id=pattern.id,
                    category=pattern.category,
                    event_id=str(event["id"]),
                    confidence=pattern.confidence,
                    captures=captures,
                    direct_answer=direct_answer,
                    minimal_packet=_minimal_packet(scan_data, event, pattern, direct_answer),
                )
                return QuickFilterResult(hit=True, match=match, evaluated_patterns=evaluated)

        return QuickFilterResult(hit=False, evaluated_patterns=evaluated)

def load_pattern_library(path: str | Path = DEFAULT_PATTERN_PATH) -> dict[str, Any]:
    raw = yaml.safe_load(Path(path).read_text(encoding="utf-8"))
    if not isinstance(raw, dict):
        raise PatternValidationError("pattern library must be a mapping")
    return {
        "schema_version": raw.get("schema_version"),
        "tier1_allowed_categories": tuple(raw.get("tier1_allowed_categories", [])),
        "tier1_forbidden_categories": tuple(raw.get("tier1_forbidden_categories", [])),
        "patterns": _compile_patterns(raw),
    }

def _compile_patterns(raw: dict[str, Any]) -> list[QuickPattern]:
    if raw.get("schema_version") != 2:
        raise PatternValidationError("pattern library schema_version must be 2")

    allowed = set(raw.get("tier1_allowed_categories", []))
    forbidden = set(raw.get("tier1_forbidden_categories", []))
    patterns = raw.get("patterns", [])
    if not isinstance(patterns, list):
        raise PatternValidationError("patterns must be a list")

    compiled: list[QuickPattern] = []
    for item in patterns:
        if not isinstance(item, dict):
            raise PatternValidationError("each pattern must be a mapping")
        if item.get("tier") != "tier1":
            continue
        _validate_tier1_pattern(item, allowed, forbidden)
        match = item["match"]
        compiled.append(
            QuickPattern(
                id=str(item["id"]),
                category=str(item["category"]),
                tier=str(item["tier"]),
                event_kinds=tuple(str(kind) for kind in item["event_kinds"]),
                regex=tuple(
                    re.compile(str(pattern), re.IGNORECASE) for pattern in match["regex"]
                ),
                required_context=dict(match.get("required_context", {})),
                negative_patterns=tuple(
                    re.compile(str(pattern), re.IGNORECASE)
                    for pattern in match.get("negative_patterns", [])
                ),
                confidence=float(item["confidence"]),
                terminal=bool(item["terminal"]),
                fix_template=str(item["fix_template"]),
            )
        )
    return compiled

def _validate_tier1_pattern(
    item: dict[str, Any], allowed: set[str], forbidden: set[str]
) -> None:
    pattern_id = item.get("id", "<unknown>")
    category = item.get("category")
    tier = item.get("tier")
    fix_template = str(item.get("fix_template", ""))

    if tier != "tier1":
        raise PatternValidationError(f"{pattern_id}: only tier1 patterns are allowed in M2")
    if category not in allowed:
        raise PatternValidationError(f"{pattern_id}: category is not tier1-allowed")
    if category in forbidden:
        raise PatternValidationError(f"{pattern_id}: category is tier1-forbidden")
    if not item.get("terminal"):
        raise PatternValidationError(f"{pattern_id}: tier1 pattern must be terminal")
    if float(item.get("confidence", 0.0)) < 0.95:
        raise PatternValidationError(f"{pattern_id}: tier1 confidence must be >= 0.95")
    limit = 150 if category == "patch_failed" else 300
    if len(fix_template) > limit:
        raise PatternValidationError(f"{pattern_id}: fix_template exceeds {limit} chars")
    if not any(word in fix_template for word in UNCERTAIN_WORDS):
        raise PatternValidationError(f"{pattern_id}: fix_template must be conservative")
    if "expand" not in fix_template:
        raise PatternValidationError(f"{pattern_id}: fix_template must mention expand")

def _match_pattern(
    pattern: QuickPattern,
    event: dict[str, Any],
    all_events: list[Any],
    commands: dict[str, dict[str, Any]],
) -> dict[str, str] | None:
    if event.get("kind") not in pattern.event_kinds:
        return None
    if not _passes_required_context(pattern.required_context, event, all_events, commands):
        return None

    message = str(event.get("message", ""))
    if any(negative.search(message) for negative in pattern.negative_patterns):
        return None

    for regex in pattern.regex:
        match = regex.search(message)
        if match:
            return {
                key: value
                for key, value in match.groupdict().items()
                if value is not None
            }
    return None

def _passes_required_context(
    context: dict[str, Any],
    event: dict[str, Any],
    all_events: list[Any],
    commands: dict[str, dict[str, Any]],
) -> bool:
    phases = context.get("phase")
    if phases is not None and event.get("phase") not in phases:
        return False

    severities = context.get("severity")
    if severities is not None and event.get("severity") not in severities:
        return False

    tools = context.get("tool_in")
    if tools is not None and _event_tool(event, commands) not in tools:
        return False

    if context.get("not_in_warning_block") and is_in_warning_block(event, all_events):
        return False

    return True

def _event_tool(event: dict[str, Any], commands: dict[str, dict[str, Any]]) -> str | None:
    command_id = event.get("command_id")
    if command_id is None:
        return None
    command = commands.get(str(command_id))
    if command is None:
        return None
    argv_short = str(command.get("argv_short", ""))
    try:
        parts = shlex.split(argv_short)
    except ValueError:
        parts = argv_short.split()
    if not parts:
        return None
    return Path(parts[0]).name

def _scan_as_dict(scan_result: ScanResult | dict[str, Any]) -> dict[str, Any]:
    if isinstance(scan_result, ScanResult):
        return scan_result.as_dict()
    return scan_result

def quick_filter(scan_result: ScanResult | dict[str, Any]) -> QuickFilterResult:
    """Evaluate the default pattern library against a scan result."""

    return QuickFilter.from_file().evaluate(scan_result)

def as_dict(self) -> dict[str, Any]:
        return {
            "root_cause_candidates": [
                candidate.as_dict() for candidate in self.root_cause_candidates
            ]
        }

def rank_score(
    event: dict[str, Any],
    all_events: list[Any],
    semantic: SemanticClass | None = None,
    *,
    failed_phase: str | None = None,
) -> tuple[float, list[dict[str, Any]]]:
    """Return the v0.5 ranking score and structured confidence reasons."""

    if event.get("kind") == "make_cascade" and event.get("parent"):
        return 0.1, [
            {"factor": "make_cascade_parent", "value": event.get("parent"), "score": 0.1}
        ]

    sem = semantic or SemanticClassifier.from_file().classify(event, {"failed_phase": None})
    reasons: list[dict[str, Any]] = [
        {"factor": "semantic_class", "value": sem.name, "base": sem.base_confidence}
    ]
    score = sem.base_confidence

    if event.get("kind") == "linker_undef":
        reasons.append({"factor": "linker_undef_no_cascade_penalty", "delta": "+0.00"})
    else:
        cascade_delta = -(sem.cascade_probability * 0.3)
        score += cascade_delta
        reasons.append(
            {
                "factor": "cascade_probability",
                "probability": sem.cascade_probability,
                "delta": _format_delta(cascade_delta),
            }
        )

    if event.get("command_id"):
        score += 0.05
        reasons.append({"factor": "has_command", "delta": "+0.05"})

    if event.get("file") and event.get("line"):
        score += 0.05
        reasons.append({"factor": "has_location", "delta": "+0.05"})

    if event.get("kind") == "patch" and event.get("phase") == failed_phase:
        score += 0.1
        reasons.append({"factor": "patch_failed_phase", "delta": "+0.10"})

    if is_in_warning_block(event, all_events):
        score -= 0.3
        reasons.append({"factor": "warning_block", "delta": "-0.30"})

    if event.get("parent"):
        score -= 0.4
        reasons.append({"factor": "parent_cascade", "delta": "-0.40"})

    clamped = clamp(score, 0.0, 1.0)
    if clamped != score:
        reasons.append({"factor": "clamp", "from": round(score, 4), "to": clamped})
    if sem.name == "generic_error":
        reasons.append(
            {
                "factor": "generic_context_satisfied",
                "value": sem.context_satisfied,
            }
        )
    return clamped, reasons

def confidence_band(score: float) -> str:
    if score >= 0.85:
        return "high"
    if score >= 0.70:
        return "medium_high"
    if score >= 0.50:
        return "medium"
    return "low"

def _summary(event: dict[str, Any], sem: SemanticClass) -> str:
    location = ""
    if event.get("file") and event.get("line"):
        location = f" at {event['file']}:{event['line']}"
    message = str(event.get("message", "")).strip()
    return f"{event.get('kind')} {sem.name}{location} - {message}"

def _candidate_severity(event: dict[str, Any]) -> str | None:
    severity = event.get("severity")
    if severity is None:
        return None
    normalized = str(severity).strip().lower()
    return normalized or None

def _score_bucket(score: float) -> int:
    """Bucket close scores so severity can break near-ties without lifting cascades."""

    return int((score + (_SCORE_BUCKET_SIZE / 2)) / _SCORE_BUCKET_SIZE)

def _line_no(event: dict[str, Any]) -> int:
    try:
        return int(event.get("line_no", 0))
    except (TypeError, ValueError):
        return 0

def _scan_as_dict(scan_result: ScanResult | dict[str, Any]) -> dict[str, Any]:
    if isinstance(scan_result, ScanResult):
        return scan_result.as_dict()
    return scan_result

def trace(self, level: str, event: str, **fields: Any) -> None:
        if self.trace_logger is not None:
            self.trace_logger.emit(level, "L0_scan", event, **fields)

def _add_event(self, event: DiagnosticEvent, line: LogLine | None = None) -> None:
        if event.kind == "rpm_phase":
            phase = str(event.details.get("phase") or event.phase or "")
            patch_parent = self._last_patch_event_by_phase.get(phase)
            if phase == "%prep" and patch_parent is not None:
                event.parent = patch_parent
                event.details["derived_from"] = "patch_failed"

        if event.kind == "make_cascade" and event.target is not None:
            suffix_index = build_suffix_index(self._source_to_event)
            event.parent = match_make_target(event.target, suffix_index)
            if event.parent is not None:
                self.trace(
                    "INFO",
                    "cascade_associated",
                    event_id=event.id,
                    parent=event.parent,
                    target=event.target,
                )

        self.events.append(event)
        if event.kind == "patch" and event.phase is not None:
            self._last_patch_event_by_phase[event.phase] = event.id
        if event.file is not None and is_supported_source(event.file):
            self._source_to_event[event.file] = event.id
        if event.kind != "make_cascade":
            self.failed_phase = event.phase or self.failed_phase
        trace_fields: dict[str, Any] = {
            "event_id": event.id,
            "kind": event.kind,
            "phase": event.phase,
            "line_no": event.line_no,
            "offset": event.raw_offset,
        }
        if line is not None:
            trace_fields.update(
                {
                    "text": line.text,
                    "raw_text": line.raw_text,
                    "gbs_seconds": line.gbs_seconds,
                }
            )
        self.trace("INFO", "diagnostic_detected", **trace_fields)

def _extract_event(self, line: LogLine) -> DiagnosticEvent | None:
        event_id = f"E{len(self.events) + 1:03d}"
        text = line.text
        lowered = text.lower()
        if not _may_contain_diagnostic(lowered):
            return None

        if "nothing provides" in lowered:
            return self._event(event_id, "depsolve", "error", text, line)

        patch_details = _match_patch(text)
        if patch_details is not None:
            message = str(patch_details.pop("_message", text))
            return self._event(event_id, "patch", "error", message, line, details=patch_details)

        if "file not found:" in lowered or "installed (but unpackaged) file(s) found" in lowered:
            return self._event(event_id, "install_missing", "error", text, line)

        unknown_warning_option = _match_unknown_warning_option(text)
        if unknown_warning_option is not None:
            return self._unknown_warning_option_event(event_id, line, unknown_warning_option)

        compiler_match = COMPILER_PATTERN.search(text)
        if compiler_match and "-werror" in lowered:
            return self._werror_event(event_id, line, compiler_match)

        if "all warnings being treated as errors" in lowered:
            return self._event(event_id, "werror", "error", text, line)

        if _looks_like_werror_diagnostic(text):
            return self._event(event_id, "werror", "error", text, line)

        linker_missing = LINKER_MISSING_PATTERN.search(text)
        if linker_missing:
            return self._event(
                event_id,
                "linker_missing",
                "error",
                text,
                line,
                details={"library": linker_missing.group("library")},
            )

        linker_undef = LINKER_UNDEF_PATTERN.search(text)
        if linker_undef:
            return self._event(
                event_id,
                "linker_undef",
                "error",
                text,
                line,
                details={"symbol": linker_undef.group("symbol")},
            )

        if compiler_match:
            return self._compiler_event(event_id, line, compiler_match)

        rpm_phase = RPM_PHASE_PATTERN.search(text)
        if rpm_phase:
            return self._event(
                event_id,
                "rpm_phase",
                "error",
                text,
                line,
                details={"phase": rpm_phase.group("phase")},
            )

        make_cascade = MAKE_CASCADE_PATTERN.search(text)
        if make_cascade:
            return self._event(
                event_id,
                "make_cascade",
                "error",
                text,
                line,
                target=make_cascade.group("target"),
            )

        if "spec file" in lowered and "error" in lowered:
            return self._event(event_id, "spec_script", "error", text, line)

        if _looks_like_raw_error(lowered):
            return self._event(event_id, "raw_error", "error", text, line)

        return None

def _compiler_event(
        self, event_id: str, line: LogLine, match: re.Match[str]
    ) -> DiagnosticEvent:
        column = match.group("column")
        file_path = match.group("file")
        details: dict[str, Any] = {"is_assembler": _is_assembler_source(file_path)}
        tool = self._current_command_tool()
        if tool is not None:
            details["tool"] = tool
        return self._event(
            event_id,
            "compiler",
            _normalize_severity(match.group("severity")),
            match.group("message"),
            line,
            file=file_path,
            diagnostic_line=int(match.group("line")),
            column=int(column) if column is not None else None,
            details=details,
        )

def _unknown_warning_option_event(
        self, event_id: str, line: LogLine, match: re.Match[str]
    ) -> DiagnosticEvent:
        return self._event(
            event_id,
            "werror",
            "error",
            line.text,
            line,
            details={
                "diagnostic_type": "unknown_warning_option",
                "warning_option": match.group("option"),
            },
        )

def _current_command_tool(self) -> str | None:
        if self.current_command_id is None:
            return None
        for command in reversed(self.commands):
            if command.id == self.current_command_id:
                return _tool_from_command(command.argv_short)
        return None

def scan_buildlog(
    buildlog_path: str | Path,
    *,
    cwd: str | Path | None = None,
    trace_logger: TraceLogger | None = None,
) -> ScanResult:
    """Scan a buildlog using the M1 Layer 0+1 scanner."""

    return BuildLogScanner(cwd=cwd, trace_logger=trace_logger).scan(buildlog_path)

def _iter_log_lines(path: Path) -> Iterator[LogLine]:
    if path.suffix == ".gz":
        yield from _iter_gzip_lines(path)
        return
    yield from _iter_mmap_lines(path)

def _normalize_log_text(raw_text: str) -> tuple[str, int | None]:
    text = ANSI_ESCAPE_PATTERN.sub("", raw_text)
    timestamp = GBS_TIMESTAMP_PATTERN.match(text)
    if timestamp is None:
        return text, None
    return text[timestamp.end() :], int(timestamp.group("seconds"))

def _match_phase_marker(text: str) -> str | None:
    phase_match = PHASE_PATTERN.match(text)
    if phase_match:
        return phase_match.group("phase").split()[0]
    executing_match = EXECUTING_PHASE_PATTERN.match(text)
    if executing_match:
        return executing_match.group("phase")
    return None

def _match_patch(text: str) -> dict[str, str] | None:
    for pattern in PATCH_PATTERNS:
        match = pattern.search(text)
        if match:
            details = {
                key: value
                for key, value in match.groupdict().items()
                if value is not None
            }
            if "can't find file to patch" in text.lower():
                details["_message"] = f"error: patch failed: {text}"
            elif (
                "hunk" in text.lower()
                and "ignored" in text.lower()
                and not text.lower().startswith("hunk")
            ):
                details["_message"] = f"Hunk #{details.get('num', '1')} FAILED: {text}"
            return details
    return None

def _normalize_severity(severity: str) -> str:
    normalized = severity.lower()
    return "error" if normalized == "fatal error" else normalized

def _tool_from_command(command_line: str) -> str | None:
    try:
        parts = shlex.split(command_line)
    except ValueError:
        parts = command_line.split()
    if not parts:
        return None
    return Path(parts[0]).name

def _match_unknown_warning_option(text: str) -> re.Match[str] | None:
    if "-wunknown-warning-option" not in text.lower():
        return None
    return UNKNOWN_WARNING_OPTION_PATTERN.search(text)

def build_source_candidate_observation(
    *,
    packet: dict[str, Any],
    scan_result: ScanResult | dict[str, Any],
    buildlog_path: Path,
    source_candidate_sidecar: dict[str, Any] | None,
    error_cluster_sidecar: dict[str, Any] | None,
) -> dict[str, Any]:
    """Return an observation report without changing analyzer or patch outputs."""

    scan_data = _scan_as_dict(scan_result)
    main_candidates = _source_candidates(source_candidate_sidecar)
    excluded = _excluded_source_diagnostics(source_candidate_sidecar)
    sidecar_items = [
        _coverage_item(candidate, source="source_candidates")
        for candidate in main_candidates
    ]
    sidecar_by_identity = {item.identity: item for item in sidecar_items}
    excluded_by_identity = {
        _identity(excluded_item): excluded_item
        for excluded_item in excluded
        if _identity(excluded_item) is not None
    }
    scan_events_by_identity = {
        _identity(event): event
        for event in _events(scan_data)
        if _identity(event) is not None
    }

    old_coverage, old_decision = _old_path_coverage(
        packet=packet,
        error_cluster_sidecar=error_cluster_sidecar,
    )
    old_by_identity = {item.identity: item for item in old_coverage}

    missed = [
        item
        for item in sidecar_items
        if item.identity not in old_by_identity
    ]
    extra = [
        _extra_item(
            item,
            excluded_by_identity.get(item.identity),
            scan_events_by_identity.get(item.identity),
        )
        for item in old_coverage
        if item.identity not in sidecar_by_identity
    ]

    scanner_gap = _scanner_coverage_gap(
        buildlog_path=buildlog_path,
        scan_data=scan_data,
    )
    type_source_stats = _type_source_stats(main_candidates)

    return {
        "schema_version": OBSERVATION_SCHEMA,
        "scope": (
            "Observation-only report. It does not alter Evidence Packet ranking, "
            "patch-suggest output, or source_candidate sidecar contents."
        ),
        "coverage_diff": {
            "sidecar_diagnostics": [_summarize(item.diagnostic) for item in sidecar_items],
            "old_path_covered": [_summarize(item.diagnostic) for item in old_coverage],
            "missed_by_old": [_summarize(item.diagnostic) for item in missed],
            "extra_by_old": extra,
            "counts": {
                "sidecar_diagnostics": len(sidecar_items),
                "old_path_covered": len(old_coverage),
                "missed_by_old": len(missed),
                "extra_by_old": len(extra),
            },
            "old_path_decision": old_decision,
        },
        "scanner_coverage_gap": scanner_gap,
        "type_source_stats": type_source_stats,
    }

def _old_path_coverage(
    *,
    packet: dict[str, Any],
    error_cluster_sidecar: dict[str, Any] | None,
) -> tuple[list[_CoverageItem], dict[str, Any]]:
    fallback_reasons: dict[str, str] = {}
    sidecar_readable: bool | None = None

    cluster_items, cluster_reason, sidecar_readable = _cluster_old_coverage(
        packet,
        error_cluster_sidecar,
    )
    if cluster_items is not None:
        return cluster_items, {
            "selected_branch": "cluster",
            "fallback_reasons": fallback_reasons,
            "sidecar_readable": sidecar_readable,
        }
    fallback_reasons["cluster"] = cluster_reason

    multi_items, multi_reason = _multi_old_coverage(packet)
    if multi_items is not None:
        return multi_items, {
            "selected_branch": "multi",
            "fallback_reasons": fallback_reasons,
            "sidecar_readable": sidecar_readable,
        }
    fallback_reasons["multi"] = multi_reason

    single_items, single_reason = _single_old_coverage(packet)
    if single_items is not None:
        return single_items, {
            "selected_branch": "single",
            "fallback_reasons": fallback_reasons,
            "sidecar_readable": sidecar_readable,
        }
    fallback_reasons["single"] = single_reason
    return [], {
        "selected_branch": "none",
        "fallback_reasons": fallback_reasons,
        "sidecar_readable": sidecar_readable,
    }

def _cluster_old_coverage(
    packet: dict[str, Any],
    error_cluster_sidecar: dict[str, Any] | None,
) -> tuple[list[_CoverageItem] | None, str, bool | None]:
    summary = packet.get("error_clusters")
    if not isinstance(summary, dict):
        return None, "no_error_clusters", None
    clusters = [cluster for cluster in summary.get("clusters", []) if isinstance(cluster, dict)]
    if not clusters:
        return None, "no_clusters", None
    selected = [cluster for cluster in clusters if _is_large_scale_source_cluster(cluster)]
    if not selected:
        if any(cluster.get("large_scale") is False for cluster in clusters):
            return None, "large_scale_false", None
        return None, "no_large_scale_source_cluster", None
    if (
        not isinstance(error_cluster_sidecar, dict)
        or error_cluster_sidecar.get("schema_version") != "error_clusters_locations/v1"
    ):
        return None, "sidecar_unreadable", False
    sidecar_by_id = {
        str(cluster.get("id")): cluster
        for cluster in error_cluster_sidecar.get("clusters", [])
        if isinstance(cluster, dict) and cluster.get("id") is not None
    }
    items: list[_CoverageItem] = []
    for summary_cluster in selected:
        cluster_id = str(summary_cluster.get("id"))
        warning_option = str(summary_cluster.get("warning_option") or "")
        sidecar_cluster = sidecar_by_id.get(cluster_id)
        if not isinstance(sidecar_cluster, dict):
            continue
        for raw_location in sidecar_cluster.get("locations", []):
            if not isinstance(raw_location, dict):
                continue
            file_value = raw_location.get("file")
            line_value = raw_location.get("line")
            if not isinstance(file_value, str) or not isinstance(line_value, int):
                continue
            location = dict(raw_location)
            location.setdefault("warning_option", warning_option)
            location.setdefault("source_cluster_id", cluster_id)
            item = _coverage_item(location, source="old_cluster")
            items.append(item)
    if not items:
        return None, "sidecar_no_usable_locations", True
    return items, "", True

def _multi_old_coverage(packet: dict[str, Any]) -> tuple[list[_CoverageItem] | None, str]:
    raw_candidates = packet.get("root_cause_candidates")
    if not isinstance(raw_candidates, list):
        return None, "no_root_cause_candidates"
    eligible = [
        candidate
        for candidate in raw_candidates
        if isinstance(candidate, dict) and _is_multi_eligible(candidate)
    ]
    if len(eligible) < 2:
        return None, "candidates_lt_2"
    return [
        _coverage_item(candidate, source="old_multi")
        for candidate in eligible
    ], ""

def _single_old_coverage(packet: dict[str, Any]) -> tuple[list[_CoverageItem] | None, str]:
    primary = packet.get("primary_error")
    if not isinstance(primary, dict) or not primary:
        return None, "no_primary_error"
    return [_coverage_item(primary, source="old_single")], ""

def _is_large_scale_source_cluster(cluster: dict[str, Any]) -> bool:
    if not cluster.get("large_scale"):
        return False
    if cluster.get("kind") != "source_warning_option":
        return False
    diagnostic_kinds = cluster.get("diagnostic_kinds")
    if not isinstance(diagnostic_kinds, list) or not diagnostic_kinds:
        return False
    kinds = {kind for kind in diagnostic_kinds if isinstance(kind, str)}
    return bool(kinds) and kinds.issubset(SOURCE_DIAGNOSTIC_KINDS)

def _is_multi_eligible(candidate: dict[str, Any]) -> bool:
    if candidate.get("is_terminal") is not True:
        return False
    if candidate.get("kind") not in SOURCE_DIAGNOSTIC_KINDS:
        return False
    if not isinstance(candidate.get("file"), str) or not candidate.get("file"):
        return False
    line_value = candidate.get("line")
    if not isinstance(line_value, int) or line_value <= 0:
        return False
    return isinstance(candidate.get("message"), str) and bool(candidate.get("message"))

def _coverage_item(diagnostic: dict[str, Any], *, source: str) -> _CoverageItem:
    identity = _identity(diagnostic)
    if identity is None:
        identity = f"fallback:{_fallback_identity(diagnostic)}"
    data = dict(diagnostic)
    data["coverage_source"] = source
    data["identity"] = identity
    return _CoverageItem(identity=identity, diagnostic=data, source=source)

def _identity(diagnostic: dict[str, Any]) -> str | None:
    event_id = diagnostic.get("event_id") or diagnostic.get("id")
    if isinstance(event_id, str) and event_id:
        return f"event_id:{event_id}"
    dedupe_key = diagnostic.get("dedupe_key")
    if isinstance(dedupe_key, str) and dedupe_key:
        return f"dedupe:{dedupe_key}"
    return None

def _fallback_identity(diagnostic: dict[str, Any]) -> str:
    warning_option = diagnostic.get("warning_option")
    if not isinstance(warning_option, str) or not warning_option:
        warning_option = extract_warning_option(diagnostic) or "<none>"
    parts = [
        f"file={diagnostic.get('normalized_file') or diagnostic.get('file') or '<unknown>'}",
        (
            f"line={diagnostic.get('line')}"
            if isinstance(diagnostic.get("line"), int)
            else "line=<unknown>"
        ),
        (
            f"column={diagnostic.get('column')}"
            if isinstance(diagnostic.get("column"), int)
            else "column=<unknown>"
        ),
        f"warning_option={warning_option}",
        f"semantic_class={diagnostic.get('semantic_class') or '<unknown>'}",
        f"message={_message_fingerprint(str(diagnostic.get('message') or ''))}",
        f"command_id={diagnostic.get('command_id') or '<unknown>'}",
        f"kind={diagnostic.get('kind') or '<unknown>'}",
    ]
    return "|".join(parts)

def _extra_item(
    item: _CoverageItem,
    excluded: dict[str, Any] | None,
    scan_event: dict[str, Any] | None,
) -> dict[str, Any]:
    data = {
        "diagnostic": _summarize(item.diagnostic),
        "new_sidecar_location": "not_present",
        "exclusion_reason": None,
    }
    if excluded is not None:
        data["new_sidecar_location"] = "excluded_source_diagnostics"
        data["exclusion_reason"] = excluded.get("exclusion_reason")
        data["excluded_diagnostic"] = _summarize(excluded)
    elif scan_event is not None:
        data["new_sidecar_location"] = "not_source_candidate_eligible"
        data["exclusion_reason"] = _source_candidate_gate_exclusion_reason(scan_event)
        data["scan_event"] = _summarize(scan_event)
    return data

def _source_candidate_gate_exclusion_reason(event: dict[str, Any]) -> str:
    if event.get("kind") not in SOURCE_DIAGNOSTIC_KINDS:
        return "non_source_kind"
    if not isinstance(event.get("file"), str) or not event.get("file"):
        return "missing_file"
    line_value = event.get("line")
    if not isinstance(line_value, int) or line_value <= 0:
        return "missing_line"
    if event.get("parent") is not None:
        return "explicit_parent"
    if not _is_structured_source_diagnostic(event):
        return "not_fatal_or_werror"
    return "not_present_in_source_candidate_sidecar"

def _scanner_coverage_gap(
    *,
    buildlog_path: Path,
    scan_data: dict[str, Any],
) -> dict[str, Any]:
    raw = _raw_source_diagnostics(buildlog_path)
    structured = [
        event
        for event in _events(scan_data)
        if _is_structured_source_diagnostic(event)
    ]
    structured_keys = {_raw_match_key(event) for event in structured}
    unmatched = [
        item
        for item in raw
        if _raw_match_key(item) not in structured_keys
    ]
    return {
        "scope": (
            "Heuristic observation only. Raw diagnostic-like lines are not converted "
            "into source_candidates."
        ),
        "raw_diagnostic_like_line_count": len(raw),
        "structured_event_count": len(structured),
        "unmatched_diagnostic_like_line_count": len(unmatched),
        "unmatched_diagnostic_like_line_samples": [
            _summarize(item) for item in unmatched[:10]
        ],
        "unmatched_categories": _unmatched_categories(unmatched),
    }

def _raw_source_diagnostics(buildlog_path: Path) -> list[dict[str, Any]]:
    try:
        lines = buildlog_path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return []
    diagnostics: list[dict[str, Any]] = []
    for line_no, line in enumerate(lines, start=1):
        match = RAW_DIAGNOSTIC_PATTERN.search(_strip_gbs_prefix(line))
        if match is None:
            continue
        level = match.group("level").lower()
        message = match.group("message").strip()
        if level == "warning" and "-Werror" not in message:
            continue
        diagnostics.append(
            {
                "line_no": line_no,
                "file": match.group("file"),
                "line": int(match.group("line")),
                "column": _optional_int(match.group("column")),
                "severity": "error" if level in {"error", "fatal error"} else "warning",
                "message": message,
                "warning_option": _warning_option_from_message(message),
            }
        )
    return diagnostics

def _is_structured_source_diagnostic(event: dict[str, Any]) -> bool:
    if event.get("kind") not in SOURCE_DIAGNOSTIC_KINDS:
        return False
    if not isinstance(event.get("file"), str) or not isinstance(event.get("line"), int):
        return False
    if str(event.get("severity") or "").lower() == "error":
        return True
    if event.get("kind") == "werror":
        return True
    return "-Werror" in str(event.get("message") or "")

def _raw_match_key(diagnostic: dict[str, Any]) -> tuple[Any, ...]:
    return (
        diagnostic.get("file"),
        diagnostic.get("line"),
        diagnostic.get("column"),
        diagnostic.get("warning_option") or _warning_option_from_message(
            str(diagnostic.get("message") or "")
        ),
    )

def _warning_option_from_message(message: str) -> str | None:
    for block in WARNING_BLOCK_PATTERN.findall(message):
        for raw_token in block.split(","):
            token = raw_token.strip()
            if token.startswith("-W") and token != "-Werror":
                return str(token)
    return None

def _unmatched_categories(unmatched: list[dict[str, Any]]) -> dict[str, int]:
    categories = {
        "werror_promoted": 0,
        "source_error": 0,
        "truncation_signal": 0,
    }
    for item in unmatched:
        message = str(item.get("message") or "")
        if "-Werror" in message:
            categories["werror_promoted"] += 1
        else:
            categories["source_error"] += 1
        if TRUNCATION_MARKER in message.lower():
            categories["truncation_signal"] += 1
    return {key: value for key, value in categories.items() if value}

def _type_source_stats(candidates: list[dict[str, Any]]) -> dict[str, Any]:
    type_unknown_by_reason: dict[str, int] = {}
    source_unreachable_by_status: dict[str, int] = {}
    source_not_owned_by_status: dict[str, int] = {}
    for candidate in candidates:
        if candidate.get("type_fixability") == "unknown":
            _increment(type_unknown_by_reason, candidate.get("type_fixability_reason"))
        if candidate.get("source_reachable") is not True:
            _increment(source_unreachable_by_status, candidate.get("source_resolution_status"))
        if candidate.get("source_owned") is not True:
            _increment(source_not_owned_by_status, candidate.get("source_ownership_status"))
    return {
        "type_unknown_by_reason": type_unknown_by_reason,
        "source_unreachable_by_status": source_unreachable_by_status,
        "source_not_owned_by_status": source_not_owned_by_status,
    }

def _increment(counter: dict[str, int], key: object) -> None:
    label = str(key) if key else "<unknown>"
    counter[label] = counter.get(label, 0) + 1

def _source_candidates(sidecar: dict[str, Any] | None) -> list[dict[str, Any]]:
    if not isinstance(sidecar, dict):
        return []
    candidates = sidecar.get("candidates")
    if not isinstance(candidates, list):
        return []
    return [candidate for candidate in candidates if isinstance(candidate, dict)]

def _excluded_source_diagnostics(sidecar: dict[str, Any] | None) -> list[dict[str, Any]]:
    if not isinstance(sidecar, dict):
        return []
    diagnostics = sidecar.get("excluded_source_diagnostics")
    if not isinstance(diagnostics, list):
        return []
    return [diagnostic for diagnostic in diagnostics if isinstance(diagnostic, dict)]

def _message_fingerprint(message: str) -> str:
    normalized = re.sub(r"\s+", " ", message.strip().lower())
    return hashlib.sha1(normalized.encode("utf-8", errors="replace")).hexdigest()[
        :MESSAGE_FINGERPRINT_LEN
    ]

def _scan_as_dict(scan_result: ScanResult | dict[str, Any]) -> dict[str, Any]:
    if isinstance(scan_result, ScanResult):
        return scan_result.as_dict()
    return scan_result

def _excluded_parent(event: dict[str, Any], file_value: str) -> dict[str, Any]:
    data = {
        "event_id": event.get("id"),
        "file": file_value,
        "line": event.get("line"),
        "parent": event.get("parent"),
        "exclusion_reason": "explicit_parent",
    }
    return {key: value for key, value in data.items() if value is not None}

def _excluded_missing_location(
    event: dict[str, Any],
    *,
    missing_file: bool,
    missing_line: bool,
) -> dict[str, Any]:
    if missing_file and missing_line:
        reason = "missing_file_and_line"
    elif missing_file:
        reason = "missing_file"
    else:
        reason = "missing_line"
    data = {
        "event_id": event.get("id"),
        "file": event.get("file"),
        "line": event.get("line"),
        "exclusion_reason": reason,
    }
    return {key: value for key, value in data.items() if value is not None}

def _fatal_detection_source(event: dict[str, Any]) -> str | None:
    if str(event.get("severity") or "").strip().lower() == "error":
        return "severity"
    if event.get("kind") == "werror":
        return "kind"
    if "-Werror" in str(event.get("message") or ""):
        return "werror_message_fallback"
    return None

def _type_fixability(
    *,
    warning_option: str | None,
    semantic_class: str,
    message: str,
) -> tuple[str, str]:
    if warning_option in PROBABLY_FIXABLE_WARNING_OPTIONS:
        return "probably_fixable", f"whitelisted_warning_option:{warning_option}"
    if _is_unused_field(semantic_class=semantic_class, message=message):
        return "probably_fixable", "unused_field_message_rule"
    return "unknown", "no_matching_fixability_rule"

def _is_unused_field(*, semantic_class: str, message: str) -> bool:
    lowered = message.lower()
    if semantic_class in {"unused_field", "unused_private_field"}:
        return True
    return (
        "unused" in lowered and "field" in lowered
    ) or "private field" in lowered and "not used" in lowered

def _source_path_info(file_value: str, src_root: str | Path | None) -> _SourcePathInfo:
    raw_normalized = _normalize_raw_file(file_value)
    if _is_system_path(raw_normalized):
        return _SourcePathInfo(
            normalized_file=raw_normalized,
            source_reachable=False,
            source_resolution_status=_unreachable_status(src_root),
            source_owned=False,
            source_ownership_status="system_or_toolchain_path",
        )

    mapped = _mapped_source_path(file_value, src_root)
    if mapped is not None:
        assert src_root is not None
        normalized = _relative_posix(mapped, Path(src_root).resolve())
        if _has_suspect_part(normalized):
            return _SourcePathInfo(
                normalized_file=normalized,
                source_reachable=True,
                source_resolution_status="mapped_to_source_root",
                source_owned=False,
                source_ownership_status="generated_or_vendor",
            )
        return _SourcePathInfo(
            normalized_file=normalized,
            source_reachable=True,
            source_resolution_status="mapped_to_source_root",
            source_owned=True,
            source_ownership_status="project_owned",
        )

    if _has_suspect_part(raw_normalized):
        return _SourcePathInfo(
            normalized_file=raw_normalized,
            source_reachable=False,
            source_resolution_status=_unreachable_status(src_root),
            source_owned=False,
            source_ownership_status="generated_or_vendor",
        )
    if src_root is None:
        return _SourcePathInfo(
            normalized_file=raw_normalized,
            source_reachable=False,
            source_resolution_status="source_root_unavailable",
            source_owned=False,
            source_ownership_status="unknown",
        )
    return _SourcePathInfo(
        normalized_file=raw_normalized,
        source_reachable=False,
        source_resolution_status="source_mapping_unavailable",
        source_owned=False,
        source_ownership_status="unknown",
    )

def _mapped_source_path(file_value: str, src_root: str | Path | None) -> Path | None:
    if src_root is None:
        return None
    root = Path(src_root)
    if not root.is_dir():
        return None
    candidates = _resolve_candidate_paths(file_value, root)
    return candidates[0] if len(candidates) == 1 else None

def _resolve_candidate_paths(file_value: str, src_root: Path) -> list[Path]:
    root = src_root.resolve()
    requested = Path(file_value)
    if requested.is_absolute():
        candidate = requested.resolve()
        if candidate.is_file():
            try:
                candidate.relative_to(root)
            except ValueError:
                pass
            else:
                return [candidate]
        parts = requested.parts
        for start in range(1, len(parts)):
            candidates = _suffix_candidates(root, parts[start:])
            if candidates:
                return candidates
        return []
    return _suffix_candidates(root, requested.parts)

def _suffix_candidates(root: Path, requested_parts: tuple[str, ...]) -> list[Path]:
    if not requested_parts:
        return []
    basename = requested_parts[-1]
    candidates: list[Path] = []
    for path in _iter_files_by_basename(root, basename):
        try:
            relative_parts = path.relative_to(root).parts
        except ValueError:
            continue
        if len(relative_parts) >= len(requested_parts) and (
            relative_parts[-len(requested_parts) :] == requested_parts
        ):
            candidates.append(path)
    return sorted(candidates)

def _iter_files_by_basename(root: Path, basename: str) -> list[Path]:
    matches: list[Path] = []
    pending = [root]
    while pending:
        current = pending.pop()
        try:
            children = sorted(current.iterdir(), key=lambda item: item.name)
        except OSError:
            continue
        for child in children:
            if child.is_dir():
                if _should_skip_dir(child):
                    continue
                pending.append(child)
            elif child.is_file() and child.name == basename:
                matches.append(child)
    return matches

def _is_system_path(normalized_file: str) -> bool:
    return any(
        normalized_file == prefix or normalized_file.startswith(prefix + "/")
        for prefix in SYSTEM_PREFIXES
    )

def _has_suspect_part(normalized_file: str) -> bool:
    parts = [part.lower() for part in normalized_file.split("/") if part]
    return any(part in SUSPECT_PATH_PARTS for part in parts)

def _message_fingerprint(message: str) -> str:
    normalized = re.sub(r"\s+", " ", message.strip().lower())
    return hashlib.sha1(normalized.encode("utf-8", errors="replace")).hexdigest()[
        :MESSAGE_FINGERPRINT_LEN
    ]

def _candidate_counts(candidates: list[dict[str, Any]]) -> dict[str, int]:
    counts = {
        "type_probably_fixable": 0,
        "type_unknown": 0,
        "type_not_fixable": 0,
        "source_reachable": 0,
        "source_owned": 0,
        "patch_ready": 0,
    }
    for candidate in candidates:
        value = candidate.get("type_fixability")
        if value == "probably_fixable":
            counts["type_probably_fixable"] += 1
        elif value == "not_fixable":
            counts["type_not_fixable"] += 1
        else:
            counts["type_unknown"] += 1
        if candidate.get("source_reachable") is True:
            counts["source_reachable"] += 1
        if candidate.get("source_owned") is True:
            counts["source_owned"] += 1
        if (
            value == "probably_fixable"
            and candidate.get("source_reachable") is True
            and candidate.get("source_owned") is True
        ):
            counts["patch_ready"] += 1
    return counts

def _scan_as_dict(scan_result: ScanResult | dict[str, Any]) -> dict[str, Any]:
    if isinstance(scan_result, ScanResult):
        return scan_result.as_dict()
    return scan_result

def __init__(
        self,
        spec_path: str | Path,
        *,
        buildlog_path: str | Path | None = None,
        buildlog_text: str | None = None,
    ) -> None:
        self.spec_path = Path(spec_path)
        self.spec_text = self.spec_path.read_text(encoding="utf-8")
        self._logical_lines = _join_continuations(self.spec_text.splitlines())
        if buildlog_text is not None:
            self.buildlog_text = buildlog_text
        elif buildlog_path is not None:
            self.buildlog_text = Path(buildlog_path).read_text(encoding="utf-8")
        else:
            self.buildlog_text = ""

def find_spec_file(package: str, src_root: str | Path) -> Path:
        """Return the package spec path from a source root.

        Exact `<package>.spec` matches win. If there is only one spec file in the
        tree, it is accepted as a fallback. Ambiguous source roots raise a
        `ValueError` rather than guessing.
        """

        root = Path(src_root)
        if not root.exists():
            raise FileNotFoundError(f"src_root does not exist: {root}")

        specs = sorted(root.rglob("*.spec"))
        exact = [path for path in specs if path.name == f"{package}.spec"]
        if len(exact) == 1:
            return exact[0]
        if len(exact) > 1:
            raise ValueError(f"ambiguous spec files for package {package}: {exact}")
        if len(specs) == 1:
            return specs[0]
        if not specs:
            raise FileNotFoundError(f"no spec file found under {root}")
        raise ValueError(f"ambiguous spec files under {root}: {specs}")

def extract_patches(self) -> list[dict[str, Any]]:
        """Return Patch tags as raw spec declarations."""

        patches: list[dict[str, Any]] = []
        for tag, value in self._iter_tags("Patch"):
            patches.append(_tag_dict(tag, value))
        return patches

def extract_sources(self) -> list[dict[str, Any]]:
        """Return Source tags as raw spec declarations."""

        sources: list[dict[str, Any]] = []
        for tag, value in self._iter_tags("Source"):
            sources.append(_tag_dict(tag, value))
        return sources

def extract_section(self, name: str) -> str:
        """Return the body of the first matching spec section."""

        target = _normalize_section_name(name)
        lines = self.spec_text.splitlines()
        start: int | None = None
        for index, line in enumerate(lines):
            match = SECTION_RE.match(line)
            if match and match.group("name").lower() == target:
                start = index + 1
                break
        if start is None:
            return ""

        end = len(lines)
        for index in range(start, len(lines)):
            match = SECTION_RE.match(lines[index])
            if match and _is_top_level_section(match.group("name")):
                end = index
                break
        return "\n".join(lines[start:end]).strip("\n")

def extract_section_failure_context(self, phase: str) -> dict[str, str]:
        """Locate the last shell command and its output within a failed phase."""

        section_text = self.extract_section(phase)
        if not self.buildlog_text:
            return {
                "last_command": "",
                "last_command_output": "",
                "spec_section_text": section_text,
            }

        phase_lines = _phase_window(self.buildlog_text.splitlines(), _normalize_section_name(phase))
        command_index: int | None = None
        last_command = ""
        for index, line in enumerate(phase_lines):
            command_match = SHELL_COMMAND_RE.match(line)
            if not command_match or _phase_marker_match(line):
                continue
            command_index = index
            last_command = command_match.group("command")

        if command_index is None:
            output_lines: list[str] = []
        else:
            output_lines = []
            for line in phase_lines[command_index + 1 :]:
                if SHELL_COMMAND_RE.match(line):
                    break
                output_lines.append(line)

        return {
            "last_command": last_command,
            "last_command_output": "\n".join(output_lines).strip("\n"),
            "spec_section_text": section_text,
        }

def get_parse_status(self) -> dict[str, Any]:
        """Return v0.5 uncertainty markers for the minimal spec parser."""

        return {
            "macro_expanded": False,
            "condition_evaluated": False,
            "subpackage_resolved": False,
            "confidence": "partial",
            "warnings": self._collect_warnings(),
        }

def _iter_tags(self, prefix: str) -> list[tuple[str, str]]:
        matches: list[tuple[str, str]] = []
        for line in self._logical_lines:
            cleaned = _strip_comment(line)
            if not cleaned:
                continue
            match = TAG_RE.match(cleaned)
            if match and match.group("tag").lower().startswith(prefix.lower()):
                matches.append((match.group("tag"), match.group("value").strip()))
        return matches

def _collect_warnings(self) -> list[str]:
        warnings: list[str] = []
        if "%{" in self.spec_text:
            warnings.append("macros_present_not_expanded")
        if any(re.match(r"^\s*%if", line) for line in self.spec_text.splitlines()):
            warnings.append("conditionals_present_not_evaluated")
        if any(re.match(r"^\s*%package\b", line) for line in self.spec_text.splitlines()):
            warnings.append("subpackages_present_not_resolved")
        return warnings

def _join_continuations(lines: list[str]) -> list[str]:
    logical: list[str] = []
    current = ""
    for line in lines:
        stripped = line.rstrip()
        if stripped.endswith("\\"):
            current += stripped[:-1].rstrip() + " "
            continue
        logical.append((current + stripped).strip())
        current = ""
    if current:
        logical.append(current.strip())
    return logical

def _strip_comment(line: str) -> str:
    stripped = line.strip()
    if not stripped or stripped.startswith("#"):
        return ""
    return re.sub(r"\s+#.*$", "", stripped).strip()

def _tag_dict(tag: str, value: str) -> dict[str, Any]:
    suffix = tag.removeprefix("Patch").removeprefix("Source")
    index = int(suffix) if suffix.isdigit() else None
    return {"tag": tag, "index": index, "value": value}

def _phase_window(lines: list[str], phase: str) -> list[str]:
    start = 0
    for index, line in enumerate(lines):
        match = _phase_marker_match(line)
        if match and match.group("phase").lower() == phase:
            start = index + 1
            break
    else:
        return lines

    end = len(lines)
    for index in range(start, len(lines)):
        if _phase_marker_match(lines[index]):
            end = index
            break
    return lines[start:end]

def _phase_marker_match(line: str) -> re.Match[str] | None:
    match = PHASE_MARKER_RE.match(line)
    if match and _is_top_level_section(match.group("phase")):
        return match
    return None

def as_dict(self) -> dict[str, Any]:
        return {
            "ts": self.ts,
            "level": self.level,
            "layer": self.layer,
            "event": self.event,
            **self.fields,
        }

def close(self) -> None:
        if self._closed:
            return
        self._text_file.close()
        self._jsonl_file.close()
        self._closed = True

def _format_text_record(record: dict[str, Any]) -> str:
    base = f"{record['ts']} {record['level']} {record['layer']} {record['event']}"
    details = {
        key: value
        for key, value in record.items()
        if key not in {"ts", "level", "layer", "event"}
    }
    if not details:
        return base
    return f"{base} {json.dumps(details, ensure_ascii=False, sort_keys=True)}"

def setup_tracing(output_dir: Path | str, *, trace: bool = False) -> TraceLogger:
    """Create a trace logger using DEBUG level when ``trace`` is enabled."""

    return TraceLogger(output_dir, debug=trace)

def estimate_buildlog_tokens(size_bytes: int) -> int:
    """Use a deterministic size heuristic for large logs."""

    return max(1, int(size_bytes / 4))

def _evidence_section_tokens(packet: dict[str, Any], estimator: TokenEstimator) -> int:
    evidence = packet.get("evidence", {})
    if not isinstance(evidence, dict):
        return 1
    snippet_keys = {"source_snippet", "symbol_context", "failure_context", "fallback_context"}
    snippet_data = {
        key: value
        for key, value in evidence.items()
        if key in snippet_keys or key.endswith("_snippet")
    }
    return estimator.estimate_obj(snippet_data or evidence)

def _command_section_tokens(packet: dict[str, Any], estimator: TokenEstimator) -> int:
    evidence = packet.get("evidence", {})
    if not isinstance(evidence, dict):
        return 1
    command_data = {
        key: value
        for key, value in evidence.items()
        if key in {"command_summary", "link_command", "current_command_summary"}
    }
    return estimator.estimate_obj(command_data)

def _header_section_tokens(packet: dict[str, Any], estimator: TokenEstimator) -> int:
    evidence = packet.get("evidence", {})
    if not isinstance(evidence, dict):
        return 1
    return estimator.estimate_obj(evidence.get("header_declarations", []))

def _downgrade_reason(packet: dict[str, Any]) -> str | None:
    reasons = packet.get("degraded_reasons", [])
    if isinstance(reasons, list) and reasons:
        return str(reasons[0])
    return None

def _load_main() -> Callable[[list[str] | None], int]:
    try:
        from gbs_analyzer.analyze import main

        return main
    except ModuleNotFoundError as exc:
        if exc.name != "gbs_analyzer":
            raise

    scripts_dir = Path(__file__).resolve().parent
    sys.path.insert(0, str(scripts_dir))
    from gbs_analyzer.analyze import main

    return main

def run_analyzer_for_buildlog(
    buildlog_path: Path,
    *,
    output_dir: Path,
    src_root: Path | None = None,
    python_executable: str = sys.executable,
    subprocess_runner: SubprocessRunner = subprocess.run,
    extra_pythonpath: Sequence[str | Path] = (),
) -> AnalyzerRunResult:
    """Run analyzer CLI and return the generated evidence path."""

    if not buildlog_path.is_file():
        return AnalyzerRunResult(
            exit_code=3,
            output_dir=output_dir,
            evidence_path=output_dir / "evidence_packet.json",
            error=f"buildlog is not readable: {buildlog_path}",
        )

    output_dir.mkdir(parents=True, exist_ok=True)
    command = [
        python_executable,
        "-m",
        "gbs_analyzer",
        "analyze",
        str(buildlog_path),
        "--output-dir",
        str(output_dir),
    ]
    if src_root is not None:
        command.extend(["--src-root", str(src_root)])

    env = build_analyzer_subprocess_env(extra_pythonpath)
    kwargs: dict[str, object] = {"check": True, "text": True}
    if env is not None:
        kwargs["env"] = env

    try:
        subprocess_runner(command, **kwargs)
    except subprocess.CalledProcessError as exc:
        return AnalyzerRunResult(
            exit_code=1,
            output_dir=output_dir,
            evidence_path=output_dir / "evidence_packet.json",
            error=f"gbs_analyzer exited with {exc.returncode}",
        )

    evidence_path = output_dir / "evidence_packet.json"
    if not evidence_path.is_file():
        return AnalyzerRunResult(
            exit_code=3,
            output_dir=output_dir,
            evidence_path=evidence_path,
            error=f"gbs_analyzer did not write evidence_packet.json: {evidence_path}",
        )
    return AnalyzerRunResult(exit_code=0, output_dir=output_dir, evidence_path=evidence_path)

def discover_analyzer_pythonpath(*, launcher_path: Path | None = None) -> tuple[Path, ...]:
    """Return analyzer sibling scripts path when available for direct-folder usage."""

    env_path = _env_skill_scripts(ANALYZER_SKILL_ENV, ANALYZER_PACKAGE_DIR)
    if env_path is not None:
        return (env_path,)
    sibling_path = _sibling_skill_scripts(
        ANALYZER_SKILL_NAME,
        ANALYZER_PACKAGE_DIR,
        launcher_path=launcher_path,
    )
    if sibling_path is not None:
        return (sibling_path,)
    return ()

def _env_skill_scripts(env_name: str, package_dir: str) -> Path | None:
    raw = os.environ.get(env_name)
    if not raw:
        return None
    root = Path(raw).expanduser().resolve()
    candidates = [root / "scripts", root] if root.name != "scripts" else [root]
    for candidate in candidates:
        if (candidate / package_dir).is_dir():
            return candidate
    raise RuntimeError(f"{env_name} must point to a skill root or scripts directory")

def _sibling_skill_scripts(
    skill_name: str,
    package_dir: str,
    *,
    launcher_path: Path | None,
) -> Path | None:
    if launcher_path is None:
        return None
    skill_root = launcher_path.resolve().parents[1]
    candidate = skill_root.parent / skill_name / "scripts"
    if (candidate / package_dir).is_dir():
        return candidate
    return None

def _clean_mode_context_dirs(output_dir: Path) -> None:
    """Remove stale mode-specific generated context directories before writing output."""

    for name in MODE_CONTEXT_DIRS:
        path = output_dir / name
        if path.is_dir() and not path.is_symlink():
            shutil.rmtree(path)
        elif path.exists():
            path.unlink()

def ingest_large_scale_clusters(
    packet: dict[str, Any],
    *,
    evidence_path: Path,
) -> ClusterIngestResult:
    """Return large-scale source diagnostic clusters exposed by analyzer evidence."""

    summary = packet.get("error_clusters")
    if not isinstance(summary, dict):
        return ClusterIngestResult()

    selected_summaries = [
        cluster
        for cluster in _cluster_summaries(summary)
        if _is_large_scale_source_cluster(cluster)
    ]
    if not selected_summaries:
        return ClusterIngestResult()

    sidecar_ref = summary.get("full_locations_path")
    if not isinstance(sidecar_ref, str) or not sidecar_ref:
        return ClusterIngestResult(advisory="cluster_sidecar_unavailable: missing path")

    sidecar_path = evidence_path.parent / sidecar_ref
    try:
        sidecar = json.loads(sidecar_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return ClusterIngestResult(advisory=f"cluster_sidecar_unavailable: {exc}")

    if (
        not isinstance(sidecar, dict)
        or sidecar.get("schema_version") != ERROR_CLUSTER_LOCATIONS_SCHEMA
    ):
        return ClusterIngestResult(advisory="cluster_sidecar_unavailable: schema mismatch")

    sidecar_by_id = {
        str(cluster.get("id")): cluster
        for cluster in sidecar.get("clusters", [])
        if isinstance(cluster, dict) and cluster.get("id") is not None
    }
    clusters: list[LargeScaleCluster] = []
    for summary_cluster in selected_summaries:
        cluster_id = str(summary_cluster.get("id"))
        sidecar_cluster = sidecar_by_id.get(cluster_id)
        if not isinstance(sidecar_cluster, dict):
            continue
        locations = tuple(_parse_locations(sidecar_cluster.get("locations", [])))
        if not locations:
            continue
        clusters.append(
            LargeScaleCluster(
                id=cluster_id,
                warning_option=str(summary_cluster.get("warning_option") or ""),
                diagnostic_kinds=tuple(
                    str(kind)
                    for kind in summary_cluster.get("diagnostic_kinds", [])
                    if isinstance(kind, str)
                ),
                truncated=bool(summary.get("truncated")),
                locations=locations,
            )
        )

    if not clusters:
        return ClusterIngestResult(advisory="cluster_sidecar_unavailable: no usable locations")
    return ClusterIngestResult(clusters=tuple(clusters))

def _cluster_summaries(summary: dict[str, Any]) -> list[dict[str, Any]]:
    clusters = summary.get("clusters")
    if not isinstance(clusters, list):
        return []
    return [cluster for cluster in clusters if isinstance(cluster, dict)]

def _is_large_scale_source_cluster(cluster: dict[str, Any]) -> bool:
    if not cluster.get("large_scale"):
        return False
    if cluster.get("kind") != "source_warning_option":
        return False
    diagnostic_kinds = cluster.get("diagnostic_kinds")
    if not isinstance(diagnostic_kinds, list) or not diagnostic_kinds:
        return False
    kinds = {kind for kind in diagnostic_kinds if isinstance(kind, str)}
    return bool(kinds) and kinds.issubset(SOURCE_DIAGNOSTIC_KINDS)

def _parse_locations(raw_locations: object) -> list[ClusterLocation]:
    if not isinstance(raw_locations, list):
        return []
    locations: list[ClusterLocation] = []
    for raw in raw_locations:
        if not isinstance(raw, dict):
            continue
        file = raw.get("file")
        line = raw.get("line")
        if not isinstance(file, str) or not file or not isinstance(line, int) or line <= 0:
            continue
        locations.append(
            ClusterLocation(
                event_id=_optional_str(raw.get("event_id")),
                kind=_optional_str(raw.get("kind")),
                file=file,
                line=line,
                column=raw.get("column") if isinstance(raw.get("column"), int) else None,
                line_no=raw.get("line_no") if isinstance(raw.get("line_no"), int) else None,
                message=str(raw.get("message") or ""),
            )
        )
    return locations

def render_cluster_meta(
    cluster_outputs: list[dict[str, Any]],
    *,
    readme_path: Path,
    context_path: Path,
    meta_path: Path,
    evidence_path: Path | None,
    buildlog_path: Path | None,
    cluster_context_dir: Path,
) -> dict[str, Any]:
    """Render machine-readable metadata for cluster mode."""

    return {
        "schema_version": "gbs_patch_suggest/meta/v1",
        "mode": "cluster",
        "status": "cluster_context_available",
        "outputs": {
            "readme_md": str(readme_path),
            "context_md": str(context_path),
            "meta_json": str(meta_path),
            "cluster_context_dir": str(cluster_context_dir),
        },
        "inputs": {
            "evidence_json": None if evidence_path is None else str(evidence_path),
            "buildlog": None if buildlog_path is None else str(buildlog_path),
        },
        "clusters": [
            {
                "id": output["cluster"].id,
                "warning_option": output["cluster"].warning_option,
                "diagnostic_kinds": list(output["cluster"].diagnostic_kinds),
                "truncated": output["cluster"].truncated,
                "index_md": str(output["index_path"]),
                "files": [
                    {
                        "file": file_output["context"].file,
                        "status": file_output["context"].status,
                        "location_count": len(file_output["context"].locations),
                        "context_md": str(file_output["path"]),
                        "edit_spec_json": None
                        if file_output["edit_spec_path"] is None
                        else str(file_output["edit_spec_path"]),
                        "source_windows_truncated": file_output[
                            "context"
                        ].source_windows_truncated,
                        "missing_line_text": [
                            {
                                "line": location.line,
                                "column": location.column,
                                "message": location.message,
                            }
                            for location in file_output[
                                "context"
                            ].missing_line_text_locations
                        ],
                        "suppressed_skeleton": [
                            {
                                "line": item.location.line,
                                "column": item.location.column,
                                "message": item.location.message,
                                "reason": item.reason,
                            }
                            for item in file_output[
                                "context"
                            ].suppressed_skeleton_locations
                        ],
                    }
                    for file_output in output["file_outputs"]
                ],
            }
            for output in cluster_outputs
        ],
    }

def _write_edit_spec_skeleton(
    cluster: ResolvedCluster,
    file_context: ClusterFileContext,
    *,
    edit_specs_dir: Path,
) -> Path | None:
    if not file_context.skeleton_edits:
        return None
    path = edit_specs_dir / _edit_spec_name(cluster, file_context)
    data = {
        "schema_version": EDIT_SPEC_SCHEMA,
        "patch_name": _patch_name(cluster, file_context),
        "description": "Fill new values for all listed source diagnostics in this file.",
        "edits": [
            {
                "file": edit.file,
                "line": edit.line,
                "old": edit.old,
                "new": FILL_REPLACEMENT_LINE,
            }
            for edit in file_context.skeleton_edits
        ],
    }
    path.write_text(
        json.dumps(data, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    return path

def _relative(path: Path, root: Path) -> str:
    try:
        return path.relative_to(root).as_posix()
    except ValueError:
        return path.as_posix()

def _group_locations_by_file(
    locations: tuple[ClusterLocation, ...],
) -> dict[str, tuple[ClusterLocation, ...]]:
    grouped: dict[str, list[ClusterLocation]] = {}
    for location in locations:
        grouped.setdefault(location.file, []).append(location)
    return {file: tuple(file_locations) for file, file_locations in grouped.items()}

def _skeleton_edits(
    file: str,
    lines: list[str],
    locations: tuple[ClusterLocation, ...],
) -> tuple[
    tuple[SkeletonEdit, ...],
    tuple[ClusterLocation, ...],
    tuple[SuppressedSkeletonLocation, ...],
]:
    grouped: dict[int, list[ClusterLocation]] = {}
    missing: list[ClusterLocation] = []
    for location in locations:
        if 1 <= location.line <= len(lines):
            grouped.setdefault(location.line, []).append(location)
        else:
            missing.append(location)

    edits: list[SkeletonEdit] = []
    suppressed: list[SuppressedSkeletonLocation] = []
    for line, line_locations in sorted(grouped.items()):
        old = lines[line - 1]
        reasons = {
            reason
            for location in line_locations
            if (reason := should_suppress_skeleton(old, location.message)) is not None
        }
        if reasons:
            reason = (
                "structural_closing_line"
                if "structural_closing_line" in reasons
                else "no_message_symbol_in_line"
            )
            suppressed.extend(
                SuppressedSkeletonLocation(location=location, reason=reason)
                for location in line_locations
            )
            continue
        edits.append(
            SkeletonEdit(
                file=file,
                line=line,
                old=old,
                covered_locations=tuple(line_locations),
            )
        )
    return tuple(edits), tuple(missing), tuple(suppressed)

def patch_ready(self) -> bool:
        return (
            self.type_fixability == "probably_fixable"
            and self.source_reachable
            and self.source_owned
        )

def not_patch_ready_reason(self) -> str | None:
        if self.patch_ready:
            return None
        if self.type_fixability != "probably_fixable":
            return f"type_fixability:{self.type_fixability}"
        if not self.source_reachable:
            return f"source_reachable:{self.source_resolution_status}"
        if not self.source_owned:
            return f"source_owned:{self.source_ownership_status}"
        return "not_patch_ready"

def ingest_source_candidates(
    packet: dict[str, Any],
    *,
    evidence_path: Path,
) -> FixAllIngestResult:
    """Load analyzer source_candidates sidecar if the packet exposes it."""

    summary = packet.get("source_candidates")
    if not isinstance(summary, dict):
        return FixAllIngestResult(advisory="source_candidates_unavailable: missing summary")
    if summary.get("schema_version") != SOURCE_CANDIDATE_SUMMARY_SCHEMA:
        return FixAllIngestResult(advisory="source_candidates_unavailable: summary schema mismatch")

    sidecar_ref = summary.get("full_candidates_path")
    if not isinstance(sidecar_ref, str) or not sidecar_ref:
        return FixAllIngestResult(advisory="source_candidates_unavailable: missing path")
    sidecar_path = evidence_path.parent / sidecar_ref
    try:
        sidecar = json.loads(sidecar_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return FixAllIngestResult(advisory=f"source_candidates_unavailable: {exc}")

    if (
        not isinstance(sidecar, dict)
        or sidecar.get("schema_version") != SOURCE_CANDIDATE_SIDECAR_SCHEMA
    ):
        return FixAllIngestResult(advisory="source_candidates_unavailable: sidecar schema mismatch")

    candidates = tuple(_parse_candidates(sidecar.get("candidates", [])))
    if not candidates:
        return FixAllIngestResult(advisory="source_candidates_unavailable: no main candidates")
    return FixAllIngestResult(candidates=candidates)

def _parse_candidates(raw_candidates: object) -> list[SourceCandidateDiagnostic]:
    if not isinstance(raw_candidates, list):
        return []
    candidates: list[SourceCandidateDiagnostic] = []
    for raw in raw_candidates:
        if not isinstance(raw, dict):
            continue
        parsed = _parse_candidate(len(candidates) + 1, raw)
        if parsed is not None:
            candidates.append(parsed)
    return candidates

def _write_edit_spec_skeleton(
    file_context: ClusterFileContext,
    *,
    edit_specs_dir: Path,
) -> Path | None:
    if not file_context.skeleton_edits:
        return None
    path = edit_specs_dir / _edit_spec_name(file_context)
    data = {
        "schema_version": EDIT_SPEC_SCHEMA,
        "patch_name": _patch_name(file_context),
        "description": "Fill new values for all patch-ready source candidates in this file.",
        "edits": [
            {
                "file": edit.file,
                "line": edit.line,
                "old": edit.old,
                "new": FILL_REPLACEMENT_LINE,
            }
            for edit in file_context.skeleton_edits
        ],
    }
    path.write_text(
        json.dumps(data, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    return path

def _relative(path: Path, root: Path) -> str:
    try:
        return path.relative_to(root).as_posix()
    except ValueError:
        return path.as_posix()

def resolve_fix_all(
    ingest: FixAllIngestResult,
    *,
    src_root: Path | None,
) -> ResolvedFixAllContext:
    """Resolve patch-ready source candidates into per-file contexts."""

    patch_ready = ingest.patch_ready_candidates
    if not patch_ready:
        return ResolvedFixAllContext(
            candidates=ingest.candidates,
            patch_ready_candidates=(),
            file_contexts=(),
        )

    cluster = LargeScaleCluster(
        id=FIX_ALL_CLUSTER_ID,
        warning_option="source_candidates",
        diagnostic_kinds=tuple(
            sorted({candidate.kind for candidate in patch_ready if candidate.kind})
        ),
        truncated=False,
        locations=tuple(candidate.as_location() for candidate in patch_ready),
    )
    resolved = resolve_clusters((cluster,), src_root=src_root)
    file_contexts = resolved[0].file_contexts if resolved else ()
    return ResolvedFixAllContext(
        candidates=ingest.candidates,
        patch_ready_candidates=patch_ready,
        file_contexts=file_contexts,
    )

def format_patch(
    options: FormatPatchOptions,
    *,
    subprocess_runner: SubprocessRunner = subprocess.run,
) -> FormatPatchResult:
    """Format an explicit edit spec into a git-apply-compatible patch."""

    try:
        spec = load_edit_spec(options.edit_spec)
        patch_text = build_patch_text(
            spec,
            src_root=options.src_root,
            git_binary=options.git_binary,
            temp_parent=options.temp_parent,
            subprocess_runner=subprocess_runner,
        )
        if options.check:
            _run_git_apply_check(
                patch_text,
                src_root=options.src_root,
                git_binary=options.git_binary,
                subprocess_runner=subprocess_runner,
            )
        options.output.parent.mkdir(parents=True, exist_ok=True)
        options.output.write_text(patch_text, encoding="utf-8")
    except FormatterError as exc:
        return FormatPatchResult(
            exit_code=EXIT_FORMATTER_ERROR,
            output_path=options.output,
            error=exc.message,
            error_code=exc.code,
        )
    except OSError as exc:
        return FormatPatchResult(
            exit_code=EXIT_FORMATTER_ERROR,
            output_path=options.output,
            error=str(exc),
            error_code="io_error",
        )

    return FormatPatchResult(
        exit_code=EXIT_SUCCESS,
        output_path=options.output,
        check_passed=options.check,
    )

def load_edit_spec(path: Path) -> EditSpec:
    """Load and validate an edit spec JSON file."""

    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise FormatterError("invalid_json", f"edit spec is not valid JSON: {exc}") from exc
    if not isinstance(data, dict):
        raise FormatterError("invalid_schema", "edit spec root must be an object")

    schema_version = _required_str(data, "schema_version")
    if schema_version != EDIT_SPEC_SCHEMA:
        raise FormatterError(
            "unsupported_schema",
            f"unsupported edit spec schema: {schema_version}",
        )
    raw_edits = data.get("edits")
    if not isinstance(raw_edits, list) or not raw_edits:
        raise FormatterError("missing_edits", "edit spec must contain at least one edit")

    edits = tuple(_parse_edit(raw_edit, index) for index, raw_edit in enumerate(raw_edits, start=1))
    return EditSpec(
        schema_version=schema_version,
        patch_name=_optional_str(data, "patch_name"),
        description=_optional_str(data, "description"),
        edits=edits,
    )

def _parse_edit(raw: object, index: int) -> Edit:
    if not isinstance(raw, dict):
        raise FormatterError("invalid_edit", f"edit #{index} must be an object")
    file = _required_str(raw, "file")
    operation = _optional_str(raw, "operation") or "replace"
    line = raw.get("line")
    if line is not None and (not isinstance(line, int) or line <= 0):
        raise FormatterError("invalid_line", f"edit #{index} line must be a positive integer")
    if operation == "replace":
        old = _required_str(raw, "old")
        if old == "":
            raise FormatterError("empty_old", f"edit #{index} old text must not be empty")
        new = _required_str(raw, "new")
        return Edit(
            file=file,
            operation=operation,
            old=old,
            new=new,
            line=line,
            before=_optional_str(raw, "before"),
            after=_optional_str(raw, "after"),
        )
    if operation == "insert_after":
        if line is None:
            raise FormatterError(
                "missing_line",
                f"edit #{index} insert_after requires a positive line",
            )
        anchor = _required_str(raw, "anchor")
        if anchor == "":
            raise FormatterError("empty_anchor", f"edit #{index} anchor must not be empty")
        insert = _required_str(raw, "insert")
        if insert == "":
            raise FormatterError("empty_insert", f"edit #{index} insert must not be empty")
        return Edit(
            file=file,
            operation=operation,
            line=line,
            anchor=anchor,
            insert=insert,
        )
    raise FormatterError("unsupported_operation", f"unsupported edit operation: {operation}")

def _required_str(data: dict[str, object], key: str) -> str:
    value = data.get(key)
    if not isinstance(value, str):
        raise FormatterError("invalid_schema", f"{key} must be a string")
    return value

def _optional_str(data: dict[str, object], key: str) -> str | None:
    value = data.get(key)
    if value is None:
        return None
    if not isinstance(value, str):
        raise FormatterError("invalid_schema", f"{key} must be a string")
    return value

def _resolve_src_root(src_root: Path) -> Path:
    resolved = src_root.resolve()
    if not resolved.is_dir():
        raise FormatterError("src_root_not_found", f"src-root is not a directory: {src_root}")
    return resolved

def _resolve_edits(
    edits: tuple[Edit, ...],
    src_root: Path,
) -> dict[Path, tuple[_ResolvedEdit, ...]]:
    grouped: dict[Path, list[_ResolvedEdit]] = defaultdict(list)
    for edit in edits:
        source_path, relative_path = _resolve_source_path(edit.file, src_root)
        grouped[relative_path].append(
            _ResolvedEdit(
                edit=edit,
                source_path=source_path,
                relative_path=relative_path,
                start=-1,
                end=-1,
            )
        )
    return {path: tuple(path_edits) for path, path_edits in grouped.items()}

def _resolve_source_path(file_name: str, src_root: Path) -> tuple[Path, Path]:
    raw_path = Path(file_name)
    candidate = raw_path.resolve() if raw_path.is_absolute() else (src_root / raw_path).resolve()
    try:
        relative_path = candidate.relative_to(src_root)
    except ValueError as exc:
        raise FormatterError(
            "file_outside_src_root",
            f"edit file escapes src-root: {file_name}",
        ) from exc
    if not candidate.is_file():
        raise FormatterError("file_not_found", f"edit file is not readable: {file_name}")
    if not relative_path.parts:
        raise FormatterError("invalid_file", f"edit file is invalid: {file_name}")
    return candidate, relative_path

def _locate_file_edits(
    original_text: str,
    edits: tuple[_ResolvedEdit, ...],
) -> tuple[_ResolvedEdit, ...]:
    located: list[_ResolvedEdit] = []
    for resolved_edit in edits:
        match = _locate_edit(original_text, resolved_edit.edit)
        located.append(
            _ResolvedEdit(
                edit=resolved_edit.edit,
                source_path=resolved_edit.source_path,
                relative_path=resolved_edit.relative_path,
                start=match.start,
                end=match.end,
            )
        )
    _ensure_non_overlapping(located)
    return tuple(located)

def _locate_edit(text: str, edit: Edit) -> _Match:
    if edit.operation == "insert_after":
        return _locate_insert_after(text, edit)
    assert edit.old is not None
    if edit.before is not None or edit.after is not None:
        before = edit.before or ""
        after = edit.after or ""
        anchor = f"{before}{edit.old}{after}"
        matches = _find_matches(text, anchor, offset=len(before), old_length=len(edit.old))
        if not matches:
            raise FormatterError(
                "context_not_found",
                f"context anchor did not match for {edit.file}",
            )
        if len(matches) > 1:
            raise FormatterError(
                "context_not_unique",
                f"context anchor matched multiple locations for {edit.file}: "
                f"{_candidate_lines(matches)}",
            )
        return matches[0]

    matches = _find_matches(text, edit.old)
    if not matches:
        raise FormatterError("old_not_found", f"old text did not match for {edit.file}")
    if len(matches) == 1:
        return matches[0]
    if edit.line is None:
        raise FormatterError(
            "old_not_unique",
            f"old text matched multiple locations for {edit.file}: {_candidate_lines(matches)}",
        )
    return _disambiguate_by_line(edit, matches)

def _disambiguate_by_line(edit: Edit, matches: list[_Match]) -> _Match:
    assert edit.line is not None
    covering = [
        match for match in matches if match.start_line <= edit.line <= match.end_line
    ]
    if len(covering) == 1:
        return covering[0]
    if len(covering) > 1:
        raise FormatterError(
            "old_not_unique",
            f"old text matched multiple locations covering line {edit.line} for {edit.file}: "
            f"{_candidate_lines(covering)}",
        )

    nearest_distance = min(abs(match.start_line - edit.line) for match in matches)
    nearest = [
        match for match in matches if abs(match.start_line - edit.line) == nearest_distance
    ]
    if len(nearest) == 1:
        return nearest[0]
    raise FormatterError(
        "old_not_unique",
        f"old text matched multiple equally near locations for {edit.file}: "
        f"{_candidate_lines(nearest)}",
    )

def _locate_insert_after(text: str, edit: Edit) -> _Match:
    assert edit.line is not None
    assert edit.anchor is not None
    lines = text.splitlines(keepends=True)
    if edit.line > len(lines):
        raise FormatterError(
            "insert_out_of_range",
            f"insert_after line {edit.line} is outside {edit.file}",
        )
    line_text = lines[edit.line - 1].removesuffix("\n").removesuffix("\r")
    if line_text != edit.anchor:
        raise FormatterError(
            "anchor_not_found",
            f"insert_after anchor did not match line {edit.line} for {edit.file}",
        )
    end = sum(len(line) for line in lines[: edit.line])
    return _Match(start=end, end=end, start_line=edit.line + 1, end_line=edit.line + 1)

def _ensure_non_overlapping(edits: list[_ResolvedEdit]) -> None:
    sorted_edits = sorted(edits, key=lambda item: item.start)
    previous: _ResolvedEdit | None = None
    for current in sorted_edits:
        if previous is not None and previous.end > current.start:
            raise FormatterError(
                "overlapping_edits",
                f"edits overlap in {current.relative_path.as_posix()}",
            )
        previous = current

def _apply_resolved_edits(text: str, edits: tuple[_ResolvedEdit, ...]) -> str:
    modified = text
    for resolved_edit in sorted(edits, key=lambda item: item.start, reverse=True):
        replacement = _replacement_text(resolved_edit.edit)
        modified = (
            modified[: resolved_edit.start]
            + replacement
            + modified[resolved_edit.end :]
        )
    return modified

def _replacement_text(edit: Edit) -> str:
    if edit.operation == "insert_after":
        assert edit.insert is not None
        return edit.insert if edit.insert.endswith("\n") else edit.insert + "\n"
    assert edit.new is not None
    return edit.new

def _run_git_diff_no_index(
    orig_file: Path,
    mod_file: Path,
    *,
    relative_path: Path,
    git_binary: str,
    subprocess_runner: SubprocessRunner,
) -> str:
    try:
        completed = subprocess_runner(
            [git_binary, "diff", "--no-index", "--", str(orig_file), str(mod_file)],
            check=False,
            capture_output=True,
            text=True,
        )
    except FileNotFoundError as exc:
        raise FormatterError("git_not_found", f"git command not found: {git_binary}") from exc
    if completed.returncode not in (0, 1):
        raise FormatterError(
            "git_diff_failed",
            f"git diff --no-index failed: {completed.stderr.strip()}",
        )
    if completed.returncode == 0:
        return ""
    if not completed.stdout:
        raise FormatterError("git_diff_failed", "git diff --no-index produced no output")
    return _rewrite_diff_headers(completed.stdout, relative_path)

def _rewrite_diff_headers(diff_text: str, relative_path: Path) -> str:
    rel = relative_path.as_posix()
    rewritten: list[str] = []
    for line in diff_text.splitlines():
        if line.startswith("diff --git "):
            rewritten.append(f"diff --git a/{rel} b/{rel}")
        elif line.startswith("--- "):
            rewritten.append(f"--- a/{rel}")
        elif line.startswith("+++ "):
            rewritten.append(f"+++ b/{rel}")
        else:
            rewritten.append(line)
    return "\n".join(rewritten) + "\n"

def _run_git_apply_check(
    patch_text: str,
    *,
    src_root: Path,
    git_binary: str,
    subprocess_runner: SubprocessRunner,
) -> None:
    try:
        completed = subprocess_runner(
            [git_binary, "-C", str(src_root), "apply", "--check", "-"],
            input=patch_text,
            check=False,
            capture_output=True,
            text=True,
        )
    except FileNotFoundError as exc:
        raise FormatterError("git_not_found", f"git command not found: {git_binary}") from exc
    if completed.returncode != 0:
        raise FormatterError(
            "git_apply_check_failed",
            f"git apply --check failed: {completed.stderr.strip()}",
        )

def extract_first_diagnostic(packet: dict[str, Any]) -> CompileErrorEvidence:
    """Extract the primary analyzer diagnostic and semantic class."""

    primary = packet.get("primary_error")
    if not isinstance(primary, dict):
        primary = {}

    evidence = packet.get("evidence")
    if not isinstance(evidence, dict):
        evidence = {}
    source_snippet = evidence.get("source_snippet")
    if not isinstance(source_snippet, dict):
        source_snippet = None

    return CompileErrorEvidence(
        kind=_string(primary.get("kind"), default="unknown"),
        message=_string(primary.get("message"), default=""),
        semantic_class=_semantic_class(packet, primary),
        file=_optional_string(primary.get("file")),
        line=_optional_int(primary.get("line")),
        column=_optional_int(primary.get("column")),
        source_snippet=source_snippet,
        raw_primary_error=primary,
    )

def _semantic_class(packet: dict[str, Any], primary: dict[str, Any]) -> str:
    direct = primary.get("semantic_class") or primary.get("category")
    if direct:
        return str(direct)
    candidates = packet.get("root_cause_candidates")
    if isinstance(candidates, list) and candidates:
        first = candidates[0]
        if isinstance(first, dict) and first.get("semantic_class"):
            return str(first["semantic_class"])
    return "unknown"

def ingest_terminal_source_candidates(packet: dict[str, Any]) -> MultiCandidateIngestResult:
    """Select independent terminal compiler/Werror candidates from analyzer evidence."""

    raw_candidates = packet.get("root_cause_candidates")
    if not isinstance(raw_candidates, list):
        return MultiCandidateIngestResult()

    eligible: list[MultiCandidateDiagnostic] = []
    skipped: list[SkippedCandidate] = []
    for raw in raw_candidates:
        if not isinstance(raw, dict):
            continue
        reason = _skip_reason(raw)
        if reason is not None:
            skipped.append(_skipped(raw, reason))
            continue
        eligible.append(_diagnostic(len(eligible) + 1, raw, packet))

    if len(eligible) < 2:
        return MultiCandidateIngestResult(skipped=tuple(skipped))
    return MultiCandidateIngestResult(
        candidates=tuple(eligible),
        skipped=tuple(skipped),
    )

def _skip_reason(candidate: dict[str, Any]) -> str | None:
    if candidate.get("is_terminal") is not True:
        return "not_terminal_cascade"
    kind = candidate.get("kind")
    if kind not in SOURCE_DIAGNOSTIC_KINDS:
        return "not_source_diagnostic"
    file_value = candidate.get("file")
    message = candidate.get("message")
    line = candidate.get("line")
    if not isinstance(file_value, str) or not file_value:
        return "missing_file"
    if not isinstance(line, int) or line <= 0:
        return "missing_line"
    if not isinstance(message, str) or not message:
        return "missing_message"
    return None

def _skipped(candidate: dict[str, Any], reason: str) -> SkippedCandidate:
    return SkippedCandidate(
        event_id=str(candidate["event_id"]) if candidate.get("event_id") is not None else None,
        kind=str(candidate["kind"]) if candidate.get("kind") is not None else None,
        rank=_optional_int(candidate.get("rank")),
        reason=reason,
        summary=str(candidate["summary"]) if isinstance(candidate.get("summary"), str) else None,
    )

def _write_edit_spec_skeleton(
    candidate: ResolvedCandidateContext,
    *,
    edit_specs_dir: Path,
) -> tuple[Path | None, bool, str | None]:
    source = candidate.resolved.source_context
    evidence = candidate.resolved.evidence
    if source is None or evidence.file is None or evidence.line is None:
        return None, False, None
    line_text = _line_text(source.text, source.start_line, evidence.line)
    if line_text is None:
        return None, True, None
    suppressed_reason = should_suppress_skeleton(line_text, evidence.message)
    if suppressed_reason is not None:
        return None, False, suppressed_reason
    path = edit_specs_dir / _edit_spec_name(candidate.diagnostic)
    data = {
        "schema_version": EDIT_SPEC_SCHEMA,
        "patch_name": _patch_name(candidate.diagnostic),
        "description": "Fill new for this independent source diagnostic.",
        "edits": [
            {
                "file": evidence.file,
                "line": evidence.line,
                "old": line_text,
                "new": FILL_REPLACEMENT_LINE,
            }
        ],
    }
    path.write_text(
        json.dumps(data, ensure_ascii=False, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    return path, False, None

def _line_text(text: str, start_line: int, target_line: int) -> str | None:
    index = target_line - start_line
    if index < 0:
        return None
    lines = text.splitlines()
    if index >= len(lines):
        return None
    return lines[index]

def _file_slug(file_value: str | None) -> str:
    if not file_value:
        return "unknown"
    return _slug(Path(file_value).name)

def _location(file: str | None, line: int | None, column: int | None) -> str:
    if not file:
        return "n/a"
    if line is None:
        return file
    if column is None:
        return f"{file}:{line}"
    return f"{file}:{line}:{column}"

def _relative(path: Path, root: Path) -> str:
    try:
        return path.relative_to(root).as_posix()
    except ValueError:
        return path.as_posix()

def _location(file: str | None, line: int | None, column: int | None) -> str:
    if not file:
        return "n/a"
    if line is None:
        return file
    if column is None:
        return f"{file}:{line}"
    return f"{file}:{line}:{column}"

def _patch_guidance_not_applicable() -> str:
    return "\n".join(
        [
            "## How to proceed",
            "",
            "This skill only prepares patch context for compiler and Werror source "
            "diagnostics. Use the workflow suggester for this fault class instead of "
            "generating a source patch here.",
        ]
    )

def resolve_context(
    evidence: CompileErrorEvidence,
    *,
    src_root: Path | None = None,
    window: int = DEFAULT_CONTEXT_WINDOW,
) -> ResolvedContext:
    """Resolve A/B/C source context levels without failing on missing source."""

    if not evidence.is_source_diagnostic:
        return ResolvedContext(
            status="not_applicable",
            level="not_applicable",
            evidence=evidence,
            advisory=(
                f"primary_error.kind is `{evidence.kind}`, so this skill is not applicable. "
                "This skill only prepares patch context for compiler and Werror source "
                "diagnostics. Use the workflow suggester for this fault class."
            ),
        )

    if evidence.source_snippet is not None:
        return ResolvedContext(
            status="source_context_available",
            level="A",
            evidence=evidence,
            source_context=_context_from_evidence(evidence.source_snippet),
        )

    if evidence.file and evidence.line:
        candidate_paths = resolve_candidate_paths(evidence.file, src_root)
        if len(candidate_paths) == 1:
            return ResolvedContext(
                status="source_context_available",
                level="A",
                evidence=evidence,
                source_context=_context_from_file(
                    candidate_paths[0],
                    evidence.line,
                    window=window,
                ),
            )
        if len(candidate_paths) > 1:
            return ResolvedContext(
                status="source_context_ambiguous",
                level="B",
                evidence=evidence,
                advisory=(
                    f"Multiple source files match `{evidence.file}` under the provided "
                    "source root. Ask the outer assistant or user to disambiguate before "
                    "generating a patch."
                ),
                candidates=tuple(str(path) for path in candidate_paths[:10]),
            )
        return ResolvedContext(
            status="source_context_unavailable",
            level="B",
            evidence=evidence,
            advisory=(
                f"Source context for `{evidence.file}:{evidence.line}` is unavailable to "
                "this skill. Ask the outer assistant to open that file and inspect the "
                "reported line before generating a patch."
            ),
        )

    return ResolvedContext(
        status="diagnostic_only",
        level="C",
        evidence=evidence,
        advisory=(
            "The source diagnostic has no usable file and line number. Provide only "
            "diagnostic context; do not guess a source patch without inspecting the tree."
        ),
    )

def resolve_candidate_paths(file_value: str, src_root: Path | None) -> list[Path]:
    """Return source candidates inside src_root using path-segment suffix matching."""

    if src_root is None or not src_root.is_dir():
        return []
    root = src_root.resolve()
    requested = Path(file_value)
    if requested.is_absolute():
        return _absolute_candidate(requested, root)

    requested_parts = _strip_leading_dot_segments(requested.parts)
    if not requested_parts:
        return []
    return _suffix_candidates(root, requested_parts)

def _strip_leading_dot_segments(parts: tuple[str, ...]) -> tuple[str, ...]:
    index = 0
    while index < len(parts) and parts[index] in {".", ".."}:
        index += 1
    return parts[index:]

def _suffix_candidates(root: Path, requested_parts: tuple[str, ...]) -> list[Path]:
    if not requested_parts:
        return []
    basename = requested_parts[-1]
    candidates: list[Path] = []
    for path in _iter_files_by_basename(root, basename):
        try:
            relative_parts = path.relative_to(root).parts
        except ValueError:
            continue
        if len(relative_parts) >= len(requested_parts) and (
            relative_parts[-len(requested_parts) :] == requested_parts
        ):
            candidates.append(path)
    return sorted(candidates)

def _context_from_evidence(snippet: dict[str, Any]) -> SourceContext:
    return SourceContext(
        path=str(snippet.get("path", "")),
        start_line=_int_or_default(snippet.get("start_line"), 1),
        end_line=_int_or_default(snippet.get("end_line"), 1),
        text=str(snippet.get("text", "")),
        origin="evidence",
    )

def _context_from_file(path: Path, line: int, *, window: int) -> SourceContext:
    lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    start = max(1, line - window)
    end = min(len(lines), line + window)
    return SourceContext(
        path=str(path),
        start_line=start,
        end_line=end,
        text="\n".join(lines[start - 1 : end]),
        origin="src_root_suffix_search",
    )

def _absolute_candidate(path: Path, root: Path) -> list[Path]:
    if _is_system_absolute_path(path):
        return []

    candidate = path.resolve()
    if candidate.is_file():
        try:
            candidate.relative_to(root)
        except ValueError:
            pass
        else:
            return [candidate]

    parts = path.parts
    for start in range(1, len(parts)):
        suffix = parts[start:]
        candidates = _suffix_candidates(root, suffix)
        if candidates:
            return candidates
    return []

def _is_system_absolute_path(path: Path) -> bool:
    parts = path.parts
    return any(parts[: len(prefix)] == prefix for prefix in SYSTEM_ABSOLUTE_PREFIXES)

def _iter_files_by_basename(root: Path, basename: str) -> list[Path]:
    matches: list[Path] = []
    pending = [root]
    while pending:
        current = pending.pop()
        try:
            children = sorted(current.iterdir(), key=lambda item: item.name)
        except OSError:
            continue
        for child in children:
            if child.is_dir():
                if _should_skip_dir(child):
                    continue
                pending.append(child)
            elif child.is_file() and child.name == basename:
                matches.append(child)
    return matches

def should_suppress_skeleton(old: str, message: str) -> str | None:
    """Return why an edit-spec skeleton row would be misleading, if known."""

    old_compact = "".join(old.strip().split())
    if old_compact in STRUCTURAL_ONLY_LINE_COMPACTS:
        return "structural_closing_line"

    tokens = tuple(_source_like_message_tokens(message))
    if tokens and not any(token in old for token in tokens):
        return "no_message_symbol_in_line"
    return None

def _source_like_message_tokens(message: str) -> tuple[str, ...]:
    tokens: list[str] = []
    for token in IDENTIFIER_RE.findall(message):
        if token in MESSAGE_TOKEN_STOPWORDS:
            continue
        if token.startswith("W"):
            continue
        if _looks_like_source_symbol(token):
            tokens.append(token)
    return tuple(dict.fromkeys(tokens))

def _looks_like_source_symbol(token: str) -> bool:
    # Conservative on purpose: lowercase words are often prose, so B/advisory covers them.
    return "_" in token or any(char.isupper() for char in token)

def ingest_spec_toolchain_flags(packet: dict[str, Any]) -> SpecToolchainFlagDiagnostic:
    """Return unknown warning options visible in analyzer evidence."""

    messages = tuple(_iter_candidate_messages(packet))
    options: list[str] = []
    seen: set[str] = set()
    for message in messages:
        if WARNING_OPTION_MARKER not in message and "unknown warning option" not in message:
            continue
        for match in UNKNOWN_WARNING_RE.finditer(message):
            option = match.group("option")
            if option not in seen:
                seen.add(option)
                options.append(option)
    return SpecToolchainFlagDiagnostic(options=tuple(options), messages=messages)

def _iter_candidate_messages(packet: dict[str, Any]) -> list[str]:
    messages: list[str] = []
    primary = packet.get("primary_error")
    if isinstance(primary, dict):
        message = primary.get("message")
        if isinstance(message, str):
            messages.append(message)
    candidates = packet.get("root_cause_candidates")
    if isinstance(candidates, list):
        for candidate in candidates:
            if not isinstance(candidate, dict):
                continue
            message = candidate.get("message")
            if isinstance(message, str):
                messages.append(message)
    return messages

def _render_edit_spec(resolved: SpecToolchainFlagResolution) -> dict[str, Any]:
    assert resolved.spec_relative_path is not None
    assert resolved.insert_after_line is not None
    assert resolved.anchor is not None
    assert resolved.insert is not None
    return {
        "schema_version": EDIT_SPEC_SCHEMA,
        "patch_name": "candidate_spec_toolchain_flags.patch",
        "description": "Insert Clang-only stripping for warning options unsupported by Clang.",
        "edits": [
            {
                "operation": "insert_after",
                "file": resolved.spec_relative_path,
                "line": resolved.insert_after_line,
                "anchor": resolved.anchor,
                "insert": resolved.insert,
            }
        ],
    }

def _relative(path: Path, base: Path) -> str:
    try:
        return path.relative_to(base).as_posix()
    except ValueError:
        return path.as_posix()

def resolve_spec_toolchain_flags(
    diagnostic: SpecToolchainFlagDiagnostic,
    *,
    src_root: Path | None,
) -> SpecToolchainFlagResolution:
    """Find a safe .spec insertion point for Clang-only flag stripping."""

    if not diagnostic.options:
        return SpecToolchainFlagResolution(status="not_applicable", options=())
    if src_root is None:
        return _advisory(diagnostic.options, "source root unavailable; cannot inspect .spec")
    try:
        spec_path = _find_single_spec(src_root)
    except (FileNotFoundError, ValueError) as exc:
        return _advisory(diagnostic.options, str(exc))

    lines = spec_path.read_text(encoding="utf-8", errors="surrogateescape").splitlines()
    section = _build_section_bounds(lines)
    if section is None:
        return _advisory(diagnostic.options, "no %build section found in .spec")
    start, end = section
    source_lines = _flag_source_lines(lines, start, end, diagnostic.options)
    if not source_lines:
        return _advisory(
            diagnostic.options,
            "unknown options were not found in %build CFLAGS/CXXFLAGS lines",
        )
    consumer_line = _first_consumer_line(lines, start, end)
    if consumer_line is None:
        return _advisory(diagnostic.options, "no flag consumer found in %build section")
    last_source_line = max(source_lines)
    if last_source_line >= consumer_line:
        return _advisory(
            diagnostic.options,
            "CFLAGS/CXXFLAGS option source appears after the first flag consumer",
        )

    try:
        existing_block = _existing_safe_clang_block(lines, last_source_line, consumer_line)
    except UnsafeSpecLayout as exc:
        return _advisory(diagnostic.options, str(exc))
    if existing_block is not None:
        insert_after, existing_lines = existing_block
        insert = _render_strip_block(diagnostic.options, wrap=False, existing_lines=existing_lines)
        if not insert:
            return _advisory(
                diagnostic.options,
                "existing clang toolchain block already strips the unknown options",
            )
    else:
        insert_after = last_source_line
        insert = _render_strip_block(diagnostic.options, wrap=True)
    anchor = lines[insert_after - 1]
    spec_relative = spec_path.resolve().relative_to(src_root.resolve()).as_posix()
    return SpecToolchainFlagResolution(
        status="spec_toolchain_flag_context_available",
        options=diagnostic.options,
        spec_path=spec_path,
        spec_relative_path=spec_relative,
        insert_after_line=insert_after,
        anchor=anchor,
        insert=insert,
    )

def _advisory(options: tuple[str, ...], reason: str) -> SpecToolchainFlagResolution:
    return SpecToolchainFlagResolution(
        status="spec_toolchain_flag_advisory",
        options=options,
        advisory=reason,
    )

def _find_single_spec(src_root: Path) -> Path:
    root = src_root.resolve()
    specs = sorted(
        path
        for path in root.rglob("*.spec")
        if ".git" not in path.parts and not any(part.startswith("GBS-ROOT") for part in path.parts)
    )
    if not specs:
        raise FileNotFoundError(f"no spec file found under {src_root}")
    if len(specs) > 1:
        raise ValueError(f"ambiguous spec files under {src_root}: {specs}")
    return specs[0]

def _build_section_bounds(lines: list[str]) -> tuple[int, int] | None:
    start: int | None = None
    for index, line in enumerate(lines, start=1):
        if BUILD_SECTION_RE.match(line):
            start = index + 1
            break
    if start is None:
        return None
    end = len(lines) + 1
    for index in range(start, len(lines) + 1):
        if TOP_LEVEL_SECTION_RE.match(lines[index - 1]):
            end = index
            break
    return start, end

def _flag_source_lines(
    lines: list[str],
    start: int,
    end: int,
    options: tuple[str, ...],
) -> list[int]:
    matches: list[int] = []
    for index in range(start, end):
        line = lines[index - 1]
        if "${CFLAGS/" in line or "${CXXFLAGS/" in line:
            continue
        if not FLAG_ASSIGN_RE.search(line):
            continue
        if any(option in line for option in options):
            matches.append(index)
    return matches

def _first_consumer_line(lines: list[str], start: int, end: int) -> int | None:
    for index in range(start, end):
        if CONSUMER_RE.match(lines[index - 1]):
            return index
    return None

def _existing_safe_clang_block(
    lines: list[str],
    last_source_line: int,
    consumer_line: int,
) -> tuple[int, set[str]] | None:
    for index in range(last_source_line + 1, consumer_line):
        if not CLANG_IF_RE.match(lines[index - 1]):
            continue
        block_end = _matching_endif(lines, index, consumer_line)
        if block_end is None:
            raise UnsafeSpecLayout(
                "existing clang toolchain block is not safely closed before the flag consumer"
            )
        existing_lines = {line.strip() for line in lines[index:block_end - 1]}
        return block_end - 1, existing_lines
    return None

def _matching_endif(lines: list[str], clang_if_line: int, consumer_line: int) -> int | None:
    depth = 0
    for index in range(clang_if_line, consumer_line):
        line = lines[index - 1]
        if line.lstrip().startswith("%if"):
            depth += 1
        elif ENDIF_RE.match(line):
            depth -= 1
            if depth == 0:
                return index
    return None

def _render_strip_block(
    options: tuple[str, ...],
    *,
    wrap: bool,
    existing_lines: set[str] | None = None,
) -> str:
    lines: list[str] = []
    if wrap:
        lines.extend(["%{?_toolchain:", "%if %{toolchain_is clang}"])
    existing = existing_lines or set()
    for option in options:
        line = f"CFLAGS=${{CFLAGS/{option}/}}"
        if line not in existing:
            lines.append(line)
    for option in options:
        line = f"CXXFLAGS=${{CXXFLAGS/{option}/}}"
        if line not in existing:
            lines.append(line)
    if wrap:
        lines.extend(["%endif", "}"])
    return "\n".join(lines)

def _load_main() -> Callable[..., int]:
    try:
        from gbs_patch_suggest.cli import main

        return main
    except ModuleNotFoundError as exc:
        if exc.name != "gbs_patch_suggest":
            raise

    scripts_dir = Path(__file__).resolve().parent
    sys.path.insert(0, str(scripts_dir))
    from gbs_patch_suggest.cli import main

    return main

def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code

def parse_gerrit_query_output(output: str) -> list[dict[str, Any]]:
    """Parse JSON-lines output from Gerrit, excluding the stats row."""

    changes: list[dict[str, Any]] = []
    for line in output.splitlines():
        if not line.strip():
            continue
        obj = json.loads(line)
        if obj.get("type") == "stats":
            continue
        if isinstance(obj, dict):
            changes.append(obj)
    return changes

def find_patchset_by_revision(obj: dict[str, Any], target_hash: str) -> GerritPatchSet | None:
    """Return the patch set whose revision equals the build commit."""

    patchsets = obj.get("patchSets")
    if not isinstance(patchsets, list):
        return None
    for item in patchsets:
        if not isinstance(item, dict):
            continue
        if item.get("revision") != target_hash:
            continue
        ref = item.get("ref")
        revision = item.get("revision")
        if isinstance(ref, str) and isinstance(revision, str):
            return GerritPatchSet(
                number=_optional_int(item.get("number")),
                revision=revision,
                ref=ref,
            )
    return None

def _reset_generated_source_dir(path: Path) -> None:
    if path.exists() and path.is_symlink():
        raise GerritError("SOURCE_DIR_UNSAFE", f"source directory is a symlink: {path}")
    if path.is_dir():
        shutil.rmtree(path)
    elif path.exists():
        path.unlink()

def _optional_int(value: Any) -> int | None:
    if isinstance(value, int):
        return value
    if isinstance(value, str) and value.isdigit():
        return int(value)
    return None

def gerrit_submit(
    options: GerritSubmitOptions,
    *,
    subprocess_runner: SubprocessRunner = subprocess.run,
) -> GerritSubmitResult:
    """Validate a verified worktree and return a dry-run Gerrit push command."""

    record = get_record(options.state_db, options.verification_id)
    if record is None:
        return _result(
            action="record_not_found",
            verification_id=options.verification_id,
            reason="verification record does not exist",
            options=options,
        )

    submission_key = build_submission_key(
        failure_key=record.failure_key,
        verified_tree_sha=record.verified_tree_sha,
    )
    latest = get_latest_status_row(options.state_db, record.failure_key)
    if latest is None or latest.status != GERRIT_READY:
        return _record_result(
            action="rejected_not_ready",
            record=record,
            submission_key=submission_key,
            options=options,
            reason="latest status is not GERRIT_READY",
        )
    if latest.verification_id != options.verification_id:
        return _record_result(
            action="rejected_not_ready",
            record=record,
            submission_key=submission_key,
            options=options,
            reason="latest GERRIT_READY belongs to a different verification_id",
        )

    worktree = Path(record.worktree_path)
    if not worktree.is_dir():
        return _record_result(
            action="rejected_worktree_missing",
            record=record,
            submission_key=submission_key,
            options=options,
            reason="verified worktree is missing; refusing to fall back to patch files",
        )

    mismatch = _verification_mismatch(record, worktree, subprocess_runner)
    if mismatch is not None:
        return _record_result(
            action="rejected_verification_mismatch",
            record=record,
            submission_key=submission_key,
            options=options,
            reason=mismatch,
        )
    dirty = _dirty_reason(worktree, subprocess_runner)
    if dirty is not None:
        return _record_result(
            action="rejected_worktree_dirty",
            record=record,
            submission_key=submission_key,
            options=options,
            reason=dirty,
        )

    warnings = _target_warnings(record, options, subprocess_runner)
    if options.submit_mode == "submit":
        return _record_result(
            action="rejected_submit_not_enabled",
            record=record,
            submission_key=submission_key,
            options=options,
            reason="Stage 1 submit mode is disabled; no git push was executed",
            warnings=warnings,
        )

    if options.state_db.get_submission(submission_key) is not None:
        return _record_result(
            action="skipped_duplicate",
            record=record,
            submission_key=submission_key,
            options=options,
            reason="submission key already exists",
            warnings=warnings,
        )

    command_argv = _push_command(record, options)
    remote_unknown = _target_head_unknown_warning(warnings)
    return _record_result(
        action="dry_run_unverified_remote" if remote_unknown else "dry_run",
        record=record,
        submission_key=submission_key,
        options=options,
        command_argv=command_argv,
        reason=(
            "remote state could not be verified "
            f"({remote_unknown}); duplicate/drift checks did not run"
            if remote_unknown
            else None
        ),
        warnings=[
            *warnings,
            (
                "verified worktree remains protected; run "
                "ci_triage release-worktree --verification-id "
                f"{options.verification_id} --state-db <path> when it is no longer needed"
            ),
        ],
    )

def _target_head_unknown_warning(warnings: list[str]) -> str | None:
    for warning in warnings:
        if warning.startswith("target_head_unknown:"):
            reason = warning.removeprefix("target_head_unknown:")
            if reason == "ls_remote_failed":
                return "ls-remote failed"
            return reason.replace("_", " ")
    return None

def release_verified_worktree(
    db: StateDatabase,
    verification_id: str,
) -> ReleaseWorktreeResult:
    """Release the protected worktree marker for one verification record."""

    record = get_record(db, verification_id)
    if record is None:
        return ReleaseWorktreeResult(
            action="record_not_found",
            verification_id=verification_id,
            worktree_path=None,
            released=False,
            reason="verification record does not exist",
        )
    released = release_worktree_protection(record.worktree_path)
    return ReleaseWorktreeResult(
        action="released" if released else "not_protected",
        verification_id=verification_id,
        worktree_path=record.worktree_path,
        released=released,
    )

def write_gerrit_submit_result(result: GerritSubmitResult, output: Path) -> None:
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(
        json.dumps(result.to_dict(), indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )

def write_release_result(result: ReleaseWorktreeResult, output: Path) -> None:
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(
        json.dumps(result.to_dict(), indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )

def exit_code_for_submit(result: GerritSubmitResult) -> int:
    if result.action == "record_not_found":
        return 2
    if result.action.startswith("rejected_"):
        return 3
    return 0

def _verification_mismatch(
    record: VerificationRecord,
    worktree: Path,
    subprocess_runner: SubprocessRunner,
) -> str | None:
    try:
        head = _git_stdout(worktree, ["rev-parse", "HEAD"], subprocess_runner)
        tree = _git_stdout(worktree, ["rev-parse", "HEAD^{tree}"], subprocess_runner)
    except subprocess.CalledProcessError as exc:
        return f"failed to read verified git object: exit {exc.returncode}"
    if head != record.verified_commit_sha:
        return "verified commit SHA does not match worktree HEAD"
    if tree != record.verified_tree_sha:
        return "verified tree SHA does not match worktree HEAD tree"
    return None

def _dirty_reason(worktree: Path, subprocess_runner: SubprocessRunner) -> str | None:
    tracked = _run_git(worktree, ["diff", "--quiet", "HEAD", "--"], subprocess_runner)
    if tracked.returncode != 0:
        return "tracked worktree changes exist after verified commit"
    staged = _run_git(worktree, ["diff", "--cached", "--quiet"], subprocess_runner)
    if staged.returncode != 0:
        return "staged changes exist after verified commit"
    return None

def _target_warnings(
    record: VerificationRecord,
    options: GerritSubmitOptions,
    subprocess_runner: SubprocessRunner,
) -> list[str]:
    branch = _target_branch(options.submit_target)
    if branch is None:
        return ["target_head_unknown:sandbox_target_not_checked"]
    remote = _remote_url(record, options)
    try:
        completed = subprocess_runner(
            ["git", "ls-remote", remote, f"refs/heads/{branch}"],
            check=False,
            text=True,
            capture_output=True,
            env=_subprocess_env(options.git_ssh_command),
        )
    except (OSError, subprocess.SubprocessError) as exc:
        return [f"target_head_unknown:{exc}"]
    if completed.returncode != 0:
        return ["target_head_unknown:ls_remote_failed"]
    first = (completed.stdout or "").splitlines()[0:1]
    if not first:
        return ["target_head_unknown:not_found"]
    target_head = first[0].split()[0]
    if target_head != record.base_commit:
        return [f"target_branch_drifted:{target_head}"]
    return []

def _target_branch(submit_target: str) -> str | None:
    if submit_target.startswith("refs/for/"):
        branch = submit_target.removeprefix("refs/for/")
        return branch.split("%", 1)[0]
    if submit_target.startswith("refs/drafts/"):
        return submit_target.removeprefix("refs/drafts/").split("%", 1)[0]
    if submit_target.startswith("refs/heads/sandbox/"):
        return None
    if submit_target.startswith("refs/heads/"):
        return submit_target.removeprefix("refs/heads/")
    return None

def _git_stdout(
    worktree: Path,
    args: list[str],
    subprocess_runner: SubprocessRunner,
) -> str:
    completed = _run_git(worktree, args, subprocess_runner, check=True)
    return (completed.stdout or "").strip()

def _run_git(
    worktree: Path,
    args: list[str],
    subprocess_runner: SubprocessRunner,
    *,
    check: bool = False,
) -> subprocess.CompletedProcess[str]:
    return subprocess_runner(
        ["git", "-C", str(worktree), *args],
        check=check,
        text=True,
        capture_output=True,
    )

def _build_id_from_failure_key(failure_key: str) -> str:
    parts = failure_key.split("/", 2)
    return parts[1] if len(parts) > 1 else ""

